Object.assign(window.BATCH_NOTES,{"生物10":{"10.1":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":10,"section_id":"10.1","goals":["由出生死亡迁入迁出分析种群变化","比较成长模型与抽样估计的条件"],"prerequisites":["同种个体与栖息地","比例与图象"],"flow":["种群边界","密度分布","四项收支","成长模型","抽样与条件"],"concept_relation":"种群边界；密度分布；四项收支；成长模型；抽样与条件","deep":["指数成长模型在相对增长率近似恒定、资源不形成明显限制等条件下使数量按固定倍数变化。数量—时间图可呈J形，普通坐标与对数坐标外形不同；模型不是所有种群永远指数增加的承诺。","逻辑斯谛模型引入密度制约和环境容纳量K，常用增长率rN(1−N/K)表达。在模型参数固定时总增长速率在N=K/2附近最大，数量曲线趋近K；这不同于每个体增长率，真实K也会随资源与环境改变。","标记重捕在样本随机、标记不影响生存捕获、个体充分混合且期间数量近似封闭等条件下，可用标记比例估总体。若标记丢失、迁移或不同个体捕获概率不同，结果可能偏；公式可算不表示假设已成立。","密度制约因素如资源竞争或部分病原传播，与密度无关的事件分类也依具体机制。真实灾变可能对某类个体选择性更强，不能把“自然事件”一概当无差别。调查和模型应由重复数据检验，不把一幅标准S曲线强套所有观察。"],"derive":["种群收支：N末=N初+B+I−D−E；密度=N/相应面积或体积。","理想固定倍增：N=N₀×2^(t/g)；逻辑斯谛模型增长速率rN(1−N/K)，固定参数时在K/2最大。","标记重捕估计N≈M×n/m，其中M首标记数、n重捕总数、m重捕中带标记数，m>0且假设需审。"],"examples":[{"q":"种群初100，期间出生20、死亡5、迁入3、迁出8，末数量及2 km²内密度？","given":"各项同一时间段，无重复计。","analysis":"数量收支后求密度。","method":"N末=100+20+3−5−8。","principle":"个体数守恒收支。","steps":["N末=110。","密度110/2=55个/km²。"],"ans":"110个，55个/km²。","verification":"净增10，与23进入/产生减13离开/死亡一致。","pitfall":"只用出生减死亡忽略迁移。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.1","related_sections":[]},{"q":"首标记40个，充分混合后重捕50个，其中10标记，估总体并写限制。","given":"标记不影响捕获，近似封闭等作为模型假设。","analysis":"样本标记比估总体比。","method":"40/N≈10/50。","principle":"代表性比例。","steps":["N≈40×50/10=200。","若标记丢失或迁出等，比例假设可能失效。"],"ans":"估200个，条件性结果。","verification":"总体标记占20%，样本10/50同20%。","pitfall":"把40+50直接当总体或无条件精确数。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.1","related_sections":[]},{"q":"逻辑斯谛模型r=.2/年、K=1000，N=100与500时总增长速率各多少？哪时每个体增长率更大？","given":"固定参数模型。","analysis":"总速率与每个体速率不同。","method":"rN(1−N/K)与r(1−N/K)。","principle":"密度制约模型。","steps":["N100时总18个/年、每个体.18/年。","N500时总50个/年、每个体.10/年。"],"ans":"总速率500时大；每个体速率100时大。","verification":"50>18但.10<.18，没有矛盾。","pitfall":"把K/2总增长最大误成每个体也最大。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.1","related_sections":[]}],"practice":[{"q":"一池塘所有鱼不分物种，可以直接叫同一种群吗？","given":"有多个物种。","analysis":"种群有同种条件。","method":"核时间空间与物种。","principle":"种群定义。","steps":["若多物种，应分别成种群。","所有这些生物的集合涉及群落层次，不能合为一个种群。"],"ans":"不能。","verification":"同池塘并不抹去物种区别。","pitfall":"只按地点定义种群。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.1","related_sections":[]},{"q":"初50个，理想每代翻倍，3代后？能无限照算吗？","given":"三代内条件满足。","analysis":"固定倍数指数模型。","method":"50×2³。","principle":"二分或对应倍增假设。","steps":["结果400。","资源和环境改变后代时或存活可变，不可无限外推。"],"ans":"400个；不可无条件无限外推。","verification":"50→100→200→400。","pitfall":"将3代写乘3。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.1","related_sections":[]},{"q":"只有幼年个体多，能保证未来数量增加吗？","given":"缺后续生存资源等资料。","analysis":"年龄结构是线索而非保证。","method":"列死亡与迁移。","principle":"种群收支多因素。","steps":["幼年可带来繁殖潜力。","若死亡高、迁出大或资源不足，仍可能下降。"],"ans":"不能保证。","verification":"未活到繁殖期就不形成预期出生。","pitfall":"把潜在增长写成确定预测。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.1","related_sections":[]},{"q":"K=800、r=.1，N=K时模型净增长多少？是否证明真实个体都不出生不死亡？","given":"逻辑斯谛模型。","analysis":"净值零不等于周转零。","method":"rK(1−1)。","principle":"数量净变化与个体过程不同。","steps":["模型增长0。","真实可出生死亡相抵，且K可变。"],"ans":"净增长0；不能说所有过程停止。","verification":"B和D都10时净0仍有更新。","pitfall":"把稳定数量等同无生命活动。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.1","related_sections":[]}],"quiz":{"q":"标记重捕中没有重捕到标记个体，能把M×n/0算成一个可靠无限大种群吗？","given":"m=0。","analysis":"估式分母失效。","method":"检查样本量混合与捕获假设。","principle":"有限样本无标记不提供该比值估计。","steps":["不能作普通除法。","应增加可靠数据或用合适统计方法并报告不确定性，不能宣布无限大。"],"ans":"不能，当前估计式不适用。","verification":"总体有限也可能小样本未抽到标记。","pitfall":"把除0当现实无限大结论。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.1","related_sections":[]},"exam":["数量题先定时间空间和计数单位，四项收支全部列","成长曲线题分总增长与每个体增长，参数条件写清","抽样题先查随机、封闭和标记效应，再算估值并报告限制"],"quick":["种群边界","密度分布","四项收支","成长模型","抽样与条件"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_10.1","url":"https://openstax.org/books/biology-2e/pages/45-3-environmental-limits-to-population-growth","page_or_section":"45-3-environmental-limits-to-population-growth","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_10.1_0","url":"https://openstax.org/books/biology-2e/pages/45-1-population-demography","page_or_section":"45-1-population-demography","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_10.1","url":"https://openstax.org/books/biology-2e/pages/45-3-environmental-limits-to-population-growth","page_or_section":"45-3-environmental-limits-to-population-growth","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_10.1_0","url":"https://openstax.org/books/biology-2e/pages/45-1-population-demography","page_or_section":"45-1-population-demography","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"数量题先定时间空间和计数单位，四项收支全部列","method":"rN(1−N/K)与r(1−N/K)。","principle":"密度制约模型。","worked_example_index":2,"verification":"50>18但.10<.18，没有矛盾。","pitfall":"把K/2总增长最大误成每个体也最大。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由出生死亡迁入迁出分析种群变化”的抽样复核：净增10，与23进入/产生减13离开/死亡一致。；若出现“只用出生减死亡忽略迁移。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“比较成长模型与抽样估计的条件”的抽样复核：50>18但.10<.18，没有矛盾。；若出现“把K/2总增长最大误成每个体也最大。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把除0当现实无限大结论。","correction":"不能，当前估计式不适用。","verification":"总体有限也可能小样本未抽到标记。"}],"illustration_spec":{"title":"种群成长模型与收支","objects":["N-t指数/逻辑斯谛图","增长率对N图","B/I/D/E收支","标记重捕比例"],"relations":["K/2为固定参数总增长率峰","每个体增长率不同","m=0时不能除法估无限大"],"labels":["N","t","K","K/2","rN(1−N/K)","M/N≈m/n"],"format":"SVG","priority":"P0","reuse":"需新准确图；表内10.1.1仅知识点，不伪造额外课本小节","english":"Plot population size versus time for explicitly idealized exponential and logistic models, separately plot logistic total growth rate versus N with its peak at K/2, and distinguish per-capita growth. Include birth/death/immigration/emigration accounting and conditional mark-recapture proportions."}},"10.2":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":10,"section_id":"10.2","goals":["辨认生态系统组成与营养关系","用食物网和环境证据解释系统变化"],"prerequisites":["种群群落","光合呼吸与分解"],"flow":["系统边界","功能类群","食物网","相互作用","演替与稳定"],"concept_relation":"系统边界；功能类群；食物网；相互作用；演替与稳定","deep":["食物链箭头通常从被食资源指向消费者，表示物质和能量转移方向，不是捕食者“攻击谁”的箭头。食物网连接多条关系，杂食者可跨营养级；同一物种不一定永远只有一个固定营养级编号。","生物间还有竞争、互利等相互作用，并受到非生物限制。移走一种捕食者可能经多条路径影响猎物、竞争者和生产者；简单单链预测只在相应模型内成立，真实食物网须以数据检验。","生态演替描述群落组成和环境在时间中改变。初生演替从缺乏原有土壤等背景开始，次生演替保留部分土壤或生物遗存，通常有不同起点；先锋种不在所有地区都同一，不能把某一经典顺序当全部地区必经路线。","系统稳定包括抵抗干扰与干扰后的恢复等不同方面，多样性、网络及外界条件共同影响。稳定不等于每个物种数量永远不变，生态系统也可能转到另一状态；评价需明确指标和观察时间。"],"derive":["生态系统=生物群落+非生物环境及其联系；边界一般有物质和能量交换。","食物箭头：资源→摄食者，分解网络接收来自多个营养级的死有机物。","干扰分析：列直接作用 → 食物网间接路径 → 非生物与时间尺度 → 提可测预测及对照。"],"examples":[{"q":"池塘的鱼、藻、细菌集合与包括池水、光照、底泥的整体，哪个更符合生态系统？","given":"前者只列生物。","analysis":"群落与系统范围不同。","method":"检查非生物组分及联系。","principle":"生态系统定义。","steps":["生物集合对应群落层次。","加非生物环境及相互作用才是生态系统整体。"],"ans":"后者。","verification":"环境条件改变会影响同样生物集合的过程。","pitfall":"把生态系统只当生物名录。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.2","related_sections":[]},{"q":"藻类被浮游动物吃，后者被小鱼吃，画箭头并说明每个箭头含义。","given":"按摄食链，不表示攻击方向。","analysis":"资源向消费者。","method":"藻→浮游动物→小鱼。","principle":"有机物及能量随摄食转移。","steps":["第一箭头藻到浮游动物。","第二浮游动物到鱼，不能倒画成攻击对象。"],"ans":"藻类→浮游动物→小鱼。","verification":"鱼获食的来源在箭头上游。","pitfall":"从捕食者指向猎物。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.2","related_sections":[]},{"q":"捕食者减少后猎物没有增加，能立即说食物网理论错误吗？","given":"真实系统可能有竞争、疾病、资源限制等。","analysis":"单一路径不是全系统。","method":"列替代过程与监测设计。","principle":"网络效应受多因素约束。","steps":["猎物可能同时受食物不足或其他捕食者控制。","需多时点、参照及其他关系数据，不能仅据一条简化预测否定全部。"],"ans":"不能，先检查模型和其他路径。","verification":"没有资源支持，减少死亡也未必形成净增。","pitfall":"把单链简化当全部生态规律。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.2","related_sections":[]}],"practice":[{"q":"生产者一定都靠太阳光吗？","given":"包含化能合成类群。","analysis":"自养不等于只光合。","method":"区分能量来源。","principle":"部分生物可用化学能固定无机碳。","steps":["光合为常见来源。","化能合成生产者可在无光条件利用相应化学反应。"],"ans":"不一定。","verification":"深海等例说明太阳光不是所有局部生产者的直接能源。","pitfall":"生产者只等于绿色植物。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.2","related_sections":[]},{"q":"分解者只接收最高营养级尸体吗？","given":"考分解网络。","analysis":"每级都有死亡排泄物。","method":"连各级有机物输入。","principle":"分解作用跨营养级来源。","steps":["生产者也可枯死。","消费者和其他生物均贡献碎屑，不只顶级。"],"ans":"不是，来自多个营养级。","verification":"落叶即可构成生产者到分解网络输入。","pitfall":"把分解者画成链的唯一末端只连顶级。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.2","related_sections":[]},{"q":"火灾后土壤和部分种子仍在，通常属初生还是次生演替？","given":"背景保留原土与遗存。","analysis":"起点不同。","method":"按条件分类。","principle":"次生演替利用保留资源。","steps":["原土壤未全失。","因此通常按次生演替分析，实际恢复受火强度等影响。"],"ans":"通常次生。","verification":"初生模型常无原有土壤起点，与题设不同。","pitfall":"只要灾后就全叫初生。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.2","related_sections":[]},{"q":"两个系统干扰后下降都20%，甲一年恢复、乙五年恢复，能比较哪项稳定性？能否说所有稳定指标甲都高？","given":"仅给同样下降及恢复时间。","analysis":"恢复力与抵抗力不同。","method":"比较对应指标。","principle":"稳定性多维。","steps":["在该干扰与指标下甲恢复更快。","下降程度相同不能据此说甲抵抗力更高，更不能全面排序。"],"ans":"可说甲该指标恢复更快，不能泛称全部更稳定。","verification":"两者冲击幅度同，恢复时间才不同。","pitfall":"把一个指标代表所有稳定性。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.2","related_sections":[]}],"quiz":{"q":"城市有人工设施，因此不可能是生态系统，这句话错在哪里？","given":"城市仍有生物非生物过程。","analysis":"人工与生态系统不是互斥分类。","method":"核组成和联系。","principle":"人类管理系统也可有生态系统结构。","steps":["城市有植物、动物、微生物和水土气候等。","依赖外部资源且受管理不取消生态关系。"],"ans":"错在把人工条件排除于生态系统定义。","verification":"后续可评价输入输出与管理，而非否定系统存在。","pitfall":"生态系统只允许无人自然环境。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.2","related_sections":[]},"exam":["组成题写生物、非生物及联系，不只列名","食物网题先声明箭头意义，杂食和分解网络勿强成单链","干扰题列多路径与时间，稳定性比较要给具体指标"],"quick":["系统边界","功能类群","食物网","相互作用","演替与稳定"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_10.2","url":"https://openstax.org/books/biology-2e/pages/46-1-ecology-of-ecosystems","page_or_section":"46-1-ecology-of-ecosystems","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_10.2","url":"https://openstax.org/books/biology-2e/pages/46-1-ecology-of-ecosystems","page_or_section":"46-1-ecology-of-ecosystems","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"组成题写生物、非生物及联系，不只列名","method":"列替代过程与监测设计。","principle":"网络效应受多因素约束。","worked_example_index":2,"verification":"没有资源支持，减少死亡也未必形成净增。","pitfall":"把单链简化当全部生态规律。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“辨认生态系统组成与营养关系”的抽样复核：环境条件改变会影响同样生物集合的过程。；若出现“把生态系统只当生物名录。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“用食物网和环境证据解释系统变化”的抽样复核：没有资源支持，减少死亡也未必形成净增。；若出现“把单链简化当全部生态规律。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"生态系统只允许无人自然环境。","correction":"错在把人工条件排除于生态系统定义。","verification":"后续可评价输入输出与管理，而非否定系统存在。"}],"illustration_spec":{"title":"生态系统功能网络","objects":["生产者","草食与肉食消费者","分解者","碎屑食者","无机环境","太阳/化学能"],"relations":["资源到消费者箭头","多个营养级到分解网络","无机养分回生产者","能量输入与热分散分开"],"labels":["群落","非生物环境","物质","能量","未按大小比例"],"format":"SVG","priority":"P0","reuse":"V22食物网可核箭头后局部复用；不改旧缺口记录","english":"Draw an ecosystem with producers, multiple consumer levels, decomposers, detritivores and abiotic pools. Food arrows go from resource to consumer; dead matter reaches decomposers from all levels. Keep nutrient return separate from energy input and heat loss, and do not make decomposers the exclusive final link of one chain."}},"10.3":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":10,"section_id":"10.3","goals":["以收支区分生产量同化与呼吸","正确追踪碳氮磷循环和营养级能流"],"prerequisites":["光合与呼吸","营养级与守恒"],"flow":["能量输入与热","生产收支","营养传递","碳库","氮磷转化"],"concept_relation":"能量输入与热；生产收支；营养传递；碳库；氮磷转化","deep":["营养级传递效率需在同一面积、时间和能量边界下比较生产或相应流量。常见10%只能作题设示例或粗略经验，不是适用于所有链的固定常数。能量金字塔的流量关系与瞬时生物量、个体数金字塔不同，后两者可以在某些系统倒置。","碳循环中光合等固定无机碳，摄食传递有机碳，呼吸、分解及燃烧等释放CO₂，海洋交换与长期储存等连接更大尺度。植物也呼吸，分解者的碳来源不只动物尸体；不要把一切释放都画成人类活动或一切吸收都视为永久储存。","氮循环须分生物固氮把N₂转为可利用含氮形式，氨化把有机氮转成铵态，硝化在相应需氧条件下由铵经亚硝酸盐到硝酸盐，反硝化在相应条件下将硝酸盐等还原并返回N₂等。植物同化铵或硝酸盐与微生物固氮不是同一步。","磷循环联系岩石风化、土壤水体磷酸盐、生物吸收、分解和沉积，通常没有像氮那样占主导的大气气态库；尘埃等仍可运输磷，不能绝对说“任何磷都不经过空气”。不同循环有共同守恒思想但具体化学形态和条件不同。","做综合题应对每个库和箭头说明物质名、过程和条件，定量收支统一单位；遗失一条呼吸或碎屑路径会让图看似闭合却算出不合理效率。边界可与外界交换，不能只因称循环就假设任何局地系统绝对封闭。"],"derive":["NPP=GPP−R生产者；消费者简化A=I−F，P=A−R。","相邻营养级传递效率=上层相应生产量/下层相应生产量×100%，边界和时间相同。","硝化：NH₄⁺→NO₂⁻→NO₃⁻（相应需氧微生物过程）；反硝化与之不是同义，固氮从N₂进入生物可利用库。"],"examples":[{"q":"GPP=20000 kJ/(m²·年)，生产者呼吸12000，同边界NPP多少？全部NPP必给草食者吗？","given":"同时间面积单位。","analysis":"先收支，再分流。","method":"NPP=GPP−R。","principle":"生产者净积累及分配。","steps":["NPP=8000 kJ/(m²·年)。","可进入储存、生长与碎屑等，不是全被草食者摄入。"],"ans":"8000，不能说全部直传草食者。","verification":"8000+12000=20000。","pitfall":"把GPP直接当可传递净生产。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.3","related_sections":[]},{"q":"消费者摄入1000 kJ，未同化排出400，呼吸450，简化求同化与生产量。","given":"其他收支项按题设忽略。","analysis":"摄入、同化、生产三级不同。","method":"A=I−F，P=A−R。","principle":"能量收支。","steps":["A=1000−400=600 kJ。","P=600−450=150 kJ。"],"ans":"同化600、生产150 kJ。","verification":"400+450+150=1000，账目闭合。","pitfall":"摄入减呼吸得550而漏未同化。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.3","related_sections":[]},{"q":"浮游植物瞬时生物量2 g/m²，浮游动物10 g/m²，是否证明能量金字塔倒置？","given":"只给瞬时质量。","analysis":"存量与单位时间能流不同。","method":"要求生产量和周转资料。","principle":"生物量金字塔不同于能量金字塔。","steps":["生产者可周转快，低存量持续支持消费者。","需同时间能量生产量比较，不能把g/m²当kJ/(m²·年)。"],"ans":"不能。","verification":"单位和时间尺度已不同。","pitfall":"把瞬时生物量比例当能量效率。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.3","related_sections":[]}],"practice":[{"q":"生产者净生产10000，下级1000，再下级100，同单位，传递效率各多少？是否普遍定律？","given":"数据是同边界生产量。","analysis":"按相邻流量比。","method":"1000/10000与100/1000。","principle":"效率定义。","steps":["各.10=10%。","只此数据如此，真实效率受物种、食物和条件等影响。"],"ans":"各10%，不代表普遍固定。","verification":"两级累计100/10000=1%。","pitfall":"把10%强套所有题。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.3","related_sections":[]},{"q":"植物直接把大气N₂吸收作蛋白质是对氮循环的充分描述吗？","given":"一般植物，不假设特殊直接能力。","analysis":"固氮与植物同化不同。","method":"说明微生物转化及可用形态。","principle":"植物通常利用相应铵/硝酸盐等。","steps":["N₂需经固氮等转为可用形式。","植物再同化，豆科共生也不能把宿主与固氮菌功能混为一体。"],"ans":"不是，应分固氮与同化。","verification":"豆科根瘤微生物提供固氮机制。","pitfall":"所有植物都直接用N₂。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.3","related_sections":[]},{"q":"NH₄⁺到NO₃⁻与NO₃⁻到N₂是同一方向的硝化吗？","given":"两个过程化学形态不同。","analysis":"氧化与还原路径不同。","method":"分别命名及条件。","principle":"硝化与反硝化。","steps":["前者经NO₂⁻属于硝化。","后者相应还原返氮气为反硝化，常在低氧等条件微生物参与。"],"ans":"不是同过程。","verification":"起终形态与氮去向不同。","pitfall":"仅因都有氮就连同一箭头。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.3","related_sections":[]},{"q":"某生产者GPP500、呼吸200，下级净生产60，同单位，求NPP、效率并说明若误用GPP分母会怎样。","given":"比较下级生产与生产者净生产。","analysis":"边界需一致。","method":"NPP=500−200。","principle":"按给定生产量口径。","steps":["NPP300。","效率60/300=20%；若除500得12%，是不同口径，不能混称本题效率。"],"ans":"300、20%。","verification":"下级60在生产者净300中占五分之一。","pitfall":"不说明分母口径就比较百分比。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.3","related_sections":[]}],"quiz":{"q":"既然能量守恒，为什么不把呼吸散出的热直接画成回到生产者光合作用的同一可用能量箭头？","given":"讨论生态能流和可用能量。","analysis":"总量守恒与可利用性不同。","method":"区分太阳/化学能输入和分散热。","principle":"能量转换后可用性降低，不能完全循环做功。","steps":["散热仍是环境能量的一部分。","并不在该生态尺度上无代价重新集中为等量光合可用能，应画外界输入和热分散。"],"ans":"不应闭合成无损循环。","verification":"物质可再利用不等于能量完全反复利用。","pitfall":"用守恒否定能量分散。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.3","related_sections":[]},"exam":["收支题先分摄入同化生产与呼吸，单位时间面积一致","循环图逐箭头写化学形态过程条件，固氮硝化反硝化不混","金字塔题先看存量还是流量，10%只按题给数据求"],"quick":["能量输入与热","生产收支","营养传递","碳库","氮磷转化"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_10.3","url":"https://openstax.org/books/biology-2e/pages/46-2-energy-flow-through-ecosystems","page_or_section":"46-2-energy-flow-through-ecosystems","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_10.3_0","url":"https://openstax.org/books/biology-2e/pages/46-3-biogeochemical-cycles","page_or_section":"46-3-biogeochemical-cycles","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_10.3","url":"https://openstax.org/books/biology-2e/pages/46-2-energy-flow-through-ecosystems","page_or_section":"46-2-energy-flow-through-ecosystems","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_10.3_0","url":"https://openstax.org/books/biology-2e/pages/46-3-biogeochemical-cycles","page_or_section":"46-3-biogeochemical-cycles","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"收支题先分摄入同化生产与呼吸，单位时间面积一致","method":"要求生产量和周转资料。","principle":"生物量金字塔不同于能量金字塔。","worked_example_index":2,"verification":"单位和时间尺度已不同。","pitfall":"把瞬时生物量比例当能量效率。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“以收支区分生产量同化与呼吸”的抽样复核：8000+12000=20000。；若出现“把GPP直接当可传递净生产。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“正确追踪碳氮磷循环和营养级能流”的抽样复核：单位和时间尺度已不同。；若出现“把瞬时生物量比例当能量效率。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"用守恒否定能量分散。","correction":"不应闭合成无损循环。","verification":"物质可再利用不等于能量完全反复利用。"}],"illustration_spec":{"title":"能流收支与碳氮磷循环","objects":["GPP/R/NPP收支","摄入排出呼吸生产","碳循环","氮化学形态","磷地质库"],"relations":["20000−12000=8000","1000=400+450+150","硝化与反硝化方向分开","能量热不闭合回生产者"],"labels":["GPP","NPP","R","NH₄⁺","NO₂⁻","NO₃⁻","N₂","条件性箭头"],"format":"SVG","priority":"P0","reuse":"V22 B50、B54可复核用于部分能量碳循环；氮磷仍需图","english":"Use separate panels for GPP 20000 minus respiration 12000 equals NPP 8000, and consumer intake 1000=egestion 400+respiration 450+production 150. Draw carbon, nitrogen and phosphorus pools with correctly directed labelled transformations; distinguish nitrogen fixation, nitrification and denitrification and never close heat loss into a lossless energy cycle."}},"10.4":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":10,"section_id":"10.4","goals":["以水分温度盐度等解释系统差异","比较自然与人工系统并评价类型推断限制"],"prerequisites":["生态系统组成","限制因素与物质循环"],"flow":["陆地气候土壤","淡水流动分层","海洋盐光营养","湿地过程","人工系统与比较"],"concept_relation":"陆地气候土壤；淡水流动分层；海洋盐光营养；湿地过程；人工系统与比较","deep":["淡水系统中河流的流动、底质和沿程输入与湖泊的深度、分层和混合有不同作用。水流可促进复氧但不保证所有河段永远溶氧高；高温、有机污染或停滞等可降低溶氧，须实际测量。","湖泊可能有透光层与深水层差异，温度分层影响氧和养分交换，具体混合模式取决纬度、深度和季节。不能把温带深湖的季节循环当所有浅湖、热带湖泊或水库的同一规律。","海洋系统受盐度、光、营养、流与深度等影响，沿岸、上升流、开放大洋和深海环境不同。河口在淡盐水交汇中有梯度，生物面临变化盐度；海水多不等于每单位面积初级生产都高，深海化能系统也不能完全照浅海光合模型。","湿地有长期或周期性水饱和土壤，影响氧化还原、物质保留和栖息地。保护效益与甲烷等过程可能并存，要按目标和条件评价；农田和城市则受强管理及外部资源输入，仍是可分析的生态系统，不能因人工就排除。","比较类型应说明尺度、指标与取样。假想地点资料可支持某些类型的可能性而不必唯一决定；分类、生产力、多样性与稳定性是不同问题，若证据不足应提出还需季节、土壤和物种资料。"],"derive":["类型推断：温度/水分及季节性 + 土壤/底质 + 水流/盐度/光 + 生物与管理历史。","水体生产需光或化学能源、营养等条件；面积大不等于单位面积生产高。","比较相同指标、单位与时间；自然/人工描述管理来源，不否定生态系统组成。"],"examples":[{"q":"假想甲地终年温暖、降雨多且无明显长旱季，乙地温暖但可利用水很少，这支持哪些类型判断？能唯一确定吗？","given":"仅给气候线索。","analysis":"水分影响植被，但土壤历史等也重要。","method":"给有条件候选并列缺数据。","principle":"多因子控制类型。","steps":["甲与湿润热带森林条件相容。","乙与荒漠/半荒漠等干旱系统相容；仍需土壤、季节及实际群落，不唯一确认。"],"ans":"支持相应候选，不足单独唯一分类。","verification":"同样气候下人为砍伐可形成不同现状。","pitfall":"把两项气候数字当完整分类证明。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.4","related_sections":[]},{"q":"湖表层白天溶氧高、深层低，可用什么机制解释？为什么不能由此说深层没有生物？","given":"水体可能分层，未给具体湖型。","analysis":"光合、呼吸和交换同时作用。","method":"连透光和混合限制。","principle":"分层与生物过程影响氧分布。","steps":["表层可有光合及空气交换。","深层光少且分解呼吸耗氧、混合有限，可能氧低；某些生物仍适应低氧或厌氧。"],"ans":"可解释氧差，但不能推无生命。","verification":"低氧与绝对无生物不是同义。","pitfall":"只按水深说一切生物无法存在。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.4","related_sections":[]},{"q":"农田输入肥料灌溉并收获外运，能因物质不完全就地循环而说它不是生态系统吗？","given":"有人为输入输出。","analysis":"生态系统一般非封闭。","method":"检查生物非生物联系。","principle":"管理系统仍有能流和物质过程。","steps":["作物、微生物与土水光等构成联系。","外部输入输出是收支的重要部分，不取消生态系统身份。"],"ans":"不能，农田是受管理的生态系统。","verification":"自然系统也可有河流、迁移等跨界交换。","pitfall":"把必须封闭当系统定义。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.4","related_sections":[]}],"practice":[{"q":"荒漠是否意味着完全无生命、无生产？","given":"水少而非逻辑上无生物。","analysis":"限制不等于绝对零。","method":"看适应与时空变化。","principle":"生物可在可用水条件下活动。","steps":["有些植物动物和微生物适应干旱。","降雨脉冲可影响生产，不能把全部过程设0。"],"ans":"不是。","verification":"少量或季节性生产仍属于生态过程。","pitfall":"把稀少当不存在。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.4","related_sections":[]},{"q":"河流流速快就必保证任何位置溶氧都高吗？","given":"还未知温度污染等。","analysis":"一个促进因素非充分条件。","method":"比较复氧与耗氧等。","principle":"溶氧受多过程收支。","steps":["流动可能增加交换。","高温或大量有机物耗氧等可抵消，需实测。"],"ans":"不保证。","verification":"同流速河段可有不同污染负荷。","pitfall":"单变量无条件预测。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.4","related_sections":[]},{"q":"河口能只按固定海水盐度研究所有季节吗？","given":"淡水输入和潮汐可变。","analysis":"过渡系统梯度变化。","method":"记录时间空间盐度。","principle":"生境条件非固定单值。","steps":["雨季径流、潮汐等改变盐度。","取样应涵盖位置时间，不能套一个恒定海水值。"],"ans":"不能。","verification":"同一地点不同潮时可有不同值。","pitfall":"把海洋标签当无变化环境。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.4","related_sections":[]},{"q":"甲系统年净生产600 g/(m²·年)，乙300；甲面积2 km²、乙10 km²，谁单位面积高、谁总量大？","given":"单位与年份可比，面积换算。","analysis":"强度与总量不同。","method":"生产率乘面积。","principle":"总量=单位面积量×面积。","steps":["甲单位面积高。","甲总600×2×10⁶=1.2×10⁹ g/年；乙300×10×10⁶=3.0×10⁹ g/年。"],"ans":"甲单位面积高，乙总量大。","verification":"乙面积5倍而率一半，总量2.5倍。","pitfall":"只比面积或只比率就回答两个问题。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.4","related_sections":[]}],"quiz":{"q":"热带森林种类多，是否可以不用资料直接宣称其所有稳定指标都高于农田？","given":"不同管理与环境背景。","analysis":"多样性与稳定性多维。","method":"明确比较目标、干扰和指标。","principle":"恢复、抵抗及服务等不同。","steps":["可提出多样性可能增强部分过程的假说。","仍需同指标数据和情境，不能给全部性质无条件排序。"],"ans":"不能直接全面宣称。","verification":"农田产量、抗某干扰与恢复的指标可不同。","pitfall":"用类型名称取代测量。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":10,"primary_section":"10.4","related_sections":[]},"exam":["类型题从限制因素解释结构，候选判断注明证据边界","水体题分光、营养、氧与混合，不把全部水域一式套用","比较题区分单位面积生产和总量，稳定多样性分别评价"],"quick":["陆地气候土壤","淡水流动分层","海洋盐光营养","湿地过程","人工系统与比较"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_10.4","url":"https://openstax.org/books/biology-2e/pages/44-3-terrestrial-biomes","page_or_section":"44-3-terrestrial-biomes","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_10.4_0","url":"https://openstax.org/books/biology-2e/pages/44-4-aquatic-biomes","page_or_section":"44-4-aquatic-biomes","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_10.4","url":"https://openstax.org/books/biology-2e/pages/44-3-terrestrial-biomes","page_or_section":"44-3-terrestrial-biomes","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_10.4_0","url":"https://openstax.org/books/biology-2e/pages/44-4-aquatic-biomes","page_or_section":"44-4-aquatic-biomes","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"类型题从限制因素解释结构，候选判断注明证据边界","method":"检查生物非生物联系。","principle":"管理系统仍有能流和物质过程。","worked_example_index":2,"verification":"自然系统也可有河流、迁移等跨界交换。","pitfall":"把必须封闭当系统定义。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“以水分温度盐度等解释系统差异”的抽样复核：同样气候下人为砍伐可形成不同现状。；若出现“把两项气候数字当完整分类证明。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“比较自然与人工系统并评价类型推断限制”的抽样复核：自然系统也可有河流、迁移等跨界交换。；若出现“把必须封闭当系统定义。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"用类型名称取代测量。","correction":"不能直接全面宣称。","verification":"农田产量、抗某干扰与恢复的指标可不同。"}],"illustration_spec":{"title":"生态系统类型与限制梯度","objects":["森林草原荒漠寒冷地","河流湖泊","海洋河口湿地","农田城市","温度水分盐度光梯度"],"relations":["类型边界有过渡","湖泊分层依条件","人工有跨界输入输出","生产率与总量分开"],"labels":["限制因素","季节性","单位面积","总量","示意非全球实测分布"],"format":"SVG","priority":"P1","reuse":"可用已审核生态示意局部；不以装饰景观代替限制关系","english":"Create a comparison matrix of terrestrial, freshwater, marine, estuarine, wetland and managed ecosystems linked to water, temperature, salinity, light and nutrient limitations. Mark gradients and conditional lake stratification, and distinguish production per unit area from total production. Do not present schematic landscapes as measured global distributions."}}},"生物11":{"11.1":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":11,"section_id":"11.1","goals":["用机制解释人类活动的生态后果","评估环境数据的因果边界"],"prerequisites":["食物网与分解者","物质循环"],"flow":["土地利用","营养与耗氧","污染物浓度","气候尺度","入侵与过度利用"],"concept_relation":"土地利用；营养与耗氧；污染物浓度；气候尺度；入侵与过度利用","deep":["某些难降解物质可在个体组织中积累；在适当物质性质和食物网条件下，较高营养级可出现更高浓度。生物累积描述个体随时间或暴露的积聚，生物放大描述营养级间浓度变化，二者不能互换，也不能推断所有污染物都必定逐级放大。","温室效应是大气某些气体吸收并再辐射地表长波辐射的物理过程，天然效应与人类增强效应应分开。气候变化会影响温度、降水、极端事件和分布范围；一次寒冷天气不能独立否定长期趋势，一次高温也不足以单独归因某个具体排放源。","外来物种不一定成为入侵种，但当其建立、扩散并造成显著生态或其他危害时，可能改变竞争、捕食及病原关系。缺乏天敌是某些案例的因素，不是所有外来种影响的唯一解释。过度捕捞还可能通过食物网间接改变其他营养级。","环境评价需要时间序列、适当对照、重复与背景条件。污染源附近生物少可以提示关联，但还要排查水流、底质、季节、其他排放和采样方法；提出机制与验证方案比简单把任何差异归因人类更有解释力。"],"derive":["富营养化的条件链：外源营养输入增加 → 初级生产或藻量变化 → 死亡有机物与分解耗氧增加 → 特定条件下溶氧下降。","浓度=污染物质量/样品质量；营养级间比较必须使用相同基准单位。","相对变化=(处理后−基准)/基准；相关数据仍需可比设计才能支持因果解释。"],"examples":[{"q":"某湖接受含磷径流后藻量增加，随后清晨溶氧降低，解释一条合理机制。","given":"有营养输入、藻量与溶氧的时间变化。","analysis":"连接营养、生物量及耗氧过程。","method":"按过程链解释并限定。","principle":"分解者和生物呼吸消耗氧。","steps":["营养增加可促进藻类繁殖。","死亡有机物增加使微生物分解耗氧增强，夜间无光合补氧时风险可增。"],"ans":"富营养化相关过程可导致缺氧，仍需排除其他因素。","verification":"若只是肥料直接结合氧，不能解释有机物分解的延迟。","pitfall":"只写藻类多所以氧少，不说过程。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]},{"q":"浮游生物污染物0.02 mg/kg，小鱼0.2 mg/kg，大鱼1 mg/kg，说明什么？","given":"同一物质、同一质量基准，给定食物关系。","analysis":"比较浓度而非每个体总质量。","method":"计算营养级浓度比。","principle":"生物放大以营养级间浓度递增为特征。","steps":["小鱼为浮游生物的10倍。","大鱼为小鱼5倍、浮游生物50倍。"],"ans":"该数据支持此食物链中出现生物放大。","verification":"统一mg/kg后比例才有意义，不能直接推广其他物质。","pitfall":"把体型大总含量高当作浓度放大。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]},{"q":"河流下游物种少于上游，是否足以证明唯一原因是某工厂？","given":"仅一次上下游比较。","analysis":"上下游还有自然与人为混杂。","method":"列重复、参照与机制检测。","principle":"因果需时间与空间可比证据。","steps":["补测排放前后、多个参照点及污染指标。","控制水流、底质和季节等，并检查暴露—效应关系。"],"ans":"不足以确定唯一原因。","verification":"若无排放时同样差异存在，单次比较不能归因。","pitfall":"把空间相关直接写成唯一因果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]}],"practice":[{"q":"生物累积与生物放大是否同义？","given":"比较不同层次。","analysis":"一个体内时间变化与营养级比较不同。","method":"分别定义。","principle":"浓度的比较轴决定概念。","steps":["累积可指个体吸收超过排出。","放大比较较高营养级的浓度升高。"],"ans":"不同。","verification":"个体可累积某物而未见食物链逐级放大。","pitfall":"看到污染物就套同一术语。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]},{"q":"两片保护林总面积相同，物种保护效果必相同吗？","given":"一片连续，一片分为隔离小斑块。","analysis":"面积不能代替连接性和边缘效应。","method":"比较迁移与小种群风险。","principle":"破碎化影响生态过程。","steps":["隔离限制迁移与基因流。","边缘比例和局部灭绝后的恢复也可不同。"],"ans":"不必相同。","verification":"空间布局即使面积相同仍不同。","pitfall":"只比较面积一项。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]},{"q":"某地一天异常寒冷，能据此否定全球长期变暖趋势吗？","given":"短时局地天气。","analysis":"时空尺度不同。","method":"区分天气与气候统计。","principle":"长期趋势需要长时序广域数据。","steps":["单日波动可与长期趋势并存。","应看多年温度及其他指标，而非挑单一天。"],"ans":"不能。","verification":"上升趋势的数据仍可包含低于均值的点。","pitfall":"用单点代替趋势。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]},{"q":"一污染物从0.04升到0.10 mg/kg，增加百分之几？这能证明存在营养级放大吗？","given":"同类样品两次测量，无营养级资料。","analysis":"数值增加不自动给出食物链机制。","method":"先算变化再审查概念。","principle":"相对增加除原值。","steps":["(0.10−0.04)/0.04=1.5=150%。","缺不同营养级与食物关系，不能据此证明放大。"],"ans":"增加150%；不能单据此证明生物放大。","verification":"新值为原来2.5倍，与增加1.5倍区别。","pitfall":"把时间增长当作营养级放大。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]}],"quiz":{"q":"所有外来物种都应直接称为入侵物种吗？","given":"仅知并非原产。","analysis":"来源与造成危害是不同条件。","method":"核是否建立扩散及产生影响。","principle":"外来是来源属性，入侵还涉及建立扩散等及危害。","steps":["有些外来种未建立。","已建立也需评价扩散和实际危害，不能只按来源下结论。"],"ans":"不能一概称入侵。","verification":"概念能区分风险监测与已发生影响。","pitfall":"将外来与入侵无条件等同。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]},"exam":["环境机制题写输入、过程、后果及限制，避免口号","食物链数据统一浓度基准，区分倍数与增加率","归因题提出替代解释、对照与重复，不只写加强环保"],"quick":["土地利用","营养与耗氧","污染物浓度","气候尺度","入侵与过度利用"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_11.1","url":"https://openstax.org/books/biology-2e/pages/47-3-threats-to-biodiversity","page_or_section":"47-3-threats-to-biodiversity","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_11.1","url":"https://openstax.org/books/biology-2e/pages/47-3-threats-to-biodiversity","page_or_section":"47-3-threats-to-biodiversity","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"环境机制题写输入、过程、后果及限制，避免口号","method":"列重复、参照与机制检测。","principle":"因果需时间与空间可比证据。","worked_example_index":2,"verification":"若无排放时同样差异存在，单次比较不能归因。","pitfall":"把空间相关直接写成唯一因果。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用机制解释人类活动的生态后果”的抽样复核：若只是肥料直接结合氧，不能解释有机物分解的延迟。；若出现“只写藻类多所以氧少，不说过程。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“评估环境数据的因果边界”的抽样复核：若无排放时同样差异存在，单次比较不能归因。；若出现“把空间相关直接写成唯一因果。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"将外来与入侵无条件等同。","correction":"不能一概称入侵。","verification":"概念能区分风险监测与已发生影响。"}],"illustration_spec":{"title":"富营养化因果链与浓度比较","objects":["营养径流","藻类","死亡有机物","分解者","溶氧曲线","三营养级"],"relations":["耗氧连到呼吸和分解而非肥料直接吸氧","食物链放大用相同mg/kg"],"labels":["营养输入","分解耗氧","条件性缺氧","浓度≠总量"],"format":"SVG","priority":"P0","reuse":"V22生态图局部可复用但需新增机制","english":"Show nutrient enrichment, algal growth, organic matter decomposition and conditional oxygen depletion. Use a separate food-chain panel with consistent mg/kg concentration units; do not equate concentration with total mass."}},"11.2":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":11,"section_id":"11.2","goals":["比较就地与迁地保护的作用","依据目标设计保育监测和权衡"],"prerequisites":["种群与群落","遗传多样性"],"flow":["保护层次","就地","迁地","恢复与连接","监测调整"],"concept_relation":"保护层次；就地；迁地；恢复与连接；监测调整","deep":["小种群可能经历遗传漂变、近交和随机事件风险，维持有效基因交流有助于保留适应潜力。廊道有时能促进迁移，也可能带来疾病、入侵或人为干扰；“任何走廊都必定好”忽略了对象、尺度与风险。","生态恢复以修复结构、功能或过程为目标，不能只比较种了多少棵树。单一快速生长树种的人工林未必等同原生群落。评价应包括本地物种建立、自然更新、土壤水文和其他生物返回，并注意时间尺度。","保育方案往往需要与当地居民共同决策，分析生计、资源使用、成本和受益分配。忽略社会条件可能让纸面保护失败。伦理判断要把价值选择与可实测的生态结论分开，不以一句“科学证明必须这样”代替讨论。","监测采用实施前后及参照区域的比较，比仅报告处理后数量更能识别效果；仍需注意参照是否可比。明确成功标准、时间安排与可调整措施，才能在数据不支持时修正方案，而不是把任何投入都宣告为成功。"],"derive":["多样性至少分遗传、物种、生态系统三个层次，指标之间不可互相完全替代。","简化前后—参照比较：措施区变化−参照区变化，可帮助扣除共同趋势，但依赖参照可比等假设。","保育决策链：明确对象与威胁 → 选措施 → 定可测指标与时间 → 监测 → 调整。"],"examples":[{"q":"把濒危植物种子放进种子库，属于就地还是迁地保护？是否已替代原生境？","given":"保存于原生境以外。","analysis":"方法分类与完整效果不同。","method":"按地点分类再评局限。","principle":"迁地保存资源不等于维持整个生态系统。","steps":["种子库属迁地保护。","还需保护授粉者、生境及自然更新等过程。"],"ans":"迁地；不能完全替代原生境。","verification":"原生境消失时即使有种子仍缺恢复条件。","pitfall":"把保存一种遗传材料说成保全生态系统。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]},{"q":"措施区数量由100到140，参照区100到120，简化扣除共同趋势的变化是多少？","given":"同一时段，可比性为工作假设。","analysis":"原始增长40含背景共同变化。","method":"比较两地前后差。","principle":"差中之差用于帮助控制共同趋势。","steps":["措施区变化40。","参照区变化20，差为40−20=20。"],"ans":"约多增加20个，不能忽略假设。","verification":"若两区共同都增20，措施区额外部分为20。","pitfall":"把全部40都归功措施。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]},{"q":"恢复项目种下一万棵单一树种就宣布生态系统恢复成功，如何评价？","given":"没有本地物种、存活和功能资料。","analysis":"投入数量与结果不同。","method":"提出结构、功能和长期监测指标。","principle":"生态恢复需评价过程与系统。","steps":["调查存活、自然更新与本地物种组成。","比较土壤水文和其他生物恢复，并设参照与长期追踪。"],"ans":"证据不足，不能只凭种植数量判成功。","verification":"全部树死亡或成为单一林都可能不满足目标。","pitfall":"把植树投入当作完整生态结果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]}],"practice":[{"q":"保护物种数不变，是否遗传多样性必不变？","given":"只给物种层指标。","analysis":"层次不同。","method":"考虑同种内部等位基因变化。","principle":"遗传多样性存在于种群内及之间。","steps":["每种仍在但种群可缩小。","等位基因可能丢失，即物种数不变仍有遗传损失。"],"ans":"不一定。","verification":"小种群漂变提供合理机制。","pitfall":"以物种计数替代全部多样性。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]},{"q":"生态廊道是否永远没有代价？","given":"问无条件优点。","analysis":"连接也可能传播不利因素。","method":"比较迁移收益与风险。","principle":"方案须与对象及空间尺度匹配。","steps":["可提高基因交流。","也可能促成疾病或入侵扩散，需评估监测。"],"ans":"并非没有代价。","verification":"同一连接能运输本地生物和不利因素。","pitfall":"只写好处不检验对象。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]},{"q":"在原生森林设保护区属于哪类保护？为何不能只设牌？","given":"保护在自然生境。","analysis":"类别不等于执行效果。","method":"分类并列管理条件。","principle":"就地保护需有效管理威胁。","steps":["属就地保护。","仍需处理盗猎、周边破碎化与资源等。"],"ans":"就地；需要持续管理。","verification":"没有执法或威胁控制可能仍下降。","pitfall":"以名义面积等同效果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]},{"q":"实施前两区各50，措施后75、参照后65，额外变化多少？若参照另遭洪灾，解释有什么问题？","given":"先按可比假设计算，再审查冲击。","analysis":"计算与因果效力需分开。","method":"作差后检查共同趋势假设。","principle":"独特冲击削弱参照可比。","steps":["(75−50)−(65−50)=10。","若参照受独有洪灾，差10可能混入灾害效应。"],"ans":"算得10，但因果解释受限。","verification":"同一数学结果并不保证方案效应。","pitfall":"把统计运算当作自动消除所有混杂。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]}],"quiz":{"q":"保育繁殖个体数量增加，是否足以证明已维持原野种群的全部遗传代表性？","given":"仅有数量，无亲本构成。","analysis":"数量与遗传代表性不同。","method":"核亲本来源及繁殖贡献。","principle":"少数亲本大量繁殖可使总数多而多样性低。","steps":["调查参与繁殖的个体与谱系。","检测遗传多样性并与原野种群比较。"],"ans":"不足以证明。","verification":"100个后代若来自极少亲本可缺很多原有变异。","pitfall":"把个体多等同有效遗传多样性高。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]},"exam":["方案题按威胁选措施，写机制、指标、限制和调整","比较题分别说明就地生态关系与迁地备份作用","评价题区分投入、产出与长期成效，给可测监测设计"],"quick":["保护层次","就地","迁地","恢复与连接","监测调整"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_11.2","url":"https://openstax.org/books/biology-2e/pages/47-4-preserving-biodiversity","page_or_section":"47-4-preserving-biodiversity","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_11.2","url":"https://openstax.org/books/biology-2e/pages/47-4-preserving-biodiversity","page_or_section":"47-4-preserving-biodiversity","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"方案题按威胁选措施，写机制、指标、限制和调整","method":"提出结构、功能和长期监测指标。","principle":"生态恢复需评价过程与系统。","worked_example_index":2,"verification":"全部树死亡或成为单一林都可能不满足目标。","pitfall":"把植树投入当作完整生态结果。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“比较就地与迁地保护的作用”的抽样复核：原生境消失时即使有种子仍缺恢复条件。；若出现“把保存一种遗传材料说成保全生态系统。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“依据目标设计保育监测和权衡”的抽样复核：全部树死亡或成为单一林都可能不满足目标。；若出现“把植树投入当作完整生态结果。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把个体多等同有效遗传多样性高。","correction":"不足以证明。","verification":"100个后代若来自极少亲本可缺很多原有变异。"}],"illustration_spec":{"title":"保育措施与评价矩阵","objects":["就地生境","种子库","恢复地","廊道","监测指标"],"relations":["就地与迁地互补而非等价","廊道有收益与风险","投入与成效分开"],"labels":["遗传","物种","生态系统","前后与参照","长期监测"],"format":"SVG","priority":"P1","reuse":"未有完整对应图","english":"Compare in-situ habitat protection, ex-situ seed banking and restoration. Link each measure to a specific threat and measurable outcome, with benefits and limitations; do not present corridors as universally risk-free."}},"11.3":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":11,"section_id":"11.3","goals":["按系统边界比较减排方案","区分碳流、能流与可持续性指标"],"prerequisites":["碳循环","能量守恒与比例"],"flow":["确定服务与边界","活动量×因子","比较基线","材料再用","长期监测"],"concept_relation":"确定服务与边界；活动量×因子；比较基线；材料再用；长期监测","deep":["节能减少为达到同样服务所需的能量，能源替代改变能量来源，二者可互补。能量不会在生态系统像碳一样循环而反复完全利用：能量转换中可用能量逐步分散为热；“循环经济”主要讨论材料和产品利用，不能据名称否定能量流的方向。","减少、重复使用和回收有不同作用。回收可降低部分原生材料需求，但收集、运输、分选和再加工仍需能量，并非所有材料都可无限无损循环。减少不必要消费和延长寿命可避免上游负担，具体结果仍取决替代与使用方式。","碳汇吸收并储存碳，但储存持续性、土地利用变化与火灾等风险须纳入。新种树吸收碳需要时间，不能在没有数量和时间对照时宣称一次植树立即抵销任何排放；同时要顾及生物多样性、水资源和当地需求。","行动评估可从可测基线出发，记录活动量和因子，估计不确定性并追踪实际结果。个人选择、学校设施、产业与公共政策共同影响结果；教学讨论应提出有机制和证据的方案，而不是将系统性问题归结为单一个人的道德标签。"],"derive":["估计排放E=活动量A×排放因子f；多来源时E总=ΣAᵢfᵢ，单位必须相消。","减排率=(基线排放−方案排放)/基线排放；相同服务量与同一系统边界是可比前提。","碳收支与能量收支分别追踪：碳可在库间循环，能量转换后向环境分散，不能画成完全闭合能量循环。"],"examples":[{"q":"学校用电1000 kWh，题设因子0.6 kg CO₂e/kWh，估计多少排放？","given":"只计题设电力环节，不代表实际地区因子。","analysis":"活动量与单位因子相乘。","method":"E=Af并核单位。","principle":"同一边界下的排放估算。","steps":["1000×0.6=600。","kWh相消，余kg CO₂e。"],"ans":"600 kg CO₂e。","verification":"每100 kWh为60 kg，十份为600。","pitfall":"将kg误写为kWh。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]},{"q":"相同服务的基线排放800 kg，方案排放600 kg，减排率多少？","given":"系统边界一致。","analysis":"求减少量相对基线。","method":"(E₀−E₁)/E₀。","principle":"百分比以基线为分母。","steps":["减少800−600=200 kg。","200/800=0.25=25%。"],"ans":"25%。","verification":"新排放是原来75%，与减少25%互补。","pitfall":"除以600得到不同指标。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]},{"q":"设备甲使用端0排放、制造500 kg；乙制造100 kg且每年使用排100 kg。只用1年能说甲全周期更低吗？","given":"忽略其他环节且功能相同。","analysis":"使用端优势可能被制造负担抵销。","method":"按相同寿命求总量并给边界。","principle":"生命周期比较需累计各环节。","steps":["一年甲500，乙100+100=200 kg。","在此简化一年边界甲较高；若使用更久，结果可能改变。"],"ans":"不能；题设一年甲更高。","verification":"五年时两者分别500与600，说明时间改变结论。","pitfall":"只看使用端零排放。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]}],"practice":[{"q":"把所有材料回收，是否意味着不再消耗能量？","given":"讨论回收处理。","analysis":"材料循环与能量流不同。","method":"列分选运输再加工。","principle":"过程仍需能量并产生分散热。","steps":["回收运输和处理需要能量。","即使材料再用，也不能使能量完全循环。"],"ans":"不意味着。","verification":"符合能量守恒并伴可用能量分散。","pitfall":"把循环经济当作永动循环。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]},{"q":"公共交通每人公里40 g，单人驾车150 g，走10人公里各多少？","given":"题设因子与人数边界一致。","analysis":"先统一服务量。","method":"因子乘人公里。","principle":"相同服务下可比较排放。","steps":["公交40×10=400 g。","单人驾车150×10=1500 g。"],"ans":"400 g与1500 g，差1100 g。","verification":"10倍各自单位因子，单位相消正确。","pitfall":"将车辆公里与人公里混用。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]},{"q":"种下一棵树即可立即抵销一次任意排放，这句话缺什么？","given":"未给树种、增长和排放量。","analysis":"吸收是随时间发生且有风险的过程。","method":"要求数量时间与持续性。","principle":"收支必须同单位同边界比较。","steps":["明确排放总量和时点。","估计树的净吸收、时间及存活与储存风险，不能说任意抵销。"],"ans":"缺数量、时间及持续性等证据。","verification":"刚栽种时尚无所声称的未来累计吸收。","pitfall":"把未来潜力当立即已实现。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]},{"q":"基线用电2000 kWh，节能后1500，因子0.5 kg/kWh不变，排放各多少、减排率多少？","given":"比较同样服务，题设因子不变。","analysis":"活动量变化传到排放。","method":"分别估算再求减少率。","principle":"E=Af。","steps":["基线1000 kg，方案750 kg。","减少250/1000=25%。"],"ans":"1000与750 kg，减25%。","verification":"用电也减500/2000=25%，因子固定时比例一致。","pitfall":"认为减500 kWh就是减500 kg。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]}],"quiz":{"q":"“电动设备使用端无燃烧，因此全生命周期温室气体排放为零”，哪一步不成立？","given":"仅知使用端没有燃烧。","analysis":"局部边界不能推出全生命周期。","method":"补发电制造与处置等环节。","principle":"总排放含边界内各环节。","steps":["使用端无燃烧可降低该环节直接排放。","仍需计电源和制造等，且地区因子不一。"],"ans":"从一个环节零排放跳到全部环节零排放。","verification":"完整边界求和后才可评价总量。","pitfall":"把间接排放漏出边界。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]},"exam":["估算题先写功能单位、边界、因子和单位","方案比较说明使用年限与上游排放，不只用绿色标签","议论题同时评价排放、生态与社会影响，并给可跟踪指标"],"quick":["确定服务与边界","活动量×因子","比较基线","材料再用","长期监测"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_11.3","url":"https://openstax.org/books/biology-2e/pages/46-3-biogeochemical-cycles","page_or_section":"46-3-biogeochemical-cycles","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_11.3","url":"https://openstax.org/books/biology-2e/pages/46-3-biogeochemical-cycles","page_or_section":"46-3-biogeochemical-cycles","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"估算题先写功能单位、边界、因子和单位","method":"按相同寿命求总量并给边界。","principle":"生命周期比较需累计各环节。","worked_example_index":2,"verification":"五年时两者分别500与600，说明时间改变结论。","pitfall":"只看使用端零排放。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“按系统边界比较减排方案”的抽样复核：五年时两者分别500与600，说明时间改变结论。；若出现“只看使用端零排放。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"p0","review_module":7,"feedback":"目标“区分碳流、能流与可持续性指标”的抽样复核：符合能量守恒并伴可用能量分散。；若出现“把循环经济当作永动循环。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把间接排放漏出边界。","correction":"从一个环节零排放跳到全部环节零排放。","verification":"完整边界求和后才可评价总量。"}],"illustration_spec":{"title":"低碳方案的系统边界","objects":["原料制造","运输","能源生产","使用","处置回收","碳汇"],"relations":["各环节排放累加","相同服务与年限比较","碳汇标时间和不确定性"],"labels":["kg CO₂e","功能单位","直接/间接","活动量×因子","非通用因子"],"format":"SVG","priority":"P1","reuse":"V22碳循环可作原理背景，非足够全生命周期图","english":"Draw a lifecycle boundary including raw materials, manufacture, energy supply, transport, use and end of life. Compare equal services over equal lifetimes using explicitly hypothetical emission factors. Mark carbon-sink storage time and uncertainty."}}},"生物13":{"13.1":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":13,"section_id":"13.1","goals":["按着丝粒与DNA分子分别计数","解释阶段变化和检查点作用"],"prerequisites":["DNA复制","同源与姐妹的区别"],"flow":["S期复制","中期姐妹相连","后期姐妹分开","胞质分配","检查点控制"],"concept_relation":"S期复制；中期姐妹相连；后期姐妹分开；胞质分配；检查点控制","deep":["后期姐妹染色单体分开成为独立子染色体，在一个尚未分开的细胞内，着丝粒计数会暂时加倍。这不是DNA再次复制。末期两套染色体到达两极并重建细胞核；胞质分裂可与后期、末期重叠，核分裂和胞质分裂不能当作完全相同的事件。","动物细胞常以收缩环形成分裂沟，植物通常在中央形成细胞板并向外扩展。植物有细胞壁，不能套用动物向内缢裂的图。标准有丝分裂把复制产物分别给两个子细胞，使染色体数通常保持；突变或分离错误须另作分析。","检查点是根据DNA状态、复制完成情况和纺锤体连接等信息调控周期的关口。药物处理后中期细胞比例增大，可能因为该阶段停留延长；不能仅凭比例证明增殖更快，更不能自动把药物称为致癌物。","显微图判断先看染色体是否凝缩、排列或向两极分开，再用计数辅助。压片、染色、观察视野和取样组织都会影响结果。根尖分生组织适合观察，成熟伸长区不能仅因细胞更大就视为更合适。"],"derive":["未复制二倍体为2n条、2C；S期后为2n条、4C，每条有两条姐妹。","后期全细胞为4n条子染色体、DNA总量仍4C；每极得到2n条、2C。n与C分别描述套数和DNA量，不可互换。","分裂指数=分裂期细胞数/总观察细胞数。只有随机取样、近似稳态等条件下，阶段比例才可辅助估计相对停留时间。"],"examples":[{"q":"2n=6的正常细胞完成S期并进入中期，有几条染色体、几个核DNA分子？","given":"复制完成，姐妹未分离。","analysis":"两种数量的计数单位不同。","method":"分别数着丝粒与染色单体。","principle":"复制增加DNA而不立即增加着丝粒单位。","steps":["复制前6条、6个DNA分子。","复制后仍6条染色体，共12条姐妹染色单体，各含1个DNA分子。"],"ans":"6条、12个。","verification":"DNA从2C到4C，染色体仍2n。","pitfall":"把复制直接当成染色体数加倍。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]},{"q":"同一2n=6细胞到后期但胞质未分开，全细胞和每一极各有几条染色体？","given":"正常分离且无丢失。","analysis":"必须先区分整细胞与单极。","method":"计分离后的着丝粒，再分配。","principle":"姐妹分离后成为独立子染色体，DNA没有再复制。","steps":["全细胞有12条。","每极6条；总DNA仍12个，每极6个。"],"ans":"全细胞12，每极6。","verification":"两极6+6=12，最终子细胞各回到2n=6。","pitfall":"把每极结果当成整个细胞结果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]},{"q":"对照1000细胞中100个分裂，处理组1000中250个分裂且多数停中期，能否证明增殖更快？","given":"两组同样取样，但未追踪周期完成时间。","analysis":"比例增大也可能是中期阻滞。","method":"计算指数，再列区分解释所需证据。","principle":"阶段占比由进入及离开该阶段共同决定。","steps":["指数分别10%和25%。","中期积累可能是检查点阻滞。","追踪完成分裂时间、活细胞总量及死亡率，才能判断净增殖。"],"ans":"不能，已知的是分裂期占比上升。","verification":"完全阻滞时指数可很高而新子细胞几乎不增加。","pitfall":"把横截面比例当成单位时间分裂次数。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]}],"practice":[{"q":"正常S期染色体数是否随DNA量一起加倍？","given":"尚未发生姐妹分离。","analysis":"复制和分离不同。","method":"分别描述计数规则。","principle":"染色体按着丝粒单位计。","steps":["DNA逐渐增加。","S期完成仍2n，到姐妹分离才改变全细胞计数。"],"ans":"不会随之加倍。","verification":"与中期2n、4C一致。","pitfall":"数线条而不数着丝粒。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]},{"q":"显微图见染色体分成两极，是否必为减数分裂？","given":"只给两极形态。","analysis":"有丝后期也有两极。","method":"结合配对、数目及分离对象判断。","principle":"分姐妹与分同源是不同事件。","steps":["寻找同源配对等证据。","再判断分开的是同源还是姐妹。"],"ans":"不能仅据两极判断。","verification":"分姐妹可见于有丝后期或减Ⅱ后期。","pitfall":"只凭两极贴标签。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]},{"q":"植物胞质分裂形成的是赤道板还是细胞板？","given":"问真实物质结构。","analysis":"几何平面与新结构不同。","method":"按时期及功能区分。","principle":"赤道板是中期排列平面，细胞板参与分隔。","steps":["中期染色体在赤道板排列。","胞质分裂形成细胞板并参与新细胞壁。"],"ans":"细胞板。","verification":"两者物质性质与出现阶段不同。","pitfall":"名字相近便认为相同。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]},{"q":"200细胞中前期12、中期6、后期2、末期4，求分裂指数并写一项限制。","given":"分类不重叠。","analysis":"分母须包括间期细胞。","method":"相加分裂数再除总数。","principle":"指数是比例，不直接给绝对增殖速率。","steps":["分裂数=12+6+2+4=24。","24/200=12%；取样是否随机、周期是否稳态限制解释。"],"ans":"12%；不能单凭此算每小时增殖数。","verification":"24+176=200。","pitfall":"只用分裂细胞作分母。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]}],"quiz":{"q":"2n=8细胞后期全细胞有16条子染色体，是否说明多复制了一次DNA？","given":"胞质未分开。","analysis":"计数变化来自姐妹分离。","method":"比较中期和后期DNA总量。","principle":"后期不是S期。","steps":["中期8条复制染色体含16个DNA。","后期16条子染色体仍含16个DNA。"],"ans":"不是，DNA总量未再增加。","verification":"最终两子细胞各8个DNA，总量守恒。","pitfall":"把染色体计数改变当成复制证据。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]},"exam":["计数题先写单核、全细胞、每极或子细胞，再列时期","图像题先辨分开的结构，再用数目辅助，不用线多就猜阶段","药物题区分观察比例与因果结论，提出追踪周期及对照"],"quick":["S期复制","中期姐妹相连","后期姐妹分开","胞质分配","检查点控制"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_13.1","url":"https://openstax.org/books/biology-2e/pages/10-2-the-cell-cycle","page_or_section":"10-2-the-cell-cycle","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_13.1","url":"https://openstax.org/books/biology-2e/pages/10-2-the-cell-cycle","page_or_section":"10-2-the-cell-cycle","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"计数题先写单核、全细胞、每极或子细胞，再列时期","method":"计算指数，再列区分解释所需证据。","principle":"阶段占比由进入及离开该阶段共同决定。","worked_example_index":2,"verification":"完全阻滞时指数可很高而新子细胞几乎不增加。","pitfall":"把横截面比例当成单位时间分裂次数。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按着丝粒与DNA分子分别计数”的抽样复核：DNA从2C到4C，染色体仍2n。；若出现“把复制直接当成染色体数加倍。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“解释阶段变化和检查点作用”的抽样复核：完全阻滞时指数可很高而新子细胞几乎不增加。；若出现“把横截面比例当成单位时间分裂次数。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把染色体计数改变当成复制证据。","correction":"不是，DNA总量未再增加。","verification":"最终两子细胞各8个DNA，总量守恒。"}],"illustration_spec":{"title":"有丝分裂计数与胞质分裂","objects":["2n=4复制前后","中期","后期全细胞/每极","分裂沟","细胞板"],"relations":["复制后DNA加倍但染色体数不变","后期DNA总量守恒","植物不画分裂沟"],"labels":["2n","2C","4C","着丝粒","姐妹","细胞板"],"format":"SVG","priority":"P0","reuse":"V22 B42计数图可复用，胞质分裂需另图","english":"Track chromosome and DNA counts in a 2n=4 mitosis model. Separate whole-cell anaphase from each pole and compare animal cleavage furrow with plant cell plate."}},"13.2":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":13,"section_id":"13.2","goals":["辨认两次分裂的分离对象","用染色体行为解释遗传变异"],"prerequisites":["有丝分裂","同源染色体与等位基因"],"flow":["一次复制","减Ⅰ分同源","减Ⅱ分姐妹","交换与独立取向","受精恢复组数"],"concept_relation":"一次复制；减Ⅰ分同源；减Ⅱ分姐妹；交换与独立取向；受精恢复组数","deep":["以2n=4的模型追踪：复制前2n、2C；复制后2n、4C；减Ⅰ完成后各细胞n、2C；减Ⅱ完成后各细胞n、1C。观察全细胞时后期的计数须另注明范围，不能把最终配子数目直接套到尚未胞质分裂的后期细胞。","同源对在中期Ⅰ的独立取向，使不同对的父母来源可有不同组合。在忽略交换且正常独立分配时，n对同源可形成2的n次方种来源组合；这不是单次减数分裂一定同时得到的不同配子数，也不是含交换时的全部基因型上限。","交换可重新组合一条染色体上的等位基因组合，随机受精再增加后代组合。正常减数分裂解释重组与分离，不负责创造所有新等位基因；新等位基因通常需追溯突变。等位基因分离与染色体行为的关联还须限定正常分离及所处位置。","不分离可发生在第一次或第二次分裂，产生染色体数目异常的配子。分析图时先判断同源还是姐妹未分开，再分别追踪各个子细胞；只背诵“异常配子一半”会把不同阶段混淆。动物精子、卵的形成在胞质分配上不同，不能把四个产物一律画成四个同样功能的卵。"],"derive":["正常二倍体：2n、2C → DNA复制 → 2n、4C → 减Ⅰ → n、2C → 减Ⅱ → n、1C。","无交换的来源组合数为2ⁿ，n是同源染色体对数；这是多次减数分裂可能产生的来源组合。","若n=2，第一次分裂某对不分离，最终四个产物对该染色体的拷贝数为2、2、0、0，而正常应各为1。"],"examples":[{"q":"某生物2n=8，正常减Ⅰ完成后每个细胞有几条染色体和几个DNA分子？","given":"DNA复制完成且正常同源分离。","analysis":"减Ⅰ分同源而不分姐妹。","method":"先减半染色体数，再按每条两条姐妹计DNA。","principle":"减Ⅰ后为n、2C。","steps":["n=4，每细胞4条染色体。","每条仍含两条姐妹，核DNA分子为8个。"],"ans":"4条、8个DNA分子。","verification":"减Ⅱ后每个配子4个DNA分子，进一步减半而染色体数仍4。","pitfall":"减Ⅰ后直接把DNA也算成4个。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]},{"q":"2n=6，不计交换，配子染色体父母来源最多有多少组合？一次减数分裂会出现全部组合吗？","given":"三对同源正常独立取向。","analysis":"理论可能性与一次分裂产物数量不同。","method":"用2ⁿ并检查一次产物。","principle":"各对有两种来源选择。","steps":["n=3，2³=8。","一次减数分裂通常形成四个产物，忽略交换时不能同时给出8种组合。"],"ans":"可能8种；一次不会同时出现全部。","verification":"一细胞四个产物的数量小于8。","pitfall":"把群体概率空间当作一次分裂的实际结果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]},{"q":"一次减数分裂中某对同源在减Ⅰ未分离，减Ⅱ正常，该染色体在四个配子中的数目怎样？","given":"不考虑其他染色体，正常每配子应有1条。","analysis":"异常在同源分配的第一步。","method":"画两次分配树。","principle":"同源一起进一侧，随后姐妹各自正常分离。","steps":["减Ⅰ两细胞对该类染色体分别有2条复制染色体和0条。","减Ⅱ后前者给出两个各含2条的配子，后者给出两个0条配子。"],"ans":"2、2、0、0；均对该类数目异常。","verification":"四产物拷贝总数4，与复制后总量一致。","pitfall":"套用减Ⅱ不分离的2、0、1、1。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]}],"practice":[{"q":"减Ⅱ前是否要再次复制全部核DNA？","given":"正常减数分裂。","analysis":"一次复制服务于两次分裂。","method":"比较减Ⅰ与减Ⅱ之间DNA量。","principle":"减Ⅰ后染色体仍含姐妹。","steps":["减Ⅰ后为n、2C。","减Ⅱ分姐妹后为n、1C，无需再S期复制。"],"ans":"一般不再复制。","verification":"若再复制，最终DNA量不能按正常过程降至1C。","pitfall":"把每次分裂都配一个S期。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]},{"q":"同源染色体交换发生在姐妹还是非姐妹之间？","given":"问正常减Ⅰ前期的交换。","analysis":"同源与姐妹是不同分类。","method":"按参与者来源作答。","principle":"交换涉及联会的同源染色体。","steps":["辨认父母来源同源。","交换位于其中非姐妹染色单体之间。"],"ans":"同源染色体的非姐妹染色单体。","verification":"复制后的同一条姐妹交换不能解释父母来源重组模型。","pitfall":"把联会的两条线都叫姐妹。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]},{"q":"细胞2n=4，减Ⅱ后每产物的核DNA分子数？","given":"正常分离，无突变。","analysis":"最终每条染色体不再有两条姐妹。","method":"求n再按单染色单体计。","principle":"减Ⅱ后n、1C。","steps":["n=2。","每个产物2条染色体、2个核DNA分子。"],"ans":"2个。","verification":"四产物合计8个，等于S期后8个。","pitfall":"继续乘2把姐妹算进去。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]},{"q":"某一减Ⅱ细胞的某条染色体姐妹不分离，另一减Ⅱ细胞正常，四个配子该染色体拷贝数？","given":"减Ⅰ正常，减Ⅱ只有一侧异常。","analysis":"两个减Ⅱ细胞须分别追踪。","method":"列异常侧与正常侧的产物。","principle":"异常侧给2与0，正常侧给1与1。","steps":["追踪异常侧得到2、0。","正常侧得到1、1，合计四个拷贝。"],"ans":"2、0、1、1。","verification":"与减Ⅰ不分离的2、2、0、0不同。","pitfall":"把两次分裂异常结果混为一谈。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]}],"quiz":{"q":"一幅图中同源已分开但姐妹仍相连，能说是有丝后期吗？","given":"图明确表示分离对象是同源。","analysis":"分离对象比“两极”形状更有辨识力。","method":"比较减Ⅰ和有丝后期。","principle":"有丝后期分姐妹；减Ⅰ后期分同源。","steps":["同源分开符合减Ⅰ后期。","姐妹仍连不符合正常有丝后期姐妹已分离的特征。"],"ans":"不能，应考虑减Ⅰ后期。","verification":"再检查配对与每极组数以支持判断。","pitfall":"见到两极就断定有丝后期。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]},"exam":["阶段图题先问分同源还是分姐妹，再数每个细胞","组合题写明是否忽略交换以及一次还是多次","异常分配题逐代画分配树，不背不加条件的比例"],"quick":["一次复制","减Ⅰ分同源","减Ⅱ分姐妹","交换与独立取向","受精恢复组数"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_13.2","url":"https://openstax.org/books/biology-2e/pages/11-1-the-process-of-meiosis","page_or_section":"11-1-the-process-of-meiosis","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_13.2","url":"https://openstax.org/books/biology-2e/pages/11-1-the-process-of-meiosis","page_or_section":"11-1-the-process-of-meiosis","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"阶段图题先问分同源还是分姐妹，再数每个细胞","method":"画两次分配树。","principle":"同源一起进一侧，随后姐妹各自正常分离。","worked_example_index":2,"verification":"四产物拷贝总数4，与复制后总量一致。","pitfall":"套用减Ⅱ不分离的2、0、1、1。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“辨认两次分裂的分离对象”的抽样复核：减Ⅱ后每个配子4个DNA分子，进一步减半而染色体数仍4。；若出现“减Ⅰ后直接把DNA也算成4个。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用染色体行为解释遗传变异”的抽样复核：四产物拷贝总数4，与复制后总量一致。；若出现“套用减Ⅱ不分离的2、0、1、1。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"见到两极就断定有丝后期。","correction":"不能，应考虑减Ⅰ后期。","verification":"再检查配对与每极组数以支持判断。"}],"illustration_spec":{"title":"减数分裂的分离对象与DNA量","objects":["两对同源染色体","联会与非姐妹交换","减Ⅰ","减Ⅱ","四个产物"],"relations":["只在分裂前复制一次","减Ⅰ同源分离","减Ⅱ姐妹分离"],"labels":["2n=4","4C","n=2","2C","1C"],"format":"SVG","priority":"P0","reuse":"可复核复用V22 B46、B56","english":"Show one DNA replication followed by homolog separation in meiosis I and sister separation in meiosis II. Use two homolog pairs and label DNA content per cell."}},"13.3":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":13,"section_id":"13.3","goals":["解释周期调控失常与肿瘤发展的关系","区分风险因素、相关性与诊断证据"],"prerequisites":["细胞周期与检查点","基因表达和突变"],"flow":["周期信号","损伤应答","异常克隆","侵袭与转移","证据边界"],"concept_relation":"周期信号；损伤应答；异常克隆；侵袭与转移；证据边界","deep":["良性与恶性肿瘤都可能是异常增殖形成的细胞团，但恶性肿瘤可侵袭周围组织并可能转移。转移包含局部侵袭、进入循环、在其他部位定植等环节；不能画成所有肿瘤细胞一出现就立即随血液扩散。某些癌症也不以明显实体肿块开始。","风险因素如烟草相关暴露、紫外线、某些病毒感染和遗传易感性，可经不同机制增加风险。病毒相关癌症不代表所有癌症都能直接传染；具有遗传易感变异也不等于癌症本身必然由亲代传给子代。必须区分体细胞突变与可遗传的生殖系变异。","实验研究可比较增殖、死亡、侵袭等指标，并设置对照、重复和适当浓度范围。体外细胞被一种物质杀死并不足以证明它是安全有效的治疗：正常细胞毒性、体内到达浓度与临床结局均未得到回答。教学实验结果应限定在观察条件内。","预防和早期发现的建议须依据可靠卫生指南，课堂模型不能用来个人诊断。治疗可能涉及手术、放疗、药物等并由专业团队按病种和个体状况决定；本节学习周期与证据判断，不把原创题中的比例解释成个体患病概率。"],"derive":["调控模型：促进生长的信号受调节 + 抑制与修复机制 → 协调细胞数量；多环节失调可能促成异常克隆扩增。","净细胞数量变化=新产生细胞数−死亡或离开系统的细胞数；分裂比例不是净增长率。","相对风险比较需要明确观察人数、事件数及可比条件，观察性相关不能单独证明某一分子机制。"],"examples":[{"q":"组织甲分裂细胞多，组织乙少，能仅据此断言甲是癌组织吗？","given":"仅有分裂比例，无侵袭、调控或病理证据。","analysis":"正常组织更新也可快。","method":"列可替代解释及需要的证据。","principle":"增殖是癌症相关行为之一，但不构成独立诊断。","steps":["甲可能处于生长或修复。","还需病理形态、持续失调和组织行为等专业证据。"],"ans":"不能。","verification":"正常根尖或胚胎的高分裂率也是反例。","pitfall":"把单一相关指标当作充分诊断条件。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]},{"q":"培养24小时内甲新生120细胞、死亡20；乙新生150、死亡80，哪组净增加更多？","given":"起始和观察条件可比，忽略迁入迁出。","analysis":"比较净变化不能只看新生数。","method":"分别作产生减死亡。","principle":"数量守恒。","steps":["甲净增120−20=100。","乙净增150−80=70。"],"ans":"甲净增加更多，差30。","verification":"甲虽新生少30，却死亡少60，净效应多30。","pitfall":"只按150>120判断。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]},{"q":"候选物使癌细胞存活率降至20%，正常细胞也降至18%，能称为已证实安全的抗癌药吗？","given":"只有单一体外条件，无体内或临床资料。","analysis":"杀伤不等于选择性与安全性。","method":"比较两类细胞并列证据缺口。","principle":"治疗评价需有效性、安全性及可达暴露。","steps":["两种细胞均受强烈损伤。","尚不能显示对癌细胞更有选择性。","需重复、剂量反应、体内与临床等进一步证据。"],"ans":"不能；只说明本实验条件下有细胞毒性。","verification":"正常细胞18%低于癌细胞20%，并不支持明显选择优势。","pitfall":"用体外杀细胞直接宣传治疗效果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]}],"practice":[{"q":"原癌基因在正常细胞中是否必定有害？","given":"问正常功能。","analysis":"名称不等于正常时已致癌。","method":"区分正常调控与异常激活。","principle":"正常生长需要相应信号通路。","steps":["正常原癌基因可参与受控生长。","异常激活才可能推动不受控过程。"],"ans":"不是。","verification":"没有正常生长调控同样不利组织功能。","pitfall":"把名称中的癌理解为存在就患癌。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]},{"q":"DNA受损后一定发生癌变吗？","given":"未给修复与细胞结局。","analysis":"损伤和稳定癌变之间有多个关口。","method":"列损伤应答。","principle":"修复、周期停滞与死亡可限制扩增。","steps":["损伤可被修复。","无法修复的细胞可能停滞或死亡，多变化积累才可能导致癌变。"],"ans":"不一定。","verification":"风险增加并非确定事件。","pitfall":"省略调控与选择过程。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]},{"q":"具有癌症易感性的家族，是否所有成员都会患同一种癌？","given":"有遗传易感信息而无个体诊断。","analysis":"易感是风险变化不是必然结果。","method":"结合其他遗传、环境与随机因素。","principle":"外显与发病受多因素影响。","steps":["同一易感变异可增加风险。","其他因素与防护使结局仍可不同。"],"ans":"不能推断所有成员必患。","verification":"风险不是100%的同义词。","pitfall":"把易感变异直接当作疾病已发生。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]},{"q":"甲培养组原有1000细胞，新生200、死亡150；乙原有1000，新生100、死亡10。比较末数量并解释为什么分裂多未必长得多。","given":"封闭体系，观察时间相同。","analysis":"需要计算净变化。","method":"原数加产生减死亡。","principle":"细胞总数守恒。","steps":["甲1000+200−150=1050。","乙1000+100−10=1090，比甲多40。"],"ans":"甲1050，乙1090；乙净增长更多。","verification":"甲净50，乙净90。","pitfall":"把分裂数和净增数等同。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]}],"quiz":{"q":"“癌细胞会转移，所以任何癌症都能通过接触患者传染。”这一推理错误在哪里？","given":"比较体内转移与个体间传播。","analysis":"两种过程所跨越的边界不同。","method":"定义后指出不能推出的结论。","principle":"转移指癌细胞在同一个体内扩散定植；感染性风险因素是另一问题。","steps":["先说明转移发生在体内组织间。","部分病毒可增加某些癌症风险，不等于癌细胞通过日常接触普遍传染。"],"ans":"把体内转移混同个体间传染。","verification":"能解释病毒相关性，也不错误推广所有癌症。","pitfall":"由一个词的扩散含义作无条件类推。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]},"exam":["判断题先分正常增殖、异常调控、侵袭与转移","实验题分别评价肿瘤细胞、正常细胞和对照，结论限定观察条件","风险题用可能性语言，不把相关性、易感与确诊混写"],"quick":["周期信号","损伤应答","异常克隆","侵袭与转移","证据边界"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_13.3","url":"https://openstax.org/books/biology-2e/pages/10-4-cancer-and-the-cell-cycle","page_or_section":"10-4-cancer-and-the-cell-cycle","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_13.3","url":"https://openstax.org/books/biology-2e/pages/10-4-cancer-and-the-cell-cycle","page_or_section":"10-4-cancer-and-the-cell-cycle","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"判断题先分正常增殖、异常调控、侵袭与转移","method":"比较两类细胞并列证据缺口。","principle":"治疗评价需有效性、安全性及可达暴露。","worked_example_index":2,"verification":"正常细胞18%低于癌细胞20%，并不支持明显选择优势。","pitfall":"用体外杀细胞直接宣传治疗效果。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“解释周期调控失常与肿瘤发展的关系”的抽样复核：正常根尖或胚胎的高分裂率也是反例。；若出现“把单一相关指标当作充分诊断条件。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“区分风险因素、相关性与诊断证据”的抽样复核：正常细胞18%低于癌细胞20%，并不支持明显选择优势。；若出现“用体外杀细胞直接宣传治疗效果。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"由一个词的扩散含义作无条件类推。","correction":"把体内转移混同个体间传染。","verification":"能解释病毒相关性，也不错误推广所有癌症。"}],"illustration_spec":{"title":"周期调控失常与证据边界","objects":["正常生长信号","检查点","损伤修复","异常克隆","局部侵袭","转移"],"relations":["损伤不必然癌变","多环节失调增加异常扩增可能","转移为同一个体内过程"],"labels":["正常调控","修复/停滞/死亡","异常扩增","证据不足不能诊断"],"format":"SVG","priority":"P1","reuse":"无完全匹配旧图","english":"Compare regulated growth with a multistep loss of control. Show repair, arrest and cell death as alternative responses to DNA damage; distinguish local invasion from metastasis within one individual."}}},"生物18":{"18.1":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":18,"section_id":"18.1","goals":["由结构推断细菌的生命活动","区分原核结构与真核细胞器"],"prerequisites":["细胞膜与核糖体","扩散与渗透"],"flow":["细胞膜","拟核与质粒","核糖体","细胞壁差异","附属结构"],"concept_relation":"细胞膜；拟核与质粒；核糖体；细胞壁差异；附属结构","deep":["部分细菌有荚膜或其他糖被，可影响附着、抗干燥与宿主相互作用；部分有菌毛或鞭毛，功能取决于具体结构。菌毛不等于所有鞭毛的简称，附着结构也不能一概解释成游动器官。结构图应标明“典型模型、部分结构并非每种都有”。","主染色体之外，部分细菌还有能独立复制的质粒。质粒可携带抗性等基因，但不能说所有抗性都在质粒上，或细菌没有质粒就无法生存。二分裂复制并分配遗传物质，不经过真核有丝分裂的纺锤体阶段。","细胞体积小带来较大的表面积体积比，有利于物质交换，但生长速率仍受营养、温度、氧等多因素限制。用球菌、杆菌、螺旋形等形态可作初步描述，不能只凭外形确定致病性或具体物种。","观察图像先区分边界层，再辨认DNA、核糖体和附属结构。光学显微镜和电子显微镜分辨能力不同，一张简单染色光学照片不能支持“已看见质粒双链”之类精细结论。图示放大比例也不能当作各结构在真实细胞中精确的大小比例。"],"derive":["球形模型表面积A=4πr²、体积V=4πr³/3，所以A/V=3/r；半径减半，表面积体积比加倍。","细菌能量代谢的论证应从膜、酶和反应途径出发，不能由“无粒线体”推出“无ATP”。","结构识别须区分必备的细胞膜、核糖体等与部分细菌才有的质粒、荚膜和鞭毛。"],"examples":[{"q":"某细胞无核膜，有细胞膜、拟核和核糖体，是否能因无细胞核而判它不是细胞？","given":"观察到膜、DNA集中区和核糖体。","analysis":"核膜有无用于区分原核与真核，不用于否定细胞性。","method":"依次检查细胞组织特征。","principle":"原核细胞不具有膜包围的细胞核。","steps":["拟核说明有遗传物质区域。","膜与核糖体符合细胞结构，可考虑原核细胞。"],"ans":"不能；这些特征支持原核细胞。","verification":"病毒本身没有这样的核糖体和完整细胞质体系。","pitfall":"将无核膜误写为无DNA。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]},{"q":"两个近似球形细菌半径为0.5 μm和1 μm，表面积体积比各是多少？","given":"只作球形几何模型。","analysis":"相对交换面积取决于A/V。","method":"推导3/r再代入。","principle":"同形缩放时面积按长度平方、体积按立方。","steps":["0.5 μm者A/V=3/0.5=6 μm⁻¹。","1 μm者A/V=3 μm⁻¹。"],"ans":"6 μm⁻¹和3 μm⁻¹。","verification":"半径小一半，比值大一倍。","pitfall":"把较大细胞的总面积与单位体积交换能力混同。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]},{"q":"学生说细菌没有线粒体，因此任何细菌都不能有氧呼吸。如何评价？","given":"确定没有真核线粒体。","analysis":"反应途径与真核细胞器位置不能无条件绑定。","method":"区分结构缺少与代谢能力。","principle":"某些细菌的呼吸链位于细胞膜等结构。","steps":["无粒线体仅说明细胞器结构不同。","能否有氧呼吸要核对其酶和电子传递系统，不能由此否定。"],"ans":"结论错误，部分细菌能有氧呼吸。","verification":"与需氧细菌的生长事实相容。","pitfall":"把真核反应场所当成所有生物的必要细胞器。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]}],"practice":[{"q":"质粒是否就是被核膜包围的小细胞核？","given":"问细菌质粒。","analysis":"DNA分子与细胞器不同。","method":"比较构成和边界。","principle":"质粒是染色体之外可复制的DNA分子。","steps":["不以核膜包围。","部分细菌具有，不构成真核细胞核。"],"ans":"不是。","verification":"原核定义仍成立。","pitfall":"见到独立DNA就叫细胞核。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]},{"q":"一张细菌模式图画了荚膜、鞭毛、质粒，是否表示所有细菌都有？","given":"图为典型教学模型。","analysis":"模式图可汇集并非普遍的结构。","method":"读取适用范围并分别分类。","principle":"附属结构存在与否因种类而异。","steps":["细胞膜和核糖体属基本细胞结构。","荚膜、鞭毛与质粒不能无条件普及到全部细菌。"],"ans":"不是，需注明部分细菌才有。","verification":"无鞭毛细菌仍可存活。","pitfall":"将模式图当作所有个体的清单。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]},{"q":"用鞭毛数量能直接确定一种细菌是否致病吗？","given":"仅有运动附属结构信息。","analysis":"致病性需要其他机制及宿主证据。","method":"区分结构功能与疾病结论。","principle":"运动能力不等于致病性。","steps":["鞭毛可参与运动。","是否致病还需毒力、感染及宿主等证据。"],"ans":"不能。","verification":"有运动结构也可为非致病种。","pitfall":"把可能接近宿主当作充分致病证据。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]},{"q":"半径从1 μm增至2 μm，球形模型体积与A/V分别变几倍？","given":"形状不变。","analysis":"两量按不同缩放规律变化。","method":"分别计算立方与倒数。","principle":"V∝r³，A/V∝1/r。","steps":["体积变2³=8倍。","A/V从3变1.5 μm⁻¹，即原来1/2。"],"ans":"体积8倍，比值1/2。","verification":"总表面积4倍而体积8倍，4/8=1/2。","pitfall":"把体积变化套成面积的4倍。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]}],"quiz":{"q":"显微图上没有画出质粒，是否证明该细菌一定没有抗性基因？","given":"模式图未标质粒，无基因检测。","analysis":"图示遗漏与不存在不同。","method":"列基因所在位置及证据限制。","principle":"抗性可与染色体或质粒基因等有关。","steps":["图未画出不能当作检测阴性。","即使无质粒，也不能排除染色体相关抗性。"],"ans":"不能证明。","verification":"须用相应遗传或表型实验判断。","pitfall":"从示意图缺失推出分子不存在。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]},"exam":["结构题先写结构—作用—适用范围，不机械罗列器官名称","推断题区分无某细胞器与无某反应能力","图像题说明分辨率限制，不能把模式图当实测比例"],"quick":["细胞膜","拟核与质粒","核糖体","细胞壁差异","附属结构"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.1","url":"https://openstax.org/books/biology-2e/pages/22-2-structure-of-prokaryotes-bacteria-and-archaea","page_or_section":"22-2-structure-of-prokaryotes-bacteria-and-archaea","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.1","url":"https://openstax.org/books/biology-2e/pages/22-2-structure-of-prokaryotes-bacteria-and-archaea","page_or_section":"22-2-structure-of-prokaryotes-bacteria-and-archaea","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"结构题先写结构—作用—适用范围，不机械罗列器官名称","method":"区分结构缺少与代谢能力。","principle":"某些细菌的呼吸链位于细胞膜等结构。","worked_example_index":2,"verification":"与需氧细菌的生长事实相容。","pitfall":"把真核反应场所当成所有生物的必要细胞器。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“由结构推断细菌的生命活动”的抽样复核：与需氧细菌的生长事实相容。；若出现“把真核反应场所当成所有生物的必要细胞器。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e0","review_module":5,"feedback":"目标“区分原核结构与真核细胞器”的抽样复核：病毒本身没有这样的核糖体和完整细胞质体系。；若出现“将无核膜误写为无DNA。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"从示意图缺失推出分子不存在。","correction":"不能证明。","verification":"须用相应遗传或表型实验判断。"}],"illustration_spec":{"title":"典型细菌结构及适用边界","objects":["细胞膜","肽聚糖壁","拟核","核糖体","可选质粒荚膜鞭毛"],"relations":["DNA无核膜包围","核糖体无膜","可选结构须标部分细菌具有"],"labels":["拟核","核糖体","细胞膜","细胞壁","部分细菌具有"],"format":"SVG","priority":"P0","reuse":"V22现有图需逐结构对照后决定","english":"Draw a typical bacterium without a nucleus or mitochondria. Label nucleoid, ribosomes, membrane and peptidoglycan wall. Clearly mark capsule, plasmid and flagellum as optional structures."}},"18.2":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":18,"section_id":"18.2","goals":["用条件解释生长曲线与实验结果","按可比设计评价抑菌实验"],"prerequisites":["二分裂","浓度与对照实验"],"flow":["营养与水","温度pH和氧","指数与限制","生长曲线","测量对象"],"concept_relation":"营养与水；温度pH和氧；指数与限制；生长曲线；测量对象","deep":["氧的作用因代谢类型不同：专性需氧、专性厌氧、兼性厌氧等对氧有不同需求或耐受。不能以“呼吸需要氧”把所有细菌置于有氧条件，也不能把缺氧下的生长一律解释成发酵，具体电子受体和代谢途径还需证据。","封闭液体培养的典型曲线包括调整期、对数期、稳定期与衰亡期。调整期可有代谢适应，未见数量明显增加并非完全无生命活动；稳定期净数量变化接近零，也不代表所有细胞停止分裂；衰亡期活菌数下降不一定与总颗粒数同步。","研究一个条件应尽量保持其余变量一致，设合适对照和重复，并说明测量的是浊度、菌落形成单位还是直接计数。浊度不能简单等于活菌数；一个菌落可能来自一团细胞，CFU不是任何条件下准确的单细胞数。","学校实验须采用批准的低风险材料、遵守指导和废弃物处理要求，不培养来源不明的人体或环境微生物。以下题目只分析给定数据，不能当作在家培养病原体的操作指南。抑菌圈大小同时受扩散、浓度等影响，不能只凭直径排名临床疗效。"],"derive":["理想倍增：N=N₀×2ᵏ，k=t/g，g为稳定条件下代时；只适用于相应指数阶段。","平板计数估算原液浓度=菌落数/(接种体积×稀释倍数)，单位CFU/mL；依赖可培养、分散和计数范围等条件。","净数量变化=繁殖产生−死亡；不同测量方式可能给不同曲线。"],"examples":[{"q":"给定理想对数期初有500个细胞，代时30 min，90 min后有多少？","given":"无死亡且条件稳定。","analysis":"先算倍增次数。","method":"N=N₀×2^(t/g)。","principle":"每代二分裂使数量乘2。","steps":["k=90/30=3。","N=500×2³=4000。"],"ans":"4000个。","verification":"依次1000、2000、4000，共三代。","pitfall":"把90当作倍增次数。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]},{"q":"10⁻⁵稀释液0.1 mL产生80 CFU，估算原液CFU/mL并说明限制。","given":"计数在允许范围，假定样品均匀。","analysis":"原液等效体积小于接种体积。","method":"用菌落数除原液等效体积。","principle":"浓度×体积对应可培养单位数。","steps":["原液等效体积=0.1×10⁻⁵=10⁻⁶ mL。","80/10⁻⁶=8×10⁷ CFU/mL；菌团与不可培养细胞影响解释。"],"ans":"8×10⁷ CFU/mL，非必然等于单细胞总数。","verification":"该浓度稀释10⁵倍后每0.1 mL为80 CFU。","pitfall":"忘记0.1 mL而少算10倍。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]},{"q":"药物甲抑菌圈大于乙，能否仅凭此认定甲在人体内疗效更好？","given":"培养与纸片实验结果，无体内资料。","analysis":"直径同时取决扩散等因素。","method":"列控制条件及临床证据缺口。","principle":"体外抑菌与人体安全有效性不同。","steps":["需核浓度、扩散和对照。","体内还涉及吸收、组织暴露、毒性与病原敏感性。"],"ans":"不能。","verification":"扩散快即使效力不更强也可能圈更大。","pitfall":"把单一体外指标直接当成治疗排名。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]}],"practice":[{"q":"冷藏是否等于灭菌？","given":"只降低储存温度。","analysis":"抑制与杀灭不同。","method":"比较过程目标。","principle":"低温通常减慢部分微生物代谢。","steps":["存活细菌可在恢复适宜条件后再增殖。","灭菌需经验证的相应过程。"],"ans":"不等于。","verification":"冷藏食品仍有保存期限。","pitfall":"把暂时不增殖当作死亡。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]},{"q":"稳定期活菌总数近似不变，是否说明分裂数为零？","given":"测得净数量稳定。","analysis":"净值为零可能是产生与死亡相抵。","method":"列数量平衡式。","principle":"净增=产生−死亡。","steps":["若每小时产生100又死亡100，净增0。","因此须测周转才能判断分裂。"],"ans":"不一定。","verification":"两项非零但差为零即反例。","pitfall":"把净变化当作单向过程。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]},{"q":"比较pH对生长的影响，温度是否可同时任意改变？","given":"目标为单因素解释。","analysis":"混杂变量会妨碍因果判断。","method":"保持温度等可比并重复。","principle":"只改变自变量以隔离效应。","steps":["设置多个pH水平。","温度、培养时间、起始量等尽量一致。"],"ans":"不可任意改变。","verification":"否则无法区分pH与温度效应。","pitfall":"用多变量变化却归因于一个因素。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]},{"q":"200个细胞代时20 min，理想生长1 h后几倍、多少？若晚期营养耗尽还能照算吗？","given":"前1 h在指数阶段。","analysis":"公式含条件限制。","method":"先计算再审查外推。","principle":"二分裂指数模型只在稳定代时条件下。","steps":["k=60/20=3，倍数8。","N=200×8=1600；营养耗尽后不能继续用原代时无限外推。"],"ans":"8倍、1600；不能无条件外推。","verification":"三次倍增对应400、800、1600。","pitfall":"将理想曲线延伸至所有培养阶段。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]}],"quiz":{"q":"浊度近似不变而CFU下降，是否必然实验错误？","given":"两种测量读数不同。","analysis":"浊度与可培养活菌并非同一指标。","method":"比较各自测量对象。","principle":"死细胞和颗粒也可能散射光，CFU只计相应培养条件下单位。","steps":["活菌失去培养能力可使CFU下降。","颗粒仍在时浊度未必同步下降。"],"ans":"不必然，先检查指标与方法。","verification":"结论同时解释两种读数，无需预设全部颗粒消失。","pitfall":"把所有计数方法视为等价。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]},"exam":["曲线题先看纵轴是活菌、总数还是浊度，再解释阶段","倍增题列代时条件，稀释题用等效原液体积验算","实验题控制起始量等变量，并区分抑制、杀灭、临床效力"],"quick":["营养与水","温度pH和氧","指数与限制","生长曲线","测量对象"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.2","url":"https://openstax.org/books/biology-2e/pages/22-3-prokaryotic-metabolism","page_or_section":"22-3-prokaryotic-metabolism","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_18.2_0","url":"https://openstax.org/books/microbiology/pages/9-1-how-microbes-grow","page_or_section":"9-1-how-microbes-grow","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.2","url":"https://openstax.org/books/biology-2e/pages/22-3-prokaryotic-metabolism","page_or_section":"22-3-prokaryotic-metabolism","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_18.2_0","url":"https://openstax.org/books/microbiology/pages/9-1-how-microbes-grow","page_or_section":"9-1-how-microbes-grow","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"曲线题先看纵轴是活菌、总数还是浊度，再解释阶段","method":"列控制条件及临床证据缺口。","principle":"体外抑菌与人体安全有效性不同。","worked_example_index":2,"verification":"扩散快即使效力不更强也可能圈更大。","pitfall":"把单一体外指标直接当成治疗排名。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用条件解释生长曲线与实验结果”的抽样复核：依次1000、2000、4000，共三代。；若出现“把90当作倍增次数。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“按可比设计评价抑菌实验”的抽样复核：扩散快即使效力不更强也可能圈更大。；若出现“把单一体外指标直接当成治疗排名。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把所有计数方法视为等价。","correction":"不必然，先检查指标与方法。","verification":"结论同时解释两种读数，无需预设全部颗粒消失。"}],"illustration_spec":{"title":"细菌生长曲线与测量边界","objects":["时间轴","活菌数对数轴","四时期","浊度与CFU对照"],"relations":["对数期直线对应原数量指数增加","稳定期净增长近零","死细胞可仍贡献浊度"],"labels":["调整期","对数期","稳定期","衰亡期","log活菌数"],"format":"SVG","priority":"P0","reuse":"无完全匹配旧图","english":"Plot viable bacterial count on a logarithmic vertical axis against time, showing lag, exponential, stationary and death phases. Explain that turbidity and CFU measure different things."}},"18.3":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":18,"section_id":"18.3","goals":["由核酸与衣壳描述病毒","解释病毒为何依赖宿主而非自行分裂"],"prerequisites":["DNA与RNA","蛋白质合成"],"flow":["基因组","衣壳","可选包膜","宿主识别","依赖翻译"],"concept_relation":"基因组；衣壳；可选包膜；宿主识别；依赖翻译","deep":["病毒不具有完整的核糖体与代谢系统，通常依赖宿主的物质、能量及翻译装置产生新组分。它并非在细胞外靠摄食生长后自行二分裂；复制是合成核酸与蛋白质再组装产生颗粒。某些病毒携带或编码必需的酶，这不等于已经有完整独立代谢。","宿主范围和组织嗜性与识别、进入以及细胞内部能否支持复制等条件有关。有受体并非任何条件下都足以使细胞被生产性感染，没有合适受体也不能据某一种途径推断所有途径都绝对不可能；题目应限定病毒与系统。","噬菌体感染细菌，是病毒的一类，并非细菌的一部分。常用带头部和尾部的模型只代表某些噬菌体，不能把所有动物、植物病毒都画成同一种“登月器”形状。动物病毒、植物病毒的进入方式和外形也不统一。","比较生物特征时，病毒有遗传与变异能力，却缺乏细胞结构和宿主之外的自主繁殖。可以据不同定义讨论其生命边界，但不能用“有无生命”替代具体机制。抗细菌药物作用于细胞壁合成等靶点时，对没有这些结构的病毒通常无相同直接作用。"],"derive":["结构最低模型：病毒基因组 + 衣壳；部分另有包膜及表面蛋白。","基因组类型须具体到所讨论病毒，不能把DNA病毒和RNA病毒的路线合并成一张无条件流程图。","病毒增殖不是细胞二分裂：宿主内合成组分 → 组装 → 释放，依赖条件须逐项说明。"],"examples":[{"q":"发现一个颗粒含RNA和蛋白质衣壳，无核糖体，是否可因为有遗传物质就称为细胞？","given":"无细胞质与独立翻译体系。","analysis":"遗传物质不是细胞性的充分条件。","method":"比较病毒与细胞组织。","principle":"细胞需膜围住的细胞质及相应生命活动体系。","steps":["RNA可作为病毒基因组。","衣壳与无核糖体的组合符合病毒模型，不能仅凭RNA称细胞。"],"ans":"不能；需结合证据考虑病毒。","verification":"真核与原核细胞都有核糖体，与该模型不同。","pitfall":"把所有含核酸实体都归为细胞。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]},{"q":"某病毒外有脂质包膜，能否据此说它有细胞膜所以是细胞？","given":"包膜含病毒表面蛋白。","analysis":"膜的存在不自动构成完整细胞。","method":"解释包膜来源与内部缺失。","principle":"包膜常由宿主膜获得，病毒无完整细胞代谢体系。","steps":["外层包膜参与保护与进入。","内部仍是基因组、衣壳等病毒组分，并非完整细胞质组织。"],"ans":"不能，包膜不等于细胞性。","verification":"无包膜病毒也能感染，细胞性不由该单项决定。","pitfall":"按有一层膜作全部分类。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]},{"q":"药物阻止细菌肽聚糖合成，是否应直接抑制所有病毒增殖？","given":"只知药物该靶点，不假设其他作用。","analysis":"病毒无肽聚糖细胞壁。","method":"按结构—靶点关系判断。","principle":"特异作用必须有相应靶标。","steps":["细菌壁合成可被影响。","病毒缺该壁，不能从此靶点推出抗病毒效果。"],"ans":"不能据此推出。","verification":"病毒依赖宿主不代表它拥有宿主或细菌全部结构。","pitfall":"把感染性实体混为同一药物靶点。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]}],"practice":[{"q":"所有病毒都有包膜吗？","given":"比较基本与可选结构。","analysis":"包膜不是普遍条件。","method":"列核心与部分结构。","principle":"衣壳和基因组构成基本模型。","steps":["部分病毒有包膜。","无包膜病毒亦可具有感染性。"],"ans":"不是。","verification":"模型图须注明部分具有。","pitfall":"把特定病毒图推广至全部。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]},{"q":"病毒依赖宿主，是否说明它没有任何基因？","given":"问题混合独立性和遗传。","analysis":"依赖不能推出无基因组。","method":"区分遗传信息与表达装置。","principle":"病毒基因组编码相应组分但翻译依赖宿主。","steps":["遗传信息仍存在。","缺独立核糖体等使它依赖细胞。"],"ans":"不是。","verification":"没有基因组无法说明其稳定遗传特性。","pitfall":"把无独立代谢说成无遗传。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]},{"q":"噬菌体的宿主是细菌，能说噬菌体就是细菌吗？","given":"按感染关系命名。","analysis":"宿主与感染者分类不同。","method":"列两者细胞结构差异。","principle":"噬菌体是病毒。","steps":["细菌具有细胞膜、核糖体。","噬菌体以基因组和衣壳等组成，利用细菌复制。"],"ans":"不能。","verification":"感染对象不等于自身分类。","pitfall":"把寄生者与宿主当作同一实体。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]},{"q":"一病毒图画DNA和RNA两条链都标为同一病毒的基因组，却未说明特殊情况或中间体，应怎样修正？","given":"拟描述一般单一病毒类型。","analysis":"无条件拼接不同类型会误导。","method":"先指定病毒模型，再标基因组及必要中间体。","principle":"基因组类型与复制过程产物须分开。","steps":["选择明确DNA或RNA基因组示例。","若表示逆转录，应把另一核酸标成复制中间体并写条件。"],"ans":"区分基因组与中间体，不能都无条件标为基因组。","verification":"结构与生命周期图应互相一致。","pitfall":"将所有复制相关核酸都叫基因组。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]}],"quiz":{"q":"两个颗粒一大一小，可否仅凭尺寸判大者是细菌、小者是病毒？","given":"无结构和复制证据。","analysis":"尺寸范围可有重叠且图比例不一定相同。","method":"要求结构与宿主依赖证据。","principle":"分类应依据组织结构及生命活动方式。","steps":["检查膜、核糖体、拟核等。","再判断是否依赖细胞组装增殖，并核实实际标尺。"],"ans":"不能只据尺寸。","verification":"即使常见趋势存在，也不能作为无例外判据。","pitfall":"把示意图大小当实测分类标准。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]},"exam":["比较题用细胞结构、核糖体、基因组、增殖方式逐项对照","药物题先找靶点再判断对象，不用病毒比细菌小作理由","流程题先指明病毒类型，明确基因组与中间体"],"quick":["基因组","衣壳","可选包膜","宿主识别","依赖翻译"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.3","url":"https://openstax.org/books/biology-2e/pages/21-1-viral-evolution-morphology-and-classification","page_or_section":"21-1-viral-evolution-morphology-and-classification","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.3","url":"https://openstax.org/books/biology-2e/pages/21-1-viral-evolution-morphology-and-classification","page_or_section":"21-1-viral-evolution-morphology-and-classification","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"比较题用细胞结构、核糖体、基因组、增殖方式逐项对照","method":"按结构—靶点关系判断。","principle":"特异作用必须有相应靶标。","worked_example_index":2,"verification":"病毒依赖宿主不代表它拥有宿主或细菌全部结构。","pitfall":"把感染性实体混为同一药物靶点。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由核酸与衣壳描述病毒”的抽样复核：真核与原核细胞都有核糖体，与该模型不同。；若出现“把所有含核酸实体都归为细胞。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"p1","review_module":7,"feedback":"目标“解释病毒为何依赖宿主而非自行分裂”的抽样复核：没有基因组无法说明其稳定遗传特性。；若出现“把无独立代谢说成无遗传。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把示意图大小当实测分类标准。","correction":"不能只据尺寸。","verification":"即使常见趋势存在，也不能作为无例外判据。"}],"illustration_spec":{"title":"病毒、细菌与细胞结构对比","objects":["无包膜病毒","有包膜病毒","细菌","基因组","衣壳","核糖体"],"relations":["病毒图不画核糖体或完整胞质","包膜标部分具有","外形不统一"],"labels":["DNA或RNA基因组","衣壳","部分病毒有包膜","非按比例"],"format":"SVG","priority":"P0","reuse":"须核现有病毒图类型后复用","english":"Compare an explicitly identified non-enveloped virus, enveloped virus and bacterium. Do not give virions ribosomes, cytoplasm or peptidoglycan. Mark figures as not to scale and distinguish genome from replication intermediates."}},"18.4":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":18,"section_id":"18.4","goals":["按条件说明病毒生命周期","区分个体内增殖与个体间传播"],"prerequisites":["病毒结构","细胞膜与核酸复制"],"flow":["进入与脱壳","合成组分","组装释放","裂解与溶原","传播链与预防"],"concept_relation":"进入与脱壳；合成组分；组装释放；裂解与溶原；传播链与预防","deep":["动物病毒可通过膜融合或内吞等途径进入，基因组复制与基因表达依类型而异。有包膜病毒可通过出芽获得膜，释放未必立即裂解宿主；无包膜与有包膜也不能简单对应“必死”和“不死”，宿主损伤须具体分析。","逆转录病毒以RNA为基因组，经逆转录形成DNA，再参与后续过程；其路线与一般直接将DNA转录成RNA的叙述不同。抗病毒药物可针对某些病毒特有的酶或进入步骤，但是否有效及安全须经验证，不能从流程图任意推断治疗方案。","传播描述病毒从一个宿主或来源到另一个易感宿主的过程，可能与呼吸道、体液、接触、媒介等有关，具体依病毒及环境而定。体内复制速度与人群传播能力不是同一个量；单一传播途径也不能推广所有病毒。","预防措施应对应实际传播链环节，疫苗主要通过免疫准备降低感染或严重结局风险，不能说任何疫苗都保证完全阻断所有感染。抗生素不能因“感染”一词便当作抗病毒药；如有细菌并发感染，治疗判断属另一证据层面。"],"derive":["裂解模型：吸附 → 遗传物质进入 → 组分合成 → 组装 → 释放；进入细胞的成分须依病毒类型画清。","若理想每个感染细胞释放b个可感染颗粒，连续k轮的数量上限模型可写N₀bᵏ；前提是宿主充足、颗粒全部成功感染等，不可当作真实传播预测。","个体内病毒复制、感染性颗粒数、个体间新病例是不同变量，不能无条件互换。"],"examples":[{"q":"某噬菌体图中尾部留在细胞外而遗传物质进入，能否把整个噬菌体都画进细胞？","given":"图描述特定注入式噬菌体模型。","analysis":"进入成分已由题设限定。","method":"按进入方式重画边界。","principle":"该模型中衣壳通常留于外部。","steps":["遗传物质穿过包被进入。","衣壳尾部保留在外侧，随后细胞内合成新组分。"],"ans":"不能在此模型把完整颗粒画入。","verification":"后续新衣壳由细胞内合成而非旧衣壳直接复制。","pitfall":"套用动物病毒内吞模型。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]},{"q":"理想系统10个细胞各被一个颗粒感染，每细胞释放50个感染性颗粒，一轮后多少？能预测实际人群病例吗？","given":"无失败与损失，仅一轮。","analysis":"颗粒产量与病例数不同。","method":"先计算再限定结论。","principle":"产量=细胞数×单细胞产量。","steps":["10×50=500个感染性颗粒。","病例还受接触、宿主易感性和进入效率等限制。"],"ans":"500个；不能直接作为病例数。","verification":"单位是颗粒而非人。","pitfall":"把病毒数当作感染人数。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]},{"q":"细胞长期带有前噬菌体DNA而未裂解，是否证明噬菌体遗传物质没有复制？","given":"宿主在生长并复制DNA。","analysis":"溶原复制不同于大量组装释放。","method":"追踪前噬菌体随宿主复制。","principle":"整合状态可随宿主遗传物质传递。","steps":["细菌复制其染色体时可一并复制前噬菌体。","未裂解只说明未观察到裂解释放，不能推出DNA未复制。"],"ans":"不能证明。","verification":"宿主后代继续含该序列支持遗传传递。","pitfall":"把不释放颗粒等同于无复制。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]}],"practice":[{"q":"病毒是否都通过宿主立即裂解释放？","given":"比较出芽与裂解。","analysis":"释放方式有差异。","method":"列反例并限定。","principle":"某些有包膜病毒可出芽。","steps":["出芽可取得膜。","未必立即导致细胞裂解，实际损伤依病毒而异。"],"ans":"不是。","verification":"与裂解噬菌体模型并不矛盾。","pitfall":"将一种生命周期推广全部。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]},{"q":"逆转录指RNA到DNA还是DNA到RNA？","given":"问该酶作用方向。","analysis":"名称相对常见转录方向。","method":"标底物与产物。","principle":"逆转录以RNA为模板合成DNA。","steps":["先识别RNA模板。","DNA产物可进入后续生命周期。"],"ans":"RNA到DNA。","verification":"DNA到RNA为通常转录。","pitfall":"把方向箭头反画。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]},{"q":"一种病毒经媒介传播，是否可推出全部病毒都经同一种媒介？","given":"只知单一病毒途径。","analysis":"样本范围有限。","method":"限定结论至对象。","principle":"传播依病毒生态与宿主环境。","steps":["该病毒的防护需针对相应传播链。","其他病毒需各自证据，不能沿用。"],"ans":"不能。","verification":"呼吸道与媒介等途径不同。","pitfall":"将局部途径当普遍规律。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]},{"q":"理想每轮感染性颗粒乘20，从5个起始经两轮多少？为什么这不是可靠的人群预测？","given":"全部成功感染且宿主无限的假设。","analysis":"数学上可算，现实条件严格。","method":"5×20²并列假设失效点。","principle":"逐轮乘积模型。","steps":["一轮100个。","二轮2000个；真实宿主、免疫和传播瓶颈使模型受限。"],"ans":"2000个，非2000病例预测。","verification":"100×20=2000，单位仍颗粒。","pitfall":"把理想模型写成现实确定结果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]}],"quiz":{"q":"已知疫苗训练免疫系统，能否声称所有接种者绝不会感染？","given":"没有具体疫苗效果数据。","analysis":"免疫准备不等于绝对屏障。","method":"区分降低风险与完全阻断。","principle":"效果依疫苗、病原与个体等。","steps":["疫苗可改善免疫应答并降低部分风险。","不能用无条件百分之百替代证据。"],"ans":"不能作绝对保证。","verification":"感染、重症与传播风险应分别评价。","pitfall":"用预防作用推出零风险。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]},"exam":["生命周期题先定病毒类型再标进入、合成、组装与释放","过程干预题明确药物靶步骤，不能由示意图宣称临床有效","传播题区分颗粒产量、个体内复制与人群新病例"],"quick":["进入与脱壳","合成组分","组装释放","裂解与溶原","传播链与预防"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.4","url":"https://openstax.org/books/biology-2e/pages/21-2-virus-infections-and-hosts","page_or_section":"21-2-virus-infections-and-hosts","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.4","url":"https://openstax.org/books/biology-2e/pages/21-2-virus-infections-and-hosts","page_or_section":"21-2-virus-infections-and-hosts","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"生命周期题先定病毒类型再标进入、合成、组装与释放","method":"追踪前噬菌体随宿主复制。","principle":"整合状态可随宿主遗传物质传递。","worked_example_index":2,"verification":"宿主后代继续含该序列支持遗传传递。","pitfall":"把不释放颗粒等同于无复制。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按条件说明病毒生命周期”的抽样复核：后续新衣壳由细胞内合成而非旧衣壳直接复制。；若出现“套用动物病毒内吞模型。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":7,"feedback":"目标“区分个体内增殖与个体间传播”的抽样复核：单位是颗粒而非人。；若出现“把病毒数当作感染人数。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"用预防作用推出零风险。","correction":"不能作绝对保证。","verification":"感染、重症与传播风险应分别评价。"}],"illustration_spec":{"title":"病毒增殖类型与传播层次","objects":["噬菌体裂解/溶原分支","宿主细胞边界","动物病毒出芽","宿主间传播单独框"],"relations":["不得把所有病毒画成注入式噬菌体","复制与传播分开","逆转录方向RNA到DNA"],"labels":["吸附","合成","组装","释放","前噬菌体","非所有病毒相同"],"format":"SVG","priority":"P0","reuse":"现有生命周期图须按类型复核","english":"Draw explicitly separated examples of phage lytic and lysogenic cycles and enveloped animal-virus budding. Distinguish intracellular replication from between-host transmission; label reverse transcription RNA to DNA only in the appropriate example."}}},"生物19":{"19.1":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":19,"section_id":"19.1","goals":["区分生命起源假说与可观察证据","解释细胞复杂性演化的主要条件"],"prerequisites":["有机分子","细胞膜与遗传信息"],"flow":["化学前体","隔离与复制","RNA假说","代谢环境","内共生证据"],"concept_relation":"化学前体；隔离与复制；RNA假说；代谢环境；内共生证据","deep":["原始隔离体系可由两亲性分子形成膜样边界，帮助把组分局限在同一空间，但边界本身不足以满足生命全部特征。维持遗传、复制准确性、能量利用与可持续繁殖仍需相互协调；把一个脂质囊泡直接叫完整原始生命会过度解释。","RNA相关起源假说关注RNA可携带信息且某些RNA有催化作用，提示信息与催化可能在早期同一类分子中结合。它并非已证明全部现代遗传系统直接由某一具体RNA按确定路线演化，前体产生、复制与稳定等仍有问题。","早期细胞及代谢方式的出现与环境相互影响，光合生物长期改变氧化环境，为某些后续代谢提供条件，也给原有不耐氧生物压力。不能把氧气作为所有最早生命必须依赖的条件，亦不能把复杂现代植物当最早光合形式。","真核细胞中粒线体、叶绿体的来源可由内共生理论解释，支持线索包括双膜、自有遗传体系及与某些细菌的相似性等。多条独立证据共同支持，不是看到双膜就单独证明；也不能把所有细胞器都一概说成相同内共生来源。"],"derive":["证据层次：实验特定条件下生成有机物 ≠ 已制造完整生命 ≠ 已证明地球唯一历史路线。","隔离、遗传复制、催化与能量利用须相互协调，不能由一个膜泡推全套生命活动。","内共生理论用多类结构、遗传与演化证据综合评价；现代相似性不等于原始事件可以直接重看。"],"examples":[{"q":"模拟环境实验产生氨基酸，可以直接宣布已在实验室创造生命吗？","given":"检测到有机小分子，无细胞复制证据。","analysis":"组成材料与完整生命体系不同。","method":"限定实验结论。","principle":"必要组分不等于充分系统。","steps":["结果支持该条件可非生物合成某些有机物。","未证明有膜内遗传复制、代谢协调与繁殖，不可称造生命。"],"ans":"不能，只支持有限化学合成结论。","verification":"氨基酸溶液本身不会因此自动成为可遗传细胞。","pitfall":"把生命原料当生命本身。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.1","related_sections":[]},{"q":"一个脂质囊泡能包住RNA，是否足以证明它能持续演化成细胞？","given":"只给包裹现象。","analysis":"隔离是部分条件，缺持续复制等。","method":"列仍需检验功能。","principle":"可持续体系需能量、复制与边界协调。","steps":["检测RNA复制、保真与催化是否可能。","还需物质输入、能量和分裂继承等，不由包裹直接推长期结果。"],"ans":"不足。","verification":"不复制且耗尽原料的囊泡不能维持所声称过程。","pitfall":"从一个结构外推全部功能。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.1","related_sections":[]},{"q":"粒线体有双膜，因此所有双膜结构都来自同一内共生事件，推理合理吗？","given":"只使用单一结构相似。","analysis":"相同特征不唯一指向同一历史。","method":"补遗传、分子与系统关系证据并限定对象。","principle":"内共生由多条证据共同支持。","steps":["粒线体理论还有自有DNA及相关系统证据。","核膜等双膜结构不能仅凭层数归同源内共生事件。"],"ans":"不合理。","verification":"一项形态特征也可能因其他过程形成。","pitfall":"把支持线索当独占且普遍的充分证明。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.1","related_sections":[]}],"practice":[{"q":"生命起源与现有种群演化是完全相同问题吗？","given":"研究层次不同。","analysis":"起源问从化学到生命，演化问可遗传体系的变化。","method":"分别界定。","principle":"问题对象与证据类型不同。","steps":["起源含化学路径及原始体系。","演化研究已存在生命的遗传变异、共同祖先和群体变化。"],"ans":"不是同一问题，但有关联。","verification":"起源某细节未知不否定已观测到的遗传变化。","pitfall":"混合两问题来否定所有证据。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.1","related_sections":[]},{"q":"RNA假说为何有吸引力，是否已证明唯一真实路线？","given":"部分RNA可有催化作用。","analysis":"功能可能性与历史唯一性不同。","method":"连信息与催化后写限制。","principle":"RNA既可携信息又可在某些结构中催化。","steps":["可设想早期信息与催化结合。","但前体合成和复制等仍需研究，不能称唯一路线已证。"],"ans":"有功能线索，未证明唯一历史路线。","verification":"假说可产生实验预测但不等于全部细节完成。","pitfall":"将假说二字理解成任意猜或已证定论两极。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.1","related_sections":[]},{"q":"最早生命一定都依赖游离氧吗？","given":"不假设现代需氧模式普遍。","analysis":"代谢类型多样且早期环境不同。","method":"区分需氧与厌氧。","principle":"有生命不必具现代有氧呼吸。","steps":["厌氧代谢可在无游离氧条件进行。","因此不能把氧设为所有原始生命的必要条件。"],"ans":"不一定。","verification":"现代厌氧生物也显示生命活动并非全需氧。","pitfall":"把人类需氧推广全部生命。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.1","related_sections":[]},{"q":"两组模拟实验仅能量输入不同，组甲产有机物、乙未检出，能得到什么结论？需什么限制？","given":"其他条件可比、检测下限存在。","analysis":"结果限于装置与测法。","method":"比较处理并写检测边界。","principle":"对照支持该条件影响所测产物。","steps":["甲乙差异支持此能量条件在该体系中影响合成或可检出量。","需重复和定量，未检出不等于绝对无，不能推广所有起源环境。"],"ans":"得到有条件的实验支持。","verification":"保留检测限和环境差异使结论不超证据。","pitfall":"将一次未检出写成宇宙中不可能形成。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.1","related_sections":[]}],"quiz":{"q":"起源研究未确定每个步骤，能否据此说粒线体与细菌的分子相似性也没有证据价值？","given":"两个命题证据不同。","analysis":"某问题未解不使另一组观察消失。","method":"分离证据对象。","principle":"独立证据应按其质量评价。","steps":["起源路径不全确定是研究边界。","粒线体结构、遗传相似等仍可支持特定内共生解释，需独立评估。"],"ans":"不能这样推。","verification":"未知不是对所有已知的自动否定。","pitfall":"用一个资料缺口抹去其他证据。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.1","related_sections":[]},"exam":["起源题按假说、实验支持、尚未证明分层写","装置题说明产物与条件，不把有机物等同细胞","内共生题列多类证据并限定粒线体/叶绿体等对象"],"quick":["化学前体","隔离与复制","RNA假说","代谢环境","内共生证据"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_19.1","url":"https://openstax.org/books/biology-2e/pages/23-1-eukaryotic-origins","page_or_section":"23-1-eukaryotic-origins","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_19.1_0","url":"https://openstax.org/books/biology-2e/pages/22-1-prokaryotic-diversity","page_or_section":"22-1-prokaryotic-diversity","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_19.1","url":"https://openstax.org/books/biology-2e/pages/23-1-eukaryotic-origins","page_or_section":"23-1-eukaryotic-origins","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_19.1_0","url":"https://openstax.org/books/biology-2e/pages/22-1-prokaryotic-diversity","page_or_section":"22-1-prokaryotic-diversity","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"起源题按假说、实验支持、尚未证明分层写","method":"补遗传、分子与系统关系证据并限定对象。","principle":"内共生由多条证据共同支持。","worked_example_index":2,"verification":"一项形态特征也可能因其他过程形成。","pitfall":"把支持线索当独占且普遍的充分证明。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“区分生命起源假说与可观察证据”的抽样复核：氨基酸溶液本身不会因此自动成为可遗传细胞。；若出现“把生命原料当生命本身。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“解释细胞复杂性演化的主要条件”的抽样复核：一项形态特征也可能因其他过程形成。；若出现“把支持线索当独占且普遍的充分证明。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"用一个资料缺口抹去其他证据。","correction":"不能这样推。","verification":"未知不是对所有已知的自动否定。"}],"illustration_spec":{"title":"生命起源的证据层次","objects":["非生物合成实验","有机小分子","膜样隔离","RNA信息/催化","内共生独立证据框"],"relations":["不能从产物直接画成确定生命路线","假说用虚线和条件","内共生对象限定且多证据"],"labels":["模型条件","实验支持","尚待研究","不是完整生命","内共生"],"format":"SVG","priority":"P1","reuse":"不得复用已隔离粒线体错误图；应另行准确结构任务","english":"Separate experimentally supported abiotic synthesis from hypothesized steps toward replication, compartmentalization and metabolism. Use conditional dashed links rather than a proven linear origin sequence. Show multiple lines of endosymbiotic evidence without reusing quarantined inaccurate mitochondrial artwork."}},"19.2":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":19,"section_id":"19.2","goals":["综合化石解剖与分子证据解释亲缘","区分同源同功及树图的推断边界"],"prerequisites":["遗传信息","分类与时间尺度"],"flow":["化石地理","结构发育","同源同功","序列比较","共同祖先树"],"concept_relation":"化石地理；结构发育；同源同功；序列比较；共同祖先树","deep":["同源结构源于共同祖先中相应结构，可在不同物种中有不同功能，如脊椎动物前肢的骨骼布局。相同功能却来自不同演化来源的相似性可为同功或趋同例，昆虫翅与鸟翼作为飞行器官需区分其结构历史。","痕迹结构可能在祖先中有更显著功能，现代可退化或改变用途；不能把“痕迹”一概说成绝无功能。胚胎相似可支持关系，但不等于个体发育逐段重演全部祖先成体，图示也不能为了相似故意删掉差异。","同源DNA或蛋白质序列比较可提供亲缘证据，需正确对齐、选择适当位点并考虑不同进化速率。一个短序列的相同百分比不是无条件的完整亲缘树，多个独立基因与其他证据可增强推断。","系统树的节点表示共同祖先假说，枝末代表采样类群，不是从低等到高等的梯子。现生人类与现生黑猩猩有共同祖先，不是说人类由今天的黑猩猩直接变来；旋转节点下的枝条不改变亲缘关系。"],"derive":["证据推断链：观察特征/序列 → 判是否可比较及同源 → 建共同祖先关系 → 用独立资料核查。","亲缘远近看最近共同祖先，不看树图左右距离或末端摆放高低。","序列相似率=对应位点相同数/可比位点数；需对齐及模型条件，不等于单独证明全部历史。"],"examples":[{"q":"鲸鳍肢与人手外形功能不同，前肢骨骼基本布局却对应，这支持什么？","given":"比较的是相应脊椎前肢结构。","analysis":"同源不要求同功能。","method":"连结构布局与共同祖先。","principle":"同源结构经不同功能改造。","steps":["对应骨骼布局支持共享祖先结构。","游泳与抓握功能不同可表示分化，不否定同源。"],"ans":"支持前肢同源与共同祖先解释。","verification":"应结合发育、分子等，非一张图孤证全部亲缘。","pitfall":"外形功能不同就否认同源。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.2","related_sections":[]},{"q":"一段对齐100位点序列甲乙相同95、甲丙相同80，能直接给出所有物种完整树吗？","given":"只有一个短片段和三者相似数。","analysis":"相似度可提示，证据范围有限。","method":"先算比例再写需多资料。","principle":"推断依同源对齐与演化速率等。","steps":["甲乙95%、甲丙80%。","此片段更支持甲乙相似，但需更多位点、类群和模型，不能单凭它确定全部树。"],"ans":"不能确定完整树。","verification":"不同基因速率或保守性会改变信息量。","pitfall":"百分比高就把单片段当完整历史证明。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.2","related_sections":[]},{"q":"树上A与B共享较近节点，C在较早节点分出。把A、B绘图位置互换后，A与C会更近缘吗？","given":"只绕节点旋转，拓扑未变。","analysis":"图上左右距离不是亲缘指标。","method":"追踪最近共同祖先。","principle":"拓扑关系决定分支亲缘。","steps":["A、B的共同祖先仍比A、C更近。","交换末端位置不改变节点连接。"],"ans":"不会。","verification":"重新沿分支回溯可见相同结构。","pitfall":"用纸上距离代替共同祖先。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.2","related_sections":[]}],"practice":[{"q":"鸟翼与昆虫翅功能都为飞行，能仅凭功能相同判为同源吗？","given":"只给功能相似。","analysis":"同功能可趋同。","method":"比较结构与演化来源。","principle":"同源要求相应祖先来源证据。","steps":["两类翅的构成与起源不同。","飞行功能相似本身不能证明同源。"],"ans":"不能。","verification":"同功特征可在不同谱系独立形成。","pitfall":"功能相同即同源。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.2","related_sections":[]},{"q":"化石记录不完整，是否完全不能支持过去存在不同生物？","given":"仍有可靠化石与地层。","analysis":"不完整不等于无信息。","method":"用已保存证据限定结论。","principle":"证据可支持部分历史而非全部细节。","steps":["化石可直接记录某些过去形态。","缺口限制连续细节，不能抹去已保存观察。"],"ans":"不是。","verification":"一册缺页记录仍可能保留可靠已有页。","pitfall":"要求无缺口才承认任何证据。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.2","related_sections":[]},{"q":"痕迹结构是否必须毫无功能？","given":"讨论演化含义。","analysis":"功能可改变或减弱。","method":"区分祖先主要功能与现代作用。","principle":"退化不等于绝对无作用。","steps":["可能失去祖先主要功能。","仍可有其他残余或新功能，因此不要求完全无用。"],"ans":"不必须。","verification":"应具体研究而非凭名称决定。","pitfall":"无用才准叫痕迹。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.2","related_sections":[]},{"q":"20个可比位点中15相同，相似率多少？若另外10位无法可靠对齐，能直接当全不同加入分母吗？","given":"先限20个可比位点。","analysis":"不可比不等于差异已知。","method":"15/20。","principle":"比较需明确可比位点。","steps":["相似率75%。","无法对齐的10位须按方法处理，不能无依据全当不同；需报告覆盖与限制。"],"ans":"75%基于可比20位；不能随意加入。","verification":"若错误加成15/30=50%会改变指标含义。","pitfall":"把资料缺失当作已观测差异。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.2","related_sections":[]}],"quiz":{"q":"“人类由现生黑猩猩直接变来”怎样改写才符合共同祖先的树状关系？","given":"比较现生两条谱系。","analysis":"共同祖先不是现生另一类群。","method":"画分叉节点。","principle":"两个现生谱系由共同祖先分化。","steps":["祖先节点向两支分开。","人类与黑猩猩各有自己的后续演化，不是一支现生成另一现生。"],"ans":"二者共享共同祖先，而非现生黑猩猩直接变成人。","verification":"分叉树允许两支同时存在。","pitfall":"把演化树看成单一路线阶梯。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.2","related_sections":[]},"exam":["证据题分别写观察、解释和限制，再综合独立证据","同源题看祖先结构来源，不以相同功能当唯一判据","树图题沿节点追最近共同祖先，忽略末端左右排列"],"quick":["化石地理","结构发育","同源同功","序列比较","共同祖先树"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_19.2","url":"https://openstax.org/books/biology-2e/pages/18-1-understanding-evolution","page_or_section":"18-1-understanding-evolution","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_19.2","url":"https://openstax.org/books/biology-2e/pages/18-1-understanding-evolution","page_or_section":"18-1-understanding-evolution","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"证据题分别写观察、解释和限制，再综合独立证据","method":"追踪最近共同祖先。","principle":"拓扑关系决定分支亲缘。","worked_example_index":2,"verification":"重新沿分支回溯可见相同结构。","pitfall":"用纸上距离代替共同祖先。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“综合化石解剖与分子证据解释亲缘”的抽样复核：应结合发育、分子等，非一张图孤证全部亲缘。；若出现“外形功能不同就否认同源。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“区分同源同功及树图的推断边界”的抽样复核：重新沿分支回溯可见相同结构。；若出现“用纸上距离代替共同祖先。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把演化树看成单一路线阶梯。","correction":"二者共享共同祖先，而非现生黑猩猩直接变成人。","verification":"分叉树允许两支同时存在。"}],"illustration_spec":{"title":"同源证据与系统树读法","objects":["脊椎前肢对应骨","鸟昆虫翅功能对照","A/B/C分叉树","节点旋转同拓扑"],"relations":["同源可异功能","同功不自动同源","旋转不改亲缘","节点不是进步阶梯"],"labels":["共同祖先","对应骨骼","最近共同祖先","同一拓扑","未按时间比例"],"format":"SVG","priority":"P0","reuse":"现有生物图须按骨连接与树拓扑复核再用","english":"Align homologous vertebrate forelimb bones without requiring identical functions; contrast flight analogy in bird and insect wings. Draw an A/B sister-group tree with C branching earlier and a rotated equivalent tree, keeping topology unchanged and avoiding a progress ladder."}},"19.3":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":19,"section_id":"19.3","goals":["用可遗传变异与繁殖差异解释适应","区分选择、定向意图和个体变化"],"prerequisites":["遗传与变异","种群及比例"],"flow":["变异","可遗传性","环境筛选","繁殖贡献","代际与替代机制"],"concept_relation":"变异；可遗传性；环境筛选；繁殖贡献；代际与替代机制","deep":["适合度在此关心遗传贡献和成功繁殖，不只是体型、力量或活得久。存活到繁殖期很重要，但如果没有后代或后代不繁殖，遗传贡献仍可能较低；比较需明确环境与代际范围。","抗药性可由突变或基因获得等产生，在用药压力下，易感个体受抑而有相应抗性者留下更多后代。并非药物把每个细菌训练成抗性，也不能绝对声称每个抗性变异都在首次暴露前出现；关键是变异产生与筛选的机制和时序要有证据。","环境改变可改变何种性状有利，适应不存在无条件最优。隐蔽颜色在一种背景有利，换背景可能不利；多种选择压力、资源和权衡也会限制单一性状无限发展。","证据分析要比较性状可遗传性、存活/繁殖及后代组成，控制环境和采样。某性状比例变多可能还涉及迁入、随机漂变等，不能每个变化都自动归自然选择；后续综合理论把这些群体机制区分。"],"derive":["选择机制链：可遗传变异 → 环境下繁殖成功差异 → 后代遗传贡献不同 → 群体组成改变。","相对繁殖成功需同环境同时间尺度比较，不等于单纯存活人数。","比例变化本身不足识别机制；需排查迁移、漂变及测量偏差等。"],"examples":[{"q":"甲型10个体各留3个可繁殖后代，乙型10个体各留1个，性状可遗传且其他条件可比，后代两型比例如何？","given":"简化假定后代保持相应类型，无迁移。","analysis":"比较遗传贡献而非初数量。","method":"数量乘每个体后代数。","principle":"差异繁殖可改变类型频率。","steps":["甲后代30、乙10，总40。","甲75%、乙25%，由初各50%改变。"],"ans":"75%与25%。","verification":"两型初数量相等但繁殖贡献不同。","pitfall":"只看存活初数量就说没有选择可能。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.3","related_sections":[]},{"q":"黑白昆虫在深色背景黑型更不易被捕，若颜色不可遗传，能仅此证明黑色适应代代增强吗？","given":"有存活差异但缺遗传。","analysis":"代际传递是必要环节。","method":"区分一次存活与遗传演化。","principle":"选择导致遗传组成变化需相关可遗传变异。","steps":["黑型可在本次有存活优势。","但若后代颜色与亲代无传递关联，不能据此推黑型遗传频率持续增加。"],"ans":"不能，缺可遗传性证据。","verification":"下一代比例可能重新产生而不反映亲代优势。","pitfall":"把任何表型筛选都当遗传适应完成。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.3","related_sections":[]},{"q":"细菌用药后抗性比例上升，学生说药物有目的地把所有细菌变成抗性，如何改写？","given":"只知处理后比例变动。","analysis":"产生变异与差异存活繁殖不同。","method":"用筛选模型并列进一步证据。","principle":"自然选择无目的设计。","steps":["群体可含不同抗性来源的变异。","药物压力使易感者更受抑，抗性者相对贡献上升。","需时间和遗传实验区分原有与新出现变异，不能声称全部被定向改造。"],"ans":"用变异加筛选解释，并限定尚未验证的时序。","verification":"药物杀掉大量易感者就足以提升抗性比例，无需全部转化。","pitfall":"将比例变化当每个体被改造。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.3","related_sections":[]}],"practice":[{"q":"最强壮个体是否必有最高适合度？","given":"没有后代资料。","analysis":"力量不是遗传贡献定义。","method":"比较成功繁殖。","principle":"适合度依环境与后代贡献。","steps":["强壮者可能不繁殖。","较弱者可能留下更多可繁殖后代，需实际数据。"],"ans":"不一定。","verification":"存活与繁殖均影响贡献。","pitfall":"适者生存只解释成肌力最大。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.3","related_sections":[]},{"q":"一种保护色在浅背景有利，在深背景还必有利吗？","given":"环境改变。","analysis":"有利性具有相对性。","method":"比较可见度与捕食。","principle":"性状效应依环境。","steps":["换背景可能使原保护色更显眼。","因此需重新评估存活繁殖优势。"],"ans":"不必。","verification":"相同性状可在两环境产生相反效应。","pitfall":"把适应当永久最优标签。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.3","related_sections":[]},{"q":"一个人在高海拔增加红细胞，能仅凭此说人类种群已发生遗传演化吗？","given":"个体生理调节。","analysis":"个体变化与代际遗传变化不同。","method":"要求遗传和种群频率证据。","principle":"适应性生理反应不等于等位基因频率变化。","steps":["该人可有可塑性应答。","尚无后代遗传与群体频率证据，不能推种群遗传演化。"],"ans":"不能。","verification":"离开高海拔后可回调也提示不同层次。","pitfall":"把一生内调节说成种群进化。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.3","related_sections":[]},{"q":"甲20个体各2后代，乙10个体各3后代，后代甲比例？能以甲总数较多证明单个甲繁殖更成功吗？","given":"后代均同类型作简化。","analysis":"总贡献与每个体贡献不同。","method":"求总数和比例再比较。","principle":"适合度比较需单位个体。","steps":["甲40、乙30，甲40/70≈57.1%。","甲单个2后代少于乙3，初数量较多造成总数较多。"],"ans":"甲约57.1%；不能说单个甲更成功。","verification":"初甲占66.7%，后代降至57.1%，与每个体贡献较低一致。","pitfall":"只比群体总后代不按初个体数。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.3","related_sections":[]}],"quiz":{"q":"某性状频率上升就必然是自然选择吗？应补哪些证据？","given":"仅给频率趋势。","analysis":"其他机制也可改频率。","method":"调查可遗传性、繁殖差异及迁移随机性。","principle":"机制判定需要过程证据。","steps":["需看该性状是否造成环境下遗传贡献差异。","同时排查迁入、漂变和采样，不能单凭上升判定。"],"ans":"不必，需多机制比较。","verification":"随机灾变或迁入也能增加某变异比例。","pitfall":"将所有变化都称选择。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.3","related_sections":[]},"exam":["机制题按变异、可遗传、差异繁殖、代际频率完整连链","抗性题分变异来源和选择作用，别写有目的变成","数据题按每个体贡献与总数分开，比例变化不单独判机制"],"quick":["变异","可遗传性","环境筛选","繁殖贡献","代际与替代机制"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_19.3","url":"https://openstax.org/books/biology-2e/pages/19-3-adaptive-evolution","page_or_section":"19-3-adaptive-evolution","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_19.3","url":"https://openstax.org/books/biology-2e/pages/19-3-adaptive-evolution","page_or_section":"19-3-adaptive-evolution","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"机制题按变异、可遗传、差异繁殖、代际频率完整连链","method":"用筛选模型并列进一步证据。","principle":"自然选择无目的设计。","worked_example_index":2,"verification":"药物杀掉大量易感者就足以提升抗性比例，无需全部转化。","pitfall":"将比例变化当每个体被改造。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用可遗传变异与繁殖差异解释适应”的抽样复核：两型初数量相等但繁殖贡献不同。；若出现“只看存活初数量就说没有选择可能。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“区分选择、定向意图和个体变化”的抽样复核：药物杀掉大量易感者就足以提升抗性比例，无需全部转化。；若出现“将比例变化当每个体被改造。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"将所有变化都称选择。","correction":"不必，需多机制比较。","verification":"随机灾变或迁入也能增加某变异比例。"}],"illustration_spec":{"title":"自然选择的完整机制链","objects":["初始不同类型","环境压力","差异繁殖","后代频率","非定向变异入口"],"relations":["选择不是把所有个体改造","可遗传性连到后代","每个体与总贡献区分"],"labels":["变异","可遗传","差异繁殖","频率变化","不由需要定向产生"],"format":"SVG","priority":"P0","reuse":"现有选择图需核是否误画个体主动变色","english":"Show heritable variation before and during selection, differential reproductive contribution under an environment, and changed offspring frequencies. Do not depict every individual intentionally transforming into the favoured type. Distinguish per-individual success from total offspring numbers."}},"19.4":{"content_batch":"batch05","subject":"生物","subject_code":"biology","chapter_id":19,"section_id":"19.4","goals":["计算种群等位基因频率及平衡期望","区分选择漂变基因流与变异来源"],"prerequisites":["基因型与等位基因","概率与比例"],"flow":["变异来源","遗传重排","基因流","漂变与选择","平衡基准"],"concept_relation":"变异来源；遗传重排；基因流；漂变与选择；平衡基准","deep":["二倍体常染色体两等位基因模型中，A频率p=[2N(AA)+N(Aa)]/(2N)，a频率q=1−p。杂合子提供一个A和一个a，不能把杂合人数全部加进一种等位基因，也不能把显性表型比例直接当p。","哈代—温伯格模型在随机交配、足够大种群及无所讨论座位的选择、迁移、突变等条件下，给合子基因型期望p²、2pq、q²。它是可比较的基准，不宣称真实群体永远满足；期望人数可为小数，抽样实数不必逐项精确等于期望。","若用隐性表型频率当q²，还需该座位的完全显性等适用条件，并说明表型与基因型关系。伴性、多等位、外显不全或未达平衡时不能无条件套；显性表现者包括AA和Aa，不可把其比例直接开方当p。","综合分析中，环境改变的选择、随机漂变与迁入可同时作用，观察到偏离平衡还需统计与设计判断。不能因一次样本与小数期望不完全相同就断言某一种机制必然发生，更不能把不显著差异当证明所有条件都成立。"],"derive":["二倍体常染色体两等位：p=(2N_AA+N_Aa)/(2N)，q=1−p。","随机结合模型：(p+q)²=p²+2pq+q²=1；三项分别为AA、Aa、aa期望频率。","若模型适用且隐性表型=aa，q=√f(隐性)；这依遗传方式、外显和群体条件。"],"examples":[{"q":"200个二倍体中AA100、Aa60、aa40，求p和q。","given":"常染色体两等位。","analysis":"分母为400个等位基因拷贝。","method":"数A和a再除2N。","principle":"杂合各贡献一个拷贝。","steps":["A=2×100+60=260，p260/400=.65。","a=2×40+60=140，q.35。"],"ans":"p=.65，q=.35。","verification":"260+140=400，p+q=1。","pitfall":"用AA人数100/200当A频率。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.4","related_sections":[]},{"q":"平衡模型适用，隐性表型频率4%，且完全显性，求q,p及杂合比例；1000人中期望杂合多少？","given":"aa表型对应q²。","analysis":"先开方求q，非直接用4%。","method":"q=√.04。","principle":"哈代—温伯格两等位模型。","steps":["q=.2，p=.8。","2pq=2×.8×.2=.32；1000×.32=320。"],"ans":"q.2、p.8，杂合32%，期望320。","verification":"AA64%+Aa32%+aa4%=100%。","pitfall":"把隐性4%当q=.04。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.4","related_sections":[]},{"q":"某岛群体A频率.5，经题设完全随机、与基因型无关灾变后，幸存10二倍体中A拷贝6个，怎样解释变化？","given":"总20等位拷贝，随机性由题设给定。","analysis":"灾变后的抽样可偏离来源比例。","method":"算频率并区分漂变与选择。","principle":"有限群体随机抽样导致漂变。","steps":["p后=6/20=.3，较.5下降。","因题设存活与基因型无关，模型支持漂变/瓶颈，而不是A必较不利。"],"ans":"p从.5到.3，随机漂变解释。","verification":"剩余a14个，q.7，拷贝数守恒于幸存样本。","pitfall":"频率下降就说该等位基因有害。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.4","related_sections":[]}],"practice":[{"q":"AA25、Aa50、aa25，总100，p,q和模型期望频率？","given":"两等位二倍体。","analysis":"先数拷贝。","method":"p=(50+50)/200。","principle":"等位频率定义。","steps":["p=.5、q=.5。","期望AA.25、Aa.50、aa.25。"],"ans":"p=q=.5，期望25%、50%、25%。","verification":"与本数据吻合，但不因此证明全部模型条件。","pitfall":"吻合即证明没有任何选择。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.4","related_sections":[]},{"q":"显性表型占96%，能直接说p=.96吗？","given":"完全显性且可能适用平衡。","analysis":"显性表型含AA与Aa。","method":"先由隐性比例或基因型信息求。","principle":"表型比例不同于等位频率。","steps":["若平衡且隐性4%，q=.2、p=.8。",".96=p²+2pq而非p。"],"ans":"不能，给定条件下p=.8。","verification":".64+.32=.96。","pitfall":"把显性表现个体当A拷贝频率。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.4","related_sections":[]},{"q":"基因流与突变都能使某群体出现原先未见等位基因，它们机制相同吗？","given":"比较变异来源途径。","analysis":"迁入已有与新序列产生不同。","method":"分别描述。","principle":"基因流在群体间交换，突变产生遗传变化。","steps":["迁入者可携其他群体已存在变异。","突变在遗传物质中产生变化，二者不能互换。"],"ans":"不同。","verification":"对本群体新见不代表在物种中全新产生。","pitfall":"把所有新出现都称突变。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.4","related_sections":[]},{"q":"p=.7、q=.3，100个体的平衡期望AA、Aa、aa数，并说明样本不是正好这些数时能否直接判自然选择。","given":"两等位常染色体模型。","analysis":"期望与随机样本有区别。","method":"p²N、2pqN、q²N。","principle":"随机结合期望。","steps":["AA49、Aa42、aa9。","偏差需统计及条件分析，也可能抽样波动或其他机制，不能单独判选择。"],"ans":"49、42、9；不能直接归因选择。","verification":"相加100，等位期望140A与60a。","pitfall":"任意偏差都归唯一机制。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.4","related_sections":[]}],"quiz":{"q":"重组重新排列等位基因，是否每次都必然创造全新的等位基因并改变单座位p？","given":"普通重组模型，无突变和偏分离。","analysis":"组合与等位身份/数量不同。","method":"追踪原拷贝。","principle":"重组通常重排已有片段组合。","steps":["多座位组合可改变。","不必产生新等位序列，也不必改变某座位A拷贝比例；特殊事件另论。"],"ans":"不必。","verification":"同样A/a拷贝可进入不同配子组合。","pitfall":"把重组与突变完全等同。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":19,"primary_section":"19.4","related_sections":[]},"exam":["遗传频率题分母用2N、杂合各计一拷贝","平衡题先写遗传方式及模型条件，再由隐性q²开方","机制题区分来源、重排、迁移、随机与选择，不凭比例变化唯一归因"],"quick":["变异来源","遗传重排","基因流","漂变与选择","平衡基准"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_19.4","url":"https://openstax.org/books/biology-2e/pages/19-1-population-evolution","page_or_section":"19-1-population-evolution","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_19.4","url":"https://openstax.org/books/biology-2e/pages/19-1-population-evolution","page_or_section":"19-1-population-evolution","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"遗传频率题分母用2N、杂合各计一拷贝","method":"算频率并区分漂变与选择。","principle":"有限群体随机抽样导致漂变。","worked_example_index":2,"verification":"剩余a14个，q.7，拷贝数守恒于幸存样本。","pitfall":"频率下降就说该等位基因有害。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“计算种群等位基因频率及平衡期望”的抽样复核：260+140=400，p+q=1。；若出现“用AA人数100/200当A频率。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“区分选择漂变基因流与变异来源”的抽样复核：剩余a14个，q.7，拷贝数守恒于幸存样本。；若出现“频率下降就说该等位基因有害。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把重组与突变完全等同。","correction":"不必。","verification":"同样A/a拷贝可进入不同配子组合。"}],"illustration_spec":{"title":"等位基因计数与平衡模型","objects":["AA/Aa/aa个体","A/a拷贝计数","p+q","p²/2pq/q²配子结合表","选择/漂变/迁移分支"],"relations":["杂合各一拷贝","二倍体分母2N","q²到q需模型条件","漂变非定向优劣"],"labels":["p=.65","q=.35","2pq","期望非保证","模型条件"],"format":"SVG","priority":"P0","reuse":"V22 B55可复核后补充，勿把模型当所有群体事实","english":"Count two allele copies per diploid individual, one A and one a in each heterozygote. Show p^2,2pq,q^2 as conditional Hardy-Weinberg expectations with explicit assumptions, and separate mutation, recombination, gene flow, drift and selection. Do not equate dominant phenotype frequency with p."}}},"化学1":{"1.1":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":1,"section_id":"1.1","goals":["以组成结构性质变化说明化学问题","用对照与收支评价材料设计的证据"],"prerequisites":["观察与测量","质量与比例"],"flow":["组成结构","宏观性质","变化条件","实验设计","实用与权衡"],"concept_relation":"组成结构；宏观性质；变化条件；实验设计；实用与权衡","deep":["实验通过明确问题、控制条件、测量与重复检验解释。设计新吸水材料时，不只比较湿后总质量，还要扣干材料质量、控制水温接触时间与排除表面附着水等，否则指标可能偏离实际吸水能力。","创造材料常有目标与权衡：吸水、强度、可重复使用、稳定性、成本和环境表现可能不同。一个单项提升不能自动支持“全面最好”，应说明比较基准和使用条件。","计算与模型帮助预测需求和产量，但理论量与实际结果不同。质量收支包含未反应、目标与副产物等；没有可测数据和足够条件，不能把一个理想方程当作可直接量产的完整工艺。","学习本章要形成提问习惯：测了什么，怎样测，能说明哪层结论，还缺什么证据。原创例子用于训练推理，实际实验应按学校规范，不以听起来新颖代替证据。"],"derive":["化学解释链：宏观性质 ↔ 组成/微观结构 ↔ 符号模型及变化条件。","质量型吸水指标示例=(湿后质量−干质量)/干质量，单位可为g水/g干料，测法须明确。","评价方案需同功能、同条件对照，理论可行不等于已验证产品全部性能。"],"examples":[{"q":"冰融化与镁燃烧，哪种主要为物理变化、哪种为化学变化？如何给依据？","given":"纯冰熔化，镁在相应氧气条件燃烧。","analysis":"是否生成新物质。","method":"比较前后化学身份。","principle":"物化变化判据。","steps":["冰仍为H₂O，只改相态，物理变化。","镁生成氧化物等新物质，化学变化。"],"ans":"前物理、后化学。","verification":"吸放热不是唯一判据，熔化也有能量变化。","pitfall":"凡发热或变亮都用作无条件定义。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"干材料2.0 g吸水后规范处理为12.0 g，求每克干料吸水质量，并说明为何不能直接12/2。","given":"已排表面游离水，质量变化主要为吸入水。","analysis":"湿质量包含原材料。","method":"(m湿−m干)/m干。","principle":"质量分项。","steps":["吸水10.0 g。","比10.0/2.0=5.0 g/g。"],"ans":"5.0 g水/g干料。","verification":"2.0+10.0=12.0 g。","pitfall":"把含干料的总湿质量当纯水。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"新材料吸水量是旧材料2倍，能宣布其所有用途都更优吗？","given":"只测一个指标。","analysis":"性能多维且依使用条件。","method":"补强度、耐用与条件比较。","principle":"一指标证据不能覆盖全部需求。","steps":["高吸水可为某目标优势。","仍需脱附、强度、循环寿命、成本和环境等资料，不能全面断言。"],"ans":"不能，只支持该测法下吸水指标更高。","verification":"若吸水后强度丧失，某些用途可能更差。","pitfall":"单指标提升等于全面最佳。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.1","related_sections":[]}],"practice":[{"q":"只看白色粉末能唯一认出食盐吗？","given":"多种物可为白色粉。","analysis":"外观不唯一。","method":"提出独立鉴别。","principle":"结构身份需多证据。","steps":["白色仅宏观性质。","需溶解、反应或仪器等适当证据，不能尝未知粉末。"],"ans":"不能。","verification":"糖、盐等外观可相似而组成不同。","pitfall":"颜色就是唯一身份证。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"同样干料测吸水，一组浸10 min另一组1 h，能直接将差别归材料种类吗？","given":"时间与材料同时改变。","analysis":"混杂变量。","method":"同条件对照。","principle":"控制变量隔离效应。","steps":["接触时间可影响吸入量。","需统一时间温度等并重复，再比较材料。"],"ans":"不能直接。","verification":"同材料不同时间也可差别。","pitfall":"实验有数字就一定公平。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"100 g反应输入最终只收70 g目标产物，是否必违反质量守恒？","given":"系统边界还可能有副产物、气体和残留。","analysis":"目标产物非全部物质。","method":"补完整收支。","principle":"质量守恒针对完整体系。","steps":["其余可在副产物、未反应或排出物。","需测各项，不能只看目标量。"],"ans":"不必。","verification":"70+30其他物即可守恒。","pitfall":"把全部输入必须变同一目标产物。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"干1.5 g材料湿后7.5 g，另一干2.0 g湿后8.0 g，按该指标哪种吸水更高？","given":"测法条件相同。","analysis":"不同干量要归一。","method":"各湿减干再除干。","principle":"单位质量比较。","steps":["第一(7.5−1.5)/1.5=4.0。","第二(8−2)/2=3.0 g/g。"],"ans":"第一更高。","verification":"直接湿质量8大于7.5会给错误排序。","pitfall":"只比总湿重不扣基线归一。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.1","related_sections":[]}],"quiz":{"q":"提出“这材料更环保”作为化学结论，还需怎样把口号变可检验问题？","given":"未说明功能与边界。","analysis":"模糊评价无单一测法。","method":"明确指标条件和比较。","principle":"科学假设需可操作。","steps":["指定相同用途、寿命和生产处置边界。","列能耗、危害、资源或排放指标并用数据检验，分价值选择与实测结果。"],"ans":"先定义指标边界与对照。","verification":"不同指标可能有权衡，不能未测先统一判优。","pitfall":"只写环保二字当完整证据。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.1","related_sections":[]},"exam":["现象题用是否新物及多证据，不靠单一颜色温度","实验比较题扣基线、归一化、控制变量并重复","评价题把目标、指标、条件与限制写成可检验链"],"quick":["组成结构","宏观性质","变化条件","实验设计","实用与权衡"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":3,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.1","url":"https://openstax.org/books/chemistry-2e/pages/1-1-chemistry-in-context","page_or_section":"1-1-chemistry-in-context","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":3,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.1","url":"https://openstax.org/books/chemistry-2e/pages/1-1-chemistry-in-context","page_or_section":"1-1-chemistry-in-context","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"现象题用是否新物及多证据，不靠单一颜色温度","method":"补强度、耐用与条件比较。","principle":"一指标证据不能覆盖全部需求。","worked_example_index":2,"verification":"若吸水后强度丧失，某些用途可能更差。","pitfall":"单指标提升等于全面最佳。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“以组成结构性质变化说明化学问题”的抽样复核：吸放热不是唯一判据，熔化也有能量变化。；若出现“凡发热或变亮都用作无条件定义。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“用对照与收支评价材料设计的证据”的抽样复核：若吸水后强度丧失，某些用途可能更差。；若出现“单指标提升等于全面最佳。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"只写环保二字当完整证据。","correction":"先定义指标边界与对照。","verification":"不同指标可能有权衡，不能未测先统一判优。"}],"illustration_spec":{"title":"化学的三层表达与材料评价","objects":["宏观样品","微观结构模型","符号与方程","干湿质量","性能矩阵"],"relations":["三层证据互相支持","湿质量扣干料","单指标不等于全优"],"labels":["组成","结构","性质","条件","g水/g干料","对照"],"format":"SVG","priority":"P2","reuse":"适合简洁结构图；辅助插画不替代测量关系","english":"Connect macroscopic observations, microscopic composition/structure and symbolic models. Show wet mass as dry material plus absorbed water, with normalized uptake in grams water per gram dry material. Separate one measured benefit from broader performance trade-offs."}},"1.2":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":1,"section_id":"1.2","goals":["用跨学科问题解释化学的桥梁作用","区分不同层次的测量与推断"],"prerequisites":["物质与能量","细胞及材料基础"],"flow":["物理基础","生命分子","地球环境","材料工程","跨层证据"],"concept_relation":"物理基础；生命分子；地球环境；材料工程；跨层证据","deep":["地球与环境问题涉及水气土中的元素形态、溶解迁移和反应。测到某元素总量不一定知道它处于何种化学形态，不同形态可能有不同迁移和生物效应；总量指标和具体机制需分开。","材料与工程把微观组成、加工结构和性能联系起来。相同元素比例可因排列、相态或缺陷不同产生不同性质；因此制造结果还依温度、压力、加工与尺度，不能只用一条化学式预测全部性能。","跨学科数据要统一单位和系统边界。例如能量J与物质的量mol是不同量，需通过每mol能量等关系桥接；溶液浓度、总体积与总质量也不可混为同一指标。","解综合题可把大问题拆成各层可检验子问题，再连接证据。桥接需要明确因果关系及适用范围，不把“相关”一词当作已经证明每一环节，也不因一个学科的资料缺口就否定其他可靠测量。"],"derive":["跨层解释：微观结构/反应 → 材料或细胞过程 → 系统表现，各箭头需证据。","总量=浓度×体积等关系只有单位与对象相容时成立。","每摩尔能量×摩尔数=相应总能量，不能把J与mol当可直接相加的量。"],"examples":[{"q":"研究电池同时涉及哪类化学和物理问题？为什么只测电压不足以知道全部可用能量？","given":"未给电荷容量。","analysis":"电压与总能量不同。","method":"连电极反应和能量关系。","principle":"E=电势差×通过电荷（相应模型）。","steps":["化学看电极反应与物料，物理看电路与能量。","还需电荷容量等，只有V不能确定总J。"],"ans":"需跨学科，电压不足定全部能量。","verification":"同电压不同容量电池可供不同总能量。","pitfall":"电压高就无条件总能量多。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"水样浓度2.0 mg/L，总体积3.0 L，所测物质量多少？若只知浓度能比较两个水库总量吗？","given":"同一被测物与均匀样品模型。","analysis":"浓度是强度非总量。","method":"m=cV。","principle":"质量单位相乘。","steps":["m=2.0×3.0=6.0 mg。","水库还需体积与分布，单浓度不定总量。"],"ans":"6.0 mg；浓度不足比较总量。","verification":"mg/L×L=mg。","pitfall":"把浓度当总污染物质量。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"试管里某分子抑制一种酶，能直接推出药物人体有效且生态无害吗？","given":"只有体外机制线索。","analysis":"跨层推断需中间证据。","method":"分有效性、安全与环境暴露。","principle":"机制可能性与系统结局不同。","steps":["人体需到达浓度、选择性与临床证据。","环境需降解、暴露和生物效应等，不能由单酶结果直接全推。"],"ans":"不能。","verification":"同机制在不同浓度或组织可有不同效果。","pitfall":"跳过多个层次的验证。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.2","related_sections":[]}],"practice":[{"q":"石墨与金刚石都主要由碳组成，为何可有不同性质？","given":"组成元素相同，结构不同。","analysis":"元素相同不等于排列相同。","method":"连键与结构。","principle":"结构影响宏观性质。","steps":["碳的连接与空间排列不同。","因此硬度、导电等可不同，需具体结构解释。"],"ans":"微观结构不同。","verification":"一条元素名称不能确定全部性能。","pitfall":"同元素就同物质同性质。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"题给每mol反应释放50 kJ，.20 mol总释放能量？","given":"同反应和条件。","analysis":"跨mol与能量需比例因子。","method":"n×每mol能。","principle":"能量可加。","steps":["E=.20×50=10 kJ。","单位mol与kJ/mol相消。"],"ans":"10 kJ。","verification":"5倍.20mol为1mol对应50kJ。","pitfall":"把50与.20直接相加。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"测到土壤中某金属总量，能唯一知道其所有化学形态吗？","given":"未做形态分析。","analysis":"总量与形态不同。","method":"列需分离或专门检测。","principle":"不同化合/离子形态可贡献同总元素量。","steps":["总量约束元素质量。","不能单独区分价态、配位与相分布，需其他证据。"],"ans":"不能。","verification":"相同总量可分配在不同物质中。","pitfall":"元素含量即完整结构身份。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"甲水样1 mg/L、100 L，乙2 mg/L、20 L，各总质量及比较。","given":"各样均匀，条件同。","analysis":"强度与总量排序可相反。","method":"cV。","principle":"质量守恒。","steps":["甲100 mg。","乙40 mg；甲总量大而浓度低。"],"ans":"100与40 mg。","verification":"甲体积5倍抵过浓度一半，总量2.5倍。","pitfall":"只看浓度高就说总量大。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.2","related_sections":[]}],"quiz":{"q":"“化学是中心科学，因此只要懂反应式就不需任何生物、工程或环境数据。”错在哪里？","given":"混淆桥梁与替代。","analysis":"不同尺度各有变量和证据。","method":"说明接口及缺项。","principle":"学科连接不取消系统条件。","steps":["反应式给物料与部分机理。","生物调控、工程传递和环境暴露等仍需专门数据，不能由一式全代。"],"ans":"中心作用是连接，不是包办全部证据。","verification":"同反应在不同装置与生态中可有不同表现。","pitfall":"把称号当无限推理权限。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.2","related_sections":[]},"exam":["跨科题逐层写对象、化学过程与可测结果，不跳层","数据题先认浓度/总量、每mol/总能量再统一单位","评价题明确本项测量能支持和不能支持什么"],"quick":["物理基础","生命分子","地球环境","材料工程","跨层证据"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":5,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.2","url":"https://openstax.org/books/chemistry-2e/pages/1-1-chemistry-in-context","page_or_section":"1-1-chemistry-in-context","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":5,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.2","url":"https://openstax.org/books/chemistry-2e/pages/1-1-chemistry-in-context","page_or_section":"1-1-chemistry-in-context","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"跨科题逐层写对象、化学过程与可测结果，不跳层","method":"分有效性、安全与环境暴露。","principle":"机制可能性与系统结局不同。","worked_example_index":2,"verification":"同机制在不同浓度或组织可有不同效果。","pitfall":"跳过多个层次的验证。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用跨学科问题解释化学的桥梁作用”的抽样复核：同电压不同容量电池可供不同总能量。；若出现“电压高就无条件总能量多。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“区分不同层次的测量与推断”的抽样复核：同机制在不同浓度或组织可有不同效果。；若出现“跳过多个层次的验证。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把称号当无限推理权限。","correction":"中心作用是连接，不是包办全部证据。","verification":"同反应在不同装置与生态中可有不同表现。"}],"illustration_spec":{"title":"化学与其他学科的证据接口","objects":["结构反应中心","物理能量","生命过程","地球环境","材料工程","单位桥接"],"relations":["连接而非取代","浓度乘体积得量","每mol能乘mol得能","跨层需独立证据"],"labels":["结构—性质","化学形态","系统边界","mg/L×L","kJ/mol×mol"],"format":"SVG","priority":"P2","reuse":"可用关系图，辅助插画不替代单位与证据链","english":"Map chemistry as a bridge among physics, biological processes, environmental speciation and materials engineering. Show explicit unit bridges concentration times volume and energy-per-mole times amount. Do not depict one molecular observation as automatically proving whole-organism or ecosystem outcomes."}},"1.3":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":1,"section_id":"1.3","goals":["联系化学应用与物料资源限制","用多指标证据比较社会技术方案"],"prerequisites":["质量守恒","用途与风险基础"],"flow":["社会用途","功能单位","物料收支","风险与暴露","多指标决策"],"concept_relation":"社会用途；功能单位；物料收支；风险与暴露；多指标决策","deep":["能源技术涉及能量转化与物料来源，燃烧、储能和电化学过程各有条件。提高效率可以减少相同服务的输入，但总需求、能源结构和设备生命周期会影响最终排放，不用单一“新能源”标签代全部账目。","材料提供轻量、耐用和加工等优势，同时产生资源与处置问题。使用寿命、维修、再用、回收与末端处理均重要；焚烧回收能量不等于把材料全部回为原单体，某些可降解声明也需具体环境条件。","饮水与污染治理要区分去除颗粒、改变化学形态、杀灭微生物等目标。水变清不证明所有溶解物或病原已除去；看不见污染不能当不存在，处理效果应由适合指标测量。","社会决策包含事实、成本和价值权衡。化学证据能说明效率、毒性、残留和反应路径，却不能把尚未测的后果冒充定论；提出明确对照、单位和长期监测，比泛称“发展化学就能解决一切”更有帮助。"],"derive":["公平比较需同功能单位、同使用寿命和明确生产—使用—处置边界。","去除率=(输入量−输出量)/输入量；浓度降低不等于污染物质量已消失，稀释与转移需区分。","效率、危害、暴露和资源是不同指标，不能自动互代。"],"examples":[{"q":"过滤后水变清，能据此保证完全可直接饮用吗？","given":"只观察浑浊下降。","analysis":"颗粒与溶解物/微生物不同。","method":"列处理目标和验证。","principle":"可见性不是全部水质。","steps":["过滤可能除部分悬浮物。","溶解污染物和病原等需相应检测处理，不能只由清澈保证。"],"ans":"不能。","verification":"透明溶液也可含有害溶解物。","pitfall":"看不见就等于无污染。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"处理前污染物100 mg、后20 mg，按同边界去除率多少？若80 mg转入污泥，是否已从环境中完全消失？","given":"质量已测。","analysis":"去水相与全环境销毁不同。","method":"(100−20)/100。","principle":"物料收支。","steps":["去除率80%。","80 mg可能在污泥，仍需处置，不是质量消失。"],"ans":"80%，不代表全部无害消失。","verification":"20+80=100 mg。","pitfall":"水中少了就称元素被消灭。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"甲包装一次耗10 g材料、可稳定用10次，乙一次耗2 g且只用1次；只按每次材料量哪种较低？能判全部环境表现吗？","given":"甲确实复用10次，忽略清洗等只比题给指标。","analysis":"统一服务次数。","method":"甲10/10、乙2/1。","principle":"功能单位比较。","steps":["甲1 g/次，乙2 g/次。","甲此指标低，但清洗、运输、原料和处置等未知。"],"ans":"甲单位服务材料低；不能全面判环境最优。","verification":"10次服务甲10g、乙20g。","pitfall":"只比单件质量2<10。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.3","related_sections":[]}],"practice":[{"q":"施肥量翻倍，产量必翻倍吗？","given":"其他限制因素未变。","analysis":"养分可能不再为限制。","method":"列水光温及过量影响。","principle":"生长受多因素和响应范围。","steps":["原缺养分时可受益。","超过需求后不一定增产，还可流失，不能按比例无限外推。"],"ans":"不必。","verification":"非限制因素增加不保证总产出增加。","pitfall":"有用就越多越好。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"把污染水加等体积清水，浓度约减半，污染物总质量会减半吗？","given":"无反应损失，体积近似相加。","analysis":"稀释改变浓度不改量。","method":"m=cV。","principle":"质量守恒。","steps":["V变2倍、c变1/2。","乘积不变。"],"ans":"不会，总量不变。","verification":"一半浓度乘两倍体积仍同质量。","pitfall":"把稀释当去除销毁。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"天然化合物一定比同结构同纯度合成物更安全吗？","given":"比较化学身份相同样品。","analysis":"来源不是自动安全判据。","method":"核剂量暴露杂质。","principle":"风险依据性质与暴露。","steps":["同结构纯样有相同关键化学特征。","实际杂质与使用方式可不同，需具体证据。"],"ans":"不能仅凭来源判。","verification":"天然也可有毒，人工也可安全用于规定场景。","pitfall":"来源标签代替检测。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"设备原输入1000 kJ提供同服务，改进后800 kJ，节能率多少？能据此保证整个城市能耗也减20%吗？","given":"设备服务相同，城市需求未知。","analysis":"局部强度与总需求不同。","method":"(1000−800)/1000。","principle":"边界与比例。","steps":["设备节能20%。","城市使用量和设备数量等可能变，不能自动推广总能耗同降20%。"],"ans":"20%；城市总量需更多数据。","verification":"效率与使用规模共同决定总量。","pitfall":"单位服务改进直接等于系统总量变化。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.3","related_sections":[]}],"quiz":{"q":"“焚烧塑料发电”能否直接称所有原料已材料回收并无任何排放？","given":"过程把化学物转为其他产物并回收部分能量。","analysis":"能源回收与材料再生不同。","method":"追踪物料和能量。","principle":"反应收支必须完整。","steps":["可回收部分能量。","原聚合物不等于全部回原单体，气体灰渣及处理等需评价。"],"ans":"不能。","verification":"能量利用不使碳等原子凭空消失。","pitfall":"将一种回收途径当全部指标满分。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.3","related_sections":[]},"exam":["社会应用题先写具体机制与目标，再列条件和权衡","处理题跟踪总质量去向，区分稀释、转移和转化","方案比较统一服务与边界，不以标签或单件重量直接判优"],"quick":["社会用途","功能单位","物料收支","风险与暴露","多指标决策"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":9,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.3","url":"https://www.acs.org/green-chemistry-sustainability/principles/12-principles-of-green-chemistry.html","page_or_section":"12-principles-of-green-chemistry.html","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":9,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.3","url":"https://www.acs.org/green-chemistry-sustainability/principles/12-principles-of-green-chemistry.html","page_or_section":"12-principles-of-green-chemistry.html","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"社会应用题先写具体机制与目标，再列条件和权衡","method":"甲10/10、乙2/1。","principle":"功能单位比较。","worked_example_index":2,"verification":"10次服务甲10g、乙20g。","pitfall":"只比单件质量2<10。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“联系化学应用与物料资源限制”的抽样复核：透明溶液也可含有害溶解物。；若出现“看不见就等于无污染。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“用多指标证据比较社会技术方案”的抽样复核：10次服务甲10g、乙20g。；若出现“只比单件质量2<10。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"将一种回收途径当全部指标满分。","correction":"不能。","verification":"能量利用不使碳等原子凭空消失。"}],"illustration_spec":{"title":"化学应用的物料与功能单位","objects":["水处理颗粒/溶解物","100mg分流20/80","复用与一次包装","设备节能与城市规模"],"relations":["稀释不销毁质量","去除转污泥仍需处置","按每次服务比较","局部效率不等全系统量"],"labels":["物料去向","功能单位","20+80=100","g/次","边界"],"format":"SVG","priority":"P1","reuse":"无完全匹配旧图；收支结构图优于装饰插画","english":"Show water treatment as distinct removal/transfer/transformation steps, with100 mg partitioned into20 mg water and80 mg sludge. Compare reusable and single-use packaging per service rather than per item, and separate device efficiency from citywide demand. Do not depict dilution as destruction."}},"1.4.1":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":1,"section_id":"1.4.1","goals":["以质子数区分元素并分清原子离子同位素","正确读取元素符号及元素与单质的关系"],"prerequisites":["原子核与电子","化学式"],"flow":["Z元素身份","原子离子","同位素A/N","符号大小写","元素与单质"],"concept_relation":"Z元素身份；原子离子；同位素A/N；符号大小写；元素与单质","deep":["元素符号通常首字母大写、第二字母小写，Co与CO含义不同。Co为钴符号，CO为含C与O的化学式；把大小写排错可从一个元素变成两个元素组成的化合物，不能当排版小问题。","元素与单质也不同：氧元素可存在于O₂、O₃及多种化合物中，O₂与O₃是不同单质形式。一个化合物中有某元素不表示其中混着该元素的游离单质，水中的氧不等于气泡O₂。","化学式下标说明相应粒子或组成单位的原子比例，式前系数乘整个式。数元素种类时看不同元素符号，而不是数原子总个数；2H₂O有H、O两种元素，共对应4H、2O原子。","元素相对原子质量可在给定同位素丰度下作加权平均，不必等于任何一个同位素的整数质量数。题设假想丰度不可冒充自然实际丰度，核质量与电子等精确影响需按题给数据层次处理。"],"derive":["Z=质子数；质量数A=Z+中子数N；中性原子电子数Z，离子另按电荷。","同位素：同Z不同N；元素符号大小写要准确。","给定近似同位素质量mᵢ及数目分数fᵢ，平均质量=Σfᵢmᵢ，Σfᵢ=1。"],"examples":[{"q":"Na原子质子11电子11，Na⁺质子11电子10，是同一元素吗？电荷差从哪里来？","given":"核内质子未变。","analysis":"元素身份与电荷分开。","method":"比较Z与质子电子差。","principle":"Z定义元素，电荷由净电荷。","steps":["二者Z都11，属同元素。","Na⁺比质子少1电子，带+1；不是多了一个质子。"],"ans":"同钠元素，电荷差为少一个电子。","verification":"11正与10负得净+1。","pitfall":"电子数变就说新元素。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.1","related_sections":[]},{"q":"Co、CO和2H₂O各含几种元素？2H₂O对应多少H、O原子？","given":"严格大小写。","analysis":"符号、化学式和系数不同。","method":"逐式读取。","principle":"元素符号及全式乘系数。","steps":["Co一种钴；CO两种C与O。","2H₂O两种H/O，对应4个H原子、2个O原子。"],"ans":"1、2、2种；4个H原子、2个O原子。","verification":"每个H₂O含2H1O，乘2。","pitfall":"把Co当C与小写o或只让系数乘H。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.1","related_sections":[]},{"q":"假想样品同位素质量近似12与13，数目占75%和25%，平均质量？能称此为自然碳的真实丰度吗？","given":"数据明确是假想。","analysis":"加权且不可误归实际来源。","method":"12×.75+13×.25。","principle":"平均质量按个数比例。","steps":["得到9+3.25=12.25。","这是题设样品，不提供自然丰度事实。"],"ans":"12.25 u，不能冒称自然丰度。","verification":"在12和13之间且靠占多的12。","pitfall":"把课堂假设写成现实常数。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.1","related_sections":[]}],"practice":[{"q":"质子6中子6与质子6中子7的中性原子，是两元素还是同位素？质量数各多少？","given":"Z相同。","analysis":"比较质子与中子角色。","method":"A=Z+N。","principle":"元素与同位素定义。","steps":["同为碳元素。","A分别12和13，为同位素。"],"ans":"同位素，质量数12、13。","verification":"电子数均6但中子不同。","pitfall":"把不同A当不同元素。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.1","related_sections":[]},{"q":"O₂与O₃是两种元素吗？","given":"只有氧符号。","analysis":"分子组成形式不同不等于元素不同。","method":"数元素种类。","principle":"同素异形单质与元素。","steps":["都只含O元素。","分子原子数不同，可为不同单质形式。"],"ans":"不是，两种单质形式但同一元素。","verification":"化学式下标不改变原子Z。","pitfall":"一个化学式就对应一种不同元素。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.1","related_sections":[]},{"q":"水含氧，能说纯水里本来混着氧气吗？","given":"H₂O组成。","analysis":"化合物元素与游离单质不同。","method":"比较结合状态。","principle":"元素可存在化合物中。","steps":["O在H₂O连接中。","不等于有游离O₂，实际溶解气另需证据。"],"ans":"不能如此解释。","verification":"电解生成O₂是化学变化，不是简单筛出原有气泡。","pitfall":"含元素就等于混入同名单质。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.1","related_sections":[]},{"q":"某离子质子17、电子18、中子18，元素、质量数、电荷各是什么？","given":"各粒子数给定。","analysis":"Z、A与电荷分别算。","method":"Z17，A17+18，净17−18。","principle":"定义与电荷守恒。","steps":["属氯元素，质量数35。","净电荷−1，即相应Cl⁻。"],"ans":"氯、35、−1。","verification":"同位素身份由核数决定，离子电荷取决电子差。","pitfall":"把电子18当氩元素。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.1","related_sections":[]}],"quiz":{"q":"一种原子失去电子后能变另一元素吗？普通化学反应与核变化应怎样区分？","given":"未改变质子。","analysis":"失电子不改Z。","method":"追踪核电荷数。","principle":"元素身份由Z。","steps":["普通电离只改电荷及电子结构。","改变元素需Z改变的核过程，不等同普通化学键重排。"],"ans":"仅失电子不能。","verification":"Na到Na⁺仍Z11。","pitfall":"把化学反应的电子转移当元素转换。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.1","related_sections":[]},"exam":["粒子题分别列Z、N、e和电荷，不用一个数包全部","符号题严格大小写，系数乘整个式，下标不当元素种类数","同位素题加权数据标来源，元素与单质结合状态分清"],"quick":["Z元素身份","原子离子","同位素A/N","符号大小写","元素与单质"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":12,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.4.1","url":"https://openstax.org/books/chemistry-2e/pages/2-3-atomic-structure-and-symbolism","page_or_section":"2-3-atomic-structure-and-symbolism","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":12,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.4.1","url":"https://openstax.org/books/chemistry-2e/pages/2-3-atomic-structure-and-symbolism","page_or_section":"2-3-atomic-structure-and-symbolism","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"粒子题分别列Z、N、e和电荷，不用一个数包全部","method":"12×.75+13×.25。","principle":"平均质量按个数比例。","worked_example_index":2,"verification":"在12和13之间且靠占多的12。","pitfall":"把课堂假设写成现实常数。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“以质子数区分元素并分清原子离子同位素”的抽样复核：11正与10负得净+1。；若出现“电子数变就说新元素。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“正确读取元素符号及元素与单质的关系”的抽样复核：每个H₂O含2H1O，乘2。；若出现“把Co当C与小写o或只让系数乘H。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把化学反应的电子转移当元素转换。","correction":"仅失电子不能。","verification":"Na到Na⁺仍Z11。"}],"illustration_spec":{"title":"元素粒子与符号层次","objects":["Na/Na⁺核电子表","同位素Z/N表","Co与CO","O₂/O₃/H₂O","系数下标"],"relations":["Z不变仍同元素","同位素同Z不同N","Co与CO不可混","2乘全H₂O"],"labels":["Z","N","e⁻","A=Z+N","元素≠单质","假想丰度"],"format":"SVG","priority":"P0","reuse":"原子结构旧图可局部复用但需核电荷和数目","english":"Separate element identity by proton number from ion charge and isotope neutron number. Contrast Co with CO, and O2/O3 with oxygen bound in H2O. Show that2H2O contains4 H and2 O atoms and label any isotope abundance example as hypothetical, not natural data."}},"1.4.2":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":1,"section_id":"1.4.2","goals":["按组成区分纯物质单质化合物和混合物","把均一性化学结合与分离证据分开"],"prerequisites":["元素与化学式","组成比例"],"flow":["物质组分","纯与混","单质化合物","均相尺度","分离与组成"],"concept_relation":"物质组分；纯与混；单质化合物；均相尺度；分离与组成","deep":["均相混合物在指定尺度呈均一，非均相有可辨相或组成差异。溶液、悬浮体系和胶体的分散尺度与性质不同，观察条件影响“看起来均一”，不能只用肉眼一眼给所有体系的微观身份。","混合物组成可变，常能利用物性差异分离相应组分，但方法必须适合具体体系。蒸发可回收食盐水中的盐，不表示所有混合物都能用同法；化合物分解成其他物质则属于化学转化。","纯物质的特征物性需注明温压纯度，混合物性质随组成变化可帮助判断，但单一测试通常不构成绝对证明。沸点范围、熔点等有常用线索，也要注意共沸或相变细节，不能把一个现象推广无例外。","计算组成时说清质量分数、摩尔分数还是其他比例，分母用完整样品相应量。稀释不改溶质量，蒸发若只失溶剂可提高质量分数；若析出、挥发或反应发生则需重新列收支。"],"derive":["纯物质→单质或化合物；混合物可均相或非均相，均一不等于纯。","质量分数w=m组分/m混合物；需同质量单位。","化合物中的元素结合不等于游离单质混合，化学式与组成比例只能在相应物质身份下解释。"],"examples":[{"q":"纯O₂、纯H₂O、空气、澄清食盐水分别怎样分类？","given":"按常见理想纯样和普通混合空气。","analysis":"先物质种类，再元素。","method":"逐级分类。","principle":"组成而非外观判据。","steps":["O₂纯单质，H₂O纯化合物。","空气和食盐水是混合物，后者可均一但非纯。"],"ans":"单质、化合物、混合物、混合物。","verification":"H₂O两元素并不意味着两物质混合。","pitfall":"透明均一就一律纯。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.2","related_sections":[]},{"q":"把H₂与O₂按2:1摩尔混合，是否立刻成为纯水？","given":"尚未反应。","analysis":"数量比不建立新连接。","method":"比较粒子身份。","principle":"混合与化合不同。","steps":["仍有H₂和O₂两组分。","需相应反应生成H₂O后才谈产物，正确计量比不等于反应已经发生。"],"ans":"不是，仍为混合物。","verification":"粒子模型应画H—H和O—O而非自行全变水。","pitfall":"配比符合就称化合物。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.2","related_sections":[]},{"q":"10 g食盐和90 g水，未饱和且只蒸发20 g水，盐质量分数怎样变？","given":"无盐损失和反应。","analysis":"分母变而溶质量不变。","method":"先总100，后80。","principle":"质量收支。","steps":["初w=10/100=10%。","后w=10/80=12.5%。"],"ans":"10%增至12.5%。","verification":"余水70g加盐10g共80g。","pitfall":"把盐也按蒸发比例减少或除90。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.2","related_sections":[]}],"practice":[{"q":"O₂与O₃混在一起只有一种元素，属于纯物质吗？","given":"两种分子身份。","analysis":"元素种类不等于物质种类。","method":"数实际组分。","principle":"纯样需一种化学物质。","steps":["O₂和O₃不同单质形式。","混合时仍两组分，非纯。"],"ans":"不是。","verification":"可只有一种元素而为混合物。","pitfall":"一种元素必一纯物。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.2","related_sections":[]},{"q":"NaCl晶体能说由许多独立NaCl小分子构成吗？","given":"常见离子晶体模型。","analysis":"化合物不必分子实体。","method":"按离子晶格解释。","principle":"式表示组成单位比。","steps":["Na⁺与Cl⁻构成延展晶格。","NaCl给1:1化学计量，不必指独立二原子分子。"],"ans":"不宜，应用离子晶格。","verification":"分类为化合物仍成立。","pitfall":"所有化学式都等同分子。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.2","related_sections":[]},{"q":"食盐水澄清且无肉眼颗粒，是否证明只有水一种物？","given":"溶解盐可能存在。","analysis":"检测尺度与组分不同。","method":"用蒸发或相应分析。","principle":"均一混合物。","steps":["离子可分散而不可直接见。","需适当方法检出，透明不排除盐。"],"ans":"不能。","verification":"过滤也未必去掉溶解离子。","pitfall":"肉眼看不见即不存在。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.2","related_sections":[]},{"q":"混合物总50 g，A占30%，加10 g不含A的B且无反应损失，A质量与新分数？","given":"初A15g。","analysis":"新增另一组分稀释。","method":"A固定，总变60。","principle":"质量守恒。","steps":["mA=.30×50=15g。","新w=15/60=25%。"],"ans":"15 g与25%。","verification":"15+45=60g。","pitfall":"新分数仍30%或把A也增加。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.2","related_sections":[]}],"quiz":{"q":"某样品可用物理方法分出两种稳定组分，是否支持混合物？能把所有“能分开”都直接当同一判据吗？","given":"明确未发生化学转化。","analysis":"物理分离与化学分解不同。","method":"先辨过程类型。","principle":"混合物含不同组分。","steps":["在无化学变化前提下分出组分支持混合。","若靠反应分解如水电解，则纯化合物也可给多物质，不能混用。"],"ans":"支持，但须确认是物理分离。","verification":"电解水反例说明“能分开”措辞过宽。","pitfall":"把化合物可分解说成它本来是混合物。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.2","related_sections":[]},"exam":["分类题逐级数物质组分与元素，均一不替纯度","粒子图按分子/原子/离子晶格实际模型，不把式都画成分子","组成题明确分母与过程收支，蒸发稀释不自动改溶质量"],"quick":["物质组分","纯与混","单质化合物","均相尺度","分离与组成"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.4.2","url":"https://openstax.org/books/chemistry-2e/pages/1-2-phases-and-classification-of-matter","page_or_section":"1-2-phases-and-classification-of-matter","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.4.2","url":"https://openstax.org/books/chemistry-2e/pages/1-2-phases-and-classification-of-matter","page_or_section":"1-2-phases-and-classification-of-matter","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"分类题逐级数物质组分与元素，均一不替纯度","method":"先总100，后80。","principle":"质量收支。","worked_example_index":2,"verification":"余水70g加盐10g共80g。","pitfall":"把盐也按蒸发比例减少或除90。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按组成区分纯物质单质化合物和混合物”的抽样复核：H₂O两元素并不意味着两物质混合。；若出现“透明均一就一律纯。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“把均一性化学结合与分离证据分开”的抽样复核：粒子模型应画H—H和O—O而非自行全变水。；若出现“配比符合就称化合物。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把化合物可分解说成它本来是混合物。","correction":"支持，但须确认是物理分离。","verification":"电解水反例说明“能分开”措辞过宽。"}],"illustration_spec":{"title":"物质分类与粒子模型","objects":["O₂纯样","H₂O纯样","H₂/O₂混合","NaCl晶格","盐水分散"],"relations":["H₂/O₂未反应不画水","O₂/O₃可一元素多组分","盐晶格不画独立NaCl分子"],"labels":["纯物质","单质","化合物","混合物","均一≠纯"],"format":"SVG","priority":"P0","reuse":"已有分类图可核粒子结构后复用","english":"Build a classification tree with accurate particle examples: pure O2, pure H2O, unreacted H2/O2 mixture, extended NaCl ionic lattice and salt solution. Show that O2/O3 can be a mixture of one element and that visual homogeneity does not prove purity."}},"1.4.3":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":1,"section_id":"1.4.3","goals":["用粒子运动解释三态及相变","区分质量粒子数与体积压力的变化"],"prerequisites":["物质粒子模型","温度与密度"],"flow":["粒子运动","宏观三态","六相变","相变守恒","温压与能量"],"concept_relation":"粒子运动；宏观三态；六相变；相变守恒；温压与能量","deep":["固→液为熔化，液→固为凝固；液→气为汽化，气→液为液化；固→气为升华，气→固为凝华。名称按起终状态判断，不凭“冷了”就统一叫凝固，水蒸气直接结霜是凝华。","普通相变不改变相应化学粒子身份与元素数。干冰升华主要仍为CO₂，水汽化仍为H₂O；密闭不漏的单纯相变中总质量不因体积增大而增加，粒子模型应保留数量。","纯物质在固定压力下相变共存时温度可在特征温度附近保持而能量仍转移。加热曲线平台不表示停止吸热，能量用于改变聚集状态；复杂混合物或非晶材料可有范围，不把平台规则无条件套任何材料。","压缩气体在温度和物质的量固定的理想模型中使压力上升，分子数不凭压缩增加。改变相态或温压后，相同质量占体积可大变；需要区分容器外观、气体量和测量条件。"],"derive":["六种相变按起终态：熔化/凝固、汽化/液化、升华/凝华。","无化学变化且不漏物：m和相应粒子总数保持，V可改变。","固定n、T理想气PV为常量；相变平台仍可吸放热，不以ΔT=0推能量转移0。"],"examples":[{"q":"水蒸气直接在冷表面结霜，干冰直接变气，分别是什么相变？","given":"明确没有液相中间步骤的模型。","analysis":"按起终物态。","method":"气→固与固→气。","principle":"相变定义。","steps":["结霜为凝华。","干冰变气为升华，仍主要CO₂。"],"ans":"凝华、升华。","verification":"不是气→液的液化，也不是液→固的凝固。","pitfall":"所有变固都叫凝固。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.3","related_sections":[]},{"q":"密闭系统18 g纯水全部变水蒸气，无分解无漏失，质量与H₂O粒子数怎样？体积必相同吗？","given":"单纯相变。","analysis":"物质量与排列体积不同。","method":"守恒粒子身份数量。","principle":"相变不创造消灭分子。","steps":["质量仍18 g，相应H₂O分子数不变。","体积与容器、温压有关，不必等于原液体体积。"],"ans":"质量粒子数保持，体积不必同。","verification":"若按M18则仍1mol水，只相态改变。","pitfall":"分子间距大就说分子数增多。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.3","related_sections":[]},{"q":"理想气在固定T和n下体积由4 L压到2 L，原压100 kPa，末压和粒子数？","given":"温度控制且近理想。","analysis":"PV常量，n未变。","method":"P₁V₁=P₂V₂。","principle":"气体模型。","steps":["P₂=100×4/2=200 kPa。","粒子数不变，只密度及碰撞情况等改变。"],"ans":"200 kPa，粒子数不变。","verification":"体积减半P加倍，P V同400 kPa·L。","pitfall":"把压强加倍说成粒子数加倍。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.3","related_sections":[]}],"practice":[{"q":"固体粒子是否完全不动？","given":"典型温度下固态模型。","analysis":"固定平均位置不等于静止。","method":"说明振动。","principle":"粒子热运动。","steps":["粒子可在平衡位置附近振动。","无整体自由流动不等于无微观运动。"],"ans":"不是。","verification":"加热常增大振动等效应。","pitfall":"图上画固定点就当绝对静止。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.3","related_sections":[]},{"q":"水在衣服表面逐渐干去，是否必须整体先到100°C？","given":"常压普通干燥。","analysis":"蒸发可低于沸点。","method":"表面汽化。","principle":"蒸发与沸腾不同。","steps":["表面可持续有分子进入气相。","不需全体先到沸点，速度受环境等影响。"],"ans":"不必须。","verification":"室温晾干即符合。","pitfall":"汽化全等于沸腾。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.3","related_sections":[]},{"q":"某纯物质固定压强熔化时温度不变，是否无热量输入？","given":"正在吸热熔化共存阶段。","analysis":"温度与能量转移不一一同义。","method":"解释潜热。","principle":"能量用于聚集状态改变。","steps":["温度平台可伴持续吸热。","不能以ΔT0代入单相mcΔT后断言全部Q0。"],"ans":"不是，可有熔化热。","verification":"单相公式前提不满足。","pitfall":"任何能量输入必让温度立刻升高。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.3","related_sections":[]},{"q":"同一气体体积10 L和5 L，在同T同P理想条件下，粒子数比？若是同一封闭样本被压缩又怎样？","given":"分别明确两个情境。","analysis":"条件相同的不同样本与变压封闭过程不同。","method":"V比与n比。","principle":"理想气关系及守恒。","steps":["同T/P两样本n比2:1。","同一封闭样本压缩则n不变，压力等条件须相应变化。"],"ans":"前2:1，后不变。","verification":"不能同时声称封闭n不变、T/P均不变却V减半。","pitfall":"把不同题设条件混用。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.3","related_sections":[]}],"quiz":{"q":"粒子图把液态10个水分子画成气态20个更大的水分子，作为密闭单纯汽化示意应修什么？","given":"无反应无物质交换。","analysis":"粒子身份数量不变。","method":"保留数量与分子大小模型，改间距排列。","principle":"物质守恒与尺度。","steps":["气态仍10个相同H₂O表示单位。","主要改变分布间距及运动，不能凭相变倍增数量或放大分子本体。"],"ans":"修数量和粒子大小，说明图非按真实距离比例。","verification":"各元素计数前后必须相同。","pitfall":"把宏观膨胀画成分子自身胀大。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.3","related_sections":[]},"exam":["相变题按起终状态命名，化学粒子身份另核","粒子图守数量和结构，体积变化主要由排列间距","气体题先说明同T/P不同样本还是封闭过程，平台温度不等于无能量"],"quick":["粒子运动","宏观三态","六相变","相变守恒","温压与能量"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":15,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.4.3","url":"https://openstax.org/books/chemistry-2e/pages/1-2-phases-and-classification-of-matter","page_or_section":"1-2-phases-and-classification-of-matter","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":15,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.4.3","url":"https://openstax.org/books/chemistry-2e/pages/1-2-phases-and-classification-of-matter","page_or_section":"1-2-phases-and-classification-of-matter","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"相变题按起终状态命名，化学粒子身份另核","method":"P₁V₁=P₂V₂。","principle":"气体模型。","worked_example_index":2,"verification":"体积减半P加倍，P V同400 kPa·L。","pitfall":"把压强加倍说成粒子数加倍。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用粒子运动解释三态及相变”的抽样复核：不是气→液的液化，也不是液→固的凝固。；若出现“所有变固都叫凝固。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“区分质量粒子数与体积压力的变化”的抽样复核：体积减半P加倍，P V同400 kPa·L。；若出现“把压强加倍说成粒子数加倍。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把宏观膨胀画成分子自身胀大。","correction":"修数量和粒子大小，说明图非按真实距离比例。","verification":"各元素计数前后必须相同。"}],"illustration_spec":{"title":"三态粒子与相变守恒","objects":["等数同型粒子的固液气","六方向相变箭头","加热平台","封闭气压缩"],"relations":["同数同大小表示单位","气态间距增大非粒子变大","气→固凝华","平台仍传能"],"labels":["熔化","凝固","汽化","液化","升华","凝华","非按比例"],"format":"SVG","priority":"P0","reuse":"旧三态图可核粒子数与箭头名称后复用","english":"Draw equal numbers of identical particles across solid, liquid and gas panels, changing arrangement and spacing rather than particle size. Label all six phase transitions correctly, especially deposition gas-to-solid, and show that a heating plateau can still involve energy transfer."}},"1.4.4":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":1,"section_id":"1.4.4","goals":["区分性质描述与变化事件","以新物质和证据判断变化并追踪体系收支"],"prerequisites":["物质三态","元素和混合物"],"flow":["性质与事件","身份改变","观测线索","可逆性限制","体系收支"],"concept_relation":"性质与事件；身份改变；观测线索；可逆性限制；体系收支","deep":["可逆性也不能单独区分两类。玻璃打碎难原样恢复仍主要为物理变化，某些化学平衡可逆；把“能恢复”当物理、“不能恢复”当化学会产生错误。","溶解要看具体物质和相互作用，常规食盐溶解可从分散与回收讨论，而氧化钙加水生成氢氧化钙为反应。不能只凭“遇水”“放热”或“消失看不见”统一定类，需证据和模型。","化学变化重排原子与电子，不把元素质量凭空创造或消灭。开放容器中气体逸出可使所称容器内容质量降低，完整体系仍应列出逸出物；物理蒸发也可有相同称量现象，质量下降不是独占化学判据。","做综合判断应写性质类别、实际过程与依据，再说明观测尚不足之处。若未取得产物证据，使用“支持某解释、还需核实”等准确表述；不要把猜测包装成唯一事实。"],"derive":["性质是可描述能力/特征；变化是发生的过程，不能只按词语相似分类。","生成新化学物质是化学变化核心；颜色/热/气泡等为线索，需条件与其他证据。","完整体系质量收支：初物质=最终留存+逸出/转移等（无核过程的课程条件）。"],"examples":[{"q":"“酒精易燃”与“点燃酒精生成新物质”，分别是性质还是变化，物理或化学？","given":"正常燃烧条件。","analysis":"能力与事件分开。","method":"按描述对象。","principle":"化学性质/化学变化定义。","steps":["易燃是化学性质。","实际燃烧生成新物是化学变化。"],"ans":"前化学性质，后化学变化。","verification":"同一化学主题仍有不同描述层次。","pitfall":"把任何含燃烧词都只叫变化。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.4","related_sections":[]},{"q":"水沸腾冒气泡、石灰石加酸放气，都有气泡，能用“气泡”唯一判断化学变化吗？","given":"前为水相变，后按碳酸盐反应。","analysis":"同现象不同机制。","method":"比较气体身份和前后物质。","principle":"新物质判据。","steps":["沸腾气体主要水蒸气，为物理变化。","石灰石与酸可生成CO₂等新物，为化学变化。"],"ans":"不能只凭气泡。","verification":"鉴别气体与物料证据可区分。","pitfall":"看到气泡全叫反应。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.4","related_sections":[]},{"q":"开放容器反应前总100 g，后内容96 g，已知逸出4 g气体，是否违反质量守恒？若不知气体来源能否单靠降重定化学变化？","given":"称量边界只剩内容物。","analysis":"完整体系含逸出。","method":"96+4。","principle":"质量收支。","steps":["完整最终100 g，与初相同。","仅降重也可为物理蒸发，不能独占判化学。"],"ans":"不违反；降重不足单独定类。","verification":"边界解释解决表观损失。","pitfall":"漏气体就说质量被消灭。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.4","related_sections":[]}],"practice":[{"q":"密度、可燃性、熔点、与酸放氢能力分别属哪类性质？","given":"均是性质描述。","analysis":"是否需生成新物质。","method":"逐项分类。","principle":"物化性质定义。","steps":["密度、熔点为物理性质。","可燃性、相应放氢反应能力为化学性质。"],"ans":"物理、化学、物理、化学。","verification":"测熔点相变通常不改变身份。","pitfall":"按是否需要仪器分类。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.4","related_sections":[]},{"q":"玻璃碎裂难恢复，必是化学变化吗？","given":"未给新物质生成。","analysis":"不可逆外观非充分判据。","method":"看组成身份。","principle":"形状改变可属物理。","steps":["主要是形状和碎片分布改变。","难原样拼回不等于发生化学反应。"],"ans":"不必，通常为物理变化。","verification":"可逆性不是核心标准。","pitfall":"不方便恢复就一定化学。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.4","related_sections":[]},{"q":"无色酸碱混合后仍无色，能证明没有反应吗？","given":"不知产物/温度/离子等证据。","analysis":"无颜色不是无变化。","method":"提出其他检测。","principle":"反应可无明显色变。","steps":["可发生中和等过程。","需适当证据，不能只凭颜色不变否定。"],"ans":"不能。","verification":"许多生成物也无色。","pitfall":"只有变色才叫化学。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.4","related_sections":[]},{"q":"20 g液体蒸发5 g，无分解，残液质量和变化类别？能由质量减少判断元素变了多少吗？","given":"只发生相变并逸出。","analysis":"质量转移非元素改变。","method":"20−5。","principle":"物理变化与收支。","steps":["残15 g。","为物理蒸发，5 g转到气相，元素身份不因相变改变。"],"ans":"15 g、物理变化。","verification":"15+5=20g，完整量保持。","pitfall":"把少掉的质量当元素消失或变其他元素。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.4","related_sections":[]}],"quiz":{"q":"观察遇水放热，能否直接断言是化学反应？应怎样补证据？","given":"只有温度线索。","analysis":"物理溶解等也可伴热效应。","method":"检测前后身份并设对照。","principle":"热不独占化学变化。","steps":["比较是否有新化学物质、原物是否可按适当方法回收等。","结合浓度状态及其他数据，不从单一放热定类。"],"ans":"不能直接，需要产物与过程证据。","verification":"相变与混合也可交换热，反例有效。","pitfall":"能量变化一律等同化学变化。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":1,"primary_section":"1.4.4","related_sections":[]},"exam":["分类答题先区分性质和事件，再看身份是否改变","现象判断至少连产物或过程证据，色/热/气泡不可独占","称量题画完整边界与转移，开放系统降重不否定守恒"],"quick":["性质与事件","身份改变","观测线索","可逆性限制","体系收支"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":15,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.4.4","url":"https://openstax.org/books/chemistry-2e/pages/1-3-physical-and-chemical-properties","page_or_section":"1-3-physical-and-chemical-properties","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":15,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_1.4.4","url":"https://openstax.org/books/chemistry-2e/pages/1-3-physical-and-chemical-properties","page_or_section":"1-3-physical-and-chemical-properties","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"分类答题先区分性质和事件，再看身份是否改变","method":"96+4。","principle":"质量收支。","worked_example_index":2,"verification":"边界解释解决表观损失。","pitfall":"漏气体就说质量被消灭。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“区分性质描述与变化事件”的抽样复核：同一化学主题仍有不同描述层次。；若出现“把任何含燃烧词都只叫变化。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“以新物质和证据判断变化并追踪体系收支”的抽样复核：边界解释解决表观损失。；若出现“漏气体就说质量被消灭。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"能量变化一律等同化学变化。","correction":"不能直接，需要产物与过程证据。","verification":"相变与混合也可交换热，反例有效。"}],"illustration_spec":{"title":"性质变化与证据判断","objects":["物理/化学性质列表","沸腾与酸放气对照","玻璃碎裂","无色中和候选","100g到96+4收支"],"relations":["气泡不唯一判化学","能力与事件分开","开放体系计逸出","热不独占反应"],"labels":["新物质证据","物理变化","化学变化","100=96+4","观察≠唯一结论"],"format":"SVG","priority":"P1","reuse":"无完全对应旧图；对照图和收支准确即可","english":"Contrast properties with events, and compare boiling-water bubbles with chemically generated gas. Include a broken-glass reversibility counterexample and an open-system mass balance100=96+4 g. Show that colour, heat or bubbles alone are not unique proof of a chemical reaction."}}},"化学2":{"2.1.1":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":2,"section_id":"2.1.1","goals":["用极性和氢键解释水的物性","在温压和相态条件内计算热量密度"],"prerequisites":["分子间作用","质量体积与温度"],"flow":["极性氢键","相态温压","密度异常","比热与潜热","溶解导电"],"concept_relation":"极性氢键；相态温压；密度异常；比热与潜热；溶解导电","deep":["比热容较大意味着同质量吸收相同热量时温升较小，不是永远不会变热。Q=mcΔT用于没有相变且c可近似恒定的过程；若跨越熔沸阶段，还需潜热，不能只把整个温差乘c。","水能溶解许多离子或极性物质，但不是万能溶剂。溶解取决离子/分子与水及原来内部作用的平衡，有的共价物可溶，有的盐难溶；不能只按“盐”或“有机”一个标签决定。","纯水导电性很弱，水中微量离子及杂质会影响导电，蒸馏水也不是逻辑上绝对没有离子。导电能力不等于是否能溶物，也不能把饮用水和实验纯水的性质无条件互相代替。","实验物性数据应带温度、压力与纯度。密度计算要区分质量守恒和体积变化，热量是传递过程量，不把“水含有多少热”当与温度完全相同的可直接读取属性。"],"derive":["ρ=m/V；相变无物质损失时m可不变而V因ρ改变。","Q=mcΔT仅用于无相变、比热近似恒定的温变段。","纯水约0°C熔点与100°C沸点对应约101.325 kPa参考；其他压力与溶质需另审。"],"examples":[{"q":"100 g水冻结成冰，题给冰密度0.92 g/mL，冰体积多少？若液水近似1.00 g/mL，体积增加多少？","given":"无损失，密度为题设。","analysis":"质量不变，体积不同。","method":"V=m/ρ。","principle":"质量体积密度关系。","steps":["V冰=100/.92≈108.7 mL。","V水100 mL，增加约8.7 mL。"],"ans":"约108.7 mL，增8.7 mL。","verification":"108.7×.92≈100 g。","pitfall":"冻结后仍强令体积100 mL。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.1","related_sections":[]},{"q":"200 g水由20°C到40°C，取c=4.2 J/(g·°C)，无热损且无相变，需热量？","given":"c按题取常量。","analysis":"温差20而非末温40。","method":"Q=mcΔT。","principle":"显热模型。","steps":["ΔT=40−20=20°C。","Q=200×4.2×20=16800 J。"],"ans":"1.68×10⁴ J。","verification":"单位g×J/(g·°C)×°C=J。","pitfall":"用40作温差或漏质量单位。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.1","related_sections":[]},{"q":"各100 g水和某金属，分别吸热420 J，c水4.2、c金属0.42，同单位，无相变，温升各多少？能由此说金属总内能必更高吗？","given":"只比较给定温升过程。","analysis":"比热影响ΔT，绝对内能需更多信息。","method":"ΔT=Q/(mc)。","principle":"能量温变关系。","steps":["水ΔT=420/(100×4.2)=1°C。","金属ΔT=420/(100×.42)=10°C。"],"ans":"1°C与10°C；不能由此比较全部内能。","verification":"金属比热1/10，温升10倍。","pitfall":"温升大就等于总内能一定大。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.1","related_sections":[]}],"practice":[{"q":"水在60°C可以蒸发吗？是否已沸腾？","given":"压力约常压。","analysis":"蒸发发生于表面多温度。","method":"区分蒸发与整体沸腾。","principle":"相变机制条件。","steps":["60°C可有蒸发。","常压纯水未达通常100°C沸点，不因此说已沸腾。"],"ans":"可蒸发，未必沸腾。","verification":"晾干常在远低100°C发生。","pitfall":"只有沸腾才有水蒸气。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.1","related_sections":[]},{"q":"冰浮起能只用“冰比水轻”而不指同体积解释吗？","given":"比较密度不是任意总质量。","analysis":"轻需同体积基准。","method":"说密度及浮力。","principle":"相同体积冰质量较小，浮力可平衡重力。","steps":["冰密度小于液水。","浸入部分即可排开足够质量水，故浮起。"],"ans":"应明确密度较小，不能任意比总质量。","verification":"一大块冰仍可能重于一滴水。","pitfall":"省比较基准造成歧义。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.1","related_sections":[]},{"q":"纯水沸腾是H₂O变H₂与O₂吗？","given":"普通物理汽化。","analysis":"分子身份保持。","method":"区分相态与化学变化。","principle":"汽化主要改变分子间状态。","steps":["水蒸气仍主要H₂O分子。","H₂、O₂生成需化学过程如适当电解，不是普通沸腾。"],"ans":"不是。","verification":"水蒸气冷凝得水而非混合气燃烧。","pitfall":"把气态水当氢氧气。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.1","related_sections":[]},{"q":"50 g液水无相变温升10°C，c4.2，需要热多少？若题实际跨沸腾为何此式不足？","given":"前半题限定单一液相。","analysis":"区分显热与潜热。","method":"Q=50×4.2×10。","principle":"温变与相变能量不同。","steps":["Q=2100 J。","跨相变还需汽化等能量与对应质量，不能只加温差项。"],"ans":"2100 J；相变需额外资料和能量项。","verification":"与200g、20°C例按质量温差比例为1/8。","pitfall":"一式覆盖所有相态过程。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.1","related_sections":[]}],"quiz":{"q":"水能溶食盐又能溶糖，能说两溶液都靠同样数量的自由离子导电吗？","given":"溶质不同。","analysis":"溶解与离子生成不同。","method":"分别看离子盐与分子糖。","principle":"导电需要移动电荷。","steps":["食盐在水中提供离子。","糖主要以分子存在，不能仅因溶解就说提供相同离子。"],"ans":"不能。","verification":"同浓度可有不同导电行为。","pitfall":"把溶解全等同电离。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.1","related_sections":[]},"exam":["物性题从分子间作用解释，普通汽化不断O—H全部键","热量题先判相态、c条件与温差，再算单位","密度题保持质量收支，冻结体积不强行不变，比较需同基准"],"quick":["极性氢键","相态温压","密度异常","比热与潜热","溶解导电"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":23,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_2.1.1","url":"https://openstax.org/books/chemistry-2e/pages/10-1-intermolecular-forces","page_or_section":"10-1-intermolecular-forces","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":23,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_2.1.1","url":"https://openstax.org/books/chemistry-2e/pages/10-1-intermolecular-forces","page_or_section":"10-1-intermolecular-forces","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"物性题从分子间作用解释，普通汽化不断O—H全部键","method":"ΔT=Q/(mc)。","principle":"能量温变关系。","worked_example_index":2,"verification":"金属比热1/10，温升10倍。","pitfall":"温升大就等于总内能一定大。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用极性和氢键解释水的物性”的抽样复核：108.7×.92≈100 g。；若出现“冻结后仍强令体积100 mL。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“在温压和相态条件内计算热量密度”的抽样复核：金属比热1/10，温升10倍。；若出现“温升大就等于总内能一定大。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把溶解全等同电离。","correction":"不能。","verification":"同浓度可有不同导电行为。"}],"illustration_spec":{"title":"水的氢键物性与相变","objects":["水分子间氢键","冰与液水相对结构","100g体积比较","单相加热段","相变条件框"],"relations":["普通汽化仍H₂O","冰密度较小体积较大","Q=mcΔT不含潜热","沸点注明压力"],"labels":["分子间氢键","O—H共价键","0.92 g/mL为题设","101.325kPa","约4°C密度最大"],"format":"SVG","priority":"P0","reuse":"已有水氢键图可复核复用；密度与相变需准确新图","english":"Distinguish intermolecular hydrogen bonds from intramolecular O-H bonds, compare the less dense ice network with liquid water qualitatively, and show 100 g occupying about108.7 mL at the stated ice density0.92 g/mL. Label pressure-dependent phase points and keep latent heat separate from mcDeltaT."}},"2.1.2":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":2,"section_id":"2.1.2","goals":["按条件描述水与金属氧化物的反应","由电解与氧化还原追踪原子和电子"],"prerequisites":["化学方程配平","氧化数与气体体积"],"flow":["水与金属","氧化物水合","电解条件","体积质量比","电子收支"],"concept_relation":"水与金属；氧化物水合；电解条件；体积质量比；电子收支","deep":["部分碱性氧化物与水生成碱，如CaO+H₂O→Ca(OH)₂并放热；不是所有金属氧化物都与水这样反应。部分酸性氧化物可与水成酸，CO₂+H₂O⇌H₂CO₃有平衡，不能说所有溶解CO₂都完全转为强酸。","水在适当电解条件下分解为氢与氧，总式2H₂O→2H₂+O₂，电能提供驱动。惰性电极与合适电解质用于相应模型；任意加盐并不保证只得到氢氧，氯化物等可能带来其他电极产物。","在同温同压且纯气计量条件下，氢氧体积比2:1来自系数对应摩尔比，质量比却为1:8。体积比不等于质量比，湿气、溶解损失与不同条件可影响实际测量；气体鉴别不能省略规范与防混合条件。","从氧化数看，钠与水反应中Na由0到+1，水中H由+1到0，水可作氧化剂；电解中H被还原、O被氧化。一个物质可在不同过程有不同角色，不能只由元素名称固定谁永远是氧化或还原剂。"],"derive":["2Na+2H₂O→2NaOH+H₂；3Fe+4H₂O(g)→Fe₃O₄+4H₂（相应高温）。","CaO+H₂O→Ca(OH)₂；CO₂+H₂O⇌H₂CO₃（不能全写单向完全）。","2H₂O→2H₂+O₂：同T/P理想气V比2:1，m比4:32=1:8。"],"examples":[{"q":"0.20 mol Na与足量水按主反应，理论H₂、NaOH各多少？","given":"2Na+2H₂O→2NaOH+H₂。","analysis":"系数比2:1:2。","method":"先按Na摩尔数比例。","principle":"原子及电子守恒。","steps":["H₂=.10 mol。","NaOH=.20 mol。"],"ans":".10 molH₂、.20 molNaOH。","verification":"Na .20 mol由0到+1失.20 mol电子，H₂ .10接受.20 mol电子。","pitfall":"Na与H₂也按1:1。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.2","related_sections":[]},{"q":"电解18.0 g水，取M18，理论氢氧各n、质量比及同温同压体积比。","given":"足量电能，按总反应完全，无其他反应。","analysis":"摩尔、质量、体积三个指标分开。","method":"n水1 mol，系数2:2:1。","principle":"总式及同条件气体模型。","steps":["H₂1 mol、O₂.5 mol。","质量2 g与16 g，比1:8。","体积比1:.5=2:1。"],"ans":"1 molH₂、.5 molO₂，质量1:8、体积2:1。","verification":"2+16=18 g守恒。","pitfall":"把体积2:1直接写成质量比。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.2","related_sections":[]},{"q":"学生把铁与蒸气反应写2Fe+3H₂O→Fe₂O₃+3H₂，原子虽平衡能否替代本节经典反应？","given":"题目指定相应高温铁—水蒸气主模型。","analysis":"配平只是必要，不决定真实产物。","method":"核实验条件与已知产物。","principle":"科学方程须同时符合现象与守恒。","steps":["应使用3Fe+4H₂O(g)→Fe₃O₄+4H₂及条件。","错误产物即使配平也不能冒充指定实际反应。"],"ans":"不能。","verification":"真实产物信息不能由守恒唯一推出。","pitfall":"配平通过就认为任何产物都真。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.2","related_sections":[]}],"practice":[{"q":"CaO与水反应产物及反应类型线索？","given":"对应生石灰水合。","analysis":"核Ca/O/H。","method":"CaO+H₂O→Ca(OH)₂。","principle":"元素守恒与碱性氧化物例。","steps":["产物氢氧化钙。","反应放热，但不推广所有金属氧化物。"],"ans":"Ca(OH)₂。","verification":"两侧Ca1、O2、H2。","pitfall":"把产物写CaOH或所有氧化物都同样。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.2","related_sections":[]},{"q":"铜片放普通水中，可以照活泼金属模板立刻写Cu(OH)₂与H₂吗？","given":"无特殊氧化剂或电解。","analysis":"模板适用对象有限。","method":"看活泼性与条件。","principle":"反应可行性不由形式配平保证。","steps":["铜不按该普通水直接置氢模型反应。","不能套Na/Ca式强写现象。"],"ans":"不可以。","verification":"无观察支持且反应条件不符。","pitfall":"看到金属就都与水放氢。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.2","related_sections":[]},{"q":"同条件收得纯H₂40 mL，理想水电解模型对应O₂体积？这说明氧质量只有一半吗？","given":"相同温压，忽略损失。","analysis":"体积比2:1不代表质量比。","method":"V氧=40/2。","principle":"摩尔比与分子量。","steps":["O₂20 mL。","氧质量反而为氢8倍，需乘摩尔质量。"],"ans":"20 mL；不能说质量一半。","verification":"同体积O₂的M32大于H₂2。","pitfall":"体积比直接当质量比。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.2","related_sections":[]},{"q":"Na与水中H氧化数各怎样变，水是哪种剂？","given":"只讨论该主反应。","analysis":"追踪电子。","method":"Na0→+1，H+1→0。","principle":"失电子氧化、得电子还原。","steps":["Na被氧化。","水中H被还原，因此水在此作氧化剂。"],"ans":"水为氧化剂。","verification":"2Na失2e，对应2H得2e成H₂。","pitfall":"因为水供H就固定叫还原剂。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.2","related_sections":[]}],"quiz":{"q":"为提高水导电性任意加入食盐，能保证气体仍只有H₂与O₂吗？","given":"电解质改为含Cl⁻体系。","analysis":"电极产物还受离子和条件影响。","method":"区分总水电解教学模型。","principle":"其他可反应离子可能参与电极过程。","steps":["Cl⁻等可能在阳极参与生成不同产物。","须用适当体系和条件，不能由导电增强推出产物不变。"],"ans":"不能保证。","verification":"导电性与选择性是不同问题。","pitfall":"把电解质只当永远不反应背景。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.1.2","related_sections":[]},"exam":["反应题既核配平也核产物和条件，水/蒸气不混","电解题分n、m、V比，同温压条件写清","氧化还原题逐元素标数及电子，不凭物质名称固定角色"],"quick":["水与金属","氧化物水合","电解条件","体积质量比","电子收支"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":25,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_2.1.2","url":"https://openstax.org/books/chemistry-2e/pages/17-7-electrolysis","page_or_section":"17-7-electrolysis","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":25,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_2.1.2","url":"https://openstax.org/books/chemistry-2e/pages/17-7-electrolysis","page_or_section":"17-7-electrolysis","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"反应题既核配平也核产物和条件，水/蒸气不混","method":"核实验条件与已知产物。","principle":"科学方程须同时符合现象与守恒。","worked_example_index":2,"verification":"真实产物信息不能由守恒唯一推出。","pitfall":"配平通过就认为任何产物都真。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按条件描述水与金属氧化物的反应”的抽样复核：Na .20 mol由0到+1失.20 mol电子，H₂ .10接受.20 mol电子。；若出现“Na与H₂也按1:1。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“由电解与氧化还原追踪原子和电子”的抽样复核：2+16=18 g守恒。；若出现“把体积2:1直接写成质量比。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把电解质只当永远不反应背景。","correction":"不能保证。","verification":"导电性与选择性是不同问题。"}],"illustration_spec":{"title":"水反应与电解条件","objects":["Na水反应","铁蒸气Fe₃O₄","适当水电解两极","H₂/O₂量比","氧化数变化"],"relations":["H₂:O₂体积2:1同T/P","质量1:8","氢在阴极氧在阳极的相应模型","电解质不任意"],"labels":["2H₂O→2H₂+O₂","高温水蒸气","Fe₃O₄","惰性电极/适当电解质","非通用盐水模型"],"format":"SVG","priority":"P0","reuse":"现有电解图须核极性、气体与电解质后复用","english":"Draw the specified water reactions with correct conditions, especially Fe3O4 from hot iron and steam. For the appropriate inert-electrode water-electrolysis model, show hydrogen at the cathode and oxygen at the anode, volume ratio2:1 at equal T/P but mass ratio1:8. Do not imply arbitrary chloride electrolyte gives the same products."}},"2.2.1":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":2,"section_id":"2.2.1","goals":["按金属酸与电解条件选择制氢方法","由气路和限量计量评价实验结果"],"prerequisites":["金属活动性","水电解与限量反应"],"flow":["反应选择","装置气路","收集与初始空气","工业来源","限量收率"],"concept_relation":"反应选择；装置气路；收集与初始空气；工业来源；限量收率","deep":["氢气难溶水且密度低，可按规范排水或用适合的排空气方式收集。收集瓶朝向和气路应由气体运动与排出空气方向解释；“气体轻”不能保证装置中没有空气混合，点燃或加热前需规范检查。","初始装置含空气，前段气体未必纯氢。气密性、漏气、溶解、湿气与原料纯度等影响实收量，实际收集不足不立刻证明方程错误；理论计量与实验偏差应分层讨论。","工业制氢可有电解水、烃重整等路线，整体物料与能量来源不同。电解的用电来源决定部分上游环境负担，烃路线可能产生含碳副产物；不能把所有氢称为无上游排放的天然能源。","计算题先配平与判限量，质量到摩尔再到目标量，最后按相应温压求体积。没有给气体纯度、压力或温度时，不能装作已得精确干气量；题设理想数据则把假设写明。"],"derive":["Zn+2HCl→ZnCl₂+H₂；Zn+H₂SO₄(稀)→ZnSO₄+H₂。","n理论H₂=min(nZn,nHCl/2)；若用酸类型不同，先核反应路径。","气路检查包括密封、出口、漏斗控制、收集朝向及初始空气，不能凭方程决定全部装置正确。"],"examples":[{"q":"6.5 g纯Zn与过量稀HCl反应，取MZn65、Vm22.4 L/mol（0°C101.325kPa），理论H₂体积？","given":"完全反应、干气理想近似。","analysis":"Zn与H₂为1:1。","method":"nZn=6.5/65。","principle":"配平方程。","steps":["n=.10 mol。","V=.10×22.4=2.24 L。"],"ans":"2.24 L，指定条件。","verification":"消耗HCl .20 mol；Zn质量转化计量一致。","pitfall":"直接用6.5/2求氢摩尔数。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.1","related_sections":[]},{"q":"Zn .10 mol与HCl .15 mol反应，求H₂和余Zn。","given":"稀盐酸模型。","analysis":"酸需2:1。","method":"比较.10与.15/2。","principle":"限量比。","steps":["HCl限量，H₂ .075 mol。","消耗Zn .075，余.025 mol。"],"ans":".075 molH₂、余.025 molZn。","verification":"消耗HCl2×.075=.15恰尽。","pitfall":"一律按金属全反应给.10。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.1","related_sections":[]},{"q":"要用稀盐酸制氢，选Zn还是Cu？若实际起初气体不纯，该怎样解释而非改写反应？","given":"只有普通金属酸模型。","analysis":"可反应材料与装置空气是两层。","method":"按活动性选，再查气路。","principle":"Zn可置氢，Cu不按此模型。","steps":["选Zn。","初始空气与生成气混合，需按规范排查检验，不把初段混合误称生成了新反应物。"],"ans":"选Zn；不纯可来自初始空气等。","verification":"化学式正确与收集气体纯度不同。","pitfall":"因一开始气体不纯就否定Zn方程。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.1","related_sections":[]}],"practice":[{"q":"锌与稀硫酸生成哪种盐？配方程。","given":"按非氧化性稀酸置氢。","analysis":"Zn转+2。","method":"Zn+H₂SO₄→ZnSO₄+H₂。","principle":"原子和电荷状态。","steps":["盐为ZnSO₄。","系数均1，两侧Zn1S1O4H2。"],"ans":"ZnSO₄与H₂。","verification":"与盐酸2HCl所给H原子数对比。","pitfall":"把盐写Zn₂SO₄。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.1","related_sections":[]},{"q":"敞口长颈漏斗下端在液面上方，气体是否可能从漏斗逃逸？","given":"装置依液封阻气。","analysis":"缺液封可连通外界。","method":"追踪气路。","principle":"气体可沿低阻通路逸出。","steps":["若下端不入液，气体可由漏斗通向空气。","按正确规范修装置，不能仅靠瓶塞存在就说完全密封。"],"ans":"可能。","verification":"分液漏斗有活塞时需另按结构分析。","pitfall":"两类漏斗混为同一控制方式。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.1","related_sections":[]},{"q":"所有酸都可替代稀盐酸按同一方式给H₂吗？","given":"包括氧化性酸。","analysis":"反应路线不同。","method":"审酸性质与浓度。","principle":"形式相似不保证同产物。","steps":["氧化性酸可有其他还原产物。","需具体条件，不能机械套金属+酸→氢气。"],"ans":"不可以一概替代。","verification":"反应物身份是模型条件。","pitfall":"只看有H就说必生成H₂。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.1","related_sections":[]},{"q":"10 g样品含Zn65%，酸过量，理论H₂ .10 mol，实收.080 mol，求产率并区分65%。","given":"杂质不产气。","analysis":"纯度先决定可反应量。","method":"mZn6.5g→.10 mol；实/理论。","principle":"纯度与收率定义。","steps":["产率.080/.10=80%。","65%为原料质量分数，不是收气效率。"],"ans":"80%；65%是纯度。","verification":"若用10g纯锌理论会错大。","pitfall":"把两个百分数当同一指标。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.1","related_sections":[]}],"quiz":{"q":"装置有通气口但气体未检验即可对反应瓶点火，能作为正确制氢示意吗？","given":"初始空气可能存在，可燃气。","analysis":"出口不等于气体已纯。","method":"按气路与规范检查。","principle":"可燃混合物不能凭想象排除。","steps":["图需保留规范检验与防混合条件。","不能把反应瓶直接点火作为通用步骤，应修正后再使用。"],"ans":"不能。","verification":"产氢化学事实不证明任意点燃位置正确。","pitfall":"有方程就忽略气路和空气。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.1","related_sections":[]},"exam":["方法题先核金属、酸与浓度，不用通式替代条件","装置题沿气路检查漏斗、液封、出口与初始空气","计量题纯度限量理论产量先算，再解释实际收率和温压"],"quick":["反应选择","装置气路","收集与初始空气","工业来源","限量收率"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":30,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_2.2.1","url":"https://openstax.org/books/chemistry-2e/pages/18-5-occurrence-preparation-and-compounds-of-hydrogen","page_or_section":"18-5-occurrence-preparation-and-compounds-of-hydrogen","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":30,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_2.2.1","url":"https://openstax.org/books/chemistry-2e/pages/18-5-occurrence-preparation-and-compounds-of-hydrogen","page_or_section":"18-5-occurrence-preparation-and-compounds-of-hydrogen","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"方法题先核金属、酸与浓度，不用通式替代条件","method":"按活动性选，再查气路。","principle":"Zn可置氢，Cu不按此模型。","worked_example_index":2,"verification":"化学式正确与收集气体纯度不同。","pitfall":"因一开始气体不纯就否定Zn方程。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按金属酸与电解条件选择制氢方法”的抽样复核：消耗HCl .20 mol；Zn质量转化计量一致。；若出现“直接用6.5/2求氢摩尔数。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“由气路和限量计量评价实验结果”的抽样复核：化学式正确与收集气体纯度不同。；若出现“因一开始气体不纯就否定Zn方程。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"有方程就忽略气路和空气。","correction":"不能。","verification":"产氢化学事实不证明任意点燃位置正确。"}],"illustration_spec":{"title":"氢气制取的反应与气路","objects":["Zn稀酸反应器","敞口长颈漏斗液封","分液漏斗另图","导气出口","排水收集","初始空气框"],"relations":["Zn:H₂=1:1","HCl:Zn=2:1","不把两种漏斗混画","不点燃反应瓶"],"labels":["稀非氧化性酸","液封","通畅气路","规范检验","指定温压"],"format":"SVG","priority":"P0","reuse":"需要可靠装置原图；未审核图不放正式页面","english":"Show zinc reacting with dilute nonoxidizing acid, distinguish an open thistle funnel requiring a liquid seal from a stopcock dropping funnel, and trace the gas outlet and appropriate collection route. Mark initial air and verification requirements; never show ignition at the reaction vessel or a blocked sealed gas path."}},"2.2.2":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":2,"section_id":"2.2.2","goals":["由分子和反应条件说明氢的物化性质","用氧化数与计量解释燃烧和还原"],"prerequisites":["氢气制取","氧化还原与气体"],"flow":["低密度分子","燃烧与相态","金属氧化物还原","氧化数","实验对照"],"concept_relation":"低密度分子；燃烧与相态；金属氧化物还原；氧化数；实验对照","deep":["氢可在适当加热条件下还原某些金属氧化物，例如CuO+H₂→Cu+H₂O。黑色氧化铜变为相应铜色并产生水是此模型现象；并非所有金属氧化物都能按同条件被H₂还原，不能以“还原剂”三个字覆盖可行性。","此反应中H从0到+1被氧化，Cu从+2到0被还原，所以H₂作还原剂。氢在多数非金属化合物中常+1，但在某些金属氢化物中可−1，不能把元素氢氧化数固定为一个值。","实验还原装置需按规范先处理空气与气流，再加热和冷却，不能对含氢氧混合的系统任意加热。水滴出现也要排除原来湿气，观察与对照应支持水由反应产生，而不是看见冷凝就跳到唯一来源。","解释氢性质时把物理分离、化学反应和能源功能区分。氢“轻”影响收集和储存，氢“可燃”涉及化学能释放，二者不是同一种性质，也不能由轻就说燃烧必快或单位体积能量一定最高。"],"derive":["2H₂+O₂→2H₂O；同温压n/V比2:1:2只对相应气态计量条件使用。","CuO+H₂→Cu+H₂O（加热等适用条件）；H0→+1，Cu+2→0。","NaH等金属氢化物中H可为−1，H₂单质为0；氧化数依化合物。"],"examples":[{"q":"0.30 mol H₂与0.10 mol O₂反应，求理论水n及剩余气体。","given":"按主反应完全到限量尽。","analysis":"氧需与两倍氢配合。","method":"nH₂/2与nO₂比较。","principle":"配平方程。","steps":["O₂ .10限量，消耗H₂ .20。","生成H₂O .20 mol，余H₂ .10 mol。"],"ans":"水.20 mol，余H₂.10 mol。","verification":"H原子初.60，末水.40+余氢.20一致。","pitfall":"氢全部反应而忽略氧不足。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.2","related_sections":[]},{"q":"7.95 g CuO被足量H₂还原，取CuO79.5、Cu63.5、水18、H₂2，求铜、水及氢消耗质量。","given":"完全主反应模型。","analysis":"CuO摩尔数先求。","method":"n=.10 mol，均1:1。","principle":"原子及电子守恒。","steps":["Cu=6.35 g，水1.80 g。","H₂消耗.20 g。"],"ans":"6.35g铜、1.80g水、.20g氢。","verification":"7.95+.20=6.35+1.80=8.15 g。","pitfall":"把CuO全部质量当铜质量。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.2","related_sections":[]},{"q":"CuO还原实验见水滴，能仅此证明水全部来自CuO与H₂反应？","given":"气体与装置原本湿度未控制。","analysis":"可能有背景水。","method":"设干气/空白或前后证据。","principle":"因果结论需排除混杂。","steps":["观察到水与反应生成相容。","需排原气水蒸气、装置残水等，结合CuO变化和对照，才能更强归因。"],"ans":"不能仅凭水滴。","verification":"未反应的湿气也可冷凝。","pitfall":"一个现象即唯一来源证明。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.2","related_sections":[]}],"practice":[{"q":"H₂燃烧产物能写为H₂O₂吗？题设为通常完全燃烧。","given":"指定反应条件。","analysis":"守恒允许多式但实际主产物有条件。","method":"核通常产物并配平。","principle":"反应事实与守恒共同决定方程。","steps":["通常写2H₂+O₂→2H₂O。","H₂O₂不是此题通常燃烧主产物，不能因可配平而替换。"],"ans":"不能。","verification":"氧氢守恒只是必要检查。","pitfall":"任意含H/O分子都当燃烧产物。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.2","related_sections":[]},{"q":"CuO+H₂中哪种物质被氧化、哪种被还原？","given":"适当加热反应。","analysis":"追踪H、Cu。","method":"氧化数变化。","principle":"失电子氧化、得电子还原。","steps":["H₂的H0到+1，被氧化。","CuO中Cu+2到0，被还原。"],"ans":"H₂被氧化，CuO被还原。","verification":"H₂为还原剂，名称与自身被氧化不矛盾。","pitfall":"还原剂自身也被还原。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.2","related_sections":[]},{"q":"NaH、H₂O、H₂中H氧化数分别？","given":"Na通常+1，O通常−2。","analysis":"按电荷和。","method":"中性化合物氧化数和0。","principle":"氧化数规则。","steps":["NaH中H−1。","H₂O中H+1，单质H₂中H0。"],"ans":"−1、+1、0。","verification":"各总和满足中性或单质规则。","pitfall":"氢永远+1。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.2","related_sections":[]},{"q":"3.18 g CuO理论生成Cu多少g？若实际金属2.40 g，纯铜产率约多少？取M79.5、63.5。","given":"产品纯且反应计量为1:1。","analysis":"先理论质量再比较。","method":"3.18/79.5×63.5。","principle":"产率定义。","steps":["nCuO=.040 mol，理论Cu2.54 g。","产率2.40/2.54≈94.5%。"],"ans":"理论2.54 g，产率约94.5%。","verification":".04×63.5=2.54，与原CuO中铜比例一致。","pitfall":"直接2.40/3.18当铜产率。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.2","related_sections":[]}],"quiz":{"q":"氢气很轻与氢气能还原CuO分别属于哪类性质？能由前者推出后者吗？","given":"一项不改变组成，一项发生化学转化。","analysis":"物理与化学层次不同。","method":"分类并说明证据。","principle":"化学性涉及生成新物。","steps":["低密度为物理性质。","还原CuO为化学性质，不能仅从密度推反应可行。"],"ans":"物理、化学；不能直接推。","verification":"其他轻气体不一定有相同还原行为。","pitfall":"把轻、易燃、还原当同义。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.2","related_sections":[]},"exam":["性质题分物化与反应条件，H₂稳定性不绝对","还原题逐元素标氧化数，剂与自身变化别反写","定量题从CuO摩尔到铜，产率以目标理论质量为分母"],"quick":["低密度分子","燃烧与相态","金属氧化物还原","氧化数","实验对照"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":32,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_2.2.2","url":"https://openstax.org/books/chemistry-2e/pages/18-5-occurrence-preparation-and-compounds-of-hydrogen","page_or_section":"18-5-occurrence-preparation-and-compounds-of-hydrogen","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":32,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_2.2.2","url":"https://openstax.org/books/chemistry-2e/pages/18-5-occurrence-preparation-and-compounds-of-hydrogen","page_or_section":"18-5-occurrence-preparation-and-compounds-of-hydrogen","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"性质题分物化与反应条件，H₂稳定性不绝对","method":"设干气/空白或前后证据。","principle":"因果结论需排除混杂。","worked_example_index":2,"verification":"未反应的湿气也可冷凝。","pitfall":"一个现象即唯一来源证明。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由分子和反应条件说明氢的物化性质”的抽样复核：H原子初.60，末水.40+余氢.20一致。；若出现“氢全部反应而忽略氧不足。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“用氧化数与计量解释燃烧和还原”的抽样复核：7.95+.20=6.35+1.80=8.15 g。；若出现“把CuO全部质量当铜质量。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把轻、易燃、还原当同义。","correction":"物理、化学；不能直接推。","verification":"其他轻气体不一定有相同还原行为。"}],"illustration_spec":{"title":"氢的燃烧与还原","objects":["H₂/O₂到水","CuO黑到Cu色","H/Cu氧化数箭头","冷凝水对照","相态条件框"],"relations":["CuO:H₂:Cu:H₂O=1:1:1:1","H氧化Cu还原","冷凝不自动唯一来源","不任意加热含空气系统"],"labels":["加热条件","H0→+1","Cu+2→0","水蒸气/液水区分","对照"],"format":"SVG","priority":"P0","reuse":"暂无已审装置图；结构气路必须参考可靠教师图","english":"Balance hydrogen combustion and CuO reduction, mark H from0 to+1 and Cu from+2 to0, and distinguish water-vapour versus liquid-water energy conventions. If depicting apparatus, show verified gas-flow and air-removal conditions and include a background-moisture control rather than treating any condensate as unique proof."}},"2.2.3":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":2,"section_id":"2.2.3","goals":["将氢的反应性质连到合成燃料还原用途","以能量收支评价氢能源和环境边界"],"prerequisites":["氢性质","功率效率与物料收支"],"flow":["合成原料","催化加氢","还原用途","燃烧/燃料电池","储运与生命周期"],"concept_relation":"合成原料；催化加氢；还原用途；燃烧/燃料电池；储运与生命周期","deep":["氢燃烧可释放能量，燃料电池则通过相应电化学过程把部分化学能转为电能，总反应也可为2H₂+O₂→2H₂O。总方程相同不意味着能量转化途径、效率和装置都相同；效率定义要说明输入和有用输出。","氢通常是能源载体，制备需要原料与能量。使用端不直接排CO₂不等于全生命周期零排放，电力、烃制氢、运输、储存和设备制造等均可能有负担；不同路线需要同一功能单位比较。","氢质量轻而常温常压体积大，储运与材料要求是技术限制。高比能的质量指标不等于体积指标也高；压缩、液化或化学储氢各有条件和能耗，不能仅凭“最轻”就说储存最方便。","技术评价应连结构/反应、可测性能、条件、能耗与风险，区分理想计量和实际装置。题给热值和效率是本题模型，不冒充所有燃料电池或工业反应的统一数据；可靠使用方式仍由专业规范决定。"],"derive":["N₂+3H₂⇌2NH₃：理论n比1:3:2，实际转化率另给。","燃料电池效率η=有用电能/题定化学能输入；E电=ηE输入。","0°C101.325kPa的理想近似体积V=n×22.4 L；质量与体积能量指标不同。"],"examples":[{"q":"理论用.30 mol H₂合成氨，需N₂多少、得NH₃多少及质量？取MNH₃17。","given":"只求理论完全转化，不代表实际单程。","analysis":"1:3:2。","method":"按H₂系数。","principle":"物料守恒。","steps":["需N₂ .10 mol，NH₃ .20 mol。","m氨=.20×17=3.4 g。"],"ans":".10 molN₂、.20 molNH₃、3.4g。","verification":"原料质量H₂ .6g加N₂2.8g=3.4g。","pitfall":"把理论等同实际平衡转化率100%。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.3","related_sections":[]},{"q":"题给每mol H₂反应生成水蒸气可释放242 kJ，某装置电输出效率60%，1 mol可输出多少电能？","given":"效率按给定化学能基准。","analysis":"输出是输入一部分。","method":"E电=.60×242。","principle":"能量收支与效率。","steps":["E电=145.2 kJ。","其余96.8 kJ按该边界为其他能量去向。"],"ans":"145.2 kJ。","verification":"145.2+96.8=242；不能混用液水热值。","pitfall":"既算满242电又加60%造成重复。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.3","related_sections":[]},{"q":"1.0 kg H₂在0°C101.325kPa按M2、Vm22.4近似占多少体积？这说明何种储运挑战？","given":"未压缩理想模型。","analysis":"轻质量对应大常压体积。","method":"n=m/M，再V。","principle":"气体计量。","steps":["n=1000/2=500 mol。","V=500×22.4=11200 L=11.2 m³。"],"ans":"约11.2 m³，常压体积大。","verification":"1 m³=1000 L；质量比能高不自动体积小。","pitfall":"把1kg轻就等同易小罐储存。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.3","related_sections":[]}],"practice":[{"q":"合成氨中.10 mol N₂、.15 mol H₂，理论氨多少？","given":"主反应完全到限量尽。","analysis":"氢需3倍而不足。","method":"比nN₂与nH₂/3。","principle":"限量计量。","steps":["H₂限量，反应进度.05 mol。","氨2×.05=.10 mol。"],"ans":".10 molNH₃。","verification":"剩N₂ .05mol，H₂消耗.15mol。","pitfall":"按N₂全转得.20mol。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.3","related_sections":[]},{"q":"燃烧与燃料电池总反应相同，可说装置原理完全相同吗？","given":"同总反应不含过程信息。","analysis":"化学能到热/电途径不同。","method":"分别描述转换。","principle":"总式不唯一确定过程。","steps":["燃烧主要直接放热。","燃料电池由电极反应与外电路提供电能，效率边界不同。"],"ans":"不能。","verification":"同起终物质可经不同能量转换路径。","pitfall":"总式相同就认为一套器材通用。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.3","related_sections":[]},{"q":"用电解制H₂使用端无CO₂，就必全周期零排放吗？","given":"电力来源未给。","analysis":"上游可能排放。","method":"扩大到明确生命周期边界。","principle":"排放收支跨多个环节。","steps":["制电、设备、储运等需评估。","可说指定使用反应不直接生成CO₂，不能说全部环节0。"],"ans":"不必。","verification":"电源不同会改同样氢的上游负担。","pitfall":"只看末反应无C元素。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.3","related_sections":[]},{"q":"题给氢能源输入1000 kJ，电输出550 kJ，求效率；若同样输出另一方案需1200 kJ，效率谁高？","given":"相同有用输出口径。","analysis":"输入输出不能互换。","method":"η=E出/E入。","principle":"效率定义。","steps":["第一55%。","第二550/1200≈45.8%，第一较高；完整环境评价仍不只效率。"],"ans":"55%与约45.8%。","verification":"相同输出第一消耗输入较少。","pitfall":"效率写输入/输出大于100%。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.3","related_sections":[]}],"quiz":{"q":"氢适合作某氧化物还原剂，能推广为相同条件还原所有金属氧化物吗？","given":"未给各反应可行性。","analysis":"用途有对象条件。","method":"审热力学和速率等。","principle":"还原性不是无限制反应许可。","steps":["CuO等在相应条件可反应。","更活泼金属氧化物等不能无条件照搬，需具体证据。"],"ans":"不能。","verification":"一个成功实例不足推出全部氧化物。","pitfall":"还原剂标签等于所有氧都能取走。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":2,"primary_section":"2.2.3","related_sections":[]},"exam":["用途题用性质—反应—条件—应用链解释","能源题定义热值相态与效率边界，再算输入输出","环境题区分使用端与全周期，质量体积指标分别比较"],"quick":["合成原料","催化加氢","还原用途","燃烧/燃料电池","储运与生命周期"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":35,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_2.2.3","url":"https://openstax.org/books/chemistry-2e/pages/17-5-batteries-and-fuel-cells","page_or_section":"17-5-batteries-and-fuel-cells","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://dokumen.pub/e329b58567bfcaac79ff8da5a0ecc507.html","page":35,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_2.2.3","url":"https://openstax.org/books/chemistry-2e/pages/17-5-batteries-and-fuel-cells","page_or_section":"17-5-batteries-and-fuel-cells","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"用途题用性质—反应—条件—应用链解释","method":"n=m/M，再V。","principle":"气体计量。","worked_example_index":2,"verification":"1 m³=1000 L；质量比能高不自动体积小。","pitfall":"把1kg轻就等同易小罐储存。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“将氢的反应性质连到合成燃料还原用途”的抽样复核：原料质量H₂ .6g加N₂2.8g=3.4g。；若出现“把理论等同实际平衡转化率100%。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“以能量收支评价氢能源和环境边界”的抽样复核：145.2+96.8=242；不能混用液水热值。；若出现“既算满242电又加60%造成重复。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"还原剂标签等于所有氧都能取走。","correction":"不能。","verification":"一个成功实例不足推出全部氧化物。"}],"illustration_spec":{"title":"氢用途与能量边界","objects":["合成氨1:3:2","有机加氢","CuO还原","燃料电池输入输出","制氢储运使用边界"],"relations":["理论与实际转化分开","242kJ基准生成水蒸气","60%给145.2kJ电","使用端不代表全周期"],"labels":["能源载体","η","物料比","上游能量","相态基准"],"format":"SVG","priority":"P1","reuse":"暂无对应图；可用清晰收支结构图，非装饰氢能插画","english":"Map hydrogen uses to specific reactions and conditions: ammonia synthesis, hydrogenation, selected oxide reduction and electrochemical energy conversion. Show a stated water-vapour energy basis242 kJ/mol with60% electrical output145.2 kJ, and include production, storage and transport in lifecycle boundaries rather than claiming universal zero emissions."}}},"化学26":{"26.1":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":26,"section_id":"26.1","goals":["按组成与结构解释有机化合物分类","由燃烧数据求最简式并检查证据限制"],"prerequisites":["物质的量","化学式与配平"],"flow":["碳的连接","有机与无机约定","烃与衍生物","最简式分子式","结构证据"],"concept_relation":"碳的连接；有机与无机约定；烃与衍生物；最简式分子式；结构证据","deep":["分子式给出一个分子的原子种类和数目，最简式给出最小整数比，结构式进一步显示连接。相同分子式可对应不同连接或空间排列，所以元素分析或燃烧分析本身通常不能唯一确定结构。","完全燃烧分析把样品中的碳转为CO₂、氢转为H₂O，在产物定量收集且无其他来源等条件下，可由n(C)=n(CO₂)、n(H)=2n(H₂O)求元素比。若样品还含氧且仅含C、H、O，可用样品质量减碳氢质量求氧，不能在未知元素存在时随意用差值全部算成氧。","由元素比求最简式时先换为摩尔数再除最小值，处理接近简单分数的比例须结合测量不确定性；不是一律对每个比值直接四舍五入。要确定分子式，还需要相对分子质量等独立信息，倍数应为接近整数。","本章的结构与计算是后续官能团和反应规律的基础。所有例题为原创分析模型，不代表已确认正式UEC出题频率。真实实验的完全燃烧、产物吸收和样品纯度均会影响数据解释，课堂理想数据不等于任何装置都能无误差复现。"],"derive":["完全燃烧且定量收集：n(C)=n(CO₂)，n(H)=2n(H₂O)。","仅含C/H/O时，m(O)=m样−m(C)−m(H)，再n(O)=m(O)/16 g·mol⁻¹。","分子式=(最简式)ₖ，k=M分子/M最简式；k应为正整数，结构仍需其他证据。"],"examples":[{"q":"CH₄、C₂H₅OH、CO₂、Na₂CO₃中，按通常学科约定哪些属有机物，哪些属烃？","given":"按本节常见分类约定。","analysis":"有机物与烃不是同一集合。","method":"先判有机，再核是否仅C/H。","principle":"烃只含碳氢，CO₂和碳酸盐通常归无机。","steps":["CH₄和C₂H₅OH归有机。","其中CH₄仅含C/H属烃；乙醇含O不属烃。"],"ans":"有机：甲烷、乙醇；烃：仅甲烷。","verification":"其余两项虽含C但在约定无机类。","pitfall":"把所有含碳物都叫烃。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]},{"q":"0.30 g仅含C/H/O样品完全燃烧得0.44 g CO₂和0.18 g H₂O，求最简式。取C12、H1、O16。","given":"产物定量且碳氢均来自样品。","analysis":"由产物先求C/H，氧用质量差。","method":"摩尔数及元素质量守恒。","principle":"CO₂每摩尔含1 mol C，H₂O含2 mol H。","steps":["n(C)=0.44/44=0.010 mol；n(H)=2×0.18/18=0.020 mol。","mC=0.12 g，mH=0.02 g，mO=0.30−0.14=0.16 g，nO=0.010 mol。","比C:H:O=1:2:1。"],"ans":"CH₂O。","verification":"最简式质量分数C40%、H约6.67%、O约53.33%，对应0.30 g各质量。","pitfall":"将水的摩尔数直接当H原子摩尔数。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]},{"q":"某物质最简式CH₂O，相对分子质量60，能确定分子式和唯一结构吗？","given":"最简式式量30。","analysis":"分子式倍数可定，连接不可仅此定。","method":"k=60/30。","principle":"元素比例和分子量约束原子数，不唯一约束连接。","steps":["k=2，分子式C₂H₄O₂。","同分子式可存在不同结构，需结构或反应等证据。"],"ans":"分子式C₂H₄O₂，不能唯一确定结构。","verification":"式量24+4+32=60。","pitfall":"把最简式当分子式或直接认定唯一官能团。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]}],"practice":[{"q":"C₆H₁₂O₆的最简式是？它是烃吗？","given":"只按分子式分析。","analysis":"先约简再分类。","method":"各下标除最大公因数。","principle":"最简式为最小整数比，烃不能含O。","steps":["6:12:6除6得1:2:1。","含氧，不能归烃。"],"ans":"CH₂O；不是烃。","verification":"(CH₂O)₆恢复原式。","pitfall":"把有机物自动当烃。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]},{"q":"某样品除C/H外还可能有N，能把剩余质量全算O吗？","given":"元素种类未确定。","analysis":"差值可能包含N等。","method":"先确定元素组成。","principle":"质量守恒不提供未知元素身份。","steps":["减去C/H只得其余元素总质量。","需氮等检测或题给仅C/H/O才能归O。"],"ans":"不能。","verification":"若剩余全部为N，氧差值法会完全错误。","pitfall":"以差值法替代元素鉴定。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]},{"q":"最简式CH，相对分子质量78，分子式？取C12、H1。","given":"式量13。","analysis":"求整数倍。","method":"78/13=6。","principle":"原子比例放大同倍数。","steps":["k=6。","分子式C₆H₆，式量72+6=78。"],"ans":"C₆H₆。","verification":"C:H仍1:1。","pitfall":"只把C乘6而H不乘。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]},{"q":"仅含C/H的0.28 g样品燃烧得0.88 g CO₂、0.36 g H₂O，求最简式并用质量检查。","given":"完全燃烧且产物定量。","analysis":"先C/H摩尔比，再总质量。","method":"nC=nCO₂，nH=2nH₂O。","principle":"原子数与质量守恒。","steps":["nC=.88/44=.020；nH=2×.36/18=.040 mol。","比1:2，最简式CH₂。","mC=.24、mH=.04，共.28 g。"],"ans":"CH₂，与样品质量相符。","verification":"无须由最简式推断一定为某一特定烯烃。","pitfall":"比值2就直接说分子式C₂H₄。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]}],"quiz":{"q":"同一最简式的两个物质，是否必有相同分子式和性质？","given":"未给分子量与结构。","analysis":"最简比例信息有限。","method":"分别列可能倍数与连接差异。","principle":"分子式和结构层次比最简式更具体。","steps":["最简式可用不同整数倍构成分子式。","即使分子式相同也可能结构不同、性质不同。"],"ans":"不必。","verification":"CH₂O与C₂H₄O₂最简式同而分子式不同。","pitfall":"以相同比例推出同种物质。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]},"exam":["分类题逐项查元素和约定例外，烃只是有机物子类","燃烧题先产物摩尔数再数C/H原子，氧差值需仅含C/H/O","结构推断题写清最简式、分子式与连接分别需要何证据"],"quick":["碳的连接","有机与无机约定","烃与衍生物","最简式分子式","结构证据"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.1","url":"https://openstax.org/books/chemistry-2e/pages/20-1-hydrocarbons","page_or_section":"20-1-hydrocarbons","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.1","url":"https://openstax.org/books/chemistry-2e/pages/20-1-hydrocarbons","page_or_section":"20-1-hydrocarbons","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"分类题逐项查元素和约定例外，烃只是有机物子类","method":"k=60/30。","principle":"元素比例和分子量约束原子数，不唯一约束连接。","worked_example_index":2,"verification":"式量24+4+32=60。","pitfall":"把最简式当分子式或直接认定唯一官能团。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按组成与结构解释有机化合物分类”的抽样复核：其余两项虽含C但在约定无机类。；若出现“把所有含碳物都叫烃。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“由燃烧数据求最简式并检查证据限制”的抽样复核：最简式质量分数C40%、H约6.67%、O约53.33%，对应0.30 g各质量。；若出现“将水的摩尔数直接当H原子摩尔数。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"以相同比例推出同种物质。","correction":"不必。","verification":"CH₂O与C₂H₄O₂最简式同而分子式不同。"}],"illustration_spec":{"title":"组成、分子式与结构的信息层次","objects":["分类集合","CO₂/H₂O燃烧产物","C/H/O摩尔比","最简式","分子式","结构证据"],"relations":["烃仅C/H","nH=2nH₂O","氧差值需元素范围条件","分子式不能自动唯一结构"],"labels":["有机物","烃","CH₂O","C₂H₄O₂","定量收集"],"format":"SVG","priority":"P0","reuse":"可复用物质的量流程局部，非完整有机分类图","english":"Show hydrocarbons as the carbon-and-hydrogen-only subset, with CO2 and carbonates treated as conventional inorganic exceptions. Trace quantitative combustion products to C/H atom amounts, then empirical and molecular formulas; require extra evidence for unique connectivity."}},"26.2":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":26,"section_id":"26.2","goals":["用结构与分子间作用解释常见性质趋势","识别概括规律的例外并评价实验结论"],"prerequisites":["共价键与分子间作用","溶解与导电"],"flow":["结构差异","分子间作用","溶解与电离","燃烧条件","趋势与例外"],"concept_relation":"结构差异；分子间作用；溶解与电离；燃烧条件；趋势与例外","deep":["许多纯共价有机物不含自由移动离子，因而导电弱，但有机酸在水中可电离，有机盐或其他有机材料也可导电。实验必须分清纯物质、溶液及浓度，不能用一次无明显电流排除所有有机物。","不少含碳氢有机物可燃，完全燃烧可生成CO₂、H₂O等；氧不足可能生成CO和烟炱，含其他元素还可能有别的产物。仅看产生烟不能唯一判定物质身份，也不能认为完全燃烧的全部有机物产物只有两种。","有机反应常涉及特定官能团与条件，可能产生混合物、经历多步骤或有副反应，但有些反应也很快。反应速率、平衡与产率是不同概念：反应快不自动给高纯度或高产率，反应慢也不表示热力学上不可发生。","把趋势用于题目时先确定比较对象属于哪类结构，并核温度、溶剂、压力及纯度等条件。用结构推理提出可检验预测，然后与数据比较；如果有例外，追查结构或条件，而不是删去不合口诀的数据。"],"derive":["分子内键决定连接；熔沸常涉及分子间作用，两者不能混同。","同类结构比较氢键、极性、相对分子质量和形状，避免单因素无条件推断。","电导须有可移动载流子；水溶性与导电性不是同一性质。"],"examples":[{"q":"学生说乙醇沸腾必把每个C—C键断开，为什么不对？","given":"正常沸腾而非分解。","analysis":"相变与化学分解不同。","method":"区分分子内键与分子间吸引。","principle":"汽化主要使分子彼此分离。","steps":["液态转气态时乙醇分子通常仍保留连接。","所克服主要是分子间作用，包括氢键等。"],"ans":"把相变误当分子内化学键断裂。","verification":"蒸气冷凝仍可回到乙醇，不需重新合成C—C键。","pitfall":"以所有吸引都叫键而混淆层次。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]},{"q":"甲乙分子大小近似，甲有可形成分子间氢键的OH，乙无且极性弱，预测沸点并说明限制。","given":"其他结构尽量相近，不指定具体数值。","analysis":"氢键可增强相互吸引。","method":"按分子间作用比较。","principle":"较强分子间作用通常需更高温度分离。","steps":["甲通常有较高沸点的理由。","仍需核实际形状、其他作用与压力，不把预测当无例外定理。"],"ans":"通常预测甲较高，需实测或可靠数据确认。","verification":"没有结构可比条件时不能只看一个基团。","pitfall":"把OH数量当唯一决定因素。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]},{"q":"糖溶液几乎不导电，醋酸溶液能弱导电，能否说后者不属有机物？","given":"两者均为相应有机物水溶液。","analysis":"导电取决移动离子，不是有机分类判据。","method":"比较是否产生离子。","principle":"酸可在水中部分电离。","steps":["糖主要以分子溶解。","醋酸可产生少量离子，故可导电而仍属有机。"],"ans":"不能；有机物也可形成导电溶液。","verification":"溶于水不自动离子化，分类与电离不同。","pitfall":"把有机物不导电当绝对规律。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]}],"practice":[{"q":"有机物都不溶于水吗？","given":"问普遍命题。","analysis":"需要反例和机制。","method":"用可形成氢键小分子说明。","principle":"水溶性依结构与相互作用。","steps":["乙醇等小分子可与水良好混合。","非极性长链又常难溶，不能统一。"],"ans":"不是。","verification":"同属有机物仍有不同极性和碳链。","pitfall":"把常见烃的性质推广所有有机物。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]},{"q":"一种有机物不完全燃烧产CO，能说违反碳守恒吗？","given":"氧可能不足。","analysis":"守恒原子不要求只生成CO₂。","method":"配平简单示例。","principle":"原子可分配到不同产物。","steps":["2CH₄+3O₂→2CO+4H₂O。","两侧C2、H8、O6守恒。"],"ans":"不违反。","verification":"氧不足使产物分布不同，碳仍守恒。","pitfall":"把完全燃烧产物当唯一可能。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]},{"q":"某反应很快，是否产率必为100%？","given":"未给平衡、副反应与收集。","analysis":"速率和产率不同。","method":"列造成产率损失的过程。","principle":"产率是实际目标产物/理论量。","steps":["快速可能也快速生成副产物。","平衡、分离和损失仍可降低目标收率。"],"ans":"不必。","verification":"快只说明时间尺度，不提供目标产物总量。","pitfall":"把快、完全、纯三者混同。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]},{"q":"乙醇样品0.10 mol完全燃烧，理论CO₂与H₂O各多少？若实测水少能直接说H不守恒吗？","given":"C₂H₅OH+3O₂→2CO₂+3H₂O。","analysis":"先按配平计量，后审实验收集。","method":"产物摩尔比2与3。","principle":"原子守恒与测量边界。","steps":["CO₂=.20 mol，H₂O=.30 mol。","水少可能因未定量收集、未完全反应等，不能据此宣称守恒失效。"],"ans":"0.20与0.30 mol；须查条件。","verification":"C原子.20 mol、H原子.60 mol与原料相合。","pitfall":"用测量损失否定守恒。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]}],"quiz":{"q":"一种分子含OH又有很长烃链，能仅凭OH断言它与水任意比例互溶吗？","given":"同时有亲水与非极性部分。","analysis":"需比较整体结构。","method":"分析两类作用竞争并需数据。","principle":"溶解由综合相互作用决定。","steps":["OH可增强与水相互作用。","长烃链可降低水溶性，不能只凭单一基团给无限互溶结论。"],"ans":"不能。","verification":"同类醇随碳链增长可出现不同溶解行为。","pitfall":"只见官能团而忽略骨架。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]},"exam":["性质解释题从结构、作用、宏观性质三层连接","分类题不能把溶解或电导当单一判据，先辨纯物质/溶液","实验异常题查纯度、条件和收集，不用绝对口诀覆盖数据"],"quick":["结构差异","分子间作用","溶解与电离","燃烧条件","趋势与例外"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.2","url":"https://openstax.org/books/chemistry-2e/pages/20-2-alcohols-and-ethers","page_or_section":"20-2-alcohols-and-ethers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.2","url":"https://openstax.org/books/chemistry-2e/pages/20-2-alcohols-and-ethers","page_or_section":"20-2-alcohols-and-ethers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"性质解释题从结构、作用、宏观性质三层连接","method":"比较是否产生离子。","principle":"酸可在水中部分电离。","worked_example_index":2,"verification":"溶于水不自动离子化，分类与电离不同。","pitfall":"把有机物不导电当绝对规律。"},"diagnostics":[{"goal_index":0,"question_ref":"e1","review_module":4,"feedback":"目标“用结构与分子间作用解释常见性质趋势”的抽样复核：没有结构可比条件时不能只看一个基团。；若出现“把OH数量当唯一决定因素。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“识别概括规律的例外并评价实验结论”的抽样复核：溶于水不自动离子化，分类与电离不同。；若出现“把有机物不导电当绝对规律。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"只见官能团而忽略骨架。","correction":"不能。","verification":"同类醇随碳链增长可出现不同溶解行为。"}],"illustration_spec":{"title":"结构与宏观性质的条件关系","objects":["分子内共价键","分子间氢键","水与小分子醇","长链醇","分子与离子溶液"],"relations":["相变不画C—C键普遍断裂","OH亲水性须结合碳链","导电依可移动离子"],"labels":["共价键","分子间作用","非极性部分","可移动离子","趋势非绝对"],"format":"SVG","priority":"P1","reuse":"氢键旧图可局部复用，需核乙醇羟基连接","english":"Distinguish intramolecular covalent bonds from intermolecular hydrogen bonding during boiling. Contrast a small alcohol with a long hydrocarbon chain bearing OH, and neutral molecular solutes with ion-producing solutes. Never imply all organic compounds are insoluble or nonconducting."}},"26.3":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":26,"section_id":"26.3","goals":["按骨架与官能团分别分类","以连接关系解释同分子式不同类别"],"prerequisites":["碳四价","结构式与分子式"],"flow":["骨架分类","关键连接","官能团","多官能团","证据与价键"],"concept_relation":"骨架分类；关键连接；官能团；多官能团；证据与价键","deep":["识别官能团要核原子连接环境：醇羟基与饱和碳相连，酚羟基直接连芳香环；羧基中的OH属于羧基整体，不能因为看到OH就把羧酸简单归醇。醚有C—O—C连接，酯有C(=O)—O—C，额外羰基改变类别。","醛常用—CHO表示，羰基碳连接H；酮羰基碳连接两个碳基团。羧酸有—COOH，酯的酸性OH被相应烃基氧连接形式替代。使用缩写时不漏必要原子，例如—CHO的O与C双键不能画成任意串联单键。","分类可帮助预测可能反应，但同官能团受邻近基团、空间和条件影响，不能只凭标签断言所有反应产物和速率相同。多官能团分子还要分析哪个部位在给定试剂与条件下反应。","答题时先把缩写还原到关键连接，再分骨架和官能团作答。若只有分子式，可列合理候选并指出还需证据，不把“可能含双键”写成“必是烯烃”，更不能为符合通式擅自忽略环。"],"derive":["分类至少分两轴：碳骨架（链/环等）与官能团（醇/醚/醛/酮/酸/酯等）。","CnH₂n可对应单环饱和烃或单烯烃等相应模型，不能仅由通式唯一判类别。","画结构后核每个C常见四价、O常见二价、H一价；官能团按连接环境识别。"],"examples":[{"q":"CH₃CH₂OH和CH₃OCH₃分子式相同吗、类别相同吗？","given":"两式均为完整中性分子。","analysis":"统计原子与判断连接是两步。","method":"数原子再识别O的邻接。","principle":"同分子式可为不同官能团的异构体。","steps":["二者均C₂H₆O。","前者OH连饱和碳属醇，后者C—O—C属醚。"],"ans":"分子式同，类别不同。","verification":"前者O连C与H，后者O连两个C。","pitfall":"只看有氧就归同一官能团。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]},{"q":"分子式C₃H₆能唯一断言是烯烃吗？","given":"没有其他结构或反应证据。","analysis":"环也可减少相对烷烃的氢数。","method":"给两种结构候选。","principle":"分子式不唯一确定骨架。","steps":["丙烯CH₂=CHCH₃符合。","环丙烷三个CH₂成环也符合。"],"ans":"不能；至少有烯烃和环烷烃候选。","verification":"两者均C3H6且价键可满足。","pitfall":"仅按CnH₂n就判唯一。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]},{"q":"CH₃COOH和CH₃COOCH₃分别是什么类别？为什么不能把前者只叫醇？","given":"CO表示所示羰基缩写，需还原。","analysis":"OH属于羧基环境。","method":"辨C(=O)—OH与C(=O)—O—C。","principle":"官能团取决连接。","steps":["前者含羧基属羧酸。","后者含酯基属酯；羧酸OH不等同饱和碳上的醇羟基。"],"ans":"羧酸、酯。","verification":"各O均满足常见价键；羰基不可漏画。","pitfall":"只抓OH字符串而忽略连接的羰基碳。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]}],"practice":[{"q":"CH₃CHO中关键官能团？","given":"末端羰基碳连H。","analysis":"还原CHO缩写。","method":"写CH₃—C(=O)—H。","principle":"醛的羰基碳有H连接。","steps":["中心C与O双键。","另连CH₃和H，故为醛基。"],"ans":"醛基，属醛。","verification":"碳键级总数4。","pitfall":"把CHO画成C—H—O直链。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]},{"q":"CH₃COCH₃属于醛还是酮？","given":"羰基两侧为CH₃。","analysis":"羰基碳无H。","method":"辨邻接原子。","principle":"酮羰基连两个碳基团。","steps":["C=O两侧各连一个CH₃。","因此为酮。"],"ans":"酮。","verification":"分子式C₃H₆O，结构决定类别。","pitfall":"凡有C=O都叫醛。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]},{"q":"一个分子同时含NH₂与COOH，能否只允许它有一个官能团？","given":"给定不同部位均存在。","analysis":"多官能团常见。","method":"分别标识。","principle":"分类维度可重叠。","steps":["氨基与羧基各自保留。","具体反应需按条件分析两处，不必删一个。"],"ans":"不能，应分别识别。","verification":"氨基酸类可体现这种组合。","pitfall":"为单一标签漏掉知识点。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]},{"q":"C₂H₄O₂的两个候选CH₃COOH与HCOOCH₃，分别计原子、判类，能用分子式单独区分吗？","given":"两结构按常见缩写。","analysis":"需核组成相同连接不同。","method":"展开关键羰基和氧连接。","principle":"官能团异构。","steps":["前者C2H4O2、羧酸。","后者C2H4O2、酯，分子式不能单独区分。"],"ans":"二者同分子式而异类。","verification":"HCOOCH₃含醛式H连接羰基但整体为酯，不简单把所有H—C=O都孤立分类。","pitfall":"忽略羰基另一侧O连接环境。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]}],"quiz":{"q":"结构图在醚的氧上画三条普通共价单键且不标电荷，作为普通中性醚是否正确？","given":"无特殊带电说明。","analysis":"常见中性氧价键数受约束。","method":"核每原子价与整体电荷。","principle":"中性醚O通常形成两条单键。","steps":["C—O—C给两连接。","第三单键需相应带电等特殊说明，不能画成普通中性醚。"],"ans":"不正确，应修为两键或明确特殊电荷结构。","verification":"逐原子价核查可发现漂亮图的科学错误。","pitfall":"只看整体像官能团而不查局部价。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]},"exam":["分类题先还原连接，再说骨架与官能团","分子式题列候选和所缺证据，别由通式唯一判类别","绘图题逐原子核价、电荷和隐含H，尤其羰基与羧基"],"quick":["骨架分类","关键连接","官能团","多官能团","证据与价键"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.3","url":"https://openstax.org/books/chemistry-2e/pages/20-3-aldehydes-ketones-carboxylic-acids-and-esters","page_or_section":"20-3-aldehydes-ketones-carboxylic-acids-and-esters","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.3","url":"https://openstax.org/books/chemistry-2e/pages/20-3-aldehydes-ketones-carboxylic-acids-and-esters","page_or_section":"20-3-aldehydes-ketones-carboxylic-acids-and-esters","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"分类题先还原连接，再说骨架与官能团","method":"辨C(=O)—OH与C(=O)—O—C。","principle":"官能团取决连接。","worked_example_index":2,"verification":"各O均满足常见价键；羰基不可漏画。","pitfall":"只抓OH字符串而忽略连接的羰基碳。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“按骨架与官能团分别分类”的抽样复核：各O均满足常见价键；羰基不可漏画。；若出现“只抓OH字符串而忽略连接的羰基碳。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e0","review_module":5,"feedback":"目标“以连接关系解释同分子式不同类别”的抽样复核：前者O连C与H，后者O连两个C。；若出现“只看有氧就归同一官能团。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"只看整体像官能团而不查局部价。","correction":"不正确，应修为两键或明确特殊电荷结构。","verification":"逐原子价核查可发现漂亮图的科学错误。"}],"illustration_spec":{"title":"有机分类的连接判据","objects":["乙醇/二甲醚","羧酸/酯","醛/酮","丙烯/环丙烷"],"relations":["同式不一定同连接","羧酸OH不画成独立醇","每个C和O满足价键"],"labels":["醇","醚","羧酸","酯","醛","酮","分子式≠唯一结构"],"format":"SVG","priority":"P0","reuse":"现有化学结构图须核官能团后局部复用","english":"Compare ethanol with dimethyl ether, carboxylic acid with ester, aldehyde with ketone, and propene with cyclopropane. Render explicit correct connectivity and valence; do not classify a carboxylic OH as an alcohol or infer a unique structure from a molecular formula."}},"26.4":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":26,"section_id":"26.4","goals":["把分离纯化、组成与结构证据分层","由多项资料作有限且可检验的推断"],"prerequisites":["有机分类","计量与实验变量"],"flow":["分离纯化","组成分子式","结构证据","候选排除","产率与报告"],"concept_relation":"分离纯化；组成分子式；结构证据；候选排除；产率与报告","deep":["元素分析和相对分子质量帮助确定组成，化学反应、光谱等进一步约束连接。不同证据回答不同问题：分子式不能直接代替结构，单一颜色变化也往往不能唯一确定物种，需适当对照及综合判断。","结构表示法包括分子式、结构式、简式和模型，各有用途与省略规则。转换时应守住原子数和连接，骨架式省略的碳氢需按端点、转折与价键规则补齐，不能将视觉上短一笔误认为化学组成相同。","本节可用光谱信号或反应证据作逻辑练习，但具体仪器细节和峰位是否属于2027考试范围需另核，不把拓展方法冒充官方要求。题给信号只能按题设可靠规则使用，不能从一个未经说明的峰值虚构完整谱图。","实验报告把原始观察、推导、假设和结论分开，并报告产率、纯度及不确定性。粗产物质量超过理论值可能来自杂质或残留溶剂，不意味着反应违反守恒或创造物质；真实改进应找到损失和污染来源而非美化数据。"],"derive":["Rf=d斑点/d前沿，同一起点同一板且前沿距离非零；无量纲。","产率=实际目标产物量/理论目标产物量×100%；粗样质量不一定等于纯产物质量。","研究证据链：纯度与分离 → 元素组成 → 分子式 → 关键连接证据 → 排除候选 → 再验证。"],"examples":[{"q":"同一色谱板斑点距起点3.0 cm，前沿6.0 cm，Rf多少？单位是什么？","given":"两距离沿同方向、同一起点。","analysis":"比值相同长度单位相消。","method":"Rf=3/6。","principle":"迁移相对距离。","steps":["Rf=.50。","cm/cm相消，不带cm。"],"ans":"0.50，无单位。","verification":"斑点在前沿一半位置符合。","pitfall":"把3 cm当Rf或保留cm。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]},{"q":"理论产物5.0 g，收得粗产物5.5 g，能宣布产率110%且合成创造物质吗？","given":"未测纯度与残留溶剂。","analysis":"粗质量不是纯目标量。","method":"先查杂质并求纯目标产率。","principle":"守恒与产物纯度。","steps":["5.5/5.0=110%是表观粗质量比。","可能含溶剂或副产物，需纯化/定量，不能称纯产率或物质创造。"],"ans":"不能，应调查纯度和干燥等。","verification":"加入非目标质量足以解释超理论。","pitfall":"把容器中所有质量都算目标产物。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]},{"q":"候选为乙醇或二甲醚，分子式均C₂H₆O；题设可靠证据显示有与H相连的O，能排除哪一个？","given":"只使用题给连接证据。","analysis":"分子式不区分，OH连接可区分。","method":"比较候选结构。","principle":"乙醇有O—H，二甲醚O连两C。","steps":["乙醇CH₃CH₂OH符合。","二甲醚CH₃OCH₃不含O—H，因此排除。"],"ans":"排除二甲醚，支持乙醇候选。","verification":"结论限定这两个候选，不声称在全世界所有物质中唯一。","pitfall":"仅凭分子量46就直接确定乙醇。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]}],"practice":[{"q":"Rf相同能无条件证明是同一物质吗？","given":"仅给一个色谱条件的相同迁移。","analysis":"不同物质可能共迁移。","method":"补多条件或独立鉴别。","principle":"单一特征不一定唯一。","steps":["相同Rf表示该条件下迁移相似。","需其他色谱条件或结构证据支持身份。"],"ans":"不能。","verification":"两个组分共迁移可呈一个斑点。","pitfall":"把单一比值当身份证。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]},{"q":"两个完全互溶液体能靠形成上下两层进行普通分液萃取吗？","given":"相同条件下完全互溶。","analysis":"分液需相分离。","method":"检查溶剂体系。","principle":"液液萃取通常要求可分开的相。","steps":["完全互溶不形成所需稳定两层。","需改用合适体系或其他分离方法，并遵规范。"],"ans":"不能按该两层模型直接操作。","verification":"无界面就没有题设的上下层分液。","pitfall":"只记分液漏斗名而忽略相性质。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]},{"q":"某目标物受热易分解，简单加热至沸点一定适合纯化吗？","given":"稳定性不足。","analysis":"分离条件可改变物质本身。","method":"评估温压和替代方案。","principle":"纯化需保留目标物化学身份。","steps":["加热可能先分解再挥发。","需可靠条件与合适方法，不能只用沸点差决定。"],"ans":"不一定。","verification":"若目标被破坏，收集到的不是原物。","pitfall":"只比较沸点不审热稳定性。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]},{"q":"理论6.5 g，实收6.0 g粗样纯度86.7%，估纯产物产率。","given":"纯度指目标物质量分数，按题给数。","analysis":"先扣除杂质质量。","method":"m纯=m粗×纯度，再除理论。","principle":"产率应以目标物量比较。","steps":["m纯=6.0×.867=5.202 g。","产率5.202/6.5×100%≈80.0%。"],"ans":"约80%。","verification":"若错用粗量会得92.3%，明显忽略杂质。","pitfall":"把纯度86.7%直接当产率。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]}],"quiz":{"q":"一条仪器信号支持某官能团，是否可以跳过全部其他证据宣布唯一分子结构？","given":"没有完整谱或候选约束。","analysis":"局部特征不唯一决定整体。","method":"列剩余骨架与连接不确定。","principle":"结构鉴定通常综合多证据。","steps":["同官能团可存在于多种分子。","需组成、分子量和其他连接信息排除候选。"],"ans":"不能无条件。","verification":"乙醇与其他醇均可有O—H。","pitfall":"把官能团信号当完整结构图。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]},"exam":["研究题明确每项证据能回答哪层问题，结论不超范围","色谱题保持同相同条件，Rf无单位且不是唯一身份","产率题先辨粗样、纯度与目标量，再按配平理论量计算"],"quick":["分离纯化","组成分子式","结构证据","候选排除","产率与报告"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.4","url":"https://openstax.org/books/chemistry-2e/pages/4-4-reaction-yields","page_or_section":"4-4-reaction-yields","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"IUPAC_Rf","url":"https://goldbook.iupac.org/terms/view/R05353/html","page_or_section":"retardation factor in planar chromatography","version":"IUPAC术语定义；非2027范围","access_date":"2026-11-18","verification_status":"verified_definition"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.4","url":"https://openstax.org/books/chemistry-2e/pages/4-4-reaction-yields","page_or_section":"4-4-reaction-yields","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"IUPAC_Rf","url":"https://goldbook.iupac.org/terms/view/R05353/html","page_or_section":"retardation factor in planar chromatography","version":"IUPAC术语定义；非2027范围","access_date":"2026-11-18","verification_status":"verified_definition"}],"verification_status":"partially_verified","strategy":{"trigger":"研究题明确每项证据能回答哪层问题，结论不超范围","method":"比较候选结构。","principle":"乙醇有O—H，二甲醚O连两C。","worked_example_index":2,"verification":"结论限定这两个候选，不声称在全世界所有物质中唯一。","pitfall":"仅凭分子量46就直接确定乙醇。"},"diagnostics":[{"goal_index":0,"question_ref":"e1","review_module":4,"feedback":"目标“把分离纯化、组成与结构证据分层”的抽样复核：加入非目标质量足以解释超理论。；若出现“把容器中所有质量都算目标产物。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“由多项资料作有限且可检验的推断”的抽样复核：结论限定这两个候选，不声称在全世界所有物质中唯一。；若出现“仅凭分子量46就直接确定乙醇。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把官能团信号当完整结构图。","correction":"不能无条件。","verification":"乙醇与其他醇均可有O—H。"}],"illustration_spec":{"title":"有机鉴定的证据层级","objects":["混合样","分离","元素分析","相对分子质量","结构候选","色谱板"],"relations":["Rf为同起点距离比","一个斑点不必纯","分子式不直接唯一连接","产率先扣杂质"],"labels":["Rf=3/6=0.50","粗样","纯度","最简式","分子式","连接证据"],"format":"SVG","priority":"P1","reuse":"无整体对应图；色谱距离须精确","english":"Show an evidence hierarchy from separation and purity to elemental composition, molecular formula and connectivity tests. Draw a chromatogram with spot travel 3 cm and solvent front 6 cm from the same baseline, Rf=0.50; state that one spot or one matching Rf is not proof of purity or identity."}},"26.5":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":26,"section_id":"26.5","goals":["从结构性能用途解释技术价值","依据收支和证据评价所谓绿色创新"],"prerequisites":["有机结构与材料","产率与系统边界"],"flow":["合成与身份","结构设计","材料与药物","绿色工艺","生命周期证据"],"concept_relation":"合成与身份；结构设计；材料与药物；绿色工艺；生命周期证据","deep":["聚合物把小单元连接成长链，为纤维、塑料及其他材料提供广泛性质。相同重复单元的材料还可因链长、支化、结晶和加工而表现不同，后续聚合物章节会系统展开；本节先说明结构层次与宏观性能之间的联系。","药物研发不只是找到能在试管中反应的分子，还需评估选择性、体内过程、安全与临床效果。细胞实验中抑制某过程是证据链的一部分，不足以证明人体疗效；教学例子不提供个体医疗判断。","绿色化学关注从源头减少危害与资源负担，可涉及催化、减少副产物、较低能耗与更安全原料。高产率不等于所有原子都进入目标产物，天然原料也不保证生命周期负担低；评价需有明确功能单位和边界。","分析“新材料更环保”的宣传，要看原料、制造、使用、回收和最终处置，区分可生物降解、可堆肥及可回收的条件。标签若缺温度、环境、时间和处理设施，不能从一个词推断在海洋或家中任何条件都会迅速无害消失。"],"derive":["产率衡量目标产物实际量/理论量；原子利用等工艺指标衡量另一个维度，不能互代。","给定工艺物料收支：输入质量=目标产物+副产物+未反应/损失等相应项，边界要完整。","技术评价：结构与机制 → 可测性能 → 使用条件 → 安全与环境 → 生命周期与证据限制。"],"examples":[{"q":"实验室合成的纯乙醇与天然发酵分离的纯乙醇，若结构与同位素等相关条件按题忽略，是否仅因来源不同而是两种化学物质？","given":"比较同样纯度、相同组成连接的理想样品。","analysis":"化学身份不能只按来源。","method":"按组成结构比较。","principle":"同一物质的关键身份由化学结构等确定。","steps":["二者均CH₃CH₂OH。","实际杂质可不同，但题设纯样条件下不能因合成/天然就判不同物质。"],"ans":"不能仅因来源判为不同物质。","verification":"来源信息不改变题给连接。","pitfall":"天然与合成必有完全不同化学式。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]},{"q":"两工艺各投入100 kg原料，甲目标产物60 kg、副产物40 kg；乙目标80 kg、副20 kg，能仅据此认定乙在所有环境指标更好？","given":"只给此物料边界，未给危害与能源。","analysis":"较高目标质量比例是一个指标。","method":"先算比例，再列其他维度。","principle":"环境评价涉及毒性、能耗与处置等。","steps":["目标比例甲60%、乙80%。","乙在该质量指标较好，但原料危害、能耗、溶剂及寿命未知。"],"ans":"不能全面断言。","verification":"乙可能用更危险原料或更高能耗，当前数据无法排除。","pitfall":"一个高百分比替代整体环境评价。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]},{"q":"材料标注“可降解”，能保证在任何环境短时间完全无害消失吗？","given":"无测试条件、时间与产物资料。","analysis":"术语有条件且降解产物仍需评价。","method":"要求测试环境和证据。","principle":"降解取决温湿度、微生物与材料结构等。","steps":["明确工业堆肥、土壤或其他环境及时间。","检测降解程度与产物，不能把标签推广海洋等所有条件。"],"ans":"不能保证。","verification":"同材料在干冷或无适宜微生物处可表现不同。","pitfall":"把有条件声明转成绝对环保承诺。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]}],"practice":[{"q":"天然提取物是否一定无毒？","given":"无剂量和成分分析。","analysis":"来源不决定全部风险。","method":"核具体物质、纯度与暴露。","principle":"风险与危害及暴露有关。","steps":["天然物也可有强生物活性或毒性。","需证据评价，不可由天然二字保证安全。"],"ans":"不一定。","verification":"同样的分子不因来源天然就失去毒性。","pitfall":"天然等于安全。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]},{"q":"催化剂让反应更快，是否把平衡常数任意提高？","given":"同一反应温度，讨论通常催化。","analysis":"动力学与平衡不同。","method":"区分路径活化与终态。","principle":"催化改变速率途径，不改变相同温度的平衡常数。","steps":["可使更快接近平衡。","不能由此说平衡组成必向目标移动。"],"ans":"不会仅靠催化任意改K。","verification":"正逆过程均可加快。","pitfall":"把快与平衡产率混同。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]},{"q":"某药物候选在细胞实验有效，是否已可直接宣称人体治疗有效？","given":"缺体内与临床证据。","analysis":"层次外推受限。","method":"列安全、到达浓度及临床验证。","principle":"体外作用不等于人体结局。","steps":["需看选择性、吸收代谢和毒性等。","经相应研究才能评价人体有效性。"],"ans":"不能直接宣称。","verification":"试管所需浓度可能人体不可安全达到。","pitfall":"用一个实验跳过完整证据链。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]},{"q":"工艺投入50 kg，可回收未反应原料10 kg，目标产品30 kg、副产物10 kg，检查物料收支；能把10 kg回收量直接算成产品吗？","given":"边界包含回收原料。","analysis":"回收与目标产物不同类别。","method":"总量相加并分类。","principle":"质量守恒不抹平物质身份。","steps":["10+30+10=50 kg，收支相符。","产品为30 kg，回收原料仍非产品，后续循环须另核实际转化。"],"ans":"收支相符；不能算40 kg产品。","verification":"分类总和守恒而目标量独立。","pitfall":"把回收原料充当已转化产物。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]}],"quiz":{"q":"一种新聚合物强度提高，就能断言可回收性、毒性和碳足迹同时改善吗？","given":"只知力学指标。","analysis":"不同指标可能有权衡。","method":"要求各自测量与生命周期边界。","principle":"结构性能关联不提供所有环境结果。","steps":["强度需相应力学测试。","回收、危害与排放要各自证据，不能从强度单指标推出。"],"ans":"不能。","verification":"更强交联可能反而更难某些回收处理。","pitfall":"一项创新等于全面无代价提升。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]},"exam":["进展题写结构、机制、价值和限制，不堆未核年代","绿色评价把产率、原料危害、能耗与处置分开","证据题限定体外/体内与使用条件，不能将标签当完整验证"],"quick":["合成与身份","结构设计","材料与药物","绿色工艺","生命周期证据"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.5","url":"https://www.acs.org/green-chemistry-sustainability/principles/12-principles-of-green-chemistry.html","page_or_section":"12-principles-of-green-chemistry.html","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.5","url":"https://www.acs.org/green-chemistry-sustainability/principles/12-principles-of-green-chemistry.html","page_or_section":"12-principles-of-green-chemistry.html","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"进展题写结构、机制、价值和限制，不堆未核年代","method":"要求测试环境和证据。","principle":"降解取决温湿度、微生物与材料结构等。","worked_example_index":2,"verification":"同材料在干冷或无适宜微生物处可表现不同。","pitfall":"把有条件声明转成绝对环保承诺。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“从结构性能用途解释技术价值”的抽样复核：来源信息不改变题给连接。；若出现“天然与合成必有完全不同化学式。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“依据收支和证据评价所谓绿色创新”的抽样复核：同材料在干冷或无适宜微生物处可表现不同。；若出现“把有条件声明转成绝对环保承诺。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"一项创新等于全面无代价提升。","correction":"不能。","verification":"更强交联可能反而更难某些回收处理。"}],"illustration_spec":{"title":"有机创新的多指标评价","objects":["分子结构","性能测试","物料收支","能源输入","使用与处置","证据阶梯"],"relations":["来源不决定安全","产率不等同完整环境表现","降解条件须标明"],"labels":["结构—性能","目标产物","副产物","能耗","条件与时间","证据范围"],"format":"SVG","priority":"P2","reuse":"不需辅助插画替代科学关系；可用清晰结构图","english":"Map organic innovation from molecular structure to measured performance, material balance, energy use and end-of-life conditions. Distinguish natural origin from safety, reaction yield from overall environmental performance, and conditional degradability from universal harmless disappearance."}}},"化学29":{"29.1":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":29,"section_id":"29.1","goals":["在限定结构下推导炔烃通式","按三键位置命名并区分同式异类"],"prerequisites":["烃的分类","碳四价与结构式"],"flow":["三键定义","条件通式","母链编号","位置与链异构","结构价核查"],"concept_relation":"三键定义；条件通式；母链编号；位置与链异构；结构价核查","deep":["乙炔最少两个碳，丙炔三键位置在链端；丁炔可有1-丁炔与2-丁炔，属于位置异构。用结构式核每个碳的总价键数，不能在三键碳上又多接超过允许的取代基。","碳骨架分支可带来链异构，但不能只凭有支链就判为新异构体；重新选择最长母链可能发现两个画法只是同一连接。翻转纸面或从另一端编号不产生新物质。","分子式相同不保证同属炔烃，C₄H₆的二烯等候选说明需结构或反应证据。识别同分异构时先核原子数相同，再比较连接，不把不同碳数的两个式子叫异构。","写结构与命名要双向校验：由名称画主链、标三键、加支链、补氢；由结构选母链和位次，再比较是否能还原同一图。若只用简单一炔模型求通式，不扩展到环、多三键或杂原子化合物。"],"derive":["无环单三键烃：CₙH₂ₙ₋₂，n≥2；相对同碳数烷烃少4H。","1-丁炔HC≡C—CH₂—CH₃；2-丁炔CH₃—C≡C—CH₃，均C₄H₆。","命名先核含三键母链及最低相应位次，画图逐碳核四价。"],"examples":[{"q":"无环单三键炔烃含5个碳，分子式是什么？能否由此唯一确定结构？","given":"无其他不饱和结构。","analysis":"通式有条件但不能唯一连接。","method":"代n5。","principle":"相对烷烃少4H。","steps":["H=2×5−2=8，式C₅H₈。","三键位置和支链仍可能不同，不能唯一。"],"ans":"C₅H₈，非唯一结构。","verification":"同碳烷烃C₅H₁₂少4H。","pitfall":"把通式解当唯一物质名。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.1","related_sections":[]},{"q":"命名CH₃CH₂C≡CH与CH₃C≡CCH₃，并判断异构关系。","given":"均四碳无环单三键。","analysis":"从靠三键端编号。","method":"确定母链与位次。","principle":"位次取三键较小碳号。","steps":["第一反向编号三键1位，为1-丁炔。","第二三键2位，为2-丁炔；同式C₄H₆、连接不同。"],"ans":"1-丁炔、2-丁炔，位置异构。","verification":"前者端炔有C≡C—H，后者内炔没有。","pitfall":"把第一叫3-丁炔而不选最低编号。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.1","related_sections":[]},{"q":"C₄H₆是否必为丁炔？给不属炔烃的同分子式候选并核价。","given":"未给反应或连接资料。","analysis":"通式必要不充分。","method":"构造二烯。","principle":"一个三键和两个双键均可少4H。","steps":["CH₂=CH—CH=CH₂含C4H6。","有两个双键、无三键，属于二烯候选。"],"ans":"不必。","verification":"每碳四价，氢2+1+1+2=6。","pitfall":"看到H=2n−2就排除全部非炔候选。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.1","related_sections":[]}],"practice":[{"q":"乙炔与丙炔的分子式？","given":"单三键无环模型。","analysis":"n2、3。","method":"CₙH₂ₙ₋₂。","principle":"通式。","steps":["乙炔C₂H₂。","丙炔C₃H₄。"],"ans":"C₂H₂、C₃H₄。","verification":"HC≡CH与CH₃C≡CH数原子吻合。","pitfall":"把乙炔写C₂H₄。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.1","related_sections":[]},{"q":"HC≡C—CH(CH₃)—CH₃的母链、三键位次和名称。","given":"连接按给定简式。","analysis":"最长含三键链4碳。","method":"从端炔侧编号。","principle":"母链与取代基。","steps":["三键1位，甲基在3位。","名称3-甲基-1-丁炔。"],"ans":"3-甲基-1-丁炔。","verification":"总C5、H8，与一炔通式相符。","pitfall":"选不含三键的链作母体。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.1","related_sections":[]},{"q":"把1-丁炔结构从右往左画，是新异构体吗？","given":"连接未变。","analysis":"画面朝向不决定化学身份。","method":"比较碳邻接和三键位置。","principle":"同一分子可有多种画法。","steps":["翻转后重新从靠三键端编号。","仍同一连接与同名。"],"ans":"不是。","verification":"原子邻接表完全相同。","pitfall":"每种画法都计一种异构。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.1","related_sections":[]},{"q":"一候选声称C≡C中的一个碳同时还连两个CH₃，作为普通中性炔是否满足四价？","given":"同一个三键碳有三键及两单键。","analysis":"键级和超出。","method":"数键级3+1+1。","principle":"通常中性碳四价。","steps":["总键级5。","不符合本节普通中性碳结构，必须修正连接，不能计为合法异构体。"],"ans":"不满足。","verification":"正常炔碳除三键外仅再一条单键。","pitfall":"只数连接对象不数三键键级。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.1","related_sections":[]}],"quiz":{"q":"单三键无环炔烃的n能取1吗？为什么不能仅按式子得到CH₀就算存在？","given":"结构要求C≡C。","analysis":"通式范围来自结构。","method":"检查最少碳数。","principle":"三键需要两个碳原子。","steps":["n至少2。","n1不满足炔烃结构，代数式不能自行创造物质。"],"ans":"不能，n≥2。","verification":"最简单成员乙炔C₂H₂。","pitfall":"公式外推到未允许的整数。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.1","related_sections":[]},"exam":["命名题先选含三键母链，再低位编号与补氢","异构题先核同分子式再核连接，翻转图不算新种","通式题每次注明无环单三键条件，不能凭式唯一分类"],"quick":["三键定义","条件通式","母链编号","位置与链异构","结构价核查"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":14,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_29.1","url":"https://openstax.org/books/chemistry-2e/pages/20-1-hydrocarbons","page_or_section":"20-1-hydrocarbons","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_29.1_0","url":"https://openstax.org/books/organic-chemistry/pages/9-1-naming-alkynes","page_or_section":"9-1-naming-alkynes","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":14,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_29.1","url":"https://openstax.org/books/chemistry-2e/pages/20-1-hydrocarbons","page_or_section":"20-1-hydrocarbons","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_29.1_0","url":"https://openstax.org/books/organic-chemistry/pages/9-1-naming-alkynes","page_or_section":"9-1-naming-alkynes","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"命名题先选含三键母链，再低位编号与补氢","method":"构造二烯。","principle":"一个三键和两个双键均可少4H。","worked_example_index":2,"verification":"每碳四价，氢2+1+1+2=6。","pitfall":"看到H=2n−2就排除全部非炔候选。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“在限定结构下推导炔烃通式”的抽样复核：同碳烷烃C₅H₁₂少4H。；若出现“把通式解当唯一物质名。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“按三键位置命名并区分同式异类”的抽样复核：每碳四价，氢2+1+1+2=6。；若出现“看到H=2n−2就排除全部非炔候选。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"公式外推到未允许的整数。","correction":"不能，n≥2。","verification":"最简单成员乙炔C₂H₂。"}],"illustration_spec":{"title":"炔烃命名与通式边界","objects":["乙炔","1-丁炔","2-丁炔","3-甲基-1-丁炔","二烯同式候选"],"relations":["三键碳四价","同式不唯一结构","端炔与内炔区分","翻转不新增异构"],"labels":["CₙH₂ₙ₋₂","n≥2","无环单三键","最低位次","C≡C"],"format":"SVG","priority":"P0","reuse":"已有烃图需核三键连接后复用，无完整对应","english":"Draw valence-correct ethyne, but-1-yne, but-2-yne and 3-methylbut-1-yne with numbered parent chains. State the acyclic single-triple-bond formula CnH2n-2 for n>=2, and contrast a C4H6 diene to show that a molecular formula is not a unique class identifier."}},"29.2":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":29,"section_id":"29.2","goals":["用sp杂化说明三键的线性几何","区分键总强度π反应性与端氢酸性"],"prerequisites":["σ键π键","杂化与官能团"],"flow":["sp局部几何","1σ2π","键长强度","π加成","端氢条件"],"concept_relation":"sp局部几何；1σ2π；键长强度；π加成；端氢条件","deep":["普通碳碳三键通常比相应双键、单键短，整体键能也较大，但仍可发生加成，因为反应可保留σ框架并重组π相关键。不能从“总键强”推出绝对惰性，也不能说加成必须一次打断所有三键。","三键区域限制相应几何和旋转自由，内炔的两个相连碳各只再有一个σ连接。与烯烃顺反异构的讨论不同，不能在一个直线三键两端简单画成烯烃式cis/trans并当成同样的几何异构。","端炔有直接连sp碳的H，内炔没有该端氢。端氢相对烯烃、烷烃中的相应C—H更易被强碱移去，可从sp碳较高s成分对负电荷稳定的模型理解；但它仍是很弱的酸，不能据此说溶于水就像强酸显著酸化。","结构决定后续特定反应条件。识别端炔反应先看C≡C—H连接，不把普通甲基上的H当端氢；判断酸碱与鉴别反应需要具体试剂，不由一个官能团词推任意实验现象。"],"derive":["C≡C=1σ+2π；两个π系统方向相互正交，σ沿核间轴。","三键碳sp模型，连接夹角约180°；整个长分子不必全线性。","端炔R—C≡C—H有相应端氢，内炔R—C≡C—R′没有；弱酸性不等于能被任意弱碱定量去质子。"],"examples":[{"q":"乙炔碳碳三键有几条σ、几条π？整分子共有几条σ？","given":"HC≡CH。","analysis":"先C—C，再加两C—H。","method":"按键模型计。","principle":"多重键一σ，其余π。","steps":["C≡C为1σ+2π。","加两C—H各1σ，整分子3σ、2π。"],"ans":"三键1σ2π；全分子3σ2π。","verification":"总连接键级为5，3+2吻合。","pitfall":"把三键计3σ或漏C—H。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.2","related_sections":[]},{"q":"2-丁炔能把三键两端取代基画成烯烃式顺反两种几何异构吗？","given":"中心C≡C线性。","analysis":"几何依据不同。","method":"比较sp线性与sp²平面双键。","principle":"炔碳两个σ方向相反。","steps":["三键两端连接沿线性轴。","不产生所声称同样cis/trans布置。"],"ans":"不能按该方式给两种。","verification":"旋转画面不改变相同线性连接。","pitfall":"把烯烃规则无条件搬到炔。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.2","related_sections":[]},{"q":"乙炔三键总键能大于单键，就一定不能加成吗？用键重组解释。","given":"只比较总键强度。","analysis":"反应涉及断键和成键全收支。","method":"区分三键总强与π体系变化。","principle":"化学反应不由单个键能一项决定。","steps":["加成可把π相关连接重组为新σ键。","无需断开整个碳碳σ骨架，需评价成断键及条件。"],"ans":"不能由总键能推出不反应。","verification":"三键到双键再到单键是分步反应模型。","pitfall":"说总强所以不可能发生任何反应。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.2","related_sections":[]}],"practice":[{"q":"HC≡C—CH₂—CH₃的四个碳是否必须全直线？","given":"三键只涉及前两C的局部几何。","analysis":"局部与全分子区分。","method":"按sp与其他碳连接。","principle":"单键碳可有不同几何。","steps":["三键处近线性。","后方CH₂、CH₃涉及近四面体局部，整分子不必所有原子共线。"],"ans":"不必须。","verification":"延伸链的单键可有构象。","pitfall":"把三键线性推广整个链。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.2","related_sections":[]},{"q":"1-丁炔和2-丁炔哪种有直接连sp碳的端氢？","given":"比较结构。","analysis":"看C≡C—H而非任意H。","method":"分别展开。","principle":"端炔定义。","steps":["1-丁炔一端为H—C≡C。","2-丁炔两端接CH₃，无此端氢。"],"ans":"1-丁炔有，2-丁炔无。","verification":"2-丁炔的H都在甲基上。","pitfall":"有氢就都能作端炔反应。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.2","related_sections":[]},{"q":"端炔较烷烃容易失H⁺，能推出NaOH水溶液必把它定量去质子吗？","given":"未给强碱或相应平衡条件。","analysis":"相对酸性仍可能很弱。","method":"审酸碱强弱和平衡。","principle":"相对比较不等于绝对强酸。","steps":["端炔仍弱酸。","需适当强碱或其他驱动力，不能由相对更酸推出任意碱都完全反应。"],"ans":"不能。","verification":"水相与OH⁻强度不足以支持该无条件断言。","pitfall":"把更强酸直接说成强酸。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.2","related_sections":[]},{"q":"一分子HC≡C—C≡CH含多少C—C σ、π以及总σ？","given":"有两个三键和中间单键。","analysis":"每三键一σ两π。","method":"逐连接计数。","principle":"σ骨架与多重π分开。","steps":["C—C σ共3，π共4。","再加两C—H σ，总σ5。"],"ans":"C—C σ3、π4；总σ5。","verification":"四C链三相邻连接均一σ。","pitfall":"把两个三键当六σ。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.2","related_sections":[]}],"quiz":{"q":"教学图把两π电子云画成同一个平面同一组p轨道的重复图，错在哪里？","given":"描述三键轨道模型。","analysis":"需要两组互相正交未杂化p轨道。","method":"说明σ轴与两π方向。","principle":"sp碳保留两组p。","steps":["每组侧向重叠构成一个π。","两组方向互相正交，不是同一轨道重复两次。"],"ans":"应画两个正交π系统和一个轴向σ。","verification":"轨道数与sp后剩余两个p模型一致。","pitfall":"把双键图复制一份就当三键。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.2","related_sections":[]},"exam":["结构题先局部杂化再计σ/π，不把局部线性扩为全分子","性质解释要看全反应键重组，不以单键能定全部反应性","端炔题核直接sp—H并写试剂条件，相对酸性不是强酸"],"quick":["sp局部几何","1σ2π","键长强度","π加成","端氢条件"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":14,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_29.2","url":"https://openstax.org/books/chemistry-2e/pages/8-2-hybrid-atomic-orbitals","page_or_section":"8-2-hybrid-atomic-orbitals","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_29.2_0","url":"https://openstax.org/books/organic-chemistry/pages/9-7-alkyne-acidity-formation-of-acetylide-anions","page_or_section":"9-7-alkyne-acidity-formation-of-acetylide-anions","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":14,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_29.2","url":"https://openstax.org/books/chemistry-2e/pages/8-2-hybrid-atomic-orbitals","page_or_section":"8-2-hybrid-atomic-orbitals","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_29.2_0","url":"https://openstax.org/books/organic-chemistry/pages/9-7-alkyne-acidity-formation-of-acetylide-anions","page_or_section":"9-7-alkyne-acidity-formation-of-acetylide-anions","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"结构题先局部杂化再计σ/π，不把局部线性扩为全分子","method":"区分三键总强与π体系变化。","principle":"化学反应不由单个键能一项决定。","worked_example_index":2,"verification":"三键到双键再到单键是分步反应模型。","pitfall":"说总强所以不可能发生任何反应。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用sp杂化说明三键的线性几何”的抽样复核：总连接键级为5，3+2吻合。；若出现“把三键计3σ或漏C—H。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“区分键总强度π反应性与端氢酸性”的抽样复核：三键到双键再到单键是分步反应模型。；若出现“说总强所以不可能发生任何反应。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把双键图复制一份就当三键。","correction":"应画两个正交π系统和一个轴向σ。","verification":"轨道数与sp后剩余两个p模型一致。"}],"illustration_spec":{"title":"炔烃sp与三键结构","objects":["H—C≡C—H线性骨架","轴向σ","两组正交p侧向重叠","端炔/内炔对比"],"relations":["180°局部几何","1σ+2π","两π正交","不把电子画成确定小球轨道"],"labels":["sp","σ","π₁","π₂","180°","端氢"],"format":"SVG","priority":"P0","reuse":"暂无对应正确轨道图；科学SVG须专门审轨道方向","english":"Draw linear H-C≡C-H with sp-hybridized carbons, one axial sigma bond and two mutually perpendicular pi systems from unhybridized p orbitals. Contrast a terminal sp-C-H with an internal alkyne; do not draw three equivalent sigma rods or fixed electron trajectories."}},"29.3":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":29,"section_id":"29.3","goals":["用分子作用解释状态溶解与沸点趋势","在同温同压模型下计算气体密度"],"prerequisites":["分子间作用","理想气体与摩尔质量"],"flow":["物态温压","色散作用","溶解条件","理想密度","体积单位"],"concept_relation":"物态温压；色散作用；溶解条件；理想密度；体积单位","deep":["乙炔在某些溶剂中有较高溶解能力，工业储存采用专用系统，不能把它等同在空罐内任意高压压缩。讨论物理溶解与储存原理时，仍要遵规范设备，不能由教学图自行设计加压装置。","同温同压下理想气体密度与摩尔质量成正比。相对空气密度可用M/约29 g·mol⁻¹作题设近似，乙炔比空气略轻；不同温压或明显非理想时不能无条件用摩尔质量比代实际密度。","状态、密度和溶解性属于物理性质，其测量应说明条件和纯度。商品气体的气味可能来自杂质，不能用闻气味识别纯乙炔，气味亦不是可靠的纯度判据。","应用题要把气体密度、体积和物质的量统一到同一温压。22.4 L/mol只在所采用的0°C、101.325 kPa理想模型下近似使用；题给其他摩尔体积时按其条件，不能把所有室温气体都代成同一数字。"],"derive":["理想气体ρ=m/V=PM/(RT)，单位体系需一致。","同温同压、近理想：ρ₁/ρ₂=M₁/M₂；若空气M按题取29，则乙炔相对空气约26/29。","气体状态与溶解比较须注明温压；汽化通常克服分子间作用，非断开全部分子内三键。"],"examples":[{"q":"同温同压理想模型中乙炔相对氢气、相对空气密度各多少？取Mr乙炔26、氢2、空气平均29。","given":"气体条件相同。","analysis":"密度比等摩尔质量比。","method":"分别26/2、26/29。","principle":"理想气体同温同压等体积有相同n。","steps":["相对H₂为13。","相对空气约.897，略小于1。"],"ans":"13和约0.90。","verification":"比氢重并不妨碍比空气轻，参照物不同。","pitfall":"把相对氢密度13直接叫相对空气密度。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.3","related_sections":[]},{"q":"0°C、101.325 kPa下按Vm=22.4 L/mol近似，纯乙炔密度多少g/L？","given":"M=26 g/mol，题给Vm。","analysis":"质量/同条件体积。","method":"ρ=M/Vm。","principle":"一摩尔质量26、体积22.4。","steps":["26/22.4≈1.16 g/L。","该数字不能直接套25°C不同Vm。"],"ans":"约1.16 g/L。","verification":"22.4 L气体质量约26 g，单位相除。","pitfall":"把26 g/mol直接当26 g/L。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.3","related_sections":[]},{"q":"题设纯物质X、Y在同压沸点分别8°C与27°C，熔点均低于20°C，在该压强、20°C平衡时它们倾向什么物态？能仅凭这判断谁是某个唯一炔烃？","given":"只考虑相应常压液气平衡，熔点低于20°C。","analysis":"20介于两沸点。","method":"比温度与沸点并限定。","principle":"同压高于沸点倾向气，低于沸点且高于熔点为液。","steps":["X在20°C高于8，倾向气。","Y低于27且高于给定熔点，倾向液；仅两个沸点不能唯一鉴定化合物。"],"ans":"X气、Y液；不能唯一鉴定。","verification":"压力改变可改沸点，条件不可省。","pitfall":"把碳数或一项物理值当唯一身份。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.3","related_sections":[]}],"practice":[{"q":"同温同压乙炔和丙炔密度比？M分别26、40。","given":"理想气体模型。","analysis":"按摩尔质量比。","method":"26:40。","principle":"同条件V/n相同。","steps":["约为13:20。","丙炔密度较大。"],"ans":"13:20。","verification":"同体积乙炔质量为丙炔.65倍。","pitfall":"把碳数比2:3当密度比。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.3","related_sections":[]},{"q":"乙炔难溶水，是否可写“绝对不溶于任何温压下的水”？","given":"只有通常低溶解趋势。","analysis":"难溶非零且条件可变。","method":"限定溶剂温压。","principle":"溶解性是量与条件关系。","steps":["可有有限溶解。","压力、温度与纯度影响，不能作绝对0的断言。"],"ans":"不应这样写。","verification":"少量可溶与常用难溶描述相容。","pitfall":"把定性词极端化。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.3","related_sections":[]},{"q":"炔烃沸腾时一定把C≡C打断成自由碳吗？","given":"正常相变。","analysis":"物理与化学变化不同。","method":"区分分子间与分子内。","principle":"汽化通常保持分子身份。","steps":["分子彼此分离。","不必断三键，过热分解是另一过程。"],"ans":"不是。","verification":"冷凝可恢复原物，非重新合成三键。","pitfall":"三键强就沸点必超高。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.3","related_sections":[]},{"q":"同一温压下题给Vm=24.5 L/mol，乙炔2.45 L的n和质量？该Vm是否可无条件叫标准状况值？","given":"按题给温压对应Vm，M26。","analysis":"使用条件匹配的体积。","method":"n=V/Vm，再m=nM。","principle":"气体体积计量。","steps":["n=2.45/24.5=.100 mol。","m=.100×26=2.60 g；此Vm不是所用0°C、1 atm的22.4模型值。"],"ans":".100 mol、2.60 g；不可无条件改称标准状况。","verification":"2.60/2.45≈1.06 g/L，温度不同可与1.16不同。","pitfall":"一律除22.4。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.3","related_sections":[]}],"quiz":{"q":"两种气体在不同温压下，能直接用密度比等于摩尔质量比吗？","given":"P,T不相同。","analysis":"密度还受P/T影响。","method":"写ρ=PM/RT。","principle":"理想气体关系。","steps":["ρ₁/ρ₂=(P₁/P₂)(M₁/M₂)(T₂/T₁)。","只有相应温压相同等条件才简为M比。"],"ans":"不能直接。","verification":"即使同一种气体，温压不同也可密度不同。","pitfall":"遗漏条件把一条比例当普遍常数。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.3","related_sections":[]},"exam":["物性题用分子间作用和温压解释，不用断共价键解释普通沸腾","密度题先统一温压与参照气体，确认理想近似","气体计量使用题给Vm条件，标签写清0°C及压力"],"quick":["物态温压","色散作用","溶解条件","理想密度","体积单位"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":14,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_29.3","url":"https://openstax.org/books/chemistry-2e/pages/9-2-relating-pressure-volume-amount-and-temperature-the-ideal-gas-law","page_or_section":"9-2-relating-pressure-volume-amount-and-temperature-the-ideal-gas-law","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":14,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_29.3","url":"https://openstax.org/books/chemistry-2e/pages/9-2-relating-pressure-volume-amount-and-temperature-the-ideal-gas-law","page_or_section":"9-2-relating-pressure-volume-amount-and-temperature-the-ideal-gas-law","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"物性题用分子间作用和温压解释，不用断共价键解释普通沸腾","method":"比温度与沸点并限定。","principle":"同压高于沸点倾向气，低于沸点且高于熔点为液。","worked_example_index":2,"verification":"压力改变可改沸点，条件不可省。","pitfall":"把碳数或一项物理值当唯一身份。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“用分子作用解释状态溶解与沸点趋势”的抽样复核：压力改变可改沸点，条件不可省。；若出现“把碳数或一项物理值当唯一身份。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e0","review_module":5,"feedback":"目标“在同温同压模型下计算气体密度”的抽样复核：比氢重并不妨碍比空气轻，参照物不同。；若出现“把相对氢密度13直接叫相对空气密度。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"遗漏条件把一条比例当普遍常数。","correction":"不能直接。","verification":"即使同一种气体，温压不同也可密度不同。"}],"illustration_spec":{"title":"炔烃物性与气体条件","objects":["乙炔/氢/空气同温同压比较","温度与沸点标尺","水/有机溶剂示意","Vm条件框"],"relations":["26/2=13","26/29≈.90","0°C101.325kPa才用22.4近似","无自行加压装置图"],"labels":["同T同P","g/L","g/mol","Vm","相变不等于断三键"],"format":"SVG","priority":"P1","reuse":"无完全对应；气体摩尔体积旧图需保留温压条件","english":"Compare acetylene density with hydrogen and air only at identical temperature and pressure, using molar masses 26,2 and29. State 0°C and101.325kPa for the approximate22.4 L/mol example. Distinguish boiling from bond cleavage and do not depict an improvised acetylene compression system."}},"29.4":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":29,"section_id":"29.4","goals":["按试剂与用量追踪三键加成产物","区别端炔反应氧化和脱色的鉴定边界"],"prerequisites":["三键结构","配平方程与反应条件"],"flow":["三键两步加成","条件与计量","端氢","氧化燃烧","证据与实验边界"],"concept_relation":"三键两步加成；条件与计量；端氢；氧化燃烧；证据与实验边界","deep":["乙炔与HCl加成可给氯乙烯CH₂=CHCl，继续相应加成可给CH₃CHCl₂。反应物的量和条件要明确，不把一个HCl加成画成两个氯。其他不对称炔的区域选择需按给定机制条件分析，不无条件推广单一方向口诀。","经典酸和汞盐催化的乙炔水合最终可得乙醛，初始烯醇经互变形成羰基；它不是直接给乙醇。这里作为反应识读模型，汞盐有毒，不能把方程当家庭操作说明或绘制无防护实验装置。","端炔有C≡C—H，可在适当银氨或亚铜氨等体系形成相应炔化物沉淀，用于区别某些端炔和内炔。相关金属炔化物存在危险，不能分离干燥、加热或当普通稳定盐展示；教学只按规范教师示范条件讨论现象，不能用此作一般纯度保证。","炔烃可燃烧及被适当氧化剂氧化。完全燃烧按原子守恒配CO₂与H₂O，不完全燃烧可有CO或烟炱；高锰酸盐脱色等也不唯一指向炔，具体氧化产物随条件变化，题目未给条件不虚构唯一裂解结果。","综合推断先列结构、端氢、试剂与计量，再决定可排除哪些候选。多项互相独立证据比单一脱色更可靠，但混合物和干扰仍需考虑。每个反应图都要核价键、原子数、条件与产物归属。"],"derive":["HC≡CH+2H₂→CH₃CH₃（相应催化、充分加氢）；一步停烯需受控条件。","HC≡CH+HCl→CH₂=CHCl；再加HCl可得CH₃CHCl₂，条件与当量分开。","2C₂H₂+5O₂→4CO₂+2H₂O；乙炔水合最终CH₃CHO，非CH₃CH₂OH。"],"examples":[{"q":"0.10 mol乙炔充分催化加氢到乙烷，理论需H₂多少、生成乙烷多少？","given":"H₂足量且按目标反应完全。","analysis":"三键有两步加成量。","method":"1:2:1计量。","principle":"原子守恒。","steps":["nH₂=.20 mol。","n乙烷=.10 mol。"],"ans":"H₂ .20 mol，乙烷.10 mol。","verification":"每乙炔C2H2加4H为C2H6。","pitfall":"只按双键一摩尔H₂算。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.4","related_sections":[]},{"q":"乙炔与一当量HCl、与两当量HCl在相应模型下的产物怎样不同？","given":"仅讨论经典加成路线。","analysis":"一步和继续加成区分。","method":"追踪C/H/Cl。","principle":"加成保留C2骨架。","steps":["一步C₂H₂+HCl→CH₂=CHCl。","两步总C₂H₂+2HCl→CH₃CHCl₂。"],"ans":"氯乙烯与1,1-二氯乙烷。","verification":"前式H3Cl1，后式H4Cl2均守恒。","pitfall":"两当量画成1,2-二氯乙烷而不核选择。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.4","related_sections":[]},{"q":"两候选1-丁炔与2-丁炔都使溴溶液脱色，可仅凭脱色区分吗？用端氢信息设计有条件判断。","given":"纯样候选限这两个。","analysis":"两者都有三键，脱色不独占。","method":"比较端炔连接及适当检验。","principle":"端氢反应需要特定试剂与规范。","steps":["脱色不能区分二者。","1-丁炔有端氢，可在相应银氨等条件表现不同于内炔的反应；需对照并严格教师规范，危险炔化物不可干燥。"],"ans":"脱色不足；端氢相关证据可在给定候选中补充。","verification":"2-丁炔虽有甲基H却无C≡C—H。","pitfall":"把任意H或脱色当唯一端炔判据。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.4","related_sections":[]}],"practice":[{"q":"0.25 mol单三键炔完全加成需Br₂多少mol？","given":"两步充分加成，无其他耗溴反应。","analysis":"一三键可消耗两当量。","method":"nBr₂=2n炔。","principle":"加成计量。","steps":["2×.25=.50 mol。","产物为相应四溴化加成物模型。"],"ans":".50 mol。","verification":"每步加一Br₂，合四Br原子。","pitfall":"只算一当量却声称完全饱和。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.4","related_sections":[]},{"q":"乙炔水合最终生成乙醛还是乙醇？写分子式守恒检查。","given":"经典催化水合模型。","analysis":"水加成不等于加氢。","method":"C₂H₂+H₂O→C₂H₄O。","principle":"烯醇互变至羰基。","steps":["乙醛CH₃CHO分子式C₂H₄O符合。","乙醇C₂H₆O多2H，单水合不符。"],"ans":"乙醛。","verification":"H2+2=4，非6。","pitfall":"把所有烃加水都写成醇终产物。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.4","related_sections":[]},{"q":"乙炔完全燃烧0.20 mol需O₂多少，生成CO₂多少？","given":"完全燃烧充分。","analysis":"配平方程比2:5:4。","method":"nO₂=2.5n，nCO₂=2n。","principle":"原子守恒。","steps":["O₂=.50 mol。","CO₂=.40 mol。"],"ans":".50 mol氧、.40 molCO₂。","verification":"碳.40 mol原子进入.40 molCO₂。","pitfall":"氧系数只用2而漏水所需O。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.4","related_sections":[]},{"q":"高锰酸盐脱色可否单独证明未知样品为炔烃且确定唯一氧化产物？","given":"未给其他结构或完整条件。","analysis":"多类物可耗氧化剂，产物条件敏感。","method":"限定检验能排除什么。","principle":"单现象不唯一鉴定。","steps":["脱色支持发生氧化还原等相应反应。","仍需结构、对照及条件，不能唯一命名或指定所有裂解产物。"],"ans":"不能。","verification":"烯或其他还原性物质也可有类似现象。","pitfall":"把定性现象当完整结构和路线证明。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.4","related_sections":[]}],"quiz":{"q":"把端炔产生的金属炔化物沉淀画成“取出烘干称量”的普通教学步骤，为什么不合适？","given":"相关金属炔化物有危险性。","analysis":"科学反应图必须包含实际物性边界。","method":"限定规范示范并隔离错误操作。","principle":"不能以沉淀通用操作套危险物。","steps":["不应分离干燥或加热该沉淀。","图应说明仅在批准规范下观察和处置，不安排普通称量干燥。"],"ans":"错误地把危险炔化物当稳定通用沉淀。","verification":"反应能发生不代表后处理都安全可行。","pitfall":"机械套用过滤洗涤烘干流程。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.4","related_sections":[]},"exam":["反应题逐步标当量、催化与产物，先守恒后判结构","鉴定题明确候选、独立证据与干扰，脱色不唯一","实验图保留端炔沉淀危险与规范边界，不能普通烘干称量"],"quick":["三键两步加成","条件与计量","端氢","氧化燃烧","证据与实验边界"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":14,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_29.4","url":"https://openstax.org/books/chemistry-2e/pages/20-1-hydrocarbons","page_or_section":"20-1-hydrocarbons","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_29.4_0","url":"https://openstax.org/books/organic-chemistry/pages/9-4-hydration-of-alkynes","page_or_section":"9-4-hydration-of-alkynes","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_29.4_1","url":"https://openstax.org/books/organic-chemistry/pages/9-summary-of-reactions","page_or_section":"9-summary-of-reactions","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":14,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_29.4","url":"https://openstax.org/books/chemistry-2e/pages/20-1-hydrocarbons","page_or_section":"20-1-hydrocarbons","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_29.4_0","url":"https://openstax.org/books/organic-chemistry/pages/9-4-hydration-of-alkynes","page_or_section":"9-4-hydration-of-alkynes","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"extra_theory_29.4_1","url":"https://openstax.org/books/organic-chemistry/pages/9-summary-of-reactions","page_or_section":"9-summary-of-reactions","version":"专项原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"反应题逐步标当量、催化与产物，先守恒后判结构","method":"比较端炔连接及适当检验。","principle":"端氢反应需要特定试剂与规范。","worked_example_index":2,"verification":"2-丁炔虽有甲基H却无C≡C—H。","pitfall":"把任意H或脱色当唯一端炔判据。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按试剂与用量追踪三键加成产物”的抽样复核：每乙炔C2H2加4H为C2H6。；若出现“只按双键一摩尔H₂算。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“区别端炔反应氧化和脱色的鉴定边界”的抽样复核：2-丁炔虽有甲基H却无C≡C—H。；若出现“把任意H或脱色当唯一端炔判据。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"机械套用过滤洗涤烘干流程。","correction":"错误地把危险炔化物当稳定通用沉淀。","verification":"反应能发生不代表后处理都安全可行。"}],"illustration_spec":{"title":"炔烃反应的当量与结构","objects":["乙炔逐步加氢","HCl一步/两步","乙醛水合终产物","端炔检验条件框","燃烧配平"],"relations":["H₂全加2当量","HCl一步氯乙烯两步CH₃CHCl₂","水合C₂H₄O非乙醇","金属炔化物不画干燥"],"labels":["1eq","2eq","催化/条件","CH₃CHO","仅规范示范"],"format":"SVG","priority":"P0","reuse":"暂无完整反应图；化学结构需确定性绘制并逐原子核验","english":"Draw separate stoichiometric pathways for complete hydrogenation using two H2 per alkyne, one versus two HCl additions to ethyne, and classical hydration ending in acetaldehyde, not ethanol. Balance every atom and label conditions. Do not depict drying or heating hazardous metal acetylide precipitates."}},"29.5":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":29,"section_id":"29.5","goals":["由电石与甲烷反应解释乙炔来源","计算纯度产率与限定温压体积"],"prerequisites":["化学方程计量","限量反应物与气体"],"flow":["来源反应","规范装置","纯度限量","产率","温压与气路"],"concept_relation":"来源反应；规范装置；纯度限量；产率；温压与气路","deep":["从原料计量到实收气体要区分三个层次：纯度决定实际CaC₂量，限量条件决定理论生成量，产率或收集效率决定实际量。三项乘法只在题设明确且边界一致时使用，不把一个百分数同时当纯度与产率重复扣除。","甲烷等烃在相应高温裂解条件下可形成乙炔，简化主反应2CH₄→C₂H₂+3H₂。真实工业过程涉及能量输入、混合产物和冷却控制等，方程用于物料分析，不代表普通加热就可得到纯乙炔。","气体体积换算必须匹配温压和题给模型。0°C、101.325 kPa下可按22.4 L/mol近似，其他条件用相应Vm或PV=nRT；水上收集若需精确干气计量，还应考虑水蒸气分压等，不把湿气总体积直接当同压纯乙炔。","实验评价既检查方程与数据，也检查装置流向、气密性、回吸和出口。图中的箭头应说明气体行进方向，滴液管、导气管与液面关系须由实际装置规范确定；器材画法整齐不代表原理正确，每个连接都要结合反应条件核对。"],"derive":["CaC₂+2H₂O→C₂H₂+Ca(OH)₂；M(CaC₂)按题取64 g/mol。","n理论C₂H₂=min[nCaC₂,nH₂O/2]；实际量需再按给定产率/收集条件。","2CH₄→C₂H₂+3H₂为简化高温主反应；0°C101.325kPa的Vm≈22.4 L/mol不可推广所有温压。"],"examples":[{"q":"纯CaC₂ 6.4 g与过量水完全反应，乙炔n及0°C、101.325 kPa理想近似体积？取CaC₂ 64、Vm22.4。","given":"水过量，理论完全转化。","analysis":"先质量到摩尔再1:1。","method":"n=6.4/64。","principle":"配平方程。","steps":["nCaC₂=.10 mol，nC₂H₂=.10 mol。","V=.10×22.4=2.24 L。"],"ans":".10 mol、2.24 L（指定温压近似）。","verification":"乙炔质量2.6 g，与碳.2 mol及氢.2 mol相符。","pitfall":"因CaC₂有2C就乘成.20 mol乙炔。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.5","related_sections":[]},{"q":"CaC₂ .10 mol与H₂O .10 mol反应，求理论乙炔及剩余CaC₂。","given":"仅主反应，理想计量。","analysis":"水需2:1所以水限量。","method":"比较nCaC₂与n水/2。","principle":"限量比值。","steps":["理论乙炔min(.10,.05)=.05 mol。","消耗CaC₂ .05，余.05 mol。"],"ans":".05 mol乙炔，余.05 molCaC₂。","verification":"消耗水.10恰好，CaC₂不全转化。","pitfall":"不管水量都按电石全部反应。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.5","related_sections":[]},{"q":"10.0 g电石含CaC₂80.0%，水过量；0°C101.325kPa理论乙炔多少L？若实收2.24 L，同条件产率多少？","given":"杂质不产该气，Vm22.4，M64。","analysis":"先纯度，后理论，最后实际/理论。","method":"有效质量与计量。","principle":"物料及产率定义。","steps":["纯CaC₂8.00 g，n=.125 mol。","理论V=.125×22.4=2.80 L。","产率2.24/2.80=80.0%。"],"ans":"理论2.80 L，产率80.0%。","verification":"原料纯度与产率碰巧同为80%，含义不同。","pitfall":"把10g直接代，或把同一个80%两次误扣。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.5","related_sections":[]}],"practice":[{"q":"纯CaC₂3.2 g，过量水，理论乙炔质量？取CaC₂64、C₂H₂26。","given":"完全反应模型。","analysis":"质量需经摩尔比。","method":"3.2/64×26。","principle":"方程1:1。","steps":["n=.050 mol。","m=1.30 g。"],"ans":"1.30 g。","verification":"碳来自.10 mol C共1.2 g、氢.1 g，共1.3 g。","pitfall":"用原料质量当气体质量。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.5","related_sections":[]},{"q":"甲烷主反应制得.20 mol乙炔，理论消耗CH₄与生成H₂各多少？","given":"按2CH₄→C₂H₂+3H₂，不考虑副反应。","analysis":"2:1:3。","method":"系数比。","principle":"原子守恒。","steps":["CH₄ .40 mol。","H₂ .60 mol。"],"ans":".40与.60 mol。","verification":"初C.40 mol进入乙炔.40，初H1.6 mol原子=乙炔.4+H₂1.2。","pitfall":"把气体摩尔比写成质量比。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.5","related_sections":[]},{"q":"室温排水收集气体，可直接把总压和体积都当干乙炔计算吗？","given":"湿气含水蒸气。","analysis":"总压是各分压和。","method":"审相应水蒸气校正及温度。","principle":"理想混合气分压模型。","steps":["若需精确干气n，应使用乙炔分压P总−P水。","还需相应温度与蒸气压资料，不能无数据强行用22.4。"],"ans":"不能无条件。","verification":"水蒸气贡献总体积对应分压，忽略可能高估干气量。","pitfall":"湿气当纯干气且温压不写。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.5","related_sections":[]},{"q":"6.4 g纯CaC₂和1.8 g水按主反应反应，求乙炔、Ca(OH)₂与剩余CaC₂质量，核总质量。","given":"M水18、Ca(OH)₂74、CaC₂64、乙炔26。","analysis":"水.1 mol限量。","method":"理论产物.05 mol。","principle":"计量和质量守恒。","steps":["乙炔1.3 g，Ca(OH)₂3.7 g。","剩CaC₂ .05×64=3.2 g。","总1.3+3.7+3.2=8.2 g，与6.4+1.8一致。"],"ans":"1.3 g、3.7 g、3.2 g。","verification":"各元素和总质量一致；按理想主反应边界。","pitfall":"总质量只加气体而忘固体残留。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.5","related_sections":[]}],"quiz":{"q":"某制气装置示意图画反应瓶完全密闭且没有气体出口，只标“积气后打开点燃”，能因方程配平而通过审核吗？","given":"可燃气放热生成，图缺关键装置条件。","analysis":"方程正确不保证装置正确。","method":"检查压力、出口与规范操作。","principle":"实验模型需气路和安全条件一致。","steps":["密闭积压与未经检验点燃不合规范。","应隔离图，按可靠教师装置资料修正后再审，不能发布。"],"ans":"不能通过。","verification":"科学审核包含结构流向与条件，不止化学式。","pitfall":"把配平或XML通过当完整实验审核。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":29,"primary_section":"29.5","related_sections":[]},"exam":["制取题先配平和判限量，再把纯度、转化/收集产率分层","体积题标温压与湿干气，标准摩尔体积不乱套","装置题从反应热、可燃性与气路审结构，不能只记器材名"],"quick":["来源反应","规范装置","纯度限量","产率","温压与气路"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":14,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_29.5","url":"https://openstax.org/books/chemistry-2e/pages/20-1-hydrocarbons","page_or_section":"20-1-hydrocarbons","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":14,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_29.5","url":"https://openstax.org/books/chemistry-2e/pages/20-1-hydrocarbons","page_or_section":"20-1-hydrocarbons","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"制取题先配平和判限量，再把纯度、转化/收集产率分层","method":"有效质量与计量。","principle":"物料及产率定义。","worked_example_index":2,"verification":"原料纯度与产率碰巧同为80%，含义不同。","pitfall":"把10g直接代，或把同一个80%两次误扣。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由电石与甲烷反应解释乙炔来源”的抽样复核：乙炔质量2.6 g，与碳.2 mol及氢.2 mol相符。；若出现“因CaC₂有2C就乘成.20 mol乙炔。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“计算纯度产率与限定温压体积”的抽样复核：原料纯度与产率碰巧同为80%，含义不同。；若出现“把10g直接代，或把同一个80%两次误扣。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把配平或XML通过当完整实验审核。","correction":"不能通过。","verification":"科学审核包含结构流向与条件，不止化学式。"}],"illustration_spec":{"title":"乙炔来源的计量与装置要求","objects":["电石水反应方程","纯度/限量/产率三级流程","气路出口与防回吸检查","甲烷工业主反应"],"relations":["CaC₂:C₂H₂=1:1","放热可燃不密闭积压","气体体积保留温压湿干条件","装置须可靠规范重画"],"labels":["CaC₂+2H₂O","C₂H₂+Ca(OH)₂","0°C101.325kPa","纯度≠产率","未审核装置不发布"],"format":"SVG","priority":"P0","reuse":"暂无合格装置图；新实验装置必须用可靠原图依据再定稿","english":"Show balanced calcium-carbide hydrolysis and separate purity, limiting-reagent and collection-yield steps. Any apparatus drawing must follow an independently verified classroom reference with a gas outlet and backflow/temperature controls, never a sealed pressure-building vessel or untested ignition instruction. Label wet/dry gas and temperature-pressure conditions."}}},"化学35":{"35.1":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":35,"section_id":"35.1","goals":["区分单体重复单元和聚合度","按平均与端基假设计算高分子数量"],"prerequisites":["有机结构","相对分子质量与物质的量"],"flow":["单体","重复单元","聚合度","端基与分布","链/单元计量"],"concept_relation":"单体；重复单元；聚合度；端基与分布；链/单元计量","deep":["加成聚合的简单计量中，重复单元组成与单体相同，链的相对分子质量可近似n乘重复单元式量；若有引发/终止端基，精确关系需补端基。缩聚还要扣除小分子，不能一律用全部单体质量相加。","天然高分子如纤维素、蛋白质和天然橡胶，合成高分子如聚乙烯等，名称按来源或制备方式分类。相同重复组成可因连接、空间结构和链长不同而性质不同，来源本身不是安全或可降解的充分判据。","实际样品的链长分布使“相对分子质量”常指特定平均。按分子数平均与按质量加权可不同，题目给平均值时要知道口径；本节题可用明确的数目分布演示，不把一个平均值说成每条链都恰有该质量。","计量区分一摩尔链分子与一摩尔重复单元：若每链约1000单元，两者数目相差约1000倍。质量样品除以平均摩尔质量得到相应平均链量的模型结果，再算单元量，不能把两种“mol”在文字中省略对象。"],"derive":["简单加成模型忽略端基：M链≈nM重复单元；n须按指定重复结构计。","数均相对分子质量的数值=ΣNᵢMrᵢ/ΣNᵢ；对应数均摩尔质量M_n单位g/mol，Nᵢ为链分子数。","链量n链=m/M_n（m用g、M_n用g/mol）；重复单元量≈聚合度×n链（分布口径和端基假设需明确）。"],"examples":[{"q":"聚乙烯题给平均摩尔质量28000 g/mol，重复单元式量28，忽略端基，平均聚合度多少？","given":"按数均口径和简单重复单元模型。","analysis":"质量比给单元数。","method":"DP≈28000/28。","principle":"链质量近似重复单元和。","steps":["DP≈1000。","是给定平均模型，非保证所有链长度相同。"],"ans":"约1000。","verification":"1000×28=28000，端基忽略已说明。","pitfall":"把乙烯C=C保留在重复主链或认为全样链长唯一。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.1","related_sections":[]},{"q":"14.0 g上述聚乙烯，近似链分子mol和重复单元mol分别多少？","given":"M_n28000，平均DP1000。","analysis":"链和单元是不同计数对象。","method":"先m/M再乘DP。","principle":"物质的量定义。","steps":["n链=14/28000=.00050 mol。","n单元≈.00050×1000=.50 mol。"],"ans":".00050 mol链、.50 mol重复单元。","verification":"单元.50×28=14g，质量回核。","pitfall":"把.50mol直接叫链分子量。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.1","related_sections":[]},{"q":"样品含等数目的Mr1000和3000两种链，数均Mr多少？是否每条链都为此值？","given":"只按分子数平均。","analysis":"等数可算术平均。","method":"(1000+3000)/2。","principle":"平均不等于个体值。","steps":["相对分子质量数均值为2000；对应M_n=2000 g/mol。","实际给定链只有1000或3000，没有必须等2000的一条。"],"ans":"2000，非每条链都如此。","verification":"总质量与总链数之比符合，分布仍两组。","pitfall":"平均值当所有分子唯一Mr。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.1","related_sections":[]}],"practice":[{"q":"乙烯单体与聚乙烯重复单元连接有何不同？","given":"比较CH₂=CH₂与链。","analysis":"组成相同连接变。","method":"画—CH₂—CH₂—。","principle":"加成聚合重组π连接。","steps":["原双键变主链单键连接。","两端键延伸相邻单元，不画成一串互不连接乙烯。"],"ans":"重复单元为—CH₂—CH₂—，无原C=C。","verification":"各碳两H加两C单键仍四价。","pitfall":"把单体图重复摆放当化学聚合。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.1","related_sections":[]},{"q":"某理想重复单元Mr100，链含500单元、端基合20，精确Mr与忽略端基近似各多少？","given":"题给端基额外组成。","analysis":"端基不应被重复500次。","method":"500×100+20。","principle":"质量相加。","steps":["精确50020。","忽略端基约50000，相差20。"],"ans":"50020与约50000。","verification":"相对差20/50020很小但非0。","pitfall":"把端基每重复一次都加20。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.1","related_sections":[]},{"q":"聚合物名称相同，能保证样品只有一个链长吗？","given":"实际材料分布未给。","analysis":"高聚物样品常有链长分布。","method":"区分结构类型和分子量分布。","principle":"聚合过程统计差异。","steps":["同重复结构可有多个n。","需平均与分布数据，不能名称推唯一链长。"],"ans":"不能。","verification":"平均Mr也不能恢复全部分布。","pitfall":"把纯材料商品名当单分子身份。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.1","related_sections":[]},{"q":"样品两种链数量比3:1，Mr分别1000、5000，求数均Mr，并说明不能直接按质量比3:1。","given":"给的是链分子数比。","analysis":"权重口径明确。","method":"(3×1000+1×5000)/4。","principle":"数均定义。","steps":["得2000。","质量贡献分别3000与5000，比3:5而非3:1。"],"ans":"相对分子质量数均值2000（对应M_n=2000 g/mol）。","verification":"总质量8000对应4个比例单位链数。","pitfall":"把数目比当质量分数。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.1","related_sections":[]}],"quiz":{"q":"缩聚物的重复单元式量，能不看小分子脱除就直接等于所有相应单体式量之和吗？","given":"存在缩合连接。","analysis":"端基与脱除小分子改变组成。","method":"按连接反应列原子收支。","principle":"质量守恒。","steps":["需扣除相应水等小分子。","有限链还要明确端基，不能无条件按简单加成公式。"],"ans":"不能。","verification":"二酸二胺形成酰胺键会失H₂O。","pitfall":"所有聚合都同组成直接相加。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.1","related_sections":[]},"exam":["高分子计量题先定单体/重复单元/链三层对象","平均题写数目或质量权重，平均不等于每个体","M≈nM₀需说明加成、端基和缩聚失小分子条件"],"quick":["单体","重复单元","聚合度","端基与分布","链/单元计量"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.1","url":"https://openstax.org/books/organic-chemistry/pages/31-7-polymer-structure-and-physical-properties","page_or_section":"31-7-polymer-structure-and-physical-properties","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.1","url":"https://openstax.org/books/organic-chemistry/pages/31-7-polymer-structure-and-physical-properties","page_or_section":"31-7-polymer-structure-and-physical-properties","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"高分子计量题先定单体/重复单元/链三层对象","method":"(1000+3000)/2。","principle":"平均不等于个体值。","worked_example_index":2,"verification":"总质量与总链数之比符合，分布仍两组。","pitfall":"平均值当所有分子唯一Mr。"},"diagnostics":[{"goal_index":0,"question_ref":"p0","review_module":4,"feedback":"目标“区分单体重复单元和聚合度”的抽样复核：各碳两H加两C单键仍四价。；若出现“把单体图重复摆放当化学聚合。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“按平均与端基假设计算高分子数量”的抽样复核：总质量与总链数之比符合，分布仍两组。；若出现“平均值当所有分子唯一Mr。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"所有聚合都同组成直接相加。","correction":"不能。","verification":"二酸二胺形成酰胺键会失H₂O。"}],"illustration_spec":{"title":"单体重复单元与链长分布","objects":["乙烯单体","聚乙烯连续链与括号n","端基","两链长数目分布","链mol/单元mol"],"relations":["主链双键已消去","端键穿括号且价正确","数均按链数加权","M近似含端基假设"],"labels":["单体","重复单元","n","端基","数均","0.00050mol链≠0.50mol单元"],"format":"SVG","priority":"P0","reuse":"暂无对应旧图；聚合链价键和括号端键必须准确","english":"Contrast ethene monomer with connected polyethylene repeat units inside brackets, with continuation bonds and labelled end groups. Show chain-length distribution and number-average weighting, and distinguish0.00050 mol of chains from0.50 mol of repeat units for average DP1000. Do not leave the monomer double bond in the polyethylene backbone."}},"35.2":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":35,"section_id":"35.2","goals":["比较线型支链交联及空间结构","由连接与链运动预测性能并说明条件"],"prerequisites":["共价连接","分子间作用与重复单元"],"flow":["主链侧基","线型支链","交联网络","空间排列","结构性能条件"],"concept_relation":"主链侧基；线型支链；交联网络；空间排列；结构性能条件","deep":["同类聚乙烯中支化程度可影响链堆积、结晶和密度，较少支化常有较紧密堆积的趋势。实际性质还取决分子量、支链分布、加工和添加剂，不能把单一结构词当作所有牌号材料的精确数据。","链的空间构型也重要，相同组成和连接可能有不同立体排列。天然橡胶以相应cis-1,4结构为主，其链形态与其他排列不同；结构图须说明采用哪种模型，不能同分子式就画成完全相同材料。","线性或支链高分子可因温度和相互作用出现热塑行为，密集交联材料通常不能像普通热塑料那样熔融流动而可能先降解。不能把“不能简单熔融再加工”夸成任何形式回收都绝对不可能，化学处理等是另一问题。","从单体功能度推结构时，双官能组分在理想条件下可形成线性链，多官能可能促支化交联，但实际网络形成还依配比、转化和环化等。预测需要条件，不是见三个官能团就宣称全部瞬间成完美网。"],"derive":["连接层次：主链/侧基/支链/链间交联，图中必须区分共价连接与链间靠近。","同化学家族内可推支化—堆积—结晶/密度趋势，但加工及分布仍会影响。","多官能单体可增加网络可能性；是否成胶/交联需转化与配比等条件。"],"examples":[{"q":"一幅“线型聚合物”画成弯曲缠绕的单链，能仅因不笔直判画错吗？","given":"连接没有分支或交联。","analysis":"线型是拓扑不是几何直线。","method":"检查连接而非外形。","principle":"链构象可变。","steps":["若仍一条连续无分支主链，属线型模型。","弯折缠绕可存在，不需拉成直棒。"],"ans":"不能仅据弯曲判错。","verification":"理想链可折叠而不新增支链。","pitfall":"把linear字面当全原子共线。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.2","related_sections":[]},{"q":"同类聚乙烯甲支化少、乙支化多，其他条件近似，哪种更易紧密堆积？能保证全部指标甲更优吗？","given":"比较同家族并控制主要其他因素。","analysis":"堆积趋势与全面性能不同。","method":"结构到结晶密度，再写限制。","principle":"支链可妨碍规整堆积。","steps":["通常甲较易紧密堆积、相应结晶密度可较高。","柔韧、加工等目标不同且受其他因素，不能全面判优。"],"ans":"甲有较紧密堆积趋势，非所有性能都更优。","verification":"较多支链可带来不同柔韧用途。","pitfall":"少支链等于任何用途最好。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.2","related_sections":[]},{"q":"二酸与二醇均双官能，另一个体系加入三官能醇，结构趋势如何？是否必定立刻形成全网？","given":"理想缩合连接模型。","analysis":"功能度影响支化，但网络需更多条件。","method":"比较连接出口数。","principle":"双官能延链，多官能可成分支点。","steps":["二/二体系可形成线性链。","加入三官能可促支化交联；具体是否网络还依量比、转化与环化。"],"ans":"后者网络可能性增加，非无条件立刻全网。","verification":"很低转化时多数单体尚未建立网络。","pitfall":"仅数官能团就忽略反应程度。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.2","related_sections":[]}],"practice":[{"q":"两条线靠近甚至缠结，必有共价交联吗？","given":"未画连接键。","analysis":"空间靠近与化学连接不同。","method":"查键与结构证据。","principle":"交联需相应链间连接。","steps":["缠结可为物理约束。","不能仅靠接近就画共价桥，需明确结构。"],"ans":"不必。","verification":"滑开链不一定需断共价键。","pitfall":"每个交叉处都补一个键。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.2","related_sections":[]},{"q":"聚丙烯每单元的CH₃是否必须画成另一条长主链？","given":"重复结构—CH₂—CH(CH₃)—。","analysis":"侧基与长支链区分。","method":"核碳连接。","principle":"主链连续路线。","steps":["CH₃是该重复单元侧基。","不等于每处都有一条长高分子链伸出。"],"ans":"不是，应为甲基侧基。","verification":"补H后碳四价且主链仍连续。","pitfall":"为显示支化任意延长CH₃。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.2","related_sections":[]},{"q":"交联越密是否一定越柔软弹性越好？","given":"只改变网络约束作趋势讨论。","analysis":"恢复与可伸展性存在权衡。","method":"比较轻度与过密网络。","principle":"链运动受约束。","steps":["适度网络可帮助恢复。","过密可能更硬、可伸长性降低，不能单调宣称更柔软。"],"ans":"不一定。","verification":"硬橡胶类说明网络密度目标不同。","pitfall":"将一种效益无限外推。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.2","related_sections":[]},{"q":"密集交联材料不易熔融重塑，是否表示任何回收都不可能？","given":"讨论普通热流动。","analysis":"机械热塑再加工与其他回收不同。","method":"限定结论。","principle":"结构限制某方法而非所有技术。","steps":["不能像简单热塑料熔融流动。","仍可研究适当机械、化学等处理，需具体证据和成本条件。"],"ans":"不能作绝对不可能结论。","verification":"难度增加不等于逻辑上所有方式均无。","pitfall":"把一个加工限制当所有途径禁绝。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.2","related_sections":[]}],"quiz":{"q":"结构示意每个链交叉点都画连结，却标题只说“物理缠结线型链”，应改图还是改标题？","given":"图和文字描述冲突。","analysis":"化学连接改变拓扑。","method":"核是否真实有交联。","principle":"结构与模型说明应一致。","steps":["若只缠结，移除假共价桥并用线型区分前后。","若确交联，应标网络及依据，不能保留线型无交联标题。"],"ans":"按真实模型修正，不能两者混用。","verification":"每条新增键都需合理连接与原子价。","pitfall":"把画面交叉自动当化学反应。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.2","related_sections":[]},"exam":["结构题先查连接拓扑再谈画面形状","性质题写结构—运动/堆积—趋势及控制条件","网络题审功能度、配比和转化，不能见多官能就宣布唯一材料"],"quick":["主链侧基","线型支链","交联网络","空间排列","结构性能条件"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.2","url":"https://openstax.org/books/organic-chemistry/pages/31-7-polymer-structure-and-physical-properties","page_or_section":"31-7-polymer-structure-and-physical-properties","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.2","url":"https://openstax.org/books/organic-chemistry/pages/31-7-polymer-structure-and-physical-properties","page_or_section":"31-7-polymer-structure-and-physical-properties","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"结构题先查连接拓扑再谈画面形状","method":"比较连接出口数。","principle":"双官能延链，多官能可成分支点。","worked_example_index":2,"verification":"很低转化时多数单体尚未建立网络。","pitfall":"仅数官能团就忽略反应程度。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“比较线型支链交联及空间结构”的抽样复核：理想链可折叠而不新增支链。；若出现“把linear字面当全原子共线。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“由连接与链运动预测性能并说明条件”的抽样复核：很低转化时多数单体尚未建立网络。；若出现“仅数官能团就忽略反应程度。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把画面交叉自动当化学反应。","correction":"按真实模型修正，不能两者混用。","verification":"每条新增键都需合理连接与原子价。"}],"illustration_spec":{"title":"线型支链交联的结构区别","objects":["弯曲线型链","甲基侧基","长支链","物理缠结","共价交联网络"],"relations":["交叉不自动成键","主链连续","交联点须合理价","稀密网络限制链运动不同"],"labels":["线型拓扑","侧基","支链","缠结","交联","非分子真实比例"],"format":"SVG","priority":"P0","reuse":"暂无对应旧图；结构示意必须区分交叉与成键","english":"Draw a curved unbranched chain, pendant methyl groups, true long-chain branches, physical entanglement and covalent crosslinks as distinct models. Do not add a bond at every drawn crossing. Mark crosslink density qualitatively and avoid claiming denser networks universally improve softness or recyclability."}},"35.3":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":35,"section_id":"35.3","goals":["由链运动与结晶解释热机械和溶胀性质","区分玻璃转变熔融及比较指标"],"prerequisites":["链结构","温度与分子间作用"],"flow":["热转变","链与晶区","力学指标","溶胀溶解","时间环境条件"],"concept_relation":"热转变；链与晶区；力学指标；溶胀溶解；时间环境条件","deep":["力学表现包括刚度、断裂应力、伸长和韧性等，指标不互相代替。较大拉断力也可能仅因试样截面较大；比较应力需F/A并保持测试条件相同，不能把“能挂更多重物”直接称材料本征更强。","溶解与溶胀不同。适当线性链在相应溶剂条件可逐渐分散，交联网络可能吸溶剂体积增大却仍维持连接；质量增加不自动证明已变成均一分子溶液，也不由一次溶胀量唯一推交联密度。","很多常见聚合物导电弱、耐某些化学环境，但存在导电聚合物、填料改性及可溶于水的高分子等例外。必须由载流子和结构解释，不能重复“所有塑料绝缘不溶不反应”的绝对说法。","选择材料先确定使用温度、载荷、溶剂及寿命，再看相应测试指标。短时好性能不保证长时抗蠕变或老化，尤其聚合物对时间温度敏感；题给比较数据只能在其条件内支持结论。"],"derive":["T_g为无定形链段运动变化的转变，不等于所有材料T_m。","简单拉伸名义应力σ=F/A；1 N/mm²=1 MPa，需同测试口径。","溶胀比需定义是质量或体积口径，吸液不等于全部网络分子溶解。"],"examples":[{"q":"题给无定形材料T_g=80°C，25°C与100°C相对玻璃转变怎样？能说100°C一定已晶体熔化吗？","given":"无定形材料，未给晶区T_m。","analysis":"玻璃转变与熔融不同。","method":"比较T与T_g。","principle":"链段运动模型。","steps":["25<T_g，通常较玻璃态硬脆。","100>T_g，链段运动增强，但无定形玻璃转变不等同晶体熔化，也不保证可任意流动。"],"ans":"前低于、后高于T_g；不能称必已晶体熔化。","verification":"题未给可据的晶体熔点。","pitfall":"把T_g直接标成所有材料熔点。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.3","related_sections":[]},{"q":"同方法拉伸，甲截面2 mm²、断裂力50 N，乙10 mm²、断裂力100 N，名义断裂应力各多少？","given":"截面积为初始测量，条件可比。","analysis":"力大小需按面积归一。","method":"σ=F/A。","principle":"应力定义。","steps":["甲25 N/mm²=25 MPa。","乙10 N/mm²=10 MPa。"],"ans":"甲25、乙10 MPa。","verification":"甲虽然断力小，但单位面积承受更大。","pitfall":"只按100>50判乙材料断裂应力高。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.3","related_sections":[]},{"q":"已知交联样品干1 g吸溶剂后3 g仍保形，能直接称已完全溶解并确定交联点数吗？","given":"有网络与吸液现象，无分子分散测量。","analysis":"溶胀与溶解不同且信息有限。","method":"按质量收支并列需证据。","principle":"网络可吸液而不解体。","steps":["吸入约2 g溶剂，符合溶胀。","保形和质量不能唯一给交联点数，也不能称完全分子溶液。"],"ans":"不能，支持溶胀模型。","verification":"3g中仍含原网络1g，不能把全部质量说成新聚合物。","pitfall":"吸液就当溶解或直接数交联。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.3","related_sections":[]}],"practice":[{"q":"较硬材料一定更韧吗？","given":"只给刚度或硬度。","analysis":"刚硬与断裂吸能不同。","method":"要求相应力学测试。","principle":"性能指标多维。","steps":["可硬而脆。","韧性需应力应变等吸能资料，不能只用硬度。"],"ans":"不一定。","verification":"玻璃态材料可体现硬但脆。","pitfall":"强硬韧三个词完全同义。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.3","related_sections":[]},{"q":"半结晶材料T_g=−20°C、T_m约120°C，20°C超过T_g，能说已经全部液化吗？","given":"仍低于晶区熔融。","analysis":"不同结构部分转变不同。","method":"比较两个温度尺度。","principle":"无定形与晶区分开。","steps":["无定形部分链段较可动。","晶区仍可维持结构，不能称全部液化。"],"ans":"不能。","verification":"20远低题给120，晶区未按模型熔融。","pitfall":"只要高于T_g就是液体。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.3","related_sections":[]},{"q":"同样塑料加入导电填料后可导电，是否违反化学规律？","given":"材料配方改变。","analysis":"常见绝缘趋势非绝对。","method":"看载流通路。","principle":"电导依载流子和网络。","steps":["填料可形成相应导电路径。","材料宏观性质可改变，不是规律失效。"],"ans":"不违反。","verification":"原聚合物与复合材料不是相同配方。","pitfall":"把塑料绝缘当无例外定义。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.3","related_sections":[]},{"q":"样品干2 g，溶胀后6 g，按吸液质量/干质量定义比值多少？若另定义总湿/干呢？","given":"无聚合物损失。","analysis":"不同口径给不同值。","method":"分别(6−2)/2与6/2。","principle":"质量分项。","steps":["吸液比2 g/g。","总湿比3，不能无说明混用。"],"ans":"2与3，口径不同。","verification":"干2+液4=湿6。","pitfall":"把两个溶胀指标混称同一数。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.3","related_sections":[]}],"quiz":{"q":"某材料短时拉伸强度高，是否足以保证长期承重在高温下永不变形？","given":"时间温度条件不同。","analysis":"聚合物可蠕变老化。","method":"要求长期和使用温度数据。","principle":"物性依时间温度及载荷。","steps":["短时数据支持对应测试。","需长期蠕变、热稳定与环境资料，不能承诺永不变形。"],"ans":"不足。","verification":"链段慢运动可在较长时间累积变形。","pitfall":"把短时极限当永久工作条件。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.3","related_sections":[]},"exam":["物性题用结构和链运动解释，T_g/T_m不互换","比较题归一到同指标同条件，力不直接等于应力","溶剂题定义比值并区别溶胀与溶解，长期性能另需数据"],"quick":["热转变","链与晶区","力学指标","溶胀溶解","时间环境条件"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.3","url":"https://openstax.org/books/organic-chemistry/pages/31-7-polymer-structure-and-physical-properties","page_or_section":"31-7-polymer-structure-and-physical-properties","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.3","url":"https://openstax.org/books/organic-chemistry/pages/31-7-polymer-structure-and-physical-properties","page_or_section":"31-7-polymer-structure-and-physical-properties","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"物性题用结构和链运动解释，T_g/T_m不互换","method":"按质量收支并列需证据。","principle":"网络可吸液而不解体。","worked_example_index":2,"verification":"3g中仍含原网络1g，不能把全部质量说成新聚合物。","pitfall":"吸液就当溶解或直接数交联。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由链运动与结晶解释热机械和溶胀性质”的抽样复核：题未给可据的晶体熔点。；若出现“把T_g直接标成所有材料熔点。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“区分玻璃转变熔融及比较指标”的抽样复核：3g中仍含原网络1g，不能把全部质量说成新聚合物。；若出现“吸液就当溶解或直接数交联。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把短时极限当永久工作条件。","correction":"不足。","verification":"链段慢运动可在较长时间累积变形。"}],"illustration_spec":{"title":"聚合物热转变与性能口径","objects":["T_g/T_m温标","无定形/晶区示意","不同截面试条","交联溶胀","测试条件框"],"relations":["T_g不等于T_m","F/A比较25与10MPa","保形溶胀非均一溶解","热塑与密交联不同"],"labels":["T_g","T_m","σ=F/A","溶胀","温度/时间/配方"],"format":"SVG","priority":"P0","reuse":"暂无对应旧图；温度标尺和数据须准确","english":"Distinguish glass transition from crystalline melting, with separate amorphous and crystalline regions. Compare tensile specimens by50N/2mm²=25MPa versus100N/10mm²=10MPa, and show solvent swelling of a connected network without depicting complete dissolution. Label time, temperature and formulation limits."}},"35.4.1":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":35,"section_id":"35.4.1","goals":["由单体双键写价键正确的重复结构","用计量与条件区分加成聚合和简单加成"],"prerequisites":["烯烃加成","高分子单元与质量"],"flow":["单体双键","引发增长","重复结构","侧基与价","质量与产率"],"concept_relation":"单体双键；引发增长；重复结构；侧基与价；质量与产率","deep":["聚合通常需要适当引发、催化、温压等，不是双键物质放在一起就必自发定量聚合。不同引发或催化会影响速率、链长、空间排列和副反应；不能把普通小分子加氢的条件当所有聚合通用配方。","链增长可概括引发、增长和终止/链转移等环节，机制依体系不同。这个概括帮助解释为什么样品有链长分布，不将每条链都固定画成n相同的精确分子；详细机理作为理解模型而非虚构官方必考细目。","反推单体时识别两个主链碳及其侧基，在合适乙烯基均聚模型下恢复双键。不是把整条主链任意剪为两半，也不能把缩聚中保留的酯/酰胺连接无条件改成烯烃单体。","计算聚合度可用链平均质量除重复单元质量近似，产率则用目标聚合物实际量比理论量；未反应单体仍有质量去向。双键消耗和结构证据可支持聚合，但“体系变稠”单一现象不证明目标重复结构正确。"],"derive":["nCH₂=CH₂→[—CH₂—CH₂—]ₙ（适当聚合条件，端基简写）。","nCH₂=CHCl→[—CH₂—CH(Cl)—]ₙ；nCH₂=CHCH₃→[—CH₂—CH(CH₃)—]ₙ。","理想加成聚合不脱小分子，M重复=M单体；M链≈nM重复需端基近似。"],"examples":[{"q":"写氯乙烯聚合的重复结构，并逐碳核价。","given":"单体CH₂=CHCl。","analysis":"侧基Cl保留。","method":"双键改主链单键并两端延伸。","principle":"加成聚合连接。","steps":["重复—CH₂—CH(Cl)—。","CH₂碳有2H和两主链键，CHCl碳有H、Cl和两主链键，均四价。"],"ans":"[—CH₂—CH(Cl)—]ₙ。","verification":"重复组成C₂H₃Cl与单体同。","pitfall":"把Cl删除或保留主链C=C。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.1","related_sections":[]},{"q":"14.0 g乙烯按理想加成聚合，80.0%进入目标聚合物，无副产物并忽略端基，聚合物及未反应乙烯质量？","given":"质量转化口径明确。","analysis":"不脱水，目标质量按转化。","method":"m聚=14×.80。","principle":"质量守恒。","steps":["聚合物11.2 g。","余单体2.8 g。"],"ans":"11.2与2.8 g。","verification":"11.2+2.8=14.0。","pitfall":"聚合就凭空失水或把剩单体当消失。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.1","related_sections":[]},{"q":"重复单元—CH₂—CH(CH₃)—的简单乙烯基单体是什么？为何不是把CH₃也放主链成三碳重复？","given":"单体反推限定常见均聚模型。","analysis":"恢复参与主链的两碳双键。","method":"CH₂=CH—CH₃。","principle":"侧基连接保留。","steps":["两个主链碳恢复C=C。","甲基保留连第二碳，得丙烯。"],"ans":"CH₂=CHCH₃。","verification":"原子C3H6与重复单元同，连接可还原。","pitfall":"把侧基误剪为第三个主链碳。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.1","related_sections":[]}],"practice":[{"q":"聚乙烯重复单元还能画CH₂=CH₂并只在外面加n吗？","given":"要求连接的主链结构。","analysis":"单体与链不同。","method":"画单键和端键。","principle":"聚合改变连接。","steps":["应为—CH₂—CH₂—并与邻单元连接。","若保留原双键且又两端接链，会使价键不符。"],"ans":"不能。","verification":"每个碳四价检验可发现。","pitfall":"外括号n自动修复错误键。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.1","related_sections":[]},{"q":"PVC重复式量62.5，链平均Mr62500，忽略端基，DP？","given":"平均口径明确。","analysis":"比值。","method":"62500/62.5。","principle":"重复质量近似。","steps":["DP1000。","仅为相应平均，不保证各链1000。"],"ans":"约1000。","verification":"1000×62.5=62500。","pitfall":"把氯原子不计质量。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.1","related_sections":[]},{"q":"体系变稠是否唯一证明形成目标聚合物？","given":"没有结构检测。","analysis":"物性变化也可由浓缩凝聚等引起。","method":"要求单体消耗和结构证据。","principle":"单现象不唯一鉴定。","steps":["变稠与聚合可相容。","还需成分、分子量和重复结构等证据，不能单凭黏度确认。"],"ans":"不是唯一证明。","verification":"溶剂蒸发也可增黏。","pitfall":"看似塑料就必为所画结构。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.1","related_sections":[]},{"q":"10 g纯单体完全理想加成成聚合物，实得9 g纯目标，求收率；若产品有10%溶剂，纯量与收率？","given":"以同一10 g理论聚合物边界。","analysis":"第二情境先扣溶剂。","method":"实际纯量/理论。","principle":"产率定义。","steps":["纯9g时收率90%。","含10%溶剂的9g样品纯聚合物8.1g，收率81%。"],"ans":"90%；第二8.1g、81%。","verification":"差值为非目标物，不可算入产率。","pitfall":"粗产物质量直接当纯量。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.1","related_sections":[]}],"quiz":{"q":"加成聚合不脱水，能据此说任何双键在无条件下都会完全聚合吗？","given":"未给引发、催化与竞争过程。","analysis":"计量类型与反应可行速率不同。","method":"分别核结构条件和反应条件。","principle":"正确总式不等于自动过程。","steps":["不脱小分子描述目标反应收支。","实际需适当体系条件，可能转化不完全或有副反应。"],"ans":"不能。","verification":"同一单体在储存与聚合条件下行为可不同。","pitfall":"由守恒类型推无条件100%转化。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.1","related_sections":[]},"exam":["写结构题先保侧基、改单键、加端键再核四价","反推题限定乙烯基均聚模型，找两主链碳恢复双键","计量题加成不脱水仍要区分转化、产率、纯度和端基"],"quick":["单体双键","引发增长","重复结构","侧基与价","质量与产率"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.4.1","url":"https://openstax.org/books/organic-chemistry/pages/31-1-chain-growth-polymers","page_or_section":"31-1-chain-growth-polymers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.4.1","url":"https://openstax.org/books/organic-chemistry/pages/31-1-chain-growth-polymers","page_or_section":"31-1-chain-growth-polymers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"写结构题先保侧基、改单键、加端键再核四价","method":"CH₂=CH—CH₃。","principle":"侧基连接保留。","worked_example_index":2,"verification":"原子C3H6与重复单元同，连接可还原。","pitfall":"把侧基误剪为第三个主链碳。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由单体双键写价键正确的重复结构”的抽样复核：重复组成C₂H₃Cl与单体同。；若出现“把Cl删除或保留主链C=C。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“用计量与条件区分加成聚合和简单加成”的抽样复核：11.2+2.8=14.0。；若出现“聚合就凭空失水或把剩单体当消失。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"由守恒类型推无条件100%转化。","correction":"不能。","verification":"同一单体在储存与聚合条件下行为可不同。"}],"illustration_spec":{"title":"乙烯基加成聚合结构","objects":["乙烯/氯乙烯/丙烯单体","对应重复结构","主链端键","侧基","质量收支"],"relations":["C=C改主链单键","Cl和CH₃保留","每碳四价","不画脱水副产物"],"labels":["适当条件","n","连续主链","端基简写","加成不脱小分子"],"format":"SVG","priority":"P0","reuse":"暂无对应图；每个键及括号必须确定性绘制","english":"Draw ethene, vinyl chloride and propene converting to correct polyethylene, PVC and polypropylene repeat units. Keep chlorine and methyl substituents, replace the participating double bond with the connected backbone, extend bonds through brackets and check carbon valence. Do not invent water byproducts in ideal addition polymerization."}},"35.4.2":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":35,"section_id":"35.4.2","goals":["由官能团连接写聚酯聚酰胺","区分重复单元近似与有限链脱水数"],"prerequisites":["酯化酰胺连接","质量和原子守恒"],"flow":["官能团","酯/酰胺键","小分子","重复单元","端基与连接数"],"concept_relation":"官能团；酯/酰胺键；小分子；重复单元；端基与连接数","deep":["重复单元式量等于相应单体组分减去形成重复连接所脱的小分子。对己二酸与己二胺的一对重复结构，常用146+116−2×18=226；这是长链重复单元口径，端基精确值另计。","有限开放线性链中，每建立一个连接才脱相应一分子水。若n个二酸和n个二胺全部连成一条无环链，共2n个单体分子、2n−1个连接，因此水为2n−1；端基保留使链质量为226n+18，而非无条件精确226n。","简写n重复单元反应常忽略端基并以约2n水表示长链收支，应明确是结构简式/高聚度近似。若题目给有限链、具体端基或环状结构，不能照抄近似；环化、封端与多链会改变连接数量。","判断缩聚与更广义逐步增长也要留边界：并非所有逐步增长都必放水，本节典型二酸体系确有缩合小分子。学习分类以具体反应证据和官能团为主，不把方法名称当无条件万能定义。"],"derive":["二酸+二醇→聚酯（酯连接）+相应H₂O；二酸+二胺→聚酰胺（酰胺连接）+H₂O。","己二酸146+己二胺116−2H₂O36=重复单元226（题取近似式量）。","n对单体成一条无环开放链：连接2n−1，水2n−1，链Mr=226n+18；若多链/成环须改计数。"],"examples":[{"q":"己二酸Mr146、己二胺116，长链尼龙-6,6重复单元式量多少？为什么不直接262？","given":"每重复对的长链连接口径，忽略端基。","analysis":"形成两个酰胺连接对应失2水。","method":"146+116−36。","principle":"原子质量守恒。","steps":["得到226。","262包含将脱去的小分子组成，不能全留在重复结构。"],"ans":"226。","verification":"可由重复式C₁₂H₂₂N₂O₂算144+22+28+32=226。","pitfall":"忘脱水或漏羰基氧。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.2","related_sections":[]},{"q":"恰10个己二酸与10个己二胺全部连成一条无环开放链，脱水几分子、链Mr多少？","given":"无分支封端杂物，20单体成一链。","analysis":"有限链端基不能忽略。","method":"20分子需19连接。","principle":"每连接一水的树状开放链计数。","steps":["失19H₂O。","Mr=10×(146+116)−19×18=2620−342=2278。"],"ans":"19个水分子，Mr2278。","verification":"226×10+18=2278；与忽略端基2260差18。","pitfall":"机械写20水使端基质量丢失。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.2","related_sections":[]},{"q":"二醇Mr62与二酸166形成题设聚酯，每重复对脱2水，平均Mr19200忽略端基，重复对数多少？","given":"指定官能团及长链近似。","analysis":"先重复式量再聚合度。","method":"M₀=62+166−36。","principle":"缩聚质量收支。","steps":["M₀=192。","n≈19200/192=100。"],"ans":"约100个重复对。","verification":"每对包含两类单体单位，不能叫只有100个总单体。","pitfall":"把228当重复式量或将对数当总单体数。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.2","related_sections":[]}],"practice":[{"q":"聚酯与聚酰胺的关键连接怎样区分？","given":"比较羰基邻接。","analysis":"O与N连接不同。","method":"写C(=O)—O与C(=O)—NH。","principle":"官能团结构。","steps":["聚酯含酯连接。","聚酰胺含相应酰胺连接，不能互换原子。"],"ans":"酯为—COO—，酰胺为—CONH—等。","verification":"羰基O都须保留。","pitfall":"只看到C和O就所有都聚酯。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.2","related_sections":[]},{"q":"5个二酸与5个二醇连一条无环开放链，每连接失一水，水几分子？","given":"共10个单体分子。","analysis":"连接数比节点少1。","method":"10−1。","principle":"开放单链连接计数。","steps":["9连接。","失9水分子。"],"ans":"9。","verification":"若形成两条链则只需8连接，题设一链重要。","pitfall":"无条件用2n=10。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.2","related_sections":[]},{"q":"加入单官能醇会有怎样的链增长影响？","given":"与相应二酸/二醇缩聚体系。","analysis":"只能从一端反应的分子可封端。","method":"比较功能度。","principle":"链延伸需两侧功能。","steps":["单官能醇反应后不能在另一端同样延伸。","可降低平均链长等，实际依量与条件。"],"ans":"可能封端、限制链增长。","verification":"与多官能促进分支不同。","pitfall":"所有含OH都同样形成长链。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.2","related_sections":[]},{"q":"n=1000重复对的尼龙模型，精确开放单链Mr与忽略端基差多少、相对差约多少？","given":"采用前述M=226n+18。","analysis":"端基为常数项。","method":"差18，除精确Mr。","principle":"有限链公式。","steps":["精确226018，近似226000。","相对18/226018≈.00796%。"],"ans":"差18，约0.008%。","verification":"n大时近似好，但不使有限链端基严格消失。","pitfall":"近似好就宣称永远精确。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.2","related_sections":[]}],"quiz":{"q":"聚合方程画每个酯链接却漏一个O，再把H₂O系数调到配平，看似总量相符就可接受吗？","given":"原官能团连接应为酯。","analysis":"总原子和与局部结构都要对。","method":"逐重复单元还原官能团和端基。","principle":"结构式与计量必须一致。","steps":["漏O使局部官能团错误。","不能靠任意水系数救一个错误连接，应重画并按真实连接核守恒。"],"ans":"不能接受。","verification":"配平不唯一决定真实化学结构。","pitfall":"数字凑平就忽略键与价。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.4.2","related_sections":[]},"exam":["缩聚题先标功能团和新键，再扣小分子与核原子","聚合度题说明单体数还是重复对数，重复单元式量先算","有限链题数连接与端基，多链/环状不可沿用一链公式"],"quick":["官能团","酯/酰胺键","小分子","重复单元","端基与连接数"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.4.2","url":"https://openstax.org/books/organic-chemistry/pages/31-4-step-growth-polymers","page_or_section":"31-4-step-growth-polymers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.4.2","url":"https://openstax.org/books/organic-chemistry/pages/31-4-step-growth-polymers","page_or_section":"31-4-step-growth-polymers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"缩聚题先标功能团和新键，再扣小分子与核原子","method":"M₀=62+166−36。","principle":"缩聚质量收支。","worked_example_index":2,"verification":"每对包含两类单体单位，不能叫只有100个总单体。","pitfall":"把228当重复式量或将对数当总单体数。"},"diagnostics":[{"goal_index":0,"question_ref":"p0","review_module":4,"feedback":"目标“由官能团连接写聚酯聚酰胺”的抽样复核：羰基O都须保留。；若出现“只看到C和O就所有都聚酯。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“区分重复单元近似与有限链脱水数”的抽样复核：226×10+18=2278；与忽略端基2260差18。；若出现“机械写20水使端基质量丢失。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"数字凑平就忽略键与价。","correction":"不能接受。","verification":"配平不唯一决定真实化学结构。"}],"illustration_spec":{"title":"缩聚连接与端基精确计数","objects":["二酸二醇聚酯","二酸二胺聚酰胺","水脱除","10对开放链端基","重复近似框"],"relations":["酯与酰胺原子正确","20单体19连接","10对Mr2278非2260精确值","端基H/OH保留"],"labels":["C=O","—COO—","—CONH—","2n−1水","226n+18","高n近似"],"format":"SVG","priority":"P0","reuse":"暂无对应图；必须逐原子核价、端基与小分子数","english":"Draw valence-correct polyester and polyamide links with every carbonyl oxygen retained. Contrast repeat-unit shorthand with a finite open chain of10 diacid and10 diamine molecules:19 water molecules lost and mass2278 using146/116/18, not an exact2260. Show terminal H/OH groups and state assumptions excluding rings and multiple chains."}},"35.5.1":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":35,"section_id":"35.5.1","goals":["联系异戊二烯cis-1,4结构与弹性","区分乳胶凝聚聚合和硫化交联"],"prerequisites":["二烯与聚合","链运动和网络"],"flow":["异戊二烯","cis-1,4链","乳胶分散","凝聚","硫化与老化"],"concept_relation":"异戊二烯；cis-1,4链；乳胶分散；凝聚；硫化与老化","deep":["未适当处理的生胶会有温度敏感、黏性和形变恢复等限制，硫化可建立链间交联改善特定性能。硫桥结构实际多样，示意可用通用链间连接表示，不把每个双键全断或硫画成不合理价的统一单一产物。","交联密度有权衡，适当交联帮助恢复和耐用，过密可使材料更硬、伸展性低。配方、填料与加工也影响性质，不能把“硫越多所有性能越好”作为线性规律。","链上不饱和结构可与氧、臭氧等过程相关而发生老化，光热和机械环境也影响寿命；防护与添加剂依具体用途选择。天然来源不保证任何环境不降解或瞬间完全降解，材料寿命和末端处理需证据。","计量时异戊二烯和该加成重复单元均C₅H₈、式量约68，忽略端基可由链质量估聚合度；乳胶干胶含量则是样品质量分数，不能把湿乳胶全部质量当纯橡胶。"],"derive":["异戊二烯CH₂=C(CH₃)—CH=CH₂，1,4重复片段—CH₂—C(CH₃)=CH—CH₂—。","加成重复式量C₅H₈≈68；M链≈68n忽略端基。","干胶质量≈乳胶质量×题给干胶质量分数，分散水不是橡胶链组成。"],"examples":[{"q":"天然橡胶题给平均Mr136000，按重复C₅H₈式量68且忽略端基，平均n？","given":"相应平均模型。","analysis":"先确认加成无脱小分子。","method":"136000/68。","principle":"重复质量近似。","steps":["n≈2000。","不保证每条链恰2000。"],"ans":"约2000。","verification":"2000×68=136000。","pitfall":"用单体加2水或保留不正确分子量。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.1","related_sections":[]},{"q":"100 g乳胶题给干胶30%，理论干胶与非干胶部分各多少？凝聚是否才开始形成所有长链？","given":"按质量分数，其他组分归非干胶。","analysis":"分散体系与聚合过程不同。","method":"干胶=.30×100。","principle":"组成收支及凝聚概念。","steps":["干胶30g，其他70g。","长链原已存在，凝聚主要使颗粒聚集分离，不是首次全体聚合。"],"ans":"30g与70g；不是首次聚合。","verification":"30+70=100，水等不计进重复结构。","pitfall":"把乳胶水全算胶或把凝聚等同聚合。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.1","related_sections":[]},{"q":"硫化后恢复更好，是否可把所有交叉链点都画成一个S原子连四个碳，并声称唯一产物？","given":"实际硫化结构有多样性。","analysis":"网络示意不能伪装唯一精确结构。","method":"用有依据通用桥并核价。","principle":"结构连接需化学合理。","steps":["可示意适当链间交联。","不无依据指定每点同一超简结构或不合理价；需标示意且保留不饱和/位点条件。"],"ans":"不能，按可靠结构或明确通用示意。","verification":"宏观性能不唯一确定每个原子连接。","pitfall":"为画网络随意给硫和碳超价。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.1","related_sections":[]}],"practice":[{"q":"天然橡胶重复单元是否没有任何双键？","given":"1,4聚异戊二烯模型。","analysis":"仍有剩余C=C。","method":"写重复结构。","principle":"二烯聚合连接重排。","steps":["—CH₂—C(CH₃)=CH—CH₂—保留一双键。","不是聚乙烯式全饱和链。"],"ans":"仍有双键。","verification":"C5H8氢数与饱和烃链模型不同。","pitfall":"两双键参与就全都消失且不审氢数。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.1","related_sections":[]},{"q":"线型长链卷曲为什么仍可叫线型？","given":"连接无分支网络另论。","analysis":"拓扑与构象不同。","method":"看是否一条连续链。","principle":"结构分类。","steps":["卷曲不新增主链分支。","线型指连接而不是物理直线。"],"ans":"可，卷曲是构象。","verification":"拉直与再卷不必打断主链。","pitfall":"把线型画成永远硬直杆。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.1","related_sections":[]},{"q":"干胶含量25%的200g乳胶，若干胶回收率90%，实收干胶多少？","given":"两个百分数意义不同。","analysis":"先组成后回收。","method":"200×.25×.90。","principle":"物料及收率。","steps":["理论50g。","实收45g。"],"ans":"45 g。","verification":"其余5g为未回收干胶，另150g非干胶。","pitfall":"25%和90%相加或只乘一个。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.1","related_sections":[]},{"q":"把交联密度不断提高，是否保证最大伸长也不断增加？","given":"其他条件近似。","analysis":"网络约束可能限制伸展。","method":"比较恢复和可动性。","principle":"结构性能权衡。","steps":["适度交联可帮助恢复。","过密限制链运动，最大伸长可降低，不能无界增加。"],"ans":"不保证。","verification":"硬胶与弹性胶的目标不同。","pitfall":"恢复好就等于可拉得无限长。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.1","related_sections":[]}],"quiz":{"q":"乳胶乳白且含水，能叫“橡胶完全分子溶于水的真溶液”吗？","given":"分散颗粒模型。","analysis":"胶体分散与分子溶液不同。","method":"比较分散单位。","principle":"颗粒相与溶解定义。","steps":["橡胶颗粒等分散于水。","不代表每条橡胶链完全成为均一水中分子溶液。"],"ans":"不能。","verification":"凝聚行为也与颗粒稳定性有关。","pitfall":"只因看起来均匀就当真溶液。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.1","related_sections":[]},"exam":["橡胶结构题核1,4连接、侧甲基、cis及剩余双键","工艺题区分已聚合乳胶、凝聚分离和硫化交联","计量题干胶含量与回收率分层，结构示意不冒充唯一产物"],"quick":["异戊二烯","cis-1,4链","乳胶分散","凝聚","硫化与老化"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.5.1","url":"https://openstax.org/books/organic-chemistry/pages/14-6-diene-polymers-natural-and-synthetic-rubbers","page_or_section":"14-6-diene-polymers-natural-and-synthetic-rubbers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.5.1","url":"https://openstax.org/books/organic-chemistry/pages/14-6-diene-polymers-natural-and-synthetic-rubbers","page_or_section":"14-6-diene-polymers-natural-and-synthetic-rubbers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"橡胶结构题核1,4连接、侧甲基、cis及剩余双键","method":"用有依据通用桥并核价。","principle":"结构连接需化学合理。","worked_example_index":2,"verification":"宏观性能不唯一确定每个原子连接。","pitfall":"为画网络随意给硫和碳超价。"},"diagnostics":[{"goal_index":0,"question_ref":"p0","review_module":4,"feedback":"目标“联系异戊二烯cis-1,4结构与弹性”的抽样复核：C5H8氢数与饱和烃链模型不同。；若出现“两双键参与就全都消失且不审氢数。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“区分乳胶凝聚聚合和硫化交联”的抽样复核：30+70=100，水等不计进重复结构。；若出现“把乳胶水全算胶或把凝聚等同聚合。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"只因看起来均匀就当真溶液。","correction":"不能。","verification":"凝聚行为也与颗粒稳定性有关。"}],"illustration_spec":{"title":"天然橡胶结构与硫化","objects":["异戊二烯","cis-1,4重复","卷曲伸展链","乳胶颗粒水相","通用硫交联"],"relations":["每重复保留一C=C","凝聚前已有长链","交联不画超价或唯一产物","卷曲非主链断裂"],"labels":["C₅H₈","cis-1,4","干胶含量","凝聚≠聚合","交联示意非唯一结构"],"format":"SVG","priority":"P0","reuse":"暂无对应正确图；cis连接及硫桥须专项审核","english":"Draw isoprene and the cis-1,4 polyisoprene repeat retaining one C=C per repeat. Separate latex particle coagulation from polymer formation and from vulcanization. Show only chemically justified or explicitly generic crosslink bridges, with no overvalent atoms or claim of one universal sulfur-crosslink structure."}},"35.5.2":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":35,"section_id":"35.5.2","goals":["由单体说明常见合成橡胶结构来源","用共聚组成和性能数据选择材料"],"prerequisites":["二烯聚合","单体质量与链结构"],"flow":["单体来源","统计序列","极性侧基","组成质量","性能与使用环境"],"concept_relation":"单体来源；统计序列；极性侧基；组成质量；性能与使用环境","deep":["氯丁橡胶可由氯丁二烯来源形成，单体CH₂=C(Cl)—CH=CH₂与异戊二烯不同。画1,4型示意时保留Cl侧基和相应剩余双键，不把Cl替成CH₃还沿用同一物质名。","性能可通过单体、链结构、交联、填料与加工调节，所谓耐油、耐热、耐候都需具体介质、温度和时间。某材料一项较好不表示耐所有溶剂、所有气候和全部力学指标都最佳。","共聚物计量需区分摩尔比与质量比。若题设所有单体完全进入目标加成共聚物且忽略端基，质量可相加；部分转化时两单体反应性不同，实际链组成未必等于初投料比，不能默认。","天然与合成橡胶可在配方中组合，选择应按任务指标而非来源标签。磨损、添加剂和末端处置也需关注，合成不等于绝对不老化，天然也不保证所有环境都无负担。"],"derive":["丁苯示例单体：1,3-丁二烯C₄H₆（Mr54）+苯乙烯C₈H₈（Mr104）。","完全进入理想加成共聚物时m聚≈ΣnᵢMᵢ；摩尔分数与质量分数一般不同。","丙烯腈CH₂=CH—C≡N含腈基，不属于只含C/H的炔烃；氯丁单体Cl不能丢。"],"examples":[{"q":"丁苯橡胶两单体是什么？画通用链段时能无依据把全部单元严格AB交替吗？","given":"仅知共聚，未给序列控制。","analysis":"组成与序列不同。","method":"列丁二烯、苯乙烯并限定图示。","principle":"共聚可有统计结构。","steps":["两类来源单元来自1,3-丁二烯与苯乙烯。","没有顺序证据，不应画成唯一严格交替，可用标明统计示意的链。"],"ans":"不能无依据严格交替。","verification":"相同总体比例可对应多种序列。","pitfall":"共聚两个单体就必ABAB。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.2","related_sections":[]},{"q":"3 mol丁二烯Mr54与1 mol苯乙烯Mr104全部进入理想加成共聚物，聚合物质量及苯乙烯来源质量分数？","given":"完全转化无副产物，忽略端基。","analysis":"摩尔25%不等质量25%。","method":"总质量3×54+104。","principle":"质量加和。","steps":["m=266 g。","苯乙烯来源质量分数104/266≈39.1%。"],"ans":"266 g，约39.1%。","verification":"丁二烯162g加104g守恒；苯乙烯摩尔分数仍25%。","pitfall":"把数目比3:1当质量3:1。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.2","related_sections":[]},{"q":"题给甲低温柔性好但某油中明显溶胀，乙在该油中稳定但低温较脆，常温油封与低温无油部件如何选？能定绝对最优吗？","given":"仅限给定测试环境。","analysis":"任务不同选指标不同。","method":"按使用条件匹配。","principle":"材料选择有权衡。","steps":["常温该油封可优先评乙，仍核力学寿命。","低温无油可优先评甲，仍核载荷与其他条件。"],"ans":"按目标分别评估，不给无条件绝对最优。","verification":"一材的短板在另一场景可能不主导。","pitfall":"同一排行榜适用于所有用途。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.2","related_sections":[]}],"practice":[{"q":"丙烯腈有C≡N，就属于炔烃吗？","given":"式CH₂=CH—CN。","analysis":"炔烃需C≡C且只C/H。","method":"核键类型与元素。","principle":"官能团分类。","steps":["三键为碳氮，不是碳碳。","分子含N，也不是烃。"],"ans":"不是。","verification":"其C=C仍可参与相应加成聚合。","pitfall":"三键符号相同就当同类。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.2","related_sections":[]},{"q":"氯丁二烯结构CH₂=C(Cl)—CH=CH₂中有几种元素、Cl在聚合图中能否删除？","given":"普通单体结构。","analysis":"侧基原子需守恒。","method":"数C/H/Cl。","principle":"组成与结构守恒。","steps":["有C、H、Cl三种元素。","加成结构中Cl仍保留，不能为简图删掉。"],"ans":"三种，Cl不能删。","verification":"删Cl会改变重复单元组成和性质。","pitfall":"只画碳骨架忘关键侧基。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.2","related_sections":[]},{"q":"等mol丁二烯与苯乙烯理想完全加成，来源质量比？","given":"Mr54、104。","analysis":"等数不等质量。","method":"n相同乘M。","principle":"质量关系。","steps":["质量比54:104=27:52。","苯乙烯来源质量较大。"],"ans":"27:52。","verification":"分子量近两倍使等mol质量近两倍。","pitfall":"等mol直接写1:1质量。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.2","related_sections":[]},{"q":"投料单体比已知但只反应10%，能保证所得共聚物来源比等于投料比吗？","given":"未给两类单体反应性。","analysis":"部分转化可有选择差。","method":"需要实际组成或反应性资料。","principle":"速率与投料统计不同。","steps":["一种单体可能优先进入链。","需分析反应性和转化，不能直接照抄初投料。"],"ans":"不能保证。","verification":"完全都进入时总收支才强约束总体来源比。","pitfall":"把总投料自动当所有时刻链组成。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.2","related_sections":[]}],"quiz":{"q":"合成橡胶耐油的常见趋势，能否扩写为“耐任何溶剂、无限温度与时间”？","given":"只有限定用途经验。","analysis":"介质和环境条件影响性质。","method":"要求规范测试范围。","principle":"材料特性有适用域。","steps":["不同油和溶剂与链作用不同。","高温老化等可改变性能，需具体测试，不能绝对无限。"],"ans":"不能。","verification":"单一实验不能覆盖无限条件。","pitfall":"定性名称取代完整使用限制。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.5.2","related_sections":[]},"exam":["单体题核腈基/三键及Cl等侧基，图不能掉原子","共聚题分组成和序列，摩尔比转质量必须乘M","选材题按介质温度载荷寿命匹配，不给来源决定论"],"quick":["单体来源","统计序列","极性侧基","组成质量","性能与使用环境"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.5.2","url":"https://openstax.org/books/organic-chemistry/pages/14-6-diene-polymers-natural-and-synthetic-rubbers","page_or_section":"14-6-diene-polymers-natural-and-synthetic-rubbers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.5.2","url":"https://openstax.org/books/organic-chemistry/pages/14-6-diene-polymers-natural-and-synthetic-rubbers","page_or_section":"14-6-diene-polymers-natural-and-synthetic-rubbers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"单体题核腈基/三键及Cl等侧基，图不能掉原子","method":"按使用条件匹配。","principle":"材料选择有权衡。","worked_example_index":2,"verification":"一材的短板在另一场景可能不主导。","pitfall":"同一排行榜适用于所有用途。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由单体说明常见合成橡胶结构来源”的抽样复核：相同总体比例可对应多种序列。；若出现“共聚两个单体就必ABAB。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用共聚组成和性能数据选择材料”的抽样复核：一材的短板在另一场景可能不主导。；若出现“同一排行榜适用于所有用途。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"定性名称取代完整使用限制。","correction":"不能。","verification":"单一实验不能覆盖无限条件。"}],"illustration_spec":{"title":"合成橡胶的单体与共聚","objects":["丁二烯","苯乙烯","丙烯腈","氯丁二烯","统计共聚链","性能对照表"],"relations":["C≡N不画C≡C","Cl侧基保留","统计链不伪装严格交替","3mol54+1mol104=266g"],"labels":["丁苯","丁腈","氯丁","摩尔比≠质量比","条件性性能"],"format":"SVG","priority":"P0","reuse":"暂无对应图；单体和重复结构逐原子核验","english":"Draw correct butadiene, styrene, acrylonitrile and chloroprene structures, retaining CN and Cl substituents. Mark copolymer sequence as statistical unless explicitly controlled. Show3 mol of54 plus1 mol of104 giving266 g and39.1% styrene-derived mass, not25% mass."}},"35.6":{"content_batch":"batch05","subject":"化学","subject_code":"chemistry","chapter_id":35,"section_id":"35.6","goals":["追踪石油馏分到单体聚合物的变化层级","评价回收及生命周期声明的结构依据"],"prerequisites":["蒸馏裂化","聚合与物料循环"],"flow":["石油混合物","分馏与裂化","单体聚合","回收结构条件","生命周期收支"],"concept_relation":"石油混合物；分馏与裂化；单体聚合；回收结构条件；生命周期收支","deep":["资源评价包括原料开采、单体生产、聚合加工、使用寿命及处置。轻量耐用可减少某用途负担，也可能延长环境持留；需要同功能与边界比较，不用一项优势或化石来源一个标签代所有指标。","机械回收主要通过收集分选、清洗和再加工保留部分材料身份，但污染、混配、热降解和性能要求可限制循环。热塑可熔流不等于任意混合废料都能回同质量产品，交联材料又有不同处理难点。","化学回收或解聚可能改变链连接，某些聚酯可通过相应反应回收组分，而普通聚乙烯C—C主链不能简单用水按同一酯水解机制处理。能量回收燃烧更不是所有原子都变回原单体，需清楚区分路径。","“生物基”描述碳来源，“可生物降解”描述特定条件下的转化行为，二者不等同。生物基聚乙烯若链结构相同，不因原料来自植物就自动在任何环境快速分解；可堆肥等声明还需环境与时间规范。","可持续方案要以真实回收率、能源、排放、材料寿命和有害副产物等数据支持。把污染物转入另一物流或把废料焚烧，仍应完整记物料能量去向，不以循环箭头画成永不损耗、无外界输入的闭环。"],"derive":["分馏=按物性分离混合物；裂化/聚合=改变连接的化学过程。","简化裂化例C₁₀H₂₂→C₂H₄+C₈H₁₈，原子守恒但非唯一产物承诺。","回收路径分机械再加工、化学转化与能源回收；生物基来源不等于可降解性能。"],"examples":[{"q":"石油分馏所得一馏分，能无数据称纯乙烯且已完成聚合原料制备吗？","given":"仅做分离，未测组成。","analysis":"馏分通常混合，化学转化与纯化另有过程。","method":"分层说明。","principle":"物理分离不自动制造指定单体。","steps":["分馏分出挥发范围相近组分。","还需相应裂化、分离与净化等证据，不能称全为纯单体。"],"ans":"不能。","verification":"原馏分可含多种烃而非单一分子。","pitfall":"蒸馏就等于把所有大分子裂成乙烯。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.6","related_sections":[]},{"q":"核查简化反应C₁₀H₂₂→C₂H₄+C₈H₁₈的原子守恒。若10 mol按此唯一模型，乙烯理论多少mol和g？取M28。","given":"明确理想单一路径例题，非真实产品分布声明。","analysis":"先守恒再系数。","method":"C10=2+8，H22=4+18。","principle":"元素守恒。","steps":["方程配平。","10 mol原料给10 mol乙烯，质量280g。"],"ans":"守恒，10mol、280g。","verification":"碳氢剩余也在C8H18，不是其余原子消失。","pitfall":"平衡就说工业实际必100%得该两物。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.6","related_sections":[]},{"q":"生物基聚乙烯与石油基聚乙烯的主链重复结构相同，能仅凭生物基断言前者必快速生物降解吗？","given":"比较相同核心链，配方另需核。","analysis":"来源和结构降解性不同概念。","method":"看键、环境与实际测试。","principle":"降解取决结构及过程条件。","steps":["来源可不同但C—C链相同。","不能由植物碳来源直接推快速降解，需具体环境时间证据。"],"ans":"不能。","verification":"来源标签不自动加入可水解键。","pitfall":"生物基等于可堆肥或任意环境降解。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.6","related_sections":[]}],"practice":[{"q":"分馏和裂化哪种主要物理、哪种化学？","given":"按常见工艺含义。","analysis":"是否改变组分连接。","method":"分别定义。","principle":"分离与反应。","steps":["分馏主要按物性分离。","裂化断/重组键形成新物，属化学变化。"],"ans":"前物理，后化学。","verification":"温度高不单独决定类型，过程本质才是。","pitfall":"所有加热过程都化学。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.6","related_sections":[]},{"q":"聚酯可按相应水解回组分，就能对聚乙烯用相同酯水解方程吗？","given":"PE无相同酯键。","analysis":"结构靶点不同。","method":"比较主链连接。","principle":"反应需相应官能团。","steps":["聚酯有可相应水解的连接。","PE普通C—C链不含该酯键，需其他方法，不能照抄。"],"ans":"不能。","verification":"把反应式套上会凭空增加氧原子和官能团。","pitfall":"所有聚合物回收反应完全一样。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.6","related_sections":[]},{"q":"100 kg单体理想加成，90%质量进入目标聚合物，其余未反应，目标与残单体多少？","given":"无副反应端基忽略。","analysis":"物料两去向。","method":"100×.9与剩余。","principle":"质量守恒。","steps":["目标90kg。","残单体10kg，后续回收需另核。"],"ans":"90与10kg。","verification":"相加100，转化率不自动等于收集纯品收率。","pitfall":"把未反应质量说成能量损耗而忽略物料。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.6","related_sections":[]},{"q":"回收100 kg废料，最终得60 kg合格材料、20 kg其他物流、20 kg损失/处置，合格材料回收比例？能画100%闭环吗？","given":"流向按题给。","analysis":"目标回收口径。","method":"60/100。","principle":"完整收支。","steps":["60%。","20+20仍有其他去向，不能把全部画回等质材料。"],"ans":"60%，不能画100%同质闭环。","verification":"60+20+20=100kg。","pitfall":"只要有回收工序就称全部循环。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.6","related_sections":[]}],"quiz":{"q":"焚烧废塑料得到能量，为什么不能直接将箭头画回“原单体100%且零排放”？","given":"燃烧改变化学结构，实际有多产物与损失。","analysis":"能源与材料路径不同。","method":"追踪碳、其他元素及能量。","principle":"原子与能量守恒不等于回原物。","steps":["能量可部分利用，但碳等进入CO₂等相应产物。","回单体需不同化学转化与分离证据，不能一箭头省掉。"],"ans":"因为没有原单体回收及零排放的证据。","verification":"总量守恒允许物料换形而非同物质闭环。","pitfall":"循环图替代真实工艺收支。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":35,"primary_section":"35.6","related_sections":[]},"exam":["路线题分分离、裂化、聚合和加工，方程只表示明确模型","回收题按键型与条件选方法，机械/化学/能源回收不混","环境声明区分生物基、可降解和可堆肥，量化真实去向"],"quick":["石油混合物","分馏与裂化","单体聚合","回收结构条件","生命周期收支"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.6","url":"https://openstax.org/books/organic-chemistry/pages/31-chemistry-matters-degradable-polymers","page_or_section":"31-chemistry-matters-degradable-polymers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":16,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_35.6","url":"https://openstax.org/books/organic-chemistry/pages/31-chemistry-matters-degradable-polymers","page_or_section":"31-chemistry-matters-degradable-polymers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"路线题分分离、裂化、聚合和加工，方程只表示明确模型","method":"看键、环境与实际测试。","principle":"降解取决结构及过程条件。","worked_example_index":2,"verification":"来源标签不自动加入可水解键。","pitfall":"生物基等于可堆肥或任意环境降解。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“追踪石油馏分到单体聚合物的变化层级”的抽样复核：原馏分可含多种烃而非单一分子。；若出现“蒸馏就等于把所有大分子裂成乙烯。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":7,"feedback":"目标“评价回收及生命周期声明的结构依据”的抽样复核：来源标签不自动加入可水解键。；若出现“生物基等于可堆肥或任意环境降解。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"循环图替代真实工艺收支。","correction":"因为没有原单体回收及零排放的证据。","verification":"总量守恒允许物料换形而非同物质闭环。"}],"illustration_spec":{"title":"石油到聚合物及回收路径","objects":["原油混合物","馏分","裂化单体","聚合物产品","机械/化学/能源三路径","外部输入输出"],"relations":["分馏不画成自动裂化","材料与能源回收分开","PE不画酯水解","60%回收不画100%闭环"],"labels":["分离","化学转化","结构条件","生物基≠可降解","真实回收率"],"format":"SVG","priority":"P1","reuse":"暂无完整图；流程需有收支出口不画永动闭环","english":"Trace crude-oil mixture through physical fractionation, chemical cracking, monomer purification and polymerization. Separate mechanical recycling, chemical conversion and energy recovery, with explicit losses and external inputs. Do not depict polyethylene as an ester undergoing ordinary hydrolysis or equate bio-based feedstock with biodegradability."}}},"数学1":{"1.1":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":1,"section_id":"1.1","goals":["用坐标和距离描述点的位置","由距离方程求点并核几何条件"],"prerequisites":["毕氏定理","平方与实数"],"flow":["坐标符号","正交差","毕氏距离","等距方程","退化核查"],"concept_relation":"坐标符号；正交差；毕氏距离；等距方程；退化核查","deep":["两点交换顺序使两个差同时变号，平方和不变；若横坐标相同，距离退为纵差绝对值，若纵坐标相同则退为横差绝对值。这些特殊情况能复核公式，不必死记三套互不联系的规则。","可由距离条件建立方程，例如到两固定点等距时两距离平方相等。因为距离非负，比较平方可等价去根号，常使二次项相消；但解后仍需检查点在某轴、某区间或不同于给定点等条件。","判断三角形性质可先求三边平方以避免多次开根。若最长边平方等于其他两边平方和，可用毕氏逆定理判直角；先确认三点不同且不共线，不能把零长度退化当正常三角形。","实际坐标问题还要给位置单位和参考对象。将地图经纬度直接代普通平面米制距离公式可能不合模型；本节采用平面正交坐标，不把近似平面方法无条件推广球面长距离。"],"derive":["d(A,B)=√[(x₂−x₁)²+(y₂−y₁)²]≥0，正交轴且单位相容。","同横坐标时d=|y₂−y₁|；同纵坐标时d=|x₂−x₁|。","d(P,A)=d(P,B)可等价平方，展开后再按P的轴/区间限制筛选。"],"examples":[{"q":"A(−2,1)、B(4,9)，求AB。","given":"平面同单位正交坐标。","analysis":"横纵差6、8。","method":"毕氏距离公式。","principle":"直角分解。","steps":["AB²=(4+2)²+(9−1)²=36+64=100。","AB=10。"],"ans":"10个长度单位。","verification":"交换点差为−6、−8，平方和仍100。","pitfall":"横差算4−2或距离不取平方根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"A(0,0)、B(3,0)、C(0,4)，不用近似根号判断三角形是否直角及直角点。","given":"三点互异不共线。","analysis":"算三边平方找最长。","method":"AB²9、AC²16、BC²25。","principle":"毕氏逆定理。","steps":["9+16=25，BC最长为斜边。","直角在A。"],"ans":"直角三角形，∠A=90°。","verification":"AB沿横轴、AC沿纵轴也互垂验证。","pitfall":"最长边对应的端点误当直角点。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"P在x轴且到A(−1,2)、B(5,4)等距，求P。","given":"P=(t,0)。","analysis":"距离平方相等可去根。","method":"列两平方和。","principle":"非负距离相等与平方相等。","steps":["(t+1)²+4=(t−5)²+16。","2t+5=−10t+41，t=3。"],"ans":"P(3,0)。","verification":"到A平方16+4=20，到B平方4+16=20。","pitfall":"把P设(0,t)放错轴。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.1","related_sections":[]}],"practice":[{"q":"点(0,−5)在哪个象限？到原点距离多少？","given":"横坐标0。","analysis":"轴点不归象限。","method":"位置与距离分别判。","principle":"坐标轴定义。","steps":["在y轴负半轴，不属象限。","距离|−5|=5。"],"ans":"不属象限；距离5。","verification":"与原点同x，纵差绝对值。","pitfall":"因y负就归第四象限。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"A(2,−3)、B(2,5)距离？","given":"同横坐标。","analysis":"退化为竖直间隔。","method":"|5−(−3)|。","principle":"距离非负。","steps":["纵差8。","AB=8。"],"ans":"8。","verification":"通式√(0²+8²)=8。","pitfall":"写5−3=2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"P(t,2)到原点距离√13，求t。","given":"实数t。","analysis":"距离条件平方后有双符号。","method":"t²+4=13。","principle":"距离平方。","steps":["t²=9。","t=±3。"],"ans":"t=−3或3。","verification":"两点(±3,2)平方和均13。","pitfall":"只取t正根，误把距离非负当坐标非负。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"A(1,1)、B(4,5)、C(7,9)，三点能构成非退化三角形吗？","given":"三点互异。","analysis":"距离可检共线。","method":"AB=5、BC=5、AC=10。","principle":"一边等于另两边和为退化。","steps":["两段差均(3,4)，AB、BC各5。","AC差(6,8)长10，A到C经B刚好同线。"],"ans":"不能，三点共线。","verification":"B也为A,C中点，方向一致。","pitfall":"三点不同就认为必成三角形。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.1","related_sections":[]}],"quiz":{"q":"两点交换顺序后距离公式中差值变号，会得到负距离吗？","given":"两个坐标差都变号。","analysis":"平方消去符号，主根非负。","method":"分别平方比较。","principle":"(−a)²=a²。","steps":["差平方和不变。","最终取非负主根，距离相同。"],"ans":"不会。","verification":"d(A,B)=d(B,A)符合长度对称性。","pitfall":"把带符号位移分量当距离。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.1","related_sections":[]},"exam":["坐标题先圈横纵次序和轴限制，设点形式正确","距离题可先算平方，等距条件平方要依距离非负","几何判定题查退化与最长边，图只辅助不凭比例猜"],"quick":["坐标符号","正交差","毕氏距离","等距方程","退化核查"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/2-1-the-rectangular-coordinate-systems-and-graphs","page_or_section":"2-1-the-rectangular-coordinate-systems-and-graphs","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/2-1-the-rectangular-coordinate-systems-and-graphs","page_or_section":"2-1-the-rectangular-coordinate-systems-and-graphs","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"坐标题先圈横纵次序和轴限制，设点形式正确","method":"列两平方和。","principle":"非负距离相等与平方相等。","worked_example_index":2,"verification":"到A平方16+4=20，到B平方4+16=20。","pitfall":"把P设(0,t)放错轴。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用坐标和距离描述点的位置”的抽样复核：交换点差为−6、−8，平方和仍100。；若出现“横差算4−2或距离不取平方根。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“由距离方程求点并核几何条件”的抽样复核：到A平方16+4=20，到B平方4+16=20。；若出现“把P设(0,t)放错轴。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把带符号位移分量当距离。","correction":"不会。","verification":"d(A,B)=d(B,A)符合长度对称性。"}],"illustration_spec":{"title":"距离公式的正交分解","objects":["A(−2,1)","B(4,9)","直角投影点","横差6","纵差8","距离10"],"relations":["投影点同一横/纵坐标","直角边6与8","斜边10","坐标比例一致"],"labels":["x","y","Δx=6","Δy=8","AB=10","非负距离"],"format":"SVG","priority":"P=0","reuse":"暂无对应旧图；坐标与比例需数学绘图库","english":"Plot A(-2,1) and B(4,9) with equal unit scales, construct horizontal and vertical projections of lengths 6 and 8, and label the hypotenuse 10. Distinguish signed coordinate differences from nonnegative Euclidean distance."}},"1.2":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":1,"section_id":"1.2","goals":["由线性插值推导内分与外分坐标","反求端点并区分中点重心和无有限外分"],"prerequisites":["坐标差","比例与向量式位移思想"],"flow":["比例顺序","内分插值","中点","外分延长","反求与重心"],"concept_relation":"比例顺序；内分插值；中点；外分延长；反求与重心","deep":["外分在延长线上，采用相同AP:PB=m:n的长度比时可写P=(mB−nA)/(m−n)，m≠n。m>n时P越过B，m<n时在A外侧；结果不应强迫落在两端之间。","若m=n>0且要求外分，在线上没有有限点使到两个不同端点的距离相等又在线段外。分母零反映几何不可实现，不是位置坐标为0；内分等比则正常是中点，不能混淆。","反求端点时把分点公式看作两个线性方程逐坐标解。三角形重心可由中点和中线内分2:1推得三顶点坐标平均；这是一条可推导结论，不靠把图中心目测出来。","验算先看P相对A、B的位置，再算相应差向量或长度比。坐标结果即使满足某个代数式，也要确认所用比的顺序和内外分条件；正负坐标不决定点在不在线段内部。"],"derive":["内分AP:PB=m:n：P=(nA+mB)/(m+n)，m,n>0。","外分同长度比：P=(mB−nA)/(m−n)，m≠n；端点不同。","中点M=(A+B)/2；三角形重心G=(A+B+C)/3，可由中线2:1推导。"],"examples":[{"q":"A(1,2)、B(7,8)，P内分AP:PB=1:2，求P。","given":"P在线段内部。","analysis":"靠近A，A权重2。","method":"P=(2A+B)/3。","principle":"内分位移比例。","steps":["x=(2×1+7)/3=3。","y=(2×2+8)/3=4。"],"ans":"P(3,4)。","verification":"AP差(2,2)、PB差(4,4)，长度比1:2。","pitfall":"把权重同顺序写(A+2B)/3。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"同样A(1,2)、B(7,8)，P外分AP:PB=2:1，求P及位置。","given":"外分且m=2、n=1（m>n）。","analysis":"应在B外侧。","method":"P=(2B−A)/(2−1)。","principle":"外分公式。","steps":["x=14−1=13，y=16−2=14。","P越过B。"],"ans":"P(13,14)，在B外侧。","verification":"AP差(12,12)、PB差(6,6)，长度比2:1。","pitfall":"外分仍用加权平均落到内部。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"A(2,−1)，P(5,2)内分AP:PB=1:2，反求B。","given":"分点和比例已知。","analysis":"P=(2A+B)/3。","method":"B=3P−2A。","principle":"坐标线性关系。","steps":["B_x=15−4=11。","B_y=6−(−2)=8。"],"ans":"B(11,8)。","verification":"AP差(3,3)，PB差(6,6)，比例正确。","pitfall":"反求时负坐标漏括号。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.2","related_sections":[]}],"practice":[{"q":"A(−2,3)、B(4,−1)中点？","given":"等比内分。","analysis":"横纵各取平均。","method":"M=(A+B)/2。","principle":"中点特例。","steps":["x=(−2+4)/2=1。","y=(3−1)/2=1。"],"ans":"M(1,1)。","verification":"MA、MB差分别(3,−2)、(3,−2)，长度相同。","pitfall":"只平均一个坐标。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"不同端点A,B能有AP:PB=1:1的有限外分点吗？","given":"P在直线延长线外分。","analysis":"等距点在线段中点而非外侧。","method":"比较外侧到远端和近端距离。","principle":"外侧两距离相差AB>0。","steps":["因此不可能等距。","外分分母1−1为0对应无有限解。"],"ans":"不能。","verification":"内分1:1中点不属于外分。","pitfall":"除零后把坐标设0。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"A(0,0)、B(6,0)、C(0,6)重心坐标，并用一条中线验证。","given":"非退化三角形。","analysis":"顶点平均。","method":"G=(A+B+C)/3。","principle":"中线2:1。","steps":["G=(2,2)。","BC中点M(3,3)，AG:GM=2√2:√2=2:1。"],"ans":"G(2,2)。","verification":"位于A到M内部2/3处。","pitfall":"把BC中点(3,3)当重心。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"A(0,1)、B(4,5)，P外分AP:PB=1:2，求P并验在A外侧。","given":"m=1、n=2（m<n）。","analysis":"外分分母负但坐标可合法。","method":"P=(B−2A)/(1−2)。","principle":"外分同长度比。","steps":["分子(4,3)，除−1得(−4,−3)。","AP长4√2，PB长8√2，比例1:2。"],"ans":"P(−4,−3)。","verification":"P在A反向延长线上，符合m<n。","pitfall":"看到负分母就判无解。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.2","related_sections":[]}],"quiz":{"q":"AP:PB=1:3内分，P应靠A还是B？用权重与位移两种方式解释。","given":"正比例内部。","analysis":"AP是较短那段。","method":"t=1/(1+3)。","principle":"位移插值。","steps":["P=A+AB/4，离A较近。","公式P=(3A+B)/4给A较大权重，同结论。"],"ans":"靠A。","verification":"AP为全长1/4，PB为3/4。","pitfall":"比例较大的3误当AP并靠B。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.2","related_sections":[]},"exam":["分点题先画内外位置、标AP:PB顺序，再套对应式","内分权重交叉，外分负分母不等于错误","反求端点与重心题用线性坐标关系，并以位置和距离比双验"],"quick":["比例顺序","内分插值","中点","外分延长","反求与重心"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/2-1-the-rectangular-coordinate-systems-and-graphs","page_or_section":"2-1-the-rectangular-coordinate-systems-and-graphs","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/2-1-the-rectangular-coordinate-systems-and-graphs","page_or_section":"2-1-the-rectangular-coordinate-systems-and-graphs","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"分点题先画内外位置、标AP:PB顺序，再套对应式","method":"B=3P−2A。","principle":"坐标线性关系。","worked_example_index":2,"verification":"AP差(3,3)，PB差(6,6)，比例正确。","pitfall":"反求时负坐标漏括号。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由线性插值推导内分与外分坐标”的抽样复核：AP差(2,2)、PB差(4,4)，长度比1:2。；若出现“把权重同顺序写(A+2B)/3。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“反求端点并区分中点重心和无有限外分”的抽样复核：AP差(3,3)，PB差(6,6)，比例正确。；若出现“反求时负坐标漏括号。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"比例较大的3误当AP并靠B。","correction":"靠A。","verification":"AP为全长1/4，PB为3/4。"}],"illustration_spec":{"title":"内分与外分的权重","objects":["A(1,2)","B(7,8)","内分P(3,4)","外分P(13,14)","A侧外分"],"relations":["内分1:2靠A","外分2:1越B","权重交叉","m=n外分无有限点"],"labels":["AP:PB","内分","外分","m,n>0","m≠n"],"format":"SVG","priority":"P=0","reuse":"暂无对应旧图；点须按同一标尺精确定位","english":"Place A(1,2), B(7,8), internal P(3,4) with AP:PB=1:2 and external P(13,14) with ratio 2:1 on the same line. Show crossed coordinate weights and distinguish an A-side external point; never draw an equal-ratio finite external division."}},"1.3":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":1,"section_id":"1.3","goals":["用坐标推导三角形及多边形面积","保留顶点顺序和绝对值处理参数"],"prerequisites":["坐标距离","分配律与绝对值"],"flow":["相对坐标","有向乘积","三角形","边界鞋带","参数与退化"],"concept_relation":"相对坐标；有向乘积；三角形；边界鞋带；参数与退化","deep":["简单多边形可按边界顺序列顶点，用相邻点乘积和差的一半求面积，末点须连回首点。顶点顺序不是随便排序：把对角点交错会形成自交路线，其有向面积可能抵消，不能当原简单多边形的普通面积。","凹多边形按实际不自交边界顺序使用也可；也可拆成无重叠三角形再加面积。拆分法须避免把外部三角形加入或重叠部分算两次，尤其图不按比例时应由顶点关系确定。","未知坐标由面积条件求解时出现绝对值常产生正负两个分支，对应点在某条边两侧。若题给“在上方”或“第一象限”等条件，再筛选分支；不能因为面积正就强迫未知坐标也正。","结果用底高、平移后分量或三角形分割独立核查，单位应是长度单位平方。整体平移不改变面积，若坐标代数式因换原点而改变结果，就应检查顺序、展开或闭合项。"],"derive":["S△ABC=| (x₂−x₁)(y₃−y₁)−(y₂−y₁)(x₃−x₁) |/2。","简单多边形按边界顺序：S=|Σ(xᵢyᵢ₊₁−yᵢxᵢ₊₁)|/2，最后点连回第一点。","面积0是共线/退化警示；绝对值方程需按两符号及题设位置筛选。"],"examples":[{"q":"A(1,1)、B(5,1)、C(2,4)，求三角形面积并用底高验证。","given":"三点按任一环向。","analysis":"水平AB作底便于复核。","method":"坐标叉积或鞋带。","principle":"有向平行四边形一半取绝对值。","steps":["AB分量(4,0)、AC分量(1,3)，面积|4×3−0×1|/2=6。","底AB4、高3，底高一半也6。"],"ans":"6平方单位。","verification":"两种计算相同，普通面积非负。","pitfall":"漏1/2或把高度当AC斜边。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"顺边界A(0,0)、B(4,0)、C(5,3)、D(1,3)，求面积。","given":"简单四边形，顺序已给。","analysis":"用闭合鞋带或平行四边形。","method":"相邻乘积和差。","principle":"坐标多边形面积。","steps":["正向和0+12+15+0=27。","反向和0+0+3+0=3，面积(27−3)/2=12。"],"ans":"12平方单位。","verification":"底4、高3，平行四边形12。","pitfall":"漏D到A闭合或把顶点改交错顺序。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"A(0,0)、B(4,0)、C(2,k)三角形面积6，求k；若C在x轴上方呢？","given":"k实数。","analysis":"高度为|k|。","method":"S=4|k|/2。","principle":"面积非负与两侧对称。","steps":["2|k|=6，|k|=3。","k=±3；若上方则k>0，仅3。"],"ans":"k=−3或3；上方条件取3。","verification":"两种点到底边高度都3。","pitfall":"面积正就只取k正。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.3","related_sections":[]}],"practice":[{"q":"A(0,0)、B(2,0)、C(0,5)面积？","given":"直角三角形。","analysis":"底高明显。","method":"S=2×5/2。","principle":"面积公式。","steps":["S=5。","坐标式|2×5|/2同得5。"],"ans":"5平方单位。","verification":"单位平方而非长度。","pitfall":"算成周长或漏单位平方。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"A(1,2)、B(3,6)、C(5,10)面积与几何含义？","given":"三点不同。","analysis":"分量比例。","method":"差式算有向面积。","principle":"零面积判共线。","steps":["AB=(2,4)、AC=(4,8)，2×8−4×4=0。","面积0，三点共线。"],"ans":"0，退化不成非零面积三角形。","verification":"B在A,C连线中间。","pitfall":"把0判为公式失效而改数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"给正方形顶点A(0,0)、B(2,0)、C(2,2)、D(0,2)，按A,C,B,D交错代鞋带为何可得0却不是正方形面积？","given":"路线自交，非边界顺序。","analysis":"有向区域抵消。","method":"按真实边界重排。","principle":"简单多边形公式要求边界顺序。","steps":["交错线路形成自交弓形，有向面积抵消。","按A,B,C,D面积4。"],"ans":"顺序错误；正方形面积4。","verification":"底边2高2独立核。","pitfall":"任意顶点排列都当原多边形。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"三角形A(−1,1)、B(3,1)、C(0,4)整体平移(5,−2)，面积变化吗？给新坐标核。","given":"刚性平移。","analysis":"坐标差不变。","method":"新点A(4,−1)、B(8,−1)、C(5,2)。","principle":"面积依相对差。","steps":["原底4高3面积6。","新底仍4高3面积6。"],"ans":"不变，仍6。","verification":"分量AB与AC都不变。","pitfall":"用坐标绝对值大小猜面积变大。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.3","related_sections":[]}],"quiz":{"q":"鞋带有向和为−18，能把面积写−9吗？交换顶点方向后呢？","given":"简单多边形按边界序。","analysis":"普通面积非负，有向量有符号。","method":"取绝对值一半。","principle":"反向只改有向符号。","steps":["面积|−18|/2=9。","方向反转和+18，普通面积仍9。"],"ans":"面积9，两方向相同。","verification":"与几何面积不依走向一致。","pitfall":"把有向符号当负普通面积。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.3","related_sections":[]},"exam":["面积题先画真实边界序，再闭合相邻项，末尾取绝对值一半","未知点题保留正负高度分支，题给位置再筛","结果用底高或分割核，面积0先查共线与自交顺序"],"quick":["相对坐标","有向乘积","三角形","边界鞋带","参数与退化"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.3","url":"https://openstax.org/books/precalculus-2e/pages/9-8-solving-systems-with-cramers-rule","page_or_section":"9-8-solving-systems-with-cramers-rule","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.3","url":"https://openstax.org/books/precalculus-2e/pages/9-8-solving-systems-with-cramers-rule","page_or_section":"9-8-solving-systems-with-cramers-rule","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"面积题先画真实边界序，再闭合相邻项，末尾取绝对值一半","method":"S=4|k|/2。","principle":"面积非负与两侧对称。","worked_example_index":2,"verification":"两种点到底边高度都3。","pitfall":"面积正就只取k正。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用坐标推导三角形及多边形面积”的抽样复核：两种计算相同，普通面积非负。；若出现“漏1/2或把高度当AC斜边。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“保留顶点顺序和绝对值处理参数”的抽样复核：两种点到底边高度都3。；若出现“面积正就只取k正。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把有向符号当负普通面积。","correction":"面积9，两方向相同。","verification":"与几何面积不依走向一致。"}],"illustration_spec":{"title":"坐标面积与边界顺序","objects":["三角形(1,1)(5,1)(2,4)","底高","有序四边形","自交对照","k正负两点"],"relations":["三角形面积6","四边形面积12","自交抵消不代表正方形面积0","高用绝对值"],"labels":["1/2","绝对值","闭合边","边界顺序","平方单位"],"format":"SVG","priority":"P=0","reuse":"暂无对应旧图；顶点与区域应精确绘制","english":"Plot triangle (1,1),(5,1),(2,4) with base 4, height 3 and area 6. Show a boundary-ordered quadrilateral of area 12 and a separate self-intersecting counterexample. Preserve the absolute-value factor 1/2 and distinguish signed area from ordinary area."}},"1.4":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":1,"section_id":"1.4","goals":["用坐标差与倾斜角解释斜率","分类处理平行垂直和竖直线"],"prerequisites":["坐标系","比例与三角正切"],"flow":["横纵差比","倾斜角","水平竖直","平行重合","垂直与参数"],"concept_relation":"横纵差比；倾斜角；水平竖直；平行重合；垂直与参数","deep":["两条不同非竖直直线平行时斜率相同，但斜率相同也可能是同一条线，需要再比较截距或一点。两竖直线之间同样可能平行或重合，不由一个不存在的m判断。","两非竖直且斜率均有限的互垂直直线满足m₁m₂=−1；当一条水平时另一条竖直，不能用除0求“负倒数”。垂直条件的斜率表达有适用范围，几何定义本身仍正常。","三点共线可比较相同基点的两段斜率，但若出现竖直就要分类；也可交叉相乘成不需除法的坐标等式，避免丢掉共同横坐标情境。两点重合时不能由它们唯一确定一条线，应先排除。","参数点问题先写差的分母非零，再解斜率条件并回代。若分母为零是题意允许的竖直情况，应单独分析而非直接删掉；横纵顺序、单位比例和点的互异条件都决定结论。"],"derive":["m=(y₂−y₁)/(x₂−x₁)，要求x₂≠x₁；竖直无实数斜率，水平m=0。","非竖直线平行需m₁=m₂且不重合；互垂直（有限斜率情境）m₁m₂=−1。","三点共线可用(x₂−x₁)(y₃−y₁)=(x₃−x₁)(y₂−y₁)，并注意互异与退化。"],"examples":[{"q":"A(1,2)、B(4,8)，斜率及横增2时纵增多少？","given":"两点横坐标不同。","analysis":"差的顺序一致。","method":"m=(8−2)/(4−1)。","principle":"直线单位横变化率。","steps":["m=6/3=2。","Δx=2时Δy=mΔx=4。"],"ans":"斜率2，纵增4。","verification":"两点横增3纵增6相同比例。","pitfall":"用8/4忽略起点或只反一个差。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.4","related_sections":[]},{"q":"直线2x−3y+1=0的斜率及与之垂直线的斜率？","given":"原线非竖直且非水平。","analysis":"先改斜截式。","method":"y=(2/3)x+1/3，再负倒数。","principle":"有限非零斜率垂直乘积−1。","steps":["原m=2/3。","垂直m=−3/2。"],"ans":"2/3与−3/2。","verification":"(2/3)(−3/2)=−1。","pitfall":"直接把一般式x系数2当斜率。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.4","related_sections":[]},{"q":"P(a,5)、Q(3,1)所在直线斜率−2，求a并查分母。","given":"两点不同且斜率有限。","analysis":"3−a须非0。","method":"(1−5)/(3−a)=−2。","principle":"坐标斜率定义。","steps":["−4=−2(3−a)，得−4=−6+2a，a=1。","3−1=2非0。"],"ans":"a=1。","verification":"P(1,5)到Q(3,1)横2纵−4，斜率−2。","pitfall":"相减顺序不一致得a=5。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.4","related_sections":[]}],"practice":[{"q":"x=4的斜率与y=4的斜率分别？","given":"两种方向。","analysis":"竖直和水平区分。","method":"看Δx或Δy。","principle":"斜率定义。","steps":["x=4竖直，Δx=0无定义。","y=4水平，Δy=0且Δx非0，m=0。"],"ans":"无定义、0。","verification":"二线互垂直但不能用两个有限m乘积公式。","pitfall":"都答0。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.4","related_sections":[]},{"q":"两线斜率都3，是否一定是不同平行线？","given":"未给截距或点。","analysis":"也可能重合。","method":"比较完整方程或一点。","principle":"同斜率只是方向相同。","steps":["y=3x+1与y=3x+2不同平行。","y=3x+1与2y=6x+2重合。"],"ans":"不一定，可能重合。","verification":"相同方向不保证不同集合。","pitfall":"把平行与重合无条件混为一类。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.4","related_sections":[]},{"q":"倾斜角135°的非竖直线斜率？","given":"角从x正向逆时针。","analysis":"钝角tan负。","method":"tan135°。","principle":"m=tanθ。","steps":["135°=180°−45°。","tan=−tan45°=−1。"],"ans":"−1。","verification":"横增1纵降1符合向右下降。","pitfall":"斜率写角度135。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.4","related_sections":[]},{"q":"A(2,0)、B(2,3)、C(2,k)，判断共线条件并说明k=0、3时的问题。","given":"三点横坐标同。","analysis":"竖直共线不需除法斜率。","method":"直接看x=2。","principle":"共同直线方程。","steps":["任意实k均在x=2，故共线。","k=0或3与A或B重合，仍在同线，但不是三个互异点。"],"ans":"任意k在同线；互异另需k≠0,3。","verification":"交叉乘坐标等式两侧均0。","pitfall":"除0后说竖直三点不能讨论共线。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.4","related_sections":[]}],"quiz":{"q":"两线互垂直，其中一条m=0，能把另一条m写成−1/0吗？","given":"一条水平。","analysis":"负倒数公式不覆盖竖直实斜率。","method":"回几何方向。","principle":"水平垂直于竖直。","steps":["另一条为竖直线。","实数斜率无定义，不能写一个实数−1/0。"],"ans":"不能，应说竖直、斜率无定义。","verification":"两线仍正常存在，并非垂直条件失败。","pitfall":"把除零形式当合法数值。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.4","related_sections":[]},"exam":["斜率题先查横差非零，差顺序保持一致","平行题还查是否重合，垂直题先分水平/竖直","参数与共线题可用不除法坐标条件，互异限制另写"],"quick":["横纵差比","倾斜角","水平竖直","平行重合","垂直与参数"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/4-1-linear-functions","page_or_section":"4-1-linear-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/4-1-linear-functions","page_or_section":"4-1-linear-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"斜率题先查横差非零，差顺序保持一致","method":"(1−5)/(3−a)=−2。","principle":"坐标斜率定义。","worked_example_index":2,"verification":"P(1,5)到Q(3,1)横2纵−4，斜率−2。","pitfall":"相减顺序不一致得a=5。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用坐标差与倾斜角解释斜率”的抽样复核：两点横增3纵增6相同比例。；若出现“用8/4忽略起点或只反一个差。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"q","review_module":5,"feedback":"目标“分类处理平行垂直和竖直线”的抽样复核：两线仍正常存在，并非垂直条件失败。；若出现“把除零形式当合法数值。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把除零形式当合法数值。","correction":"不能，应说竖直、斜率无定义。","verification":"两线仍正常存在，并非垂直条件失败。"}],"illustration_spec":{"title":"斜率及例外分类","objects":["A(1,2)到B(4,8)","水平线","竖直线","斜率2/3及−3/2","同斜率重合/平行"],"relations":["Δy=6/Δx=3=2","竖直无定义水平0","有限非零垂直斜率乘积−1"],"labels":["Δx","Δy","m","无定义","平行≠必不同"],"format":"SVG","priority":"P=0","reuse":"暂无对应旧图；同坐标尺度绘制，不用视觉角替数值","english":"Plot a rise of 6 over a run of 3, giving slope 2. Clearly separate horizontal slope zero from undefined vertical slope. Show perpendicular finite slopes 2/3 and -3/2 and distinguish equal-slope parallel lines from coincident lines using labelled equal scales."}},"1.5":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":1,"section_id":"1.5","goals":["按已知条件选择直线表达形式","检查竖直线及截距公式的适用条件"],"prerequisites":["斜率","代数方程与坐标"],"flow":["一般式范围","点斜","两点","截距","等价回代"],"concept_relation":"一般式范围；点斜；两点；截距；等价回代","deep":["斜截式y=mx+b便于读斜率与y截距，适用于非竖直线；这里b既是截距数值，也是交点(0,b)的纵坐标，不要把截距数值与点坐标混为一种表达。","截距式x/a+y/b=1要求两个截距a,b均非零且有限。经过原点、竖直或水平线有时不具这组条件，应换一般式或其他形式，不能为套公式除以0。","由平行或垂直条件求式时，先确定所需方向，再代一点。一般式Ax+By+C=0若B≠0斜率−A/B；B=0时竖直，不能把斜率公式的分母0当成合法实数。形式转换必须保持同一点集。","结果至少回代所有给定点，并核斜率或几何关系。展开、移项、约系数是表达简化，不应改变直线；若两个式子相差非零倍数则等价，若漏常数项则可能变成平行的另一条线。"],"derive":["一般式Ax+By+C=0，(A,B)≠(0,0)。","点斜式y−y₀=m(x−x₀)，竖直例外x=x₀。","两点交叉式适用于不同两点；截距式x/a+y/b=1要求a,b非零有限。"],"examples":[{"q":"求过(2,−1)且斜率3的直线方程。","given":"非竖直方向已给。","analysis":"选点斜式减少未知。","method":"y+1=3(x−2)。","principle":"线上斜率固定。","steps":["展开y+1=3x−6。","得y=3x−7或3x−y−7=0。"],"ans":"y=3x−7。","verification":"代x=2给−1，斜率3。","pitfall":"把点负纵坐标写成y−1。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.5","related_sections":[]},{"q":"求过A(−1,2)、B(3,−6)的直线，并说明是否适合用非零截距式。","given":"两点横差4非0。","analysis":"先斜率再点斜。","method":"m=(−6−2)/(3+1)。","principle":"两点决定一线。","steps":["m=−2，y−2=−2(x+1)。","化简y=−2x，经过原点，不能用a,b非零的截距式。"],"ans":"2x+y=0；不适合该截距式。","verification":"两点分别2(−1)+2=0、6−6=0。","pitfall":"强行把0截距放分母。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.5","related_sections":[]},{"q":"求过(2,3)且垂直于2x−y+4=0的直线。","given":"原线斜率2。","analysis":"所求斜率−1/2。","method":"点斜式。","principle":"有限非零斜率垂直关系。","steps":["y−3=−(x−2)/2。","乘2化简x+2y−8=0。"],"ans":"x+2y−8=0。","verification":"代点2+6−8=0；2×(−1/2)=−1。","pitfall":"把原线斜率误读−2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.5","related_sections":[]}],"practice":[{"q":"过(5,1)和(5,−2)的直线？","given":"两点不同，同x。","analysis":"竖直无斜率。","method":"直接固定x。","principle":"直线点集。","steps":["所有线上点x=5。","方程x=5。"],"ans":"x=5。","verification":"两已知点都满足，纵坐标可任意。","pitfall":"用y=mx+b硬求m。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.5","related_sections":[]},{"q":"x截距4、y截距6的直线方程。","given":"截距均非零有限。","analysis":"截距式适用。","method":"x/4+y/6=1。","principle":"两轴交点决定直线。","steps":["乘12得3x+2y=12。","截距点(4,0)、(0,6)均满足。"],"ans":"3x+2y=12。","verification":"斜率−3/2与截距6一致。","pitfall":"把截距式写4/x+6/y=1。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.5","related_sections":[]},{"q":"x−2y+3=0与2x−4y+6=0是不是不同线？","given":"第二为第一2倍。","analysis":"非零倍数不改解集。","method":"比较系数比例。","principle":"方程整体倍乘等价。","steps":["三个系数均乘2。","两式满足的点相同。"],"ans":"同一直线。","verification":"任一点满足一式就满足另一式。","pitfall":"系数不同就判不同线。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.5","related_sections":[]},{"q":"过(−2,4)且平行y=3的直线，求式并说明为何无需斜率分母。","given":"原线水平。","analysis":"平行方向也水平。","method":"纵坐标恒4。","principle":"水平线方程。","steps":["所求y=4。","可写0x+y−4=0，一般式A0、B1合法。"],"ans":"y=4。","verification":"与y=3不同且平行，包含给定点。","pitfall":"认为A=0就不是直线。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.5","related_sections":[]}],"quiz":{"q":"一般式0x+0y+5=0是否为直线？若常数也0呢？","given":"A=B=0。","analysis":"一般式条件失效。","method":"看实际点集。","principle":"直线需至少一个方向系数非零。","steps":["0=−5无点，不是线。","0=0是整个平面，也不是一条线。"],"ans":"两者都不是直线。","verification":"点集分别空集与R²。","pitfall":"只看写成Ax+By+C就当线。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.5","related_sections":[]},"exam":["求式题按点斜、两点、截距等条件选最短合法形式","横差0直接写竖直，截距0不套分式","答案回代点与方向两核，非零倍乘可视同一线"],"quick":["一般式范围","点斜","两点","截距","等价回代"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.5","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/4-1-linear-functions","page_or_section":"4-1-linear-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.5","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/4-1-linear-functions","page_or_section":"4-1-linear-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"求式题按点斜、两点、截距等条件选最短合法形式","method":"点斜式。","principle":"有限非零斜率垂直关系。","worked_example_index":2,"verification":"代点2+6−8=0；2×(−1/2)=−1。","pitfall":"把原线斜率误读−2。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按已知条件选择直线表达形式”的抽样复核：代x=2给−1，斜率3。；若出现“把点负纵坐标写成y−1。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“检查竖直线及截距公式的适用条件”的抽样复核：两点分别2(−1)+2=0、6−6=0。；若出现“强行把0截距放分母。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"只看写成Ax+By+C就当线。","correction":"两者都不是直线。","verification":"点集分别空集与R²。"}],"illustration_spec":{"title":"直线方程形式与适用条件","objects":["点斜式图","竖直x=5","截距(4,0)(0,6)","过原点线","一般式"],"relations":["竖直不写有限m","截距式要求非零","非零倍数同一线"],"labels":["Ax+By+C=0","(A,B)≠(0,0)","y−y₀=m(x−x₀)","x/a+y/b=1"],"format":"SVG","priority":"P=0","reuse":"暂无对应图；直线与点准确绘制","english":"Compare point-slope, general and intercept forms with accurate coordinate diagrams. Include x=5 as a vertical exception, a line through (4,0),(0,6), and a line through the origin where nonzero-intercept form is invalid. State that A and B cannot both be zero."}},"1.6":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":1,"section_id":"1.6","goals":["以联立方程判交点平行或重合","对参数退化分类并给完整坐标"],"prerequisites":["直线方程","二元一次方程组"],"flow":["联立","唯一解条件","方向退化","完整比例","参数与共点"],"concept_relation":"联立；唯一解条件；方向退化；完整比例；参数与共点","deep":["判断比例时要避免除以可能为零的系数。可用交叉乘条件或直接比较方程倍数；两条竖直线照样能平行或重合，不必为了斜率表达而制造无定义商。","参数方程组在消元后可能出现(k−2)x=c−2等形式。先分k−2是否零，非零时可除求唯一解，为零时检查右侧是否零，再判无解或剩下一条独立方程；不能将0/0当坐标0。","三线共点问题可先求其中两条唯一交点，再代第三线求参数；如果前两条重合或平行，应先处理退化，否则“先求交点”这步可能并不存在或不唯一。","几何图有助说明三种位置，但应由方程证据决定。两条在有限画框看似不交的线可能在远处相交；显示窗口不含交点不能作为平行证明。"],"derive":["D=A₁B₂−A₂B₁；D≠0有唯一交点。","D=0时再查完整系数是否成同一非零比例：是则重合，否则不同平行。","参数消元需先分除数是否0；0=非零无解，0=0需查看剩余独立约束。"],"examples":[{"q":"求x+y=5与2x−y=1的交点。","given":"两直线方向不同。","analysis":"加法可消y。","method":"联立消元。","principle":"交点同时满足两式。","steps":["相加3x=6，x=2。","代首式y=3。"],"ans":"(2,3)。","verification":"2+3=5，4−3=1。","pitfall":"只答x=2或代回漏负号。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.6","related_sections":[]},{"q":"比较x−2y+3=0与2x−4y+1=0的位置。","given":"各自均合法直线。","analysis":"方向系数成2倍，常数不成。","method":"比较完整比例。","principle":"D0再判重合。","steps":["第二方向是第一2倍，但2×3=6≠1。","两线平行不同，无交点。"],"ans":"不同平行线。","verification":"若第一乘2再相减得5=0，矛盾。","pitfall":"只看D0就说重合。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.6","related_sections":[]},{"q":"讨论x+y=1与kx+2y=c的交点，k,c为实数。","given":"两式各为合法线，第二B2非0。","analysis":"分参数除数。","method":"第二减首式2倍。","principle":"消元与退化分类。","steps":["得(k−2)x=c−2。","k≠2时x=(c−2)/(k−2)，y=(k−c)/(k−2)。","k=2且c=2时重合；k=2且c≠2时平行不同。"],"ans":"唯一解、重合、平行三类如上。","verification":"k=3,c=4给x=2,y−1，两式均满足；k=2,c=2第二正是2倍。","pitfall":"直接除k−2忽略k=2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.6","related_sections":[]}],"practice":[{"q":"x=3与y=−2的交点？","given":"竖直与水平。","analysis":"各固定一个坐标。","method":"组合条件。","principle":"联立定义。","steps":["x=3且y−2。","交点(3,−2)。"],"ans":"(3,−2)。","verification":"两式直接回代。","pitfall":"因竖直无斜率就说不能求交点。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.6","related_sections":[]},{"q":"x+y=1与2x+2y=2有几个交点？","given":"第二整体为第一2倍。","analysis":"同一线。","method":"判重合。","principle":"独立方程只有一条。","steps":["无限多个公共点。","可写(x,1−x)，x任意实数。"],"ans":"无穷多个。","verification":"每个首式解都满足第二式。","pitfall":"消元0=0后给唯一(0,0)。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.6","related_sections":[]},{"q":"x+y=1、x+y=3相交吗？","given":"方向相同常数不同。","analysis":"同左边不能同时等不同值。","method":"两式相减。","principle":"联立矛盾。","steps":["相减0=2。","无共同点，平行不同。"],"ans":"不相交。","verification":"任意点只能在其中一条相应线。","pitfall":"把两个y截距平均当交点。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.6","related_sections":[]},{"q":"线x+y=4、x−y=2及tx+y=5三线共点，求t。","given":"前两线唯一交点。","analysis":"先求点再代第三。","method":"两式相加。","principle":"共点需同时满足。","steps":["2x=6，x=3，y=1。","3t+1=5，t=4/3。"],"ans":"t=4/3，共点(3,1)。","verification":"(4/3)3+1=5。","pitfall":"只比较斜率而不代公共点。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.6","related_sections":[]}],"quiz":{"q":"D=0就必定“没有交点”吗？需要什么补充判断？","given":"一般合法两直线。","analysis":"D只判方向退化。","method":"比较完整系数。","principle":"重合时有无限公共点。","steps":["若全系数成同比例，重合。","否则不同平行无交点。"],"ans":"不必；还可能重合。","verification":"x+y=1与2x+2y2提供反例。","pitfall":"把无唯一解当无任何解。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.6","related_sections":[]},"exam":["交点题消元后写完整坐标并代两式","D0或参数除数0必须另分类，完整系数决定平行/重合","三线题先核前两线交点存在唯一，再代第三"],"quick":["联立","唯一解条件","方向退化","完整比例","参数与共点"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.6","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/11-1-systems-of-linear-equations-two-variables","page_or_section":"11-1-systems-of-linear-equations-two-variables","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.6","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/11-1-systems-of-linear-equations-two-variables","page_or_section":"11-1-systems-of-linear-equations-two-variables","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"交点题消元后写完整坐标并代两式","method":"第二减首式2倍。","principle":"消元与退化分类。","worked_example_index":2,"verification":"k=3,c=4给x=2,y−1，两式均满足；k=2,c=2第二正是2倍。","pitfall":"直接除k−2忽略k=2。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“以联立方程判交点平行或重合”的抽样复核：2+3=5，4−3=1。；若出现“只答x=2或代回漏负号。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“对参数退化分类并给完整坐标”的抽样复核：k=3,c=4给x=2,y−1，两式均满足；k=2,c=2第二正是2倍。；若出现“直接除k−2忽略k=2。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把无唯一解当无任何解。","correction":"不必；还可能重合。","verification":"x+y=1与2x+2y2提供反例。"}],"illustration_spec":{"title":"两直线三种位置与参数","objects":["相交(2,3)","不同平行","重合线","参数消元分支"],"relations":["D非零唯一","D0后查常数比例","k=2,c=2重合而c≠2平行"],"labels":["D=A₁B₂−A₂B₁","唯一交点","无交点","无限公共点","先分除数0"],"format":"SVG","priority":"P=0","reuse":"暂无对应旧图；不同位置须与所示方程一致","english":"Draw three accurately labelled cases: intersecting lines at (2,3), distinct parallel lines and coincident lines. Explain D=A1B2-A2B1, then separately classify the D=0 cases. Include parameter equation (k-2)x=c-2 without dividing before handling k=2."}},"1.7":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":1,"section_id":"1.7","goals":["推导并使用垂直距离和垂足公式","统一直线系数后求平行线距离并核绝对值"],"prerequisites":["距离公式","垂直与一般式直线"],"flow":["垂线定义","法向方向","投影推导","绝对值归一","平行与参数"],"concept_relation":"垂线定义；法向方向；投影推导；绝对值归一；平行与参数","deep":["分子绝对值保证距离非负，分母归一化消除方程整体倍数影响。把整条方程乘非零λ，分子分母都乘|λ|，距离不变；若只取分子值不除法向长度，则不同等价方程会算出不同“距离”。","平行线距离可以选一线上任一点到另一线，或先统一A,B写为Ax+By+C₁=0和Ax+By+C₂=0，再用|C₂−C₁|/√(A²+B²)。未经统一就直接相减常数会错，尤其第二线方程是第一方向系数的倍数时。","距离条件求参数常因绝对值有两个分支，对应直线或点在两侧。题给位置或半平面条件才可进一步筛；正距离不意味着Ax₀+By₀+C必须正，符号表达的是相对法向的侧别。","验算距离可核垂足在直线上、PH与线垂直以及PH长度；水平竖直可用简单坐标差复核。公式看似一行，适用条件、系数归一和绝对值是准确使用的核心。"],"derive":["d(P,l)=|Ax₀+By₀+C|/√(A²+B²)，(A,B)≠(0,0)。","t=(Ax₀+By₀+C)/(A²+B²)，H=(x₀−tA,y₀−tB)。","平行线先统一A,B后，d=|C₂−C₁|/√(A²+B²)。"],"examples":[{"q":"求原点到3x+4y−10=0的距离。","given":"A3、B4、C−10。","analysis":"分子有符号但距离取绝对。","method":"点线距离公式。","principle":"垂直距离归一化。","steps":["分子|−10|=10，分母√(9+16)=5。","d=2。"],"ans":"2个长度单位。","verification":"线上最近点为(6/5,8/5)，长度√(36+64)/5=2。","pitfall":"给−2或不除5答10。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.7","related_sections":[]},{"q":"P(3,4)到3x+4y−5=0的距离与垂足。","given":"非零法向。","analysis":"先算L(P)与t。","method":"t=L/(A²+B²)。","principle":"法向投影到线。","steps":["L=9+16−5=20，t=20/25=.8。","H=(3−2.4,4−3.2)=(.6,.8)，d=20/5=4。"],"ans":"d4，H(3/5,4/5)。","verification":"H在线：1.8+3.2−5=0；PH分量(2.4,3.2)长4且沿法向3:4。","pitfall":"把t直接当距离或垂足加错方向。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.7","related_sections":[]},{"q":"求3x+4y−5=0与6x+8y+10=0的距离。","given":"方向系数成倍，先统一。","analysis":"常数不能未经归一直接相减。","method":"第二式除2。","principle":"平行线距离公式条件。","steps":["第二变3x+4y+5=0。","d=|5−(−5)|/5=2。"],"ans":"2。","verification":"首线取(3,−1)：9−4−5=0；代统一第二得10，除5为2。","pitfall":"用10−(−5)除5得3。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.7","related_sections":[]}],"practice":[{"q":"P(2,−3)到水平线y=1距离？","given":"一般式y−1=0。","analysis":"可坐标差直接核。","method":"|−3−1|。","principle":"垂直方向为竖直。","steps":["d=4。","公式A0、B1给同值。"],"ans":"4。","verification":"垂足(2,1)。","pitfall":"把横差也加入。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.7","related_sections":[]},{"q":"P(−1,5)到竖直线x=3距离？","given":"一般式x−3=0。","analysis":"垂线水平。","method":"|−1−3|。","principle":"距离定义。","steps":["d=4。","垂足(3,5)。"],"ans":"4。","verification":"公式A1、B0亦4。","pitfall":"竖直无斜率就说距离公式不可用。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.7","related_sections":[]},{"q":"点(1,2)到2x−y+c=0距离3，求c。","given":"方向系数非零，c实数。","analysis":"绝对值给两侧。","method":"|2−2+c|/√5=3。","principle":"点线距离公式。","steps":["|c|=3√5。","c=±3√5。"],"ans":"c=−3√5或3√5。","verification":"两式分子绝对值均3√5，分母√5。","pitfall":"只取正c。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.7","related_sections":[]},{"q":"同一直线x−2y+4=0和−3x+6y−12=0，用P(0,0)算距离应一致吗？独立求。","given":"后式为前式−3倍。","analysis":"分母也随系数放大。","method":"分别代入公式。","principle":"非零整体倍乘不改变直线。","steps":["前式4/√5。","后式12/√45=12/(3√5)=4/√5。"],"ans":"一致，4/√5。","verification":"若忘分母归一就会误得4和12。","pitfall":"方程倍乘后距离也倍乘。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.7","related_sections":[]}],"quiz":{"q":"点到直线距离为0能否说点在直线上？是否需要再判断法向系数？","given":"先假定A,B不同时0。","analysis":"分母正，因此零来自分子。","method":"令Ax₀+By₀+C=0。","principle":"点在线的方程定义。","steps":["d0等价分子0。","即P满足线方程，在线上；若A=B0原本不是合法直线不能套。"],"ans":"合法直线条件下可以。","verification":"点线距离与代入判点一致。","pitfall":"把一般式非法情境也套公式。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":1,"primary_section":"1.7","related_sections":[]},"exam":["距离题先规范一般式，绝对值分子与法向长度都保留","平行线题先统一方向系数再相减常数","垂足题核在线、垂直和长度三条件，参数题保留双侧分支"],"quick":["垂线定义","法向方向","投影推导","绝对值归一","平行与参数"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.7","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/2-1-the-rectangular-coordinate-systems-and-graphs","page_or_section":"2-1-the-rectangular-coordinate-systems-and-graphs","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_1.7","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/2-1-the-rectangular-coordinate-systems-and-graphs","page_or_section":"2-1-the-rectangular-coordinate-systems-and-graphs","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"距离题先规范一般式，绝对值分子与法向长度都保留","method":"第二式除2。","principle":"平行线距离公式条件。","worked_example_index":2,"verification":"首线取(3,−1)：9−4−5=0；代统一第二得10，除5为2。","pitfall":"用10−(−5)除5得3。"},"diagnostics":[{"goal_index":0,"question_ref":"e1","review_module":4,"feedback":"目标“推导并使用垂直距离和垂足公式”的抽样复核：H在线：1.8+3.2−5=0；PH分量(2.4,3.2)长4且沿法向3:4。；若出现“把t直接当距离或垂足加错方向。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“统一直线系数后求平行线距离并核绝对值”的抽样复核：首线取(3,−1)：9−4−5=0；代统一第二得10，除5为2。；若出现“用10−(−5)除5得3。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把一般式非法情境也套公式。","correction":"合法直线条件下可以。","verification":"点线距离与代入判点一致。"}],"illustration_spec":{"title":"点线距离与垂足","objects":["P(3,4)","直线3x+4y−5=0","H(3/5,4/5)","垂线PH","平行线统一系数"],"relations":["PH沿法向3:4","H在线","PH长4","系数倍乘不改变距离"],"labels":["d=4","垂足H","直角标","|Ax₀+By₀+C|","√(A²+B²)"],"format":"SVG","priority":"P=0","reuse":"暂无对应图；垂足和直角必须精确定位","english":"Plot P(3,4), line 3x+4y-5=0 and foot H(3/5,4/5) on equal scales. Draw PH perpendicular to the line with length 4 and normal direction ratio 3:4. Show that parallel-line constant differences require matching A and B first."}}},"数学2":{"2.1":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":2,"section_id":"2.1","goals":["由配方推导判别式与实根数","对参数先检次数再分类并回代"],"prerequisites":["配方法","实数平方与根式"],"flow":["二次条件","配方","判别式","根公式","参数退化"],"concept_relation":"二次条件；配方；判别式；根公式；参数退化","deep":["求根公式x=(−b±√Δ)/(2a)由配方得到，分母是整个2a，负号属于b的代数值。若b本来为负，−b应变正；两个分支都须保留，最后根据题目原域筛选。","判别式只判根的实性与重合，不单独告诉根正负、是否为整数或是否落某区间。Δ是完全平方数时在整数系数等条件下可支持有理根判断，但“Δ>0所以两正根”明显不足。","参数题先列a≠0，再把Δ作为参数不等式求解。若题求不同实根数，还要把退化一次方程贡献的根数单列合并；不能把判别式表达式在a=0的值直接套二次分类。","验证可回代根、检查和积与几何交点。近零判别式的数值题须关注给定精度，课堂精确参数题与实验近似系数的结论强度不同。本节例题用精确数据，不暗示官方评分步骤或考频。"],"derive":["a≠0时，配方得(2ax+b)²=Δ=b²−4ac。","Δ>0：两不同实根；Δ=0：二重实根；Δ<0：无实根。","x=(−b±√Δ)/(2a)；参数a=0需回原式另解。"],"examples":[{"q":"判断2x²−3x−2=0实根数并求根。","given":"a=2、b=−3、c=−2。","analysis":"先判Δ再保留±。","method":"Δ=b²−4ac，套公式。","principle":"配方推导的二次根式。","steps":["Δ=9+16=25>0。","x=(3±5)/4，得2、−1/2。"],"ans":"两个不同实根2与−1/2。","verification":"代2得8−6−2=0；代−1/2得.5+1.5−2=0。","pitfall":"把−b写−3或漏分母2a。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"x²−4x+k=0有实根时k范围？重根时何值？","given":"二次系数恒1。","analysis":"有实根包含重根。","method":"Δ=16−4k≥0。","principle":"实平方条件。","steps":["得k≤4。","Δ=0时k=4，方程(x−2)²=0。"],"ans":"有实根k≤4；重根k=4。","verification":"k=4根2，k=5可写(x−2)²+1=0无实根。","pitfall":"将有实根仅写Δ>0而漏等号。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"讨论tx²+2x+1=0的不同实根数。","given":"t为实数，可能退为一次。","analysis":"先分t=0。","method":"t≠0用Δ=4−4t，t=0直接解。","principle":"二次定义与判别式条件。","steps":["t=0时2x+1=0，一个根−1/2。","t≠0且t<1时Δ>0，两不同实根。","t=1时(x+1)²=0，一个不同根；t>1无实根。"],"ans":"两根：t<1且t≠0；一个：t=0或1；无根：t>1。","verification":"t=0不能放进两根范围，原式确为一次。","pitfall":"只按Δ>0把t=0也算两根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.1","related_sections":[]}],"practice":[{"q":"3x²+2x+1=0在实数有解吗？","given":"a=3非0。","analysis":"判Δ。","method":"4−12。","principle":"Δ非负才有实根。","steps":["Δ=−8。","故无实根。"],"ans":"无实根。","verification":"配方3(x+1/3)²+2/3>0。","pitfall":"写无任何数域解而未限定。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"x²+6x+9=0的不同实根数及重数？","given":"Δ=0。","analysis":"两个相等根对应一个不同值。","method":"完全平方。","principle":"(x+3)²=0。","steps":["x=−3。","不同实根1，重数2。"],"ans":"一个不同实根−3，二重。","verification":"Δ=36−36=0。","pitfall":"把两相等根当两个不同解。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"Δ>0能推出两根都正吗？举具体反例。","given":"只给实性条件。","analysis":"正负还取决和积。","method":"取x²−1=0。","principle":"判别式不单独判正负。","steps":["Δ=4>0。","根1、−1异号。"],"ans":"不能。","verification":"直接平方等1得到两符号。","pitfall":"从两实根跳到两正根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"求m使(m−1)x²+2x+1=0恰有一个不同实根。","given":"可能二次重根或一次。","analysis":"分类两种来源。","method":"m=1先解；m≠1令Δ=0。","principle":"退化与判别式。","steps":["m=1时一次根−1/2。","m≠1时Δ=4−4(m−1)=8−4m，等0得m=2，根−1。"],"ans":"m=1或2。","verification":"m=2方程(x+1)²=0；两情境均一根。","pitfall":"只答m=2而漏退化。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.1","related_sections":[]}],"quiz":{"q":"方程写作0x²+0x+0=0，可用Δ=0称有一个二重根吗？","given":"最高系数与其他系数均0。","analysis":"不是二次方程。","method":"回到原等式。","principle":"二次判别式要求a≠0。","steps":["原式0=0对所有实数成立。","不存在一个二次定义下的独有重根。"],"ans":"不可以，解集R。","verification":"任何实数代入都0=0。","pitfall":"看见形式x²就无视系数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.1","related_sections":[]},"exam":["参数判根题先审a是否0，再解Δ条件","求根题写带符号系数与整个2a分母，最后代回","根数描述注明不同实根或重数，实性与正负分开"],"quick":["二次条件","配方","判别式","根公式","参数退化"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_2.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/2-5-quadratic-equations","page_or_section":"2-5-quadratic-equations","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_2.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/2-5-quadratic-equations","page_or_section":"2-5-quadratic-equations","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"参数判根题先审a是否0，再解Δ条件","method":"t≠0用Δ=4−4t，t=0直接解。","principle":"二次定义与判别式条件。","worked_example_index":2,"verification":"t=0不能放进两根范围，原式确为一次。","pitfall":"只按Δ>0把t=0也算两根。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由配方推导判别式与实根数”的抽样复核：代2得8−6−2=0；代−1/2得.5+1.5−2=0。；若出现“把−b写−3或漏分母2a。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“对参数先检次数再分类并回代”的抽样复核：t=0不能放进两根范围，原式确为一次。；若出现“只按Δ>0把t=0也算两根。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"看见形式x²就无视系数。","correction":"不可以，解集R。","verification":"任何实数代入都0=0。"}],"illustration_spec":{"title":"判别式从配方到根数","objects":["(2ax+b)²=Δ","三种Δ情境","参数a=0分支","抛物线与x轴"],"relations":["a≠0才用二次分类","Δ=0仅一个不同值","退化回原式"],"labels":["Δ=b²−4ac","两不同实根","二重实根","无实根","先查a=0"],"format":"SVG","priority":"P=0","reuse":"暂无对应图；三类曲线坐标必须准确","english":"Derive (2ax+b)^2=Delta and show the three real-root cases for a nonzero quadratic coefficient. Include a separate a=0 degeneration branch, distinguish a double root from two distinct roots, and do not infer root signs from Delta alone."}},"2.2":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":2,"section_id":"2.2","goals":["由因式展开推导根的和积","用对称式和实根条件处理新根与参数"],"prerequisites":["因式定理","二次判别式"],"flow":["因式系数比较","S与P","对称式","新根方程","实性正负约束"],"concept_relation":"因式系数比较；S与P；对称式；新根方程；实性正负约束","deep":["构造新根方程时先求新根和积，再写首一方程y²−S新y+P新=0。例如两根各加1，新和为S+2，新积为P+S+1；若取倒数，原根必须均非零。","判正负实根还需实性。两正实根（允许重合）可用Δ≥0、S>0、P>0；两负相应S<0，P>0；异号需P<0并在实系数二次条件下保证实根。若要求两不同根则Δ严格大于0。","参数不等式必须联合求交集，不能分别解后取并集。边界P=0意味着有零根，不属于严格正或负；Δ=0是否允许取决“不同”还是“可相等”的题意。","验算可用显式根、回乘新方程或简单参数点。韦达给必要关系，但若题目限定实根范围，必须把判别式和范围约束一起落实，不要把代数和积当作自动存在两实根的保证。"],"derive":["S=α+β=−b/a，P=αβ=c/a（a≠0）。","α²+β²=S²−2P；αβ≠0时1/α+1/β=S/P。","新根α+1、β+1：S新=S+2，P新=P+S+1；方程y²−S新y+P新=0。"],"examples":[{"q":"2x²−5x+2=0两根α,β，不先求根，求S、P及α²+β²。","given":"a=2、b=−5、c=2。","analysis":"表达式对称可由和积。","method":"韦达及平方展开。","principle":"比较a(x−α)(x−β)系数。","steps":["S=5/2，P=1。","平方和S²−2P=25/4−2=17/4。"],"ans":"S=5/2、P=1、平方和17/4。","verification":"实际根2、1/2，平方4+1/4=17/4。","pitfall":"根和漏负号或平方和忘−2P。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"原方程x²−3x+1=0两根各加1，求新根的首一方程。","given":"无需显式根。","analysis":"新和积由原S=3、P=1。","method":"S新=S+2，P新=P+S+1。","principle":"由新根因式展开。","steps":["S新5，P新1+3+1=5。","新方程y²−5y+5=0。"],"ans":"y²−5y+5=0。","verification":"把原变量写y−1，(y−1)²−3(y−1)+1同得新式。","pitfall":"积只加1漏S项。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"x²−(k+1)x+k=0何时有两个不同正实根？","given":"k实数，要求严格正且不同。","analysis":"可直接因式看根，也可和积判。","method":"(x−1)(x−k)=0。","principle":"根和积与判别式。","steps":["两根1与k，正需k>0。","不同需k≠1；Δ=(k−1)²，条件一致。"],"ans":"k>0且k≠1。","verification":"k=0有零根，k=1重根，均排除。","pitfall":"只写S>0、P>0而未排除重合。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.2","related_sections":[]}],"practice":[{"q":"3x²+6x−2=0两根和积？","given":"a=3非0。","analysis":"带符号取系数。","method":"S=−b/a、P=c/a。","principle":"韦达。","steps":["S=−6/3=−2。","P=−2/3。"],"ans":"−2与−2/3。","verification":"P负表示实根异号，与Δ=36+24>0相容。","pitfall":"积也加负号写+2/3。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"根和4、根积3，首一方程及根？","given":"两根按重数。","analysis":"由和积构造。","method":"x²−4x+3。","principle":"(x−α)(x−β)展开。","steps":["方程(x−1)(x−3)=0。","根1、3。"],"ans":"x²−4x+3=0，根1和3。","verification":"和4、积3。","pitfall":"方程中间项写+4x。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"α+β=3、αβ=2，求倒数和，若积为0还能用吗？","given":"先给非零积2。","analysis":"分式需非零根。","method":"S/P。","principle":"通分。","steps":["倒数和3/2。","若P=0则至少一个根0，倒数无定义，不能代公式除0。"],"ans":"3/2；P=0不可用。","verification":"根1、2倒数和1+.5=1.5。","pitfall":"公式化简后忘非零条件。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"x²+2x+k=0有两个负实根且允许相等，求k。","given":"a=1恒定。","analysis":"实性与负号联合。","method":"S=−2<0，P=k>0，Δ=4−4k≥0。","principle":"和积与判别式。","steps":["k>0且k≤1。","交集0<k≤1。"],"ans":"(0,1]。","verification":"k=1为−1重根允许，k=0含0不负。","pitfall":"取并集或漏Δ上界。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.2","related_sections":[]}],"quiz":{"q":"方程x²+2x+5=0的根和−2、积5，能据此说两根都是负实数吗？","given":"实系数，未核Δ。","analysis":"同号和负还不保证实根存在。","method":"计算判别式。","principle":"实根条件独立。","steps":["Δ=4−20=−16。","无实根，所以不能谈两个负实根。"],"ans":"不能，缺实性且实际无实根。","verification":"配方(x+1)²+4>0。","pitfall":"仅用S<0、P>0省去Δ。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.2","related_sections":[]},"exam":["韦达题从S和P组织对称式，分母含根需先排零","新根题先求新和积，再构造并以代换复核","参数根号题把Δ、S、P及不同性全部取交集"],"quick":["因式系数比较","S与P","对称式","新根方程","实性正负约束"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_2.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/2-5-quadratic-equations","page_or_section":"2-5-quadratic-equations","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_2.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/2-5-quadratic-equations","page_or_section":"2-5-quadratic-equations","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"韦达题从S和P组织对称式，分母含根需先排零","method":"(x−1)(x−k)=0。","principle":"根和积与判别式。","worked_example_index":2,"verification":"k=0有零根，k=1重根，均排除。","pitfall":"只写S>0、P>0而未排除重合。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由因式展开推导根的和积”的抽样复核：实际根2、1/2，平方4+1/4=17/4。；若出现“根和漏负号或平方和忘−2P。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用对称式和实根条件处理新根与参数”的抽样复核：k=0有零根，k=1重根，均排除。；若出现“只写S>0、P>0而未排除重合。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"仅用S<0、P>0省去Δ。","correction":"不能，缺实性且实际无实根。","verification":"配方(x+1)²+4>0。"}],"illustration_spec":{"title":"韦达关系与新根","objects":["a(x−α)(x−β)展开","S/P框","平方和","新根平移","参数交集"],"relations":["S=−b/a","P=c/a","S新=S+2","P新=P+S+1","正实根还需Δ条件"],"labels":["a≠0","S","P","倒数需P≠0","条件取交集"],"format":"SVG","priority":"P=1","reuse":"暂无对应旧图；代数关系图确定性排版","english":"Derive the root sum -b/a and product c/a by expansion. Show symmetric expressions, the nonzero-product requirement for reciprocal roots, and shifted-root sums/products S+2 and P+S+1. Keep discriminant and sign conditions as a joint intersection."}},"2.3":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":2,"section_id":"2.3","goals":["配方确定顶点开口与值域","在给定区间和参数条件下求真正最值"],"prerequisites":["函数图象","平方与区间"],"flow":["配方","顶点轴开口","截距","受限区间","参数最近点"],"concept_relation":"配方；顶点轴开口；截距；受限区间；参数最近点","deep":["在受限区间求最值，不能只报顶点值。先看顶点是否在区间内，再比合法端点；若区间开端点对应最佳值未被取到，可能只有上界或下界而无最大/最小值。","利用对称轴可判断区间内距顶点最远和最近的位置，避免机械求导。a>0时最小对应最近，最大对应最远；a<0时反向。这个距离思想也便于参数顶点随位置移动的分类。","参数题若顶点h随参数变化，应按它落在区间左边、内部或右边分类。每段最值表达式的边界要检查一致性，并说明在哪个x处取得；单独列公式却不写区间容易漏掉情境。","画图和计算相互验证：顶点、截距、对称点和区间端点应能全部落在同一图上。最值是具体输出且必须可取到；把向无穷的趋势叫最大值无穷是不严谨的。"],"derive":["f=a(x+b/(2a))²−Δ/(4a)，a≠0；顶点(−b/(2a),−Δ/(4a))。","闭区间最值候选为合法端点及区间内顶点；开端点不能作为已取到点。","f=(x−t)²在[0,2]的最小值由t到该区间的最近距离平方得到。"],"examples":[{"q":"f=2x²−8x+5，求顶点、轴和全实数域最值。","given":"a=2>0。","analysis":"配方结构最直接。","method":"2(x−2)²−3。","principle":"平方非负。","steps":["顶点(2,−3)，轴x=2。","最小值−3在x=2，无最大值，值域[−3,+∞)。"],"ans":"顶点(2,−3)，最小−3。","verification":"代x=2得8−16+5=−3。","pitfall":"把顶点x坐标2当最小值。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"f=−x²+4x+1，域[0,5]，求最大和最小。","given":"闭区间，开口向下。","analysis":"顶点在域内，最小需比端点。","method":"f=−(x−2)²+5。","principle":"候选顶点与合法端点。","steps":["顶点x=2得最大5。","f(0)=1，f(5)=−4，最小−4在5。"],"ans":"最大5、最小−4。","verification":"距顶点3的x=5给更低输出，符合开口向下。","pitfall":"只报最大而误以无最小，忘受限域。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"f=(x−t)²，x∈[0,2]，按t求最小值并给取得位置。","given":"t实数。","analysis":"看顶点在区间何处。","method":"用最近点。","principle":"平方距离最小。","steps":["t<0时最近x=0，最小t²。","0≤t≤2时x=t，最小0。","t>2时最近x=2，最小(t−2)²。"],"ans":"三段如上。","verification":"t=0或2边界两表达式均0，连续衔接。","pitfall":"不论顶点是否在域都答最小0。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.3","related_sections":[]}],"practice":[{"q":"y=(x+3)²−4的顶点和开口？","given":"系数a=1。","analysis":"读x−h形式。","method":"h=−3、k=−4。","principle":"顶点式。","steps":["顶点(−3,−4)。","开口向上，对称轴x=−3。"],"ans":"(−3,−4)，向上。","verification":"x=−3平方项0。","pitfall":"把+3读成顶点x=3。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"f=x²，域(0,1)，有最大或最小值吗？","given":"两端均开。","analysis":"最佳边界均未取。","method":"由0<x²<1。","principle":"最值须取得。","steps":["值域(0,1)。","无最小无最大，下界0上界1。"],"ans":"都没有。","verification":"任意x可选更靠0或1的输入改善输出。","pitfall":"闭区间习惯直接报0与1。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"a<0、Δ>0时，顶点纵坐标−Δ/(4a)正还是负？","given":"a负Δ正。","analysis":"符号需同时看分母。","method":"负除负。","principle":"顶点公式。","steps":["−Δ负、4a负。","商为正。"],"ans":"正。","verification":"开口向下且穿x轴两点，顶点在上方。","pitfall":"把Δ正统一说顶点负。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"f=x²−6x+8，域[0,2]，求最小值并说明为什么不用全域顶点。","given":"顶点x=3在区间外。","analysis":"受限域最近点为右端。","method":"f=(x−3)²−1。","principle":"平方距离随靠近3减小。","steps":["区间[0,2]距3最近x=2。","f(2)=0为最小，最大f(0)=8。"],"ans":"最小0在x=2。","verification":"顶点值−1无法在该域取到。","pitfall":"直接答−1。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.3","related_sections":[]}],"quiz":{"q":"若图象纵横比例尺不同，还能用曲线看起来更窄来直接断言a绝对值更大吗？","given":"比较图的比例尺可能不同。","analysis":"画面形状受尺度影响。","method":"统一坐标再比较相同Δx对应Δy。","principle":"二次项系数关系依数值坐标。","steps":["缩放纵轴可让同一函数看似更窄。","应由标尺和点计算a，或统一比例再比较。"],"ans":"不能直接断言。","verification":"同一公式可因截图变形呈不同宽窄。","pitfall":"把视觉尺度当系数事实。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.3","related_sections":[]},"exam":["最值题先配方并核顶点是否在域，闭端点一起比较","参数题按顶点位置分段，写取得点并核边界","图象题标同一尺度，最值须可达，别把上界下界当取得值"],"quick":["配方","顶点轴开口","截距","受限区间","参数最近点"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_2.3","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-1-quadratic-functions","page_or_section":"5-1-quadratic-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_2.3","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-1-quadratic-functions","page_or_section":"5-1-quadratic-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"最值题先配方并核顶点是否在域，闭端点一起比较","method":"用最近点。","principle":"平方距离最小。","worked_example_index":2,"verification":"t=0或2边界两表达式均0，连续衔接。","pitfall":"不论顶点是否在域都答最小0。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“配方确定顶点开口与值域”的抽样复核：代x=2得8−16+5=−3。；若出现“把顶点x坐标2当最小值。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“在给定区间和参数条件下求真正最值”的抽样复核：t=0或2边界两表达式均0，连续衔接。；若出现“不论顶点是否在域都答最小0。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把视觉尺度当系数事实。","correction":"不能直接断言。","verification":"同一公式可因截图变形呈不同宽窄。"}],"illustration_spec":{"title":"抛物线顶点与区间最值","objects":["2(x−2)²−3图","受限区间","顶点区间外示例","参数t位置三段"],"relations":["顶点(2,−3)","闭区间比端点顶点","x²在(0,1)无取得最值"],"labels":["x","y","顶点","合法端点","最近点","空心/实心"],"format":"SVG","priority":"P=0","reuse":"暂无对应图；曲线与端点必须数值绘制","english":"Plot 2(x-2)^2-3 with vertex (2,-3) and equal labelled scales. Contrast unrestricted and restricted-domain extrema, including a vertex outside the interval and open endpoints. Show the closest-point cases for (x-t)^2 on [0,2]."}},"2.4":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":2,"section_id":"2.4","goals":["把交点问题转为二次方程并回到坐标","用判别式讨论割线切线与参数范围"],"prerequisites":["二次函数","直线方程与判别式"],"flow":["联立差式","交点判别式","坐标回代","切线重根","参数边界与例外"],"concept_relation":"联立差式；交点判别式；坐标回代；切线重根；参数边界与例外","deep":["切点求出后可把差式写成a(x−r)²来复核交点重合。一个参数可通过Δ=0求，多个切线参数可能都合法，需逐个求切点与回代；不应只因图中草图画了一条就丢掉另一解。","若求直线在整条抛物线上方或下方，应讨论差值函数对所有x的符号，同时看二次项开口与Δ。相切意味着某点等号，不等于处处严格上/下；限定区间的上下关系又需区间最值条件，不能无条件用全域Δ。","参数改变可使交点由无到一到二，边界通常是Δ=0。写范围时标明“至少一个”“两个不同”“不相交”等词对应的严格或非严格不等式，避免边界切点被漏掉。","验算同时检查每个候选满足两条原方程，坐标和代数根的重数一致。画图用关键点与实际尺度展示相对位置，示意图不按比例时不得凭视觉给交点或切线数值。"],"derive":["交点横坐标满足ax²+(b−m)x+(c−n)=0，a≠0。","非竖直线：Δ交=(b−m)²−4a(c−n)；正为两交点、零为相切、负为不交。","求完整交点需y=mx+n；竖直x=d的单交点不套上述切线判据。"],"examples":[{"q":"求y=x²与y=3x−2的交点。","given":"非竖直线。","analysis":"先横坐标根再求y。","method":"x²=3x−2。","principle":"同一点的两个y表达相等。","steps":["x²−3x+2=(x−1)(x−2)=0，x=1、2。","代直线得y=1、4。"],"ans":"(1,1)、(2,4)。","verification":"两点平方分别1、4，与直线同。","pitfall":"只报x=1、2当坐标。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"讨论y=x²与y=2x+k随k的交点数及相切位置。","given":"k实数。","analysis":"差式判Δ并核边界。","method":"x²−2x−k=0。","principle":"交点判别式。","steps":["Δ=4+4k。","k>−1两交点，k=−1一切点，k<−1无交点。","k=−1时(x−1)²=0，切点(1,1)。"],"ans":"三段如上，相切k=−1。","verification":"等价(x−1)²=k+1，直接解释实解数。","pitfall":"用原x²=0的Δ=0说任何直线都相切。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"求直线y=mx+1与y=x²−4x+5相切时的m及切点。","given":"非竖直线族，参数m。","analysis":"切线可有两条。","method":"差式x²−(m+4)x+4=0，令Δ=0。","principle":"重交点条件。","steps":["(m+4)²−16=0，m=0或−8。","m=0时x=2、y=1；m=−8时x−2、y=17。"],"ans":"m=0切点(2,1)；m−8切点(−2,17)。","verification":"差式分别(x−2)²、(x+2)²；两点代原图均成立。","pitfall":"开平方只取m+4=4而漏−4。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.4","related_sections":[]}],"practice":[{"q":"y=x²与y=−1有交点吗？","given":"实数范围。","analysis":"平方不为负。","method":"x²=−1或Δ。","principle":"交点实性。","steps":["无实x满足。","故无实交点。"],"ans":"没有。","verification":"抛物线全在y≥0。","pitfall":"为求交点强写±1。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"竖直线x=2与y=x²仅有一点，能据此称其为前述Δ=0切线吗？","given":"竖直线不写y=mx+n。","analysis":"单交点原因不同。","method":"代固定x并限定判据。","principle":"二次差式判据针对非竖直线。","steps":["交点(2,4)。","不能仅凭一个交点说相切，不能给无限斜率机械代Δ。"],"ans":"不能这样判断。","verification":"每条竖直线对函数都单值相交。","pitfall":"把任何一交点直线都叫切线。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"y=x²与y=c至少有一个实交点，c范围？","given":"水平非竖直线。","analysis":"至少一含相切。","method":"x²=c。","principle":"实平方非负。","steps":["c≥0有解。","c=0一个重交点，c>0两个不同。"],"ans":"c≥0。","verification":"c负无平方等它。","pitfall":"只写c>0漏切线边界。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"y=x²−2x+3与水平y=k不相交时k范围？并给相切边界。","given":"抛物线最小值2。","analysis":"低于顶点才不交。","method":"差式x²−2x+3−k=0。","principle":"Δ=4−4(3−k)=4k−8。","steps":["不交Δ<0得k<2。","k=2相切(1,2)。"],"ans":"k<2不交，k=2相切。","verification":"配方(x−1)²+2与水平线比较同结论。","pitfall":"把不交写k≤2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.4","related_sections":[]}],"quiz":{"q":"用抛物线与x轴的根判别式，能直接判断它与任意斜线的交点数吗？","given":"斜线y=mx+n改变联立差式系数。","analysis":"比较对象不同。","method":"重新令函数值相等。","principle":"交点根来自差函数。","steps":["应使用b−m、c−n。","原Δ只对应m=n=0的x轴特例。"],"ans":"不能，需计算Δ交。","verification":"同一抛物线与不同高度斜率线可0、1、2交点。","pitfall":"忽略线的系数沿用原Δ。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":2,"primary_section":"2.4","related_sections":[]},"exam":["交点题先联立写差式，横坐标求完代回给完整坐标","切线题说明非竖直条件，Δ=0所有参数分支均验","位置范围题逐词翻译不等号，至少一与两不同不混写"],"quick":["联立差式","交点判别式","坐标回代","切线重根","参数边界与例外"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_2.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-1-quadratic-functions","page_or_section":"5-1-quadratic-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_2.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-1-quadratic-functions","page_or_section":"5-1-quadratic-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"交点题先联立写差式，横坐标求完代回给完整坐标","method":"差式x²−(m+4)x+4=0，令Δ=0。","principle":"重交点条件。","worked_example_index":2,"verification":"差式分别(x−2)²、(x+2)²；两点代原图均成立。","pitfall":"开平方只取m+4=4而漏−4。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“把交点问题转为二次方程并回到坐标”的抽样复核：两点平方分别1、4，与直线同。；若出现“只报x=1、2当坐标。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用判别式讨论割线切线与参数范围”的抽样复核：差式分别(x−2)²、(x+2)²；两点代原图均成立。；若出现“开平方只取m+4=4而漏−4。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"忽略线的系数沿用原Δ。","correction":"不能，需计算Δ交。","verification":"同一抛物线与不同高度斜率线可0、1、2交点。"}],"illustration_spec":{"title":"抛物线与非竖直线的交点","objects":["y=x²","y=2x+k三位置","切点(1,1)","竖直线例外","双切线参数示例"],"relations":["k=−1为切线边界","差式Δ非原抛物线Δ","竖直单点不套切线规则"],"labels":["k>−1","k=−1","k<−1","Δ交","切点坐标"],"format":"SVG","priority":"P=0","reuse":"暂无对应旧图；线与曲线须精确绘制","english":"Plot y=x^2 with lines y=2x+k for k above, equal to and below -1, showing the tangent at (1,1) when k=-1. Compute intersections from the difference quadratic. Include a clearly separate vertical-line example to prevent equating any single intersection with tangency."}}},"数学3":{"3.1":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":3,"section_id":"3.1","goals":["按指数与系数判断多项式及次数","以恒等式完成运算和参数分类"],"prerequisites":["整式运算","指数与分配律"],"flow":["定义与次数","系数比较","加减乘","除法商余","参数退化"],"concept_relation":"定义与次数；系数比较；加减乘；除法商余；参数退化","deep":["加减运算按同次幂合并，乘法逐项分配再合并。次数的常见规律有条件：两个非零多项式乘积次数相加，和的次数不超过较高者且可能因首项抵消下降。零项与参数退化须单独处理。","多项式除法把被除式表示为除式乘商加余式。非零除式D确定时，余式R的次数必须小于D，或R=0；这个次数限制使商余表达具有唯一性。若余式次数仍高，说明除法尚未完成。","实际运算可按降幂排列，并为缺次项补0占位，减少长除或综合除法错位。占位零不是新的非零项，不改变次数；结果应用D×Q+R回乘，而非只相信列式排得整齐。","学习多项式为余式、因式和高次方程提供语言基础。任何约分都须先因式分解并保留分母非零条件；多项式恒等式与分式等价的定义域不能混用。"],"derive":["P(x)=aₙxⁿ+…+a₁x+a₀，aₙ≠0时次数n；零多项式另论。","非零P,Q有deg(PQ)=degP+degQ；deg(P+Q)可能下降。","F=DQ+R，D≠0，R=0或degR<degD；验证用回乘与合并系数。"],"examples":[{"q":"判断x²+√2x−1、x^(−1)+2、√x+1是否是关于x的实系数多项式。","given":"变量为x，√2是常数。","analysis":"检查变量指数而非系数是否有根号。","method":"逐项核非负整数指数。","principle":"多项式定义。","steps":["第一式指数2、1、0，系数均实数，是。","第二有−1次幂，第三有1/2次幂，不是。"],"ans":"只有第一式是。","verification":"把√2当常系数不会使x的指数变成分数。","pitfall":"凡有根号就判非多项式。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"展开(x+2)(x²−2x+3)，求次数并回查首末项。","given":"普通实系数。","analysis":"乘法分配可能有中间抵消。","method":"逐项乘并合并。","principle":"分配律。","steps":["x乘得x³−2x²+3x，2乘得2x²−4x+6。","合为x³−x+6，次数3。"],"ans":"x³−x+6，3次。","verification":"首项x·x²=x³，常项2·3=6；x=1两边6。","pitfall":"x²项抵消后仍保留错误系数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"P=(a−1)x³+(a+1)x²+2x+3，随实数a次数怎样变化？","given":"系数含参数。","analysis":"最高项可能消失。","method":"按a−1是否0分类。","principle":"次数看最高非零系数。","steps":["a≠1时x³系数非0，次数3。","a=1时x³项0、x²系数2非0，次数2。"],"ans":"a≠1为3次；a=1为2次。","verification":"a=1式为2x²+2x+3，确实二次。","pitfall":"不分参数一律说三次。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]}],"practice":[{"q":"0x⁵+3x²−1的次数？","given":"先去零系数项。","analysis":"写出的最高指数不一定非零。","method":"找最高非零项。","principle":"次数定义。","steps":["0x⁵为零项。","3x²非零且最高，次数2。"],"ans":"2。","verification":"x很大时主导为3x²。","pitfall":"看到x⁵就答5。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"若(x+1)²=x²+ax+b为恒等式，求a,b。","given":"对所有x成立。","analysis":"系数对应。","method":"展开左边。","principle":"多项式恒等需对应系数同。","steps":["左边x²+2x+1。","a=2，b=1。"],"ans":"a=2、b=1。","verification":"x=0给b=1，x=1给1+a+b=4。","pitfall":"只代一个点就定两个未知量。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"三次与二次非零多项式的乘积次数？和的次数必为3吗？","given":"首项系数均非零，两个次数不同。","analysis":"乘积相加；不同次数和不能抵消最高三次。","method":"检查首项。","principle":"最高项来源唯一。","steps":["乘积3+2=5次。","和最高三次项无同次项抵消，仍3次。"],"ans":"乘积5次，和3次。","verification":"若两者都三次，和才可能降次，条件不同。","pitfall":"把所有和都说次数相加。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"F=x³+1，D=x+1，给Q=x²−x、R=x+1，是否为合格商余表达？怎样完成？","given":"回乘可得F，但R次数等于D。","analysis":"还需余式次数限制。","method":"把R再除D。","principle":"余式应低于除式次数。","steps":["DQ+R=(x+1)(x²−x)+(x+1)=x³+1，但R仍一次。","补商1，最终Q=x²−x+1，R=0。"],"ans":"原不是最终商余；最终商x²−x+1、余0。","verification":"(x+1)(x²−x+1)=x³+1。","pitfall":"只看回乘正确就忽略余式次数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]}],"quiz":{"q":"两个二次多项式相加，次数一定二次吗？给反例并说明条件。","given":"二者各自最高项非零。","analysis":"首项可能抵消。","method":"构造相反二次系数。","principle":"加法次数可下降。","steps":["(x²+x)+(−x²+2)=x+2。","和一次；若所有系数抵消则为零多项式需另论。"],"ans":"不一定，取决最高项相加是否0。","verification":"两原式都二次而和一次，已否定必然。","pitfall":"把乘积次数规则套加法。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]},"exam":["次数题先化简并审参数首项，零多项式单独说明","恒等题按系数比较，方程某点成立不能冒充恒等","除法题检查回乘和余式次数，两项缺一不可"],"quick":["定义与次数","系数比较","加减乘","除法商余","参数退化"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-2-power-functions-and-polynomial-functions","page_or_section":"5-2-power-functions-and-polynomial-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-2-power-functions-and-polynomial-functions","page_or_section":"5-2-power-functions-and-polynomial-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"次数题先化简并审参数首项，零多项式单独说明","method":"按a−1是否0分类。","principle":"次数看最高非零系数。","worked_example_index":2,"verification":"a=1式为2x²+2x+3，确实二次。","pitfall":"不分参数一律说三次。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按指数与系数判断多项式及次数”的抽样复核：把√2当常系数不会使x的指数变成分数。；若出现“凡有根号就判非多项式。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“以恒等式完成运算和参数分类”的抽样复核：a=1式为2x²+2x+3，确实二次。；若出现“不分参数一律说三次。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把乘积次数规则套加法。","correction":"不一定，取决最高项相加是否0。","verification":"两原式都二次而和一次，已否定必然。"}],"illustration_spec":{"title":"多项式的次数与商余","objects":["合法/非合法指数","含参数首项","降幂系数表","F=DQ+R关系"],"relations":["系数可含常根号","a=1时三次退为二次","余式次数低于除式"],"labels":["非负整数指数","最高非零项","a−1","商Q","余R"],"format":"SVG","priority":"P=1","reuse":"无对应旧图；代数关系用文字层","english":"Distinguish a radical constant coefficient from a fractional variable exponent. Show how the leading coefficient a-1 vanishes at a=1, reducing degree, and illustrate F=DQ+R with the explicit degree restriction on R."}},"3.2":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":3,"section_id":"3.2","goals":["由除法恒等式推导余式定理","用适当代入求参数或一次余式"],"prerequisites":["多项式除法","联立方程"],"flow":["除法恒等式","一次除式根","常数余数","二次余式","参数验证"],"concept_relation":"除法恒等式；一次除式根；常数余数；二次余式；参数验证","deep":["对二次除式，余式一般一次或更低。若除式(x−a)(x−b)且a≠b，可写R=ux+v并在a、b代入，由两条独立方程确定u,v。只代一个根不足以确定两个未知系数。","如果除式有重复根，代入同一点两次不会产生两个独立条件，不能把重复的同一方程当成两条信息。本阶段可用实际除法或其他额外条件处理，不能凭空凑系数。","给多个余数条件求F中的参数时，每条件都从对应除式根生成，再联立。最后回代原F验证每个余数，避免移项或正负号误差；多项式系数中缺次项不影响代入法，但综合除法须补0。","余式定理不用于含分母奇点的任意表达式而不检查对象。若所给不是多项式，必须先按题意判断除法与定义域；把任何函数在a的值都称为多项式余数是不受支持的推广。"],"derive":["F=(x−a)Q+r，代a得r=F(a)。","对bx−c（b≠0），r=F(c/b)；商的尺度与b有关，但余数代入点由除式零点决定。","对(x−a)(x−b)、a≠b，令R=ux+v：ua+v=F(a)，ub+v=F(b)。"],"examples":[{"q":"F=x³−2x+5除以x−2的余数？","given":"F为多项式，除式一次。","analysis":"不用长除求商。","method":"r=F(2)。","principle":"余式定理由除法恒等式。","steps":["F(2)=8−4+5。","r=9。"],"ans":"9。","verification":"长除可得商x²+2x+2，回乘加9恢复F。","pitfall":"把余数误设0。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"F=2x²+3x−1除以2x−1，余数是多少？","given":"除式根x=1/2。","analysis":"前系数不能忽略。","method":"r=F(1/2)。","principle":"一次除式为零时商项消失。","steps":["2×1/4+3×1/2−1=.5+1.5−1=1。","余数常数1。"],"ans":"1。","verification":"可写F=(2x−1)(x+2)+1，回乘正确。","pitfall":"代x=1或−1。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"F=x³+2x²−x+4除以x²−1，求余式。","given":"除式根为±1且不同。","analysis":"余式至多一次，需两条件。","method":"设R=ux+v，代±1。","principle":"除法恒等式在除式根处使F=R。","steps":["F(1)=6，F(−1)=6。","u+v=6，−u+v=6，得u=0、v=6。"],"ans":"余式6。","verification":"F=(x²−1)(x+2)+6，展开得原式。","pitfall":"以为二次除式余式必为一次且u不能0。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]}],"practice":[{"q":"F=x²+4x+1除以x+3的余数？","given":"除式根−3。","analysis":"正负号由x+3=0确定。","method":"r=F(−3)。","principle":"余式定理。","steps":["9−12+1=−2。","余数可为负。"],"ans":"−2。","verification":"F=(x+3)(x+1)−2。","pitfall":"代+3得到22。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"F=x²+ax+2除以x−1余4，求a。","given":"r=4而非整除。","analysis":"生成参数方程。","method":"F(1)=4。","principle":"余式定理。","steps":["1+a+2=4。","a=1。"],"ans":"a=1。","verification":"F(1)=1+1+2=4。","pitfall":"把余数4忘掉写F(1)=0。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"多项式除以(x−2)²，能代x=2两次唯一求一次余式ux+v吗？","given":"只有一个点的函数值。","analysis":"同一条件重复不独立。","method":"统计未知与独立方程。","principle":"代入只给2u+v=F(2)。","steps":["两个未知只有一条独立方程。","需额外信息或实际除法，重复代2不新增约束。"],"ans":"不能。","verification":"不同u配相应v可满足同一值。","pitfall":"把重复根当两个不同代入点。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"F=x³除以(x−1)(x−2)，余式？","given":"根1、2不同。","analysis":"设一次余式并联立。","method":"R=ux+v。","principle":"F(1)=R1，F(2)=R2。","steps":["u+v=1，2u+v=8。","u=7，v=−6，R=7x−6。"],"ans":"7x−6。","verification":"(x²−3x+2)(x+3)+(7x−6)=x³。","pitfall":"只给F(1)=1当完整余式。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]}],"quiz":{"q":"若F(3)=5，能说x−3是F的因式吗？","given":"余数已知非零。","analysis":"余式与整除判据不同。","method":"按余式定理解释。","principle":"因式需余数0。","steps":["除以x−3的余数是5。","因此不是整除，不是因式。"],"ans":"不能，且x−3不是因式。","verification":"F=(x−3)Q+5在3处仍为5非0。","pitfall":"看见代入点就误认根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]},"exam":["余式题先把除式设0找代入点，不记孤立符号口诀","二次除式先写一次余式，两个不同根给独立方程","有参数题把给定余数写右边，最后逐条件回代"],"quick":["除法恒等式","一次除式根","常数余数","二次余式","参数验证"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-4-dividing-polynomials","page_or_section":"5-4-dividing-polynomials","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-4-dividing-polynomials","page_or_section":"5-4-dividing-polynomials","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"余式题先把除式设0找代入点，不记孤立符号口诀","method":"设R=ux+v，代±1。","principle":"除法恒等式在除式根处使F=R。","worked_example_index":2,"verification":"F=(x²−1)(x+2)+6，展开得原式。","pitfall":"以为二次除式余式必为一次且u不能0。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由除法恒等式推导余式定理”的抽样复核：长除可得商x²+2x+2，回乘加9恢复F。；若出现“把余数误设0。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用适当代入求参数或一次余式”的抽样复核：F=(x²−1)(x+2)+6，展开得原式。；若出现“以为二次除式余式必为一次且u不能0。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"看见代入点就误认根。","correction":"不能，且x−3不是因式。","verification":"F=(x−3)Q+5在3处仍为5非0。"}],"illustration_spec":{"title":"余式定理的消元关系","objects":["F=(x−a)Q+r","代入x=a","2x−1根1/2","二次余式ux+v"],"relations":["一次除式余式常数","二次两不同根可定u,v","重复根只给一个值条件"],"labels":["r=F(a)","F(c/b)","a≠b","独立条件"],"format":"SVG","priority":"P=1","reuse":"无合格对应图；公式流程需准确","english":"Derive the remainder theorem from F=(x-a)Q+r by substituting x=a. For divisor 2x-1 use a=1/2. For two distinct linear factors, show how R=ux+v is determined by two independent values; do not count a repeated root twice as independent data."}},"3.3":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":3,"section_id":"3.3","goals":["以余式定理证明根与一次因式的等价","求参数并核因式重数"],"prerequisites":["余式定理","乘法恒等式"],"flow":["余数为零","根与因式","求商","参数联立","重数与次数"],"concept_relation":"余数为零；根与因式；求商；参数联立；重数与次数","deep":["F(a)=0只说明至少含一次x−a，不能仅据一次代入判断重数。将因式除去后若商在a处仍为零，可以继续除；重数会影响图象和根的计数，但本章可用反复因式法认识，不需偷用尚未建立的微分公式。","给定两个不同根可生成两个独立参数条件，但要留意首项是否因参数而退化，以及给定条件是否重复。参数解后还应验证多项式是否确有相应因式，不以代数移项中的一个结果直接结束。","对于非零n次多项式，互不相同的根不超过n个，可用不断抽取不同一次因式说明；重根按重数计与不同根数是不同说法。零多项式在任何x都为零，不能套这个结论而称它有某个有限次数。","因式定理用于多项式，若表达式有分母或根式，应先检查定义域与是否满足多项式条件。把分式分子为零当整个分式为零还需要分母非零，这个限制不能因因式分解而消失。"],"derive":["F(a)=0 ⇔ F=(x−a)Q，证明来自F=(x−a)Q+r且r=F(a)。","若Q(a)=0，还可再抽取x−a；重复次数决定该根重数。","非零n次多项式最多n个不同实根；是否存在全部n个实根不能由次数单独保证。"],"examples":[{"q":"F=x³−4x，证明x−2为因式，并求完整实因式分解。","given":"F为实系数多项式。","analysis":"先零值证明，再求商/共同因子。","method":"计算F(2)并分解。","principle":"因式定理与平方差。","steps":["F(2)=8−8=0，所以x−2是因式。","F=x(x²−4)=x(x−2)(x+2)。"],"ans":"x(x−2)(x+2)。","verification":"乘回x³−4x，根0、±2均使F为0。","pitfall":"只写F(2)=0就声称已给完整分解。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"F=x³+ax²+bx−2，x−1与x+2均为因式，求a,b。","given":"两个不同一次因式。","analysis":"代入点1、−2。","method":"F(1)=0、F(−2)=0联立。","principle":"因式定理。","steps":["1+a+b−2=0，a+b=1。","−8+4a−2b−2=0，2a−b=5。","解a=2、b=−1。"],"ans":"a=2、b=−1。","verification":"F=(x+2)(x−1)(x+1)，常项−2且x²系数2。","pitfall":"x+2代+2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"F=(x−1)²(x+3)，只算F(1)=0能证明1是二重根吗？如何验证？","given":"已给分解但要求说明判据。","analysis":"一次取零只保证至少一重。","method":"除一次后再检查商。","principle":"重数是同一因式出现次数。","steps":["除x−1得Q=(x−1)(x+3)，Q1=0可再除。","再得x+3，在1处4非0，故恰二重。"],"ans":"单次取零不足；反复除得恰二重。","verification":"展开(x²−2x+1)(x+3)后仍可回乘验证。","pitfall":"由F(1)=0直接猜任何重数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]}],"practice":[{"q":"F(−3)=0，对应一次因式是什么？","given":"根为−3。","analysis":"因式x−a。","method":"代a=−3。","principle":"因式定理。","steps":["x−(−3)=x+3。","故F可被x+3整除。"],"ans":"x+3。","verification":"该因式在−3处为0。","pitfall":"写x−3。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"F=x²+1在实数范围有一次实因式吗？","given":"实系数一次因式。","analysis":"实根存在与一次实因式等价。","method":"看x²+1是否可0。","principle":"实数平方非负。","steps":["x²+1≥1>0。","没有实根，因此无一次实因式。"],"ans":"没有。","verification":"若改复数范围结论会不同，但本题实数。","pitfall":"认为二次必有两个实根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"已知x−2为三次F的因式，能推出除去后商一定一次吗？","given":"F确为非零三次。","analysis":"次数相减。","method":"degQ=3−1。","principle":"非零乘积次数相加。","steps":["F=(x−2)Q。","Q应为二次，不是一次。"],"ans":"不能，商二次。","verification":"一次乘二次才三次。","pitfall":"把因式个数与次数混淆。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"F=x³−3x²+3x−1，求1的重数及不同实根数。","given":"非零三次。","analysis":"利用完全立方。","method":"F=(x−1)³。","principle":"重复因式决定重数。","steps":["展开(x−1)³正好原式。","只有x=1使乘积为0，重数3，不同实根1个。"],"ans":"三重根1；不同实根1个。","verification":"次数3按重数吻合，而非三种不同值。","pitfall":"三次就列三个不同根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]}],"quiz":{"q":"一个非零二次多项式在三个不同实数处都为0，可能吗？若系数全0又怎样？","given":"明确非零或零两种。","analysis":"不同根数受次数限制。","method":"用因式定理逐根抽因式。","principle":"三个不同根意味着至少三个一次因式。","steps":["非零二次无法含三次因子，故不可能。","若全系数0是零多项式，不是非零二次，每个实数都满足。"],"ans":"非零二次不可能；零多项式例外。","verification":"避免把“0x²+0x+0”称二次。","pitfall":"忘非零条件和退化情况。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]},"exam":["因式题写根—因式对应，正负号由x−a来核","参数题每个不同根给一条件，算后回乘验证","重根题反复除因式，区分重数与不同根数"],"quick":["余数为零","根与因式","求商","参数联立","重数与次数"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.3","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-5-zeros-of-polynomial-functions","page_or_section":"5-5-zeros-of-polynomial-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.3","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-5-zeros-of-polynomial-functions","page_or_section":"5-5-zeros-of-polynomial-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"因式题写根—因式对应，正负号由x−a来核","method":"除一次后再检查商。","principle":"重数是同一因式出现次数。","worked_example_index":2,"verification":"展开(x²−2x+1)(x+3)后仍可回乘验证。","pitfall":"由F(1)=0直接猜任何重数。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“以余式定理证明根与一次因式的等价”的抽样复核：乘回x³−4x，根0、±2均使F为0。；若出现“只写F(2)=0就声称已给完整分解。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“求参数并核因式重数”的抽样复核：展开(x²−2x+1)(x+3)后仍可回乘验证。；若出现“由F(1)=0直接猜任何重数。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"忘非零条件和退化情况。","correction":"非零二次不可能；零多项式例外。","verification":"避免把“0x²+0x+0”称二次。"}],"illustration_spec":{"title":"根、一次因式与重数","objects":["F(a)=0到x−a因式","根−3与x+3","重复因式链","次数计数"],"relations":["两个方向等价","重数需反复除","非零n次不同根不超过n"],"labels":["F(a)=0","x−a","重数","不同实根","非零多项式"],"format":"SVG","priority":"P=1","reuse":"无对应旧图；关系图与可选函数图应准确","english":"Connect a numerical root a with the linear factor x-a in both directions, including a=-3 and factor x+3. Show repeated division for a double root and distinguish multiplicity from the number of distinct real roots of a nonzero polynomial."}},"3.4":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":3,"section_id":"3.4","goals":["依结构选择提因式、分组或求根方法","在指定数域内完成分解并回乘"],"prerequisites":["多项式运算","因式定理"],"flow":["公因式","恒等式","分组","求根降次","数域与回乘"],"concept_relation":"公因式；恒等式；分组；求根降次；数域与回乘","deep":["若直接看不出结构，可用因式定理尝试合适根，再除去对应一次因式。对于整数系数，若既约有理根p/q存在，可用常数项与首项系数的整除关系缩小候选；这是候选筛选，不保证一定有有理根。","偶次幂结构可用y=x²代换成较低次多项式，再把y换回。因式分解只做代数等价时仍要回原变量；解方程时则还要注意y≥0的实数限制，两类任务不可混淆。","分解到什么程度与数域有关。x²−2在有理数系数内不能拆成两个一次因式，在实数内可写(x−√2)(x+√2)；x²+1在实数内不可同样拆成实一次式。题目未指明时应清楚说明所用范围。","完成后逐项回乘核首项、常项和中间项，并检查是否漏了公因子。抽出负号时每项符号都要反转；只查若干代入值可辅助发现错误，但展开恒等验证更完整。"],"derive":["a²−b²=(a−b)(a+b)；a³−b³=(a−b)(a²+ab+b²)。","整数系数多项式若有既约有理根p/q，则p整除常数项、q整除首项系数（首常项非零等条件下）。","分解流程：公因式 → 恒等结构/分组/代换 → 因式定理找根 → 指定数域继续 → 回乘。"],"examples":[{"q":"分解3x³−12x。","given":"实系数，多项式。","analysis":"先公因式再平方差。","method":"提3x。","principle":"分配律和a²−b²。","steps":["3x³−12x=3x(x²−4)。","再得3x(x−2)(x+2)。"],"ans":"3x(x−2)(x+2)。","verification":"回乘3x(x²−4)=3x³−12x。","pitfall":"只提3x后不继续，或把x²−4写(x−2)²。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"分解x³−3x²−4x+12。","given":"四项可分组。","analysis":"前两与后两共享x−3。","method":"分为x²(x−3)−4(x−3)。","principle":"分配律反向。","steps":["提共同(x−3)得(x−3)(x²−4)。","平方差得(x−3)(x−2)(x+2)。"],"ans":"(x−3)(x−2)(x+2)。","verification":"展开x³−3x²−4x+12。","pitfall":"后组提−4时把括号写x+3。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"在实数内分解x⁴−5x²+4，并说明代换步骤。","given":"只含偶次幂。","analysis":"可把x²视为一变量。","method":"y=x²。","principle":"代换后保持恒等。","steps":["y²−5y+4=(y−1)(y−4)。","换回(x²−1)(x²−4)。","实数下进一步为(x−1)(x+1)(x−2)(x+2)。"],"ans":"四个一次因式的乘积。","verification":"(x²−1)(x²−4)=x⁴−5x²+4。","pitfall":"解出y=1、4就把它们当x值。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]}],"practice":[{"q":"x²+6x+9怎样分解？","given":"完整二次式。","analysis":"识别完全平方。","method":"比较x²+2·3x+3²。","principle":"(a+b)²。","steps":["中项6x吻合。","得(x+3)²。"],"ans":"(x+3)²。","verification":"展开还原，常项9。","pitfall":"把+9只写(x+9)²。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"x²−2在有理数内与实数内的分解有何不同？","given":"指定数域两种。","analysis":"是否允许√2作系数。","method":"找根并核系数范围。","principle":"实根±√2不是有理数。","steps":["有理数系数内不可拆一次。","实数内可写(x−√2)(x+√2)。"],"ans":"数域不同导致可分解程度不同。","verification":"乘回x²−2。","pitfall":"无条件说不能分或必能有理分。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"2x³−3x²−8x+12以分组分解。","given":"前后可提共同2x−3。","analysis":"识别配对。","method":"x²(2x−3)−4(2x−3)。","principle":"共同因式与平方差。","steps":["得(2x−3)(x²−4)。","再得(2x−3)(x−2)(x+2)。"],"ans":"(2x−3)(x−2)(x+2)。","verification":"首项2x³、常项(−3)(−2)(2)=12，中间项吻合。","pitfall":"以非首一因式为由漏系数2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"分解x³+1，并用x=1核查错误答案(x+1)³。","given":"立方和。","analysis":"立方和不同于和的立方。","method":"用a³+b³。","principle":"a³+b³=(a+b)(a²−ab+b²)。","steps":["x³+1=(x+1)(x²−x+1)。","x=1原2，错误答案8，不能相等。"],"ans":"(x+1)(x²−x+1)。","verification":"完整展开中间项抵消。","pitfall":"见立方就对和整体立方。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]}],"quiz":{"q":"因式分解得到(2x−3)(x−2)(x+2)，只检查首项和常项相同就足够证明吗？","given":"中间项尚未核对。","analysis":"两个指标不足唯一确定三次多项式。","method":"展开全部系数。","principle":"恒等式需对应各项相同。","steps":["首常项可快速筛错。","仍需核x²、x等中间系数或其他充分证明。"],"ans":"不足，应完整回乘或用充分代数证明。","verification":"可给相同首常项而中间系数任意不同的反例。","pitfall":"把快速检查当充分恒等证明。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]},"exam":["分解题先提公因式、识别结构，不盲猜根","偶次式代换后换回x，方程求根另核变量限制","写清数域，最终回乘所有系数，首常项只作快查"],"quick":["公因式","恒等式","分组","求根降次","数域与回乘"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-5-factoring-polynomials","page_or_section":"1-5-factoring-polynomials","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-5-factoring-polynomials","page_or_section":"1-5-factoring-polynomials","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"分解题先提公因式、识别结构，不盲猜根","method":"y=x²。","principle":"代换后保持恒等。","worked_example_index":2,"verification":"(x²−1)(x²−4)=x⁴−5x²+4。","pitfall":"解出y=1、4就把它们当x值。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“依结构选择提因式、分组或求根方法”的抽样复核：回乘3x(x²−4)=3x³−12x。；若出现“只提3x后不继续，或把x²−4写(x−2)²。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“在指定数域内完成分解并回乘”的抽样复核：(x²−1)(x²−4)=x⁴−5x²+4。；若出现“解出y=1、4就把它们当x值。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把快速检查当充分恒等证明。","correction":"不足，应完整回乘或用充分代数证明。","verification":"可给相同首常项而中间系数任意不同的反例。"}],"illustration_spec":{"title":"因式分解的方法选择","objects":["共同因式示例","四项分组","y=x²代换","数域分支","回乘检查"],"relations":["x⁴−5x²+4分为四实一次因式","平方和不误用平方差","候选根不等于必存在根"],"labels":["公因式","分组","代换后换回","有理数/实数","完整回乘"],"format":"SVG","priority":"P=1","reuse":"无对应图；代数结构关系可用页面图与SVG","english":"Create a method-selection diagram for common factors, identities, grouping, substitution and root-based division. Work x^4-5x^2+4 through y=x^2 to four real linear factors, distinguish rational and real factorization, and require full coefficient verification."}},"3.5":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":3,"section_id":"3.5","goals":["用因式分解与代换求全部实根","处理重根、参数退化和非等价除法"],"prerequisites":["因式分解","二次方程与定义域"],"flow":["移项归零","找因式降次","零乘积","代换范围","参数与回代"],"concept_relation":"移项归零；找因式降次；零乘积；代换范围；参数与回代","deep":["用y=x²代换时，实数解要求y≥0。二次方程给负的y候选，不能当作实数x的平方；正y给x=±√y，零y只给x=0。换回步骤和双符号是常见漏解处。","找一个有理根后把对应一次因式除去，继续解二次商；判别式负时该商没有实根，并不否定已经找到的实根。若题目要求复根，则需相应复数知识，本节不把超出实数的结果强填为实根。","参数题须关注最高系数、因式退化和根相等的临界值，按参数范围列解集。方程次数变化与根的重合是不同事情，不能把每个参数区间的解数机械按最高写出的幂确定。","最终把每个候选代回原方程并回顾变形是否等价。原式若含分母、根式等，化成多项式后的根仍需原域筛选；回代只验证已有候选不自动证明无漏根，无漏依据来自等价分解与完整分类。"],"derive":["F=AB=0 ⇔ A=0或B=0（实数代数）；重复因式保留重数但解集去重。","y=x²时y≥0，y>0回得±√y，y=0回得0，y<0无实x。","含变量因子除法：先分该因子为0与非0，或避免除法而用零乘积。"],"examples":[{"q":"解实数方程x³=x，说明直接除x会漏什么。","given":"原式为多项式方程。","analysis":"x可能为0。","method":"移项分解。","principle":"零乘积原理。","steps":["x³−x=x(x²−1)=x(x−1)(x+1)=0。","逐因式得x=0、1、−1。"],"ans":"{−1,0,1}。","verification":"三值代原式均成立；直接除x会漏0。","pitfall":"未分类就除含未知因子。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"解x⁴−3x²−4=0的全部实根。","given":"只含偶次幂。","analysis":"先解y=x²且筛负y。","method":"y²−3y−4=0。","principle":"代换与非负平方。","steps":["(y−4)(y+1)=0，y=4或−1。","y=−1无实x；y=4给x=±2。"],"ans":"x=−2或2。","verification":"16−12−4=0，负y候选不可回实数。","pitfall":"把x答成4与−1，或漏−2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"讨论实数参数a下x³−ax=0的不同实根。","given":"关于x，首项恒1。","analysis":"分解后根随a符号变化。","method":"x(x²−a)=0分类。","principle":"实平方非负及根重合。","steps":["a>0时x=0、±√a，共3个不同根。","a=0时x³=0，仅0（重数3）。","a<0时x²=a无实解，仅0。"],"ans":"按a正、零、负分别为3、1、1个不同根。","verification":"每段均由完整因式分支，a=0时三表达式合成一个值。","pitfall":"a<0仍写±√a为实数，或a=0重复算3个不同根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]}],"practice":[{"q":"解(x−2)²(x+1)=0，写不同解和重数。","given":"实数范围。","analysis":"重复因式不增加不同值。","method":"逐因式。","principle":"零乘积。","steps":["x=2或−1。","2重数2，−1重数1。"],"ans":"解集{−1,2}。","verification":"重数总3与次数3吻合。","pitfall":"把2重复列成两个不同解。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"解x³+1=0的实根。","given":"实数范围。","analysis":"立方和分解后判二次商。","method":"(x+1)(x²−x+1)=0。","principle":"因式与判别式。","steps":["一次得x=−1。","二次判别式1−4=−3<0，无实根。"],"ans":"仅x=−1。","verification":"(−1)³+1=0；二次式=(x−1/2)²+3/4>0。","pitfall":"认为三次必须给三个实根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"解x⁴−5x²+4=0。","given":"实数范围。","analysis":"分解或代换。","method":"(x²−1)(x²−4)=0。","principle":"零乘积及平方方程。","steps":["x²=1或4。","x=±1、±2。"],"ans":"{−2,−1,1,2}。","verification":"各平方1或4，均使原式0。","pitfall":"只列正平方根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"解(x²−1)/(x−1)=0并保留原域，和解x²−1=0有什么区别？","given":"原分母x≠1。","analysis":"分子为0还需分母非0。","method":"先分子根±1再筛。","principle":"分式零值条件。","steps":["分子根1、−1。","x=1原无定义排除，x=−1分母−2可取。"],"ans":"原分式解仅−1；多项式解±1。","verification":"−1代入分子0分母非0。","pitfall":"约分后或解分子时忘原排除点。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]}],"quiz":{"q":"给多项式找到一个根并回代成功，是否已证明解集完整？","given":"次数可能大于1。","analysis":"验证存在与排除其他根是不同任务。","method":"继续降次并逐因式解。","principle":"完整分解或其他充分方法才控制无漏。","steps":["已找到根说明一个解成立。","除相应因式后继续分析全部商根，并审数域及条件。"],"ans":"没有，还需无漏解的推理。","verification":"x³−x中找到1仍有0、−1。","pitfall":"把一例成功当全部。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]},"exam":["高次题先移零、分解、逐因式求解，变形链说明无漏","代换题把新变量范围写在旁边，换回保留双符号","参数题按平方可行性、退化与根重合分类，最后解集去重"],"quick":["移项归零","找因式降次","零乘积","代换范围","参数与回代"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.5","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-5-zeros-of-polynomial-functions","page_or_section":"5-5-zeros-of-polynomial-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.5","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-5-zeros-of-polynomial-functions","page_or_section":"5-5-zeros-of-polynomial-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"高次题先移零、分解、逐因式求解，变形链说明无漏","method":"x(x²−a)=0分类。","principle":"实平方非负及根重合。","worked_example_index":2,"verification":"每段均由完整因式分支，a=0时三表达式合成一个值。","pitfall":"a<0仍写±√a为实数，或a=0重复算3个不同根。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用因式分解与代换求全部实根”的抽样复核：三值代原式均成立；直接除x会漏0。；若出现“未分类就除含未知因子。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“处理重根、参数退化和非等价除法”的抽样复核：每段均由完整因式分支，a=0时三表达式合成一个值。；若出现“a<0仍写±√a为实数，或a=0重复算3个不同根。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把一例成功当全部。","correction":"没有，还需无漏解的推理。","verification":"x³−x中找到1仍有0、−1。"}],"illustration_spec":{"title":"高次方程的完整解集","objects":["x³=x因式树","x²代换","正零负参数分支","实根集合与重数"],"relations":["保留x=0分支","负y不回实根","正y给±根","a=0时根合并"],"labels":["全部实根","y≥0","±√y","原域","不同根/重数"],"format":"SVG","priority":"P=0","reuse":"无对应旧图；函数曲线如新增须确定性绘制","english":"Show a complete solution tree for x^3=x retaining x=0, and for an even-power equation using y=x^2 with y>=0 and both square-root signs. Include parameter branches for x(x^2-a)=0, distinguishing root multiplicity from distinct real solutions."}}},"数学4":{"4.1":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":4,"section_id":"4.1","goals":["以实数范围定义根式与定义域","解释主平方根和绝对值的关系"],"prerequisites":["实数与平方","绝对值与不等式"],"flow":["根的次数","主根非负","定义域","绝对值","等价条件"],"concept_relation":"根的次数；主根非负；定义域；绝对值；等价条件","deep":["由非负主根定义，√(x²)=|x|，而不是对所有实数x都等于x。若x≥0可写x，若x<0应写−x。绝对值是在保证结果非负，不是多余装饰符号；这也是许多根式化简漏符号的来源。","确定定义域是化简与方程的前提。等式变形可能把原限制隐藏，例如√(x²)在所有实数有定义，而把它错写x会在负区改变值；约去分母因子也不能把原来分母为零的点重新加回。","含多个根式或分母时，把每一条件分别列出再取交集。对于√((x−1)/(x+2))，需要分式非负且x≠−2，不能把分子分母都强制非负，因为同为负也能使商非负。","图象或数值验证可发现错误，但不能代替全域证明。试x=−2能否定√(x²)=x，却不能用几个正数样本证明等式总成立；证明应回到非负主根和分段定义。"],"derive":["实数范围：偶次根要求被开方数≥0，奇次根可为任意实数；分母另需非零。","√(x²)=|x|={x（x≥0），−x（x<0）}。","若√g(x)在分母，需g(x)>0；若分母还含其他项，需直接检查整个分母，而非一律令每项正。"],"examples":[{"q":"求√49，并解方程x²=49，二者答案为什么不同形式？","given":"实数范围，√为主平方根。","analysis":"一个是定义的单值函数，一个是方程全部解。","method":"用非负根和平方对称性。","principle":"√a≥0，但x²相同可来自±x。","steps":["√49=7。","方程有x=7或x=−7，两者平方均49。"],"ans":"主根7；方程解±7。","verification":"−7不是√49的值，却是方程的解。","pitfall":"把根号值写±7。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"化简√((x−3)²)，并求x=1时的值。","given":"x任意实数。","analysis":"主根需非负。","method":"先写绝对值再分段或代入。","principle":"√y²=|y|。","steps":["原式=|x−3|。","x=1得|−2|=2；分段为x≥3时x−3，x<3时3−x。"],"ans":"|x−3|，x=1时2。","verification":"直接√((1−3)²)=√4=2。","pitfall":"去根号后直接写x−3导致−2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"求√((x−1)/(x+2))的实数定义域。","given":"分母x+2不能为0。","analysis":"商非负有两个符号区间。","method":"列临界点−2、1并作号表。","principle":"偶次根要求商≥0，分母非零。","steps":["x<−2时分子分母均负，商正。","−2<x<1时商负；x≥1时商非负。","−2排除，1可取。"],"ans":"(−∞,−2)∪[1,+∞)。","verification":"x=−3时商4、根为2；x=0时商−1/2不可；x=1时根0可。","pitfall":"只取分子分母各自非负而漏x<−2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]}],"practice":[{"q":"√0、∛(−27)、√(−4)在实数内各怎样？","given":"偶根与奇根规则。","analysis":"先判定义再求值。","method":"按根的次数。","principle":"偶次平方非负，奇次立方可负。","steps":["√0=0，∛(−27)=−3。","√(−4)在实数内无定义。"],"ans":"0、−3、无实数定义。","verification":"0²=0、(−3)³=−27。","pitfall":"把所有负被开方数都视为无定义。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"1/√(2x−6)定义域？","given":"根式位于整个分母。","analysis":"被开方为零仍使分母零。","method":"2x−6>0。","principle":"实根与非零分母同时。","steps":["2x>6。","x>3，3不取。"],"ans":"(3,+∞)。","verification":"x=3给零分母，x=4可。","pitfall":"只写x≥3。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"x<0时√(9x²)怎样化简？","given":"已知x负。","analysis":"根式提出系数但保留绝对值。","method":"3|x|再用符号。","principle":"主根非负。","steps":["√(9x²)=3|x|。","x<0时|x|=−x，故−3x。"],"ans":"−3x。","verification":"x=−2时结果6，与√36相同。","pitfall":"写3x为负。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"求√(x+1)+1/(x−2)定义域，并判断化简后能否补入x=2。","given":"两个限制同时存在。","analysis":"根式与分母分别列。","method":"x+1≥0且x−2≠0。","principle":"定义域为条件交集。","steps":["x≥−1。","排除2，得[−1,2)∪(2,+∞)；任何等价化简仍保留原排除。"],"ans":"[−1,2)∪(2,+∞)，不能补2。","verification":"−1可取根号0，2不可因分母0。","pitfall":"只查根号忘分母。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]}],"quiz":{"q":"有人用x=1、2、3证明√(x²)=x对所有实数成立，怎样完整纠正？","given":"只验证正数。","analysis":"样本不足且负数反例。","method":"反例后给一般恒等式。","principle":"主平方根非负。","steps":["x=−1时左1右−1，原命题假。","正确为√x²=|x|，用x符号分段说明。"],"ans":"应改为|x|并分正负。","verification":"绝对值总非负且平方为x²，满足主根定义。","pitfall":"用有限正样本代替全域证明。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]},"exam":["根式题先写实数范围和定义域，偶根与奇根分开","去平方根必须保留非负性，用绝对值或符号条件","分式根号题作号表取交集，分母零点明确排除"],"quick":["根的次数","主根非负","定义域","绝对值","等价条件"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"根式题先写实数范围和定义域，偶根与奇根分开","method":"列临界点−2、1并作号表。","principle":"偶次根要求商≥0，分母非零。","worked_example_index":2,"verification":"x=−3时商4、根为2；x=0时商−1/2不可；x=1时根0可。","pitfall":"只取分子分母各自非负而漏x<−2。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“以实数范围定义根式与定义域”的抽样复核：x=−3时商4、根为2；x=0时商−1/2不可；x=1时根0可。；若出现“只取分子分母各自非负而漏x<−2。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“解释主平方根和绝对值的关系”的抽样复核：直接√((1−3)²)=√4=2。；若出现“去根号后直接写x−3导致−2。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"用有限正样本代替全域证明。","correction":"应改为|x|并分正负。","verification":"绝对值总非负且平方为x²，满足主根定义。"}],"illustration_spec":{"title":"主平方根与定义域","objects":["y=√(x²)=|x|图","x²=a的两根","分式号表","排除点"],"relations":["根号输出非负","偶次根需非负","分母不能零","号表保留x<−2"],"labels":["√x²=|x|","x=±7为方程解","−2","1","定义域"],"format":"SVG","priority":"P=0","reuse":"数学暂无合格对应图；必须确定性绘制","english":"Draw the exact V-shaped graph y=sqrt(x^2)=abs(x), distinguish the principal root sqrt(49)=7 from equation solutions ±7, and show a sign chart for (x-1)/(x+2) with -2 excluded and 1 included."}},"4.2":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":4,"section_id":"4.2","goals":["用根式定义有理指数并注明底数条件","正确处理负指数与指数运算的边界"],"prerequisites":["根式定义","整数指数"],"flow":["有理指数定义","正底数","负指数倒数","指数律","负底数边界"],"concept_relation":"有理指数定义；正底数；负指数倒数；指数律；负底数边界","deep":["正底数下可使用a^r a^s=a^(r+s)、a^r/a^s=a^(r−s)、(a^r)^s=a^(rs)。这些规则的实数扩展对负底数需要额外审查，不能把含偶根的运算当所有形式都等价。","负底数的某些有理幂可以用约分后的奇次根定义，例如(−8)^(1/3)=−2；若指数分母偶数则通常无实数值。写同一有理数为不同未约分形式后套用偶根，可能改变定义步骤，故必须先约分并明确约定，或将题目限定正底数。","解指数与根式混合题先确认定义域，再选择指数法或根式法。消去负指数可使分母限制更清楚，但形式上的约分不允许把原来无定义的底数0放回。","验算应选满足条件的值并回到定义，不能让计算器的复数结果或程序使用的幂函数约定悄悄替换实数问题。对负底数有疑问时，写成明确的奇次根往往更稳妥。"],"derive":["a>0时，a^(m/n)=ⁿ√(a^m)，指数先视为约分的有理数，n>0。","a≠0时a^(−r)=1/a^r；a>0时常用指数律在本节有理指数范围成立。","负底数只在相应实根有意义并明确约定时处理；(−8)^(1/3)=−2，而(−8)^(1/2)无实数值。"],"examples":[{"q":"求27^(2/3)，解释分子分母的作用。","given":"底数正。","analysis":"先立方根再平方。","method":"(∛27)²。","principle":"分母为根次数，分子为幂次数。","steps":["∛27=3。","3²=9。"],"ans":"9。","verification":"9³=729=27²。","pitfall":"算成27²/3。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"求16^(−3/4)。","given":"底数正非零。","analysis":"负号表示倒数，不是结果负。","method":"先四次根与立方，再取倒数。","principle":"a^(−r)=1/a^r。","steps":["16^(1/4)=2，16^(3/4)=8。","原式=1/8。"],"ans":"1/8。","verification":"乘16^(3/4)=8得1。","pitfall":"答−8或−1/8。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"有人由((−1)²)^(1/2)=(−1)^(2×1/2)推出1=−1，哪一步越过条件？","given":"底数为负，外层平方根取非负主根。","analysis":"幂的幂法则不能无条件用于该负底数扩展。","method":"分别按定义计算并查条件。","principle":"实数主根使√x²=|x|。","steps":["左边√1=1。","右边(−1)^1=−1；把幂律从正底数推广到此例不合法。"],"ans":"错误在无条件合并指数。","verification":"正确左式等于|−1|=1，不造成矛盾。","pitfall":"只背指数律不检查底数与根定义。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]}],"practice":[{"q":"81^(3/4)是多少？","given":"正底数。","analysis":"四次根后立方。","method":"(⁴√81)³。","principle":"有理指数定义。","steps":["⁴√81=3。","3³=27。"],"ans":"27。","verification":"27⁴=81³。","pitfall":"把分母当除数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"a>0，a^(1/2)×a^(3/2)化简。","given":"底数同且为正。","analysis":"同底数乘法加指数。","method":"1/2+3/2=2。","principle":"指数律适用。","steps":["指数和2。","结果a²。"],"ans":"a²。","verification":"a=4时2×8=16。","pitfall":"指数相乘而非相加。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"0^(−1/2)在实数内是否有定义？","given":"负指数要求倒数。","analysis":"根可0但倒数不可。","method":"写1/√0。","principle":"分母不得为0。","steps":["√0=0。","1/0无定义。"],"ans":"无定义。","verification":"0的正1/2次幂有定义，不可混淆。","pitfall":"见根号0就说全部可算。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"a>0，(a^(3/2)/a^(1/2))^(−2)化简并说明条件。","given":"同一正底数。","analysis":"先同底数相除再幂。","method":"指数差1后取负二次幂。","principle":"正底数指数律及倒数。","steps":["里面a^(3/2−1/2)=a。","a^(−2)=1/a²，a>0保留。"],"ans":"1/a²，a>0。","verification":"a=2时(√8/√2)⁻²=2⁻²=1/4。","pitfall":"化简后擅自加回a=0或负底数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]}],"quiz":{"q":"对正底数a，有a^(1/2)+a^(1/2)=a¹吗？","given":"是加法而非同底数乘法。","analysis":"指数律适用运算类型不同。","method":"合并同类根式。","principle":"a^r×a^s才加指数。","steps":["和为2a^(1/2)。","取a=9，左6而a¹=9，否定原式。"],"ans":"不对，应为2√a。","verification":"与两个相同项相加的代数规则一致。","pitfall":"把乘法指数律套进加法。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]},"exam":["指数题先圈底数和完整指数，负指数先辨倒数","合并前写条件，正底数规则不能无条件推负底数","加减只合并同类项，不把乘除指数律跨运算使用"],"quick":["有理指数定义","正底数","负指数倒数","指数律","负底数边界"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"指数题先圈底数和完整指数，负指数先辨倒数","method":"分别按定义计算并查条件。","principle":"实数主根使√x²=|x|。","worked_example_index":2,"verification":"正确左式等于|−1|=1，不造成矛盾。","pitfall":"只背指数律不检查底数与根定义。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用根式定义有理指数并注明底数条件”的抽样复核：9³=729=27²。；若出现“算成27²/3。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“正确处理负指数与指数运算的边界”的抽样复核：乘16^(3/4)=8得1。；若出现“答−8或−1/8。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把乘法指数律套进加法。","correction":"不对，应为2√a。","verification":"与两个相同项相加的代数规则一致。"}],"illustration_spec":{"title":"有理指数与条件","objects":["a^(m/n)与根式对应","27^(2/3)","16^(−3/4)","正负底数边界"],"relations":["分母开根分子幂","负指数取倒数","正底数指数律有条件"],"labels":["a>0","n为正整数","1/a^r","27^(2/3)=9","实数范围"],"format":"SVG","priority":"P=0","reuse":"暂无对应旧图；公式需文字层和准确上下标","english":"Explain rational exponents for positive bases: denominator as root index and numerator as power. Show 27^(2/3)=9 and 16^(-3/4)=1/8. State nonzero conditions for negative exponents and warn that power-of-a-power rules cannot be extended blindly to negative bases and principal even roots."}},"4.3":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":4,"section_id":"4.3","goals":["在定义域内化简与合并根式","保留绝对值并解释平方变形风险"],"prerequisites":["根式与有理指数","分配律"],"flow":["定义域","提出平方因子","同类项","交叉项","平方与增根"],"concept_relation":"定义域；提出平方因子；同类项；交叉项；平方与增根","deep":["根式乘法遵守分配律，并需处理交叉项。平方(a+b)²=a²+2ab+b²，根式里的平方也不能漏2ab。比如(√3+√2)²=5+2√6，不是5。","涉及变量符号时可分区间化简绝对值。若同时有|x−1|和|x+1|，以−1、1分段，每段才有确定去符号形式。多个根号的定义域与分段条件应同时保留，不可只给一个看似短的式子。","方程中两边平方通常只保证原解满足平方后的式子，反向可能引入额外解。需先检查根号一侧非负等条件，得到候选后代回原式；简化恒等式与解方程中的变形逻辑应分开。","检验可用近似估值、代入边界和反例辅助，最终仍应给代数依据。把√2+√3估成约3.146，而√5约2.236，可以快速发现误合并；但数值接近不能作为恒等证明。"],"derive":["a,b≥0时√a√b=√(ab)；a≥0、b>0时√a/√b=√(a/b)。","√(x²)=|x|；(√a+√b)²=a+b+2√(ab)，a,b≥0。","解含根式方程：定义域与符号 → 隔离根式 → 平方求候选 → 代回原式排除增根。"],"examples":[{"q":"化简√72−√32+√8。","given":"均为非负常数根式。","analysis":"先提出平方因子。","method":"分别化为√2的倍数再合并。","principle":"乘法根式法则及同类项。","steps":["√72=6√2，√32=4√2，√8=2√2。","合为(6−4+2)√2=4√2。"],"ans":"4√2。","verification":"近似8.485−5.657+2.828≈5.656=4√2。","pitfall":"直接根号内72−32+8。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"展开(2√3−√2)²并验算。","given":"实数根式。","analysis":"交叉项有负号。","method":"a²−2ab+b²。","principle":"完全平方展开。","steps":["(2√3)²=12，(√2)²=2。","交叉项−4√6，合14−4√6。"],"ans":"14−4√6。","verification":"原括号约2.050，平方约4.202；结果14−9.798≈4.202。","pitfall":"漏交叉项或把−√2平方成−2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"解√(x+2)=x，说明平方后的两个候选如何筛选。","given":"实数范围。","analysis":"右侧也必须非负。","method":"先x≥0，再平方并代回。","principle":"主根非负；平方可能引增根。","steps":["平方得x+2=x²，(x−2)(x+1)=0，候选2、−1。","x=2满足√4=2；x=−1时√1=1≠−1，排除。"],"ans":"x=2。","verification":"定义域x≥−2不够，等式还要求x≥0。","pitfall":"只检查被开方非负就保留−1。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]}],"practice":[{"q":"√50+2√8化简。","given":"常数非负。","analysis":"先化简再合并。","method":"√50=5√2，√8=2√2。","principle":"同类根式系数相加。","steps":["原式=5√2+4√2。","合9√2。"],"ans":"9√2。","verification":"平方或近似可核约12.728。","pitfall":"把2√8当√16。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"x<0、y≥0，化简√(4x²y)。","given":"给定符号范围。","analysis":"提出|x|再用x<0。","method":"2|x|√y。","principle":"主根非负。","steps":["√(4x²y)=2|x|√y。","x<0得−2x√y。"],"ans":"−2x√y。","verification":"x=−1、y=9时原6，结果6。","pitfall":"写2x√y为负。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"√(−2)√(−8)=√16=4在实数题中合法吗？","given":"两个单独根式负被开方数。","analysis":"左式无实数定义。","method":"核法则前提。","principle":"平方根乘法法则要求各被开方非负。","steps":["√(−2)、√(−8)在实数内无定义。","故不能用乘积为正挽救原式。"],"ans":"不合法。","verification":"若改讨论复数，运算约定也不能沿用该实数乘法结论。","pitfall":"只检查ab≥0而不查a,b本身。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"化简√((x−1)²)+√((x+1)²)的全实数分段式。","given":"原式所有实数有定义。","analysis":"绝对值符号在±1处改变。","method":"转为|x−1|+|x+1|分段。","principle":"主根和绝对值定义。","steps":["x<−1：1−x−x−1=−2x。","−1≤x≤1：1−x+x+1=2。","x>1：x−1+x+1=2x。"],"ans":"x<−1为−2x，中间为2，x>1为2x。","verification":"边界±1两侧都给2，连续且非负。","pitfall":"两个根号直接去掉得2x全域。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]}],"quiz":{"q":"“√(a+b)=√a+√b对a,b≥0都成立”，怎样用代数指出遗漏条件？","given":"两边有实数意义。","analysis":"平方右边出现交叉项。","method":"比较平方。","principle":"非负数相等可由平方等比较。","steps":["右边平方=a+b+2√ab。","要与左平方a+b相等，需ab=0；一般a,b都正时不成立。"],"ans":"一般错误；在a,b≥0且至少一个为0时才成立。","verification":"a=b=1给√2≠2。","pitfall":"根号对加法当作可分配。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]},"exam":["运算题先化简根式再合并同类，变量提出平方保留绝对值","含根式方程平方后一定回原式，符号约束比根号域更强时要列出","证明题用展开交叉项或反例，别用几个近似值替代"],"quick":["定义域","提出平方因子","同类项","交叉项","平方与增根"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.3","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.3","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"运算题先化简根式再合并同类，变量提出平方保留绝对值","method":"先x≥0，再平方并代回。","principle":"主根非负；平方可能引增根。","worked_example_index":2,"verification":"定义域x≥−2不够，等式还要求x≥0。","pitfall":"只检查被开方非负就保留−1。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“在定义域内化简与合并根式”的抽样复核：近似8.485−5.657+2.828≈5.656=4√2。；若出现“直接根号内72−32+8。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“保留绝对值并解释平方变形风险”的抽样复核：定义域x≥−2不够，等式还要求x≥0。；若出现“只检查被开方非负就保留−1。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"根号对加法当作可分配。","correction":"一般错误；在a,b≥0且至少一个为0时才成立。","verification":"a=b=1给√2≠2。"}],"illustration_spec":{"title":"根式运算的条件与交叉项","objects":["平方因子分解","√2同类项","完全平方交叉矩形","绝对值分段图","方程候选筛选"],"relations":["保留2ab交叉项","提出x²为绝对值","平方候选−1需排除"],"labels":["a,b≥0","√x²=|x|","2√ab","候选≠原解"],"format":"SVG","priority":"P=0","reuse":"无对应旧图；坐标和面积关系应确定性构图","english":"Illustrate extraction of square factors and like radicals, retain the 2ab cross term in a square-area model, and graph abs(x-1)+abs(x+1) with breakpoints -1 and 1. Show why squaring sqrt(x+2)=x gives an extraneous candidate -1 that must be rejected."}},"4.4":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":4,"section_id":"4.4","goals":["用共轭及乘法恒等式有理化","在等价变形中保留原定义域"],"prerequisites":["根式运算","平方差与分式"],"flow":["同乘非零因子","共轭平方差","单项根式","高次恒等式","原域保留"],"concept_relation":"同乘非零因子；共轭平方差；单项根式；高次恒等式；原域保留","deep":["有理化因式不止限平方根共轭，某些高次根可用相应乘法恒等式，例如立方根项用a³−b³关系。是否在具体课程与题目中要求哪种形式需按教材与题设，本节基础以平方根及清楚给定的立方差示例为主。","含变量的分母要把根式定义域和整个分母非零条件先写出。化简后的式子可能在原排除点有值，这不代表原式已定义；等价是在共同的原定义域内，不能擅自扩域。","有理化还可帮助比较接近数、计算差值或把嵌套根式化为较简表达，但不能为了形式短而引入数值不稳定或漏掉符号。是否最终必须有理化取决题目要求，数学上原式有意义即为一个合法表达。","检查结果用分母乘回、代值和极限辅助。若分母由正数构成而结果明显为负，要回查共轭符号；若化简得0/0，在原式定义与所乘因子条件之间寻找问题，而非立即把值设0。"],"derive":["a>0：1/√a=√a/a。","m,n≥0且m≠n时，1/(√m+√n)=(√m−√n)/(m−n)；m=n>0时应直接处理2√m。","(a−b)(a²+ab+b²)=a³−b³，可为特定立方根分母构造有理化因式。"],"examples":[{"q":"有理化3/√5。","given":"分母√5非零。","analysis":"同乘√5。","method":"分子分母乘同一非零量。","principle":"√5×√5=5。","steps":["3/√5=(3√5)/(√5√5)。","得到3√5/5。"],"ans":"3√5/5。","verification":"结果乘原分母√5得3。","pitfall":"只把分母改5而分子不变。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"有理化1/(√3+√2)并验符号。","given":"分母正且共轭非零。","analysis":"用平方差。","method":"同乘√3−√2。","principle":"(a+b)(a−b)=a²−b²。","steps":["分母变3−2=1。","结果√3−√2。"],"ans":"√3−√2。","verification":"约0.318，原1/(1.732+1.414)约0.318且为正。","pitfall":"把共轭差平方当3+2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"化简(√x−1)/(x−1)，写定义域并解释为何不能补x=1。","given":"实数平方根。","analysis":"分母可因式分解，取消需非零。","method":"x−1=(√x−1)(√x+1)。","principle":"等价约分保留原排除点。","steps":["原域x≥0且x≠1。","约去非零√x−1得1/(√x+1)。","新式在1处可算1/2，但原式仍0/0无定义。"],"ans":"1/(√x+1)，x≥0且x≠1。","verification":"x=4时原(2−1)/3=1/3，新式同；x=1仍排除。","pitfall":"约分后把可去间断点当原函数值。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]}],"practice":[{"q":"有理化2/(3√2)。","given":"常数分母非零。","analysis":"系数与根式分别处理。","method":"同乘√2再约分。","principle":"分式等价。","steps":["2√2/(3×2)=2√2/6。","约为√2/3。"],"ans":"√2/3。","verification":"乘3√2得2。","pitfall":"把3也平方成9。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"有理化1/(2−√3)。","given":"2−√3>0。","analysis":"同乘共轭2+√3。","method":"平方差。","principle":"4−3=1。","steps":["分子2+√3。","分母1，结果2+√3。"],"ans":"2+√3。","verification":"(2−√3)(2+√3)=1。","pitfall":"只改根号号不同时改完整因子。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"a>0，能对1/(√a+√a)同乘√a−√a吗？应怎样做？","given":"原分母2√a非零，共轭却0。","analysis":"所乘因子必须非零。","method":"先合并再单项有理化。","principle":"不能同乘0/0。","steps":["原式1/(2√a)。","乘√a/√a得√a/(2a)。"],"ans":"不能乘零共轭；结果√a/(2a)。","verification":"a=1时为1/2，与原相符。","pitfall":"把共轭法无条件用于相同根式。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"有理化1/(∛2−1)，给出乘因子并回乘。","given":"实数立方根，分母非零。","analysis":"使用立方差恒等式。","method":"设a=∛2，乘a²+a+1。","principle":"(a−1)(a²+a+1)=a³−1。","steps":["分母变2−1=1。","结果∛4+∛2+1。"],"ans":"∛4+∛2+1。","verification":"乘回∛2−1后中间项抵消得1。","pitfall":"仍用平方共轭却误认为分母已无根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]}],"quiz":{"q":"为何把1/(√x−1)有理化成(√x+1)/(x−1)后，定义域仍需x≥0且x≠1？","given":"两式都应在原域比较。","analysis":"平方根与分母限制不因变形消失。","method":"逐条保留条件。","principle":"同乘非零因子的等价变形。","steps":["x≥0使根式有意义。","x=1使原分母0；有理化式分母也0，不能以形式变化改变域。"],"ans":"因原定义条件必须保留。","verification":"x=0时原−1，新式1/(−1)=−1，边界0可取。","pitfall":"把分母含x−1就只写x≠1，漏根域。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]},"exam":["有理化题说明同乘因子并查非零，平方差符号写完整","变量题先写定义域，约分后保留原排除点","共轭为零的退化情况直接合并，不能机械除零"],"quick":["同乘非零因子","共轭平方差","单项根式","高次恒等式","原域保留"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"有理化题说明同乘因子并查非零，平方差符号写完整","method":"x−1=(√x−1)(√x+1)。","principle":"等价约分保留原排除点。","worked_example_index":2,"verification":"x=4时原(2−1)/3=1/3，新式同；x=1仍排除。","pitfall":"约分后把可去间断点当原函数值。"},"diagnostics":[{"goal_index":0,"question_ref":"e1","review_module":4,"feedback":"目标“用共轭及乘法恒等式有理化”的抽样复核：约0.318，原1/(1.732+1.414)约0.318且为正。；若出现“把共轭差平方当3+2。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“在等价变形中保留原定义域”的抽样复核：x=4时原(2−1)/3=1/3，新式同；x=1仍排除。；若出现“约分后把可去间断点当原函数值。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把分母含x−1就只写x≠1，漏根域。","correction":"因原定义条件必须保留。","verification":"x=0时原−1，新式1/(−1)=−1，边界0可取。"}],"illustration_spec":{"title":"有理化与原定义域","objects":["共轭乘法矩形","√3±√2","变量约分","x=1空点","立方差因式"],"relations":["分子分母同乘非零","平方差3−2=1","取消因子仍保留排除点"],"labels":["共轭","非零因子","x≥0且x≠1","1/(√x+1)","空点不是原函数值"],"format":"SVG","priority":"P=0","reuse":"暂无对应旧图；代数和函数空点需确定性SVG","english":"Show rationalization of 1/(sqrt(3)+sqrt(2)) by its nonzero conjugate. For (sqrt(x)-1)/(x-1), retain x>=0 and x!=1 after simplification to 1/(sqrt(x)+1), drawing an open point at x=1 rather than filling in the original undefined value."}}},"数学5":{"5.1":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":5,"section_id":"5.1","goals":["用定义域陪域与单值对应判断函数","把不同表示法转为可验证的输入输出规则"],"prerequisites":["集合与有序对","代数式求值"],"flow":["定义域A","单值对应","陪域B和值域","表示法","分段边界"],"concept_relation":"定义域A；单值对应；陪域B和值域；表示法；分段边界","deep":["函数可由解析式、列表、图象或文字规则表示，各自需说明范围。有限表格中未出现的输入不能随意插补；图象若无刻度与范围也不能冒充精确数据。一个有限样本可符合多个规则，不能自动确定唯一公式。","分段定义根据输入所在条件选择相应规则。区间应覆盖规定定义域，且重叠处若两规则不同会产生冲突。边界等号属于哪一段直接决定函数值，不能只看靠近哪一支曲线。","竖线检验用于判断平面关系能否表示y为x的函数：每条固定x的竖线与关系最多相交一点，且定义域内应有对应点。它不是水平线检验，后者与一对一性有关；圆整体通常不通过竖线检验，选上半圆可构成函数。","应用模型要写输入输出含义与单位，并核是否忽略了其他影响。把温度作为时间函数的实验记录，不表示所有年份同一时刻温度唯一相同；函数关系总是在指定系统、时段或规则中定义。"],"derive":["f:A→B：对每个x∈A，存在且仅存在一个f(x)∈B。","值域={f(x):x∈A}⊆B；多对一仍是函数。","f(a+1)按整体代入，分段函数按输入条件选择，重叠边界须一致或排除重叠。"],"examples":[{"q":"A={1,2,3}、B={a,b}，关系1→a、2→a、3→b是否为函数？若再加1→b呢？","given":"定义域与陪域明确。","analysis":"多对一允许，一对多不允许。","method":"逐个输入数输出。","principle":"函数每输入恰一个输出。","steps":["原关系每个A元素有一个B输出，成立。","再加1→b后输入1有a,b两个不同输出，不成立。"],"ans":"原是函数；加箭头后不是。","verification":"2与1同到a不违反单值。","pitfall":"误以不同输入不能共享输出。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"f(x)=2x²−3，求f(a+1)及f(a)+1，比较。","given":"a实数。","analysis":"括号位置改变代入。","method":"分别整体替换与输出加1。","principle":"函数求值定义。","steps":["f(a+1)=2(a+1)²−3=2a²+4a−1。","f(a)+1=2a²−2。"],"ans":"分别2a²+4a−1、2a²−2，通常不同。","verification":"a=0时为−1与−2，直接规则可核。","pitfall":"把f(a+1)自动写f(a)+1。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"在全实数域定义：x≤0时f=x+1，x≥0时f=2x+c，何时边界不冲突？","given":"两段都包含x=0。","analysis":"重叠点需同一输出。","method":"在0比较两规则。","principle":"函数单值性。","steps":["第一段在0输出1。","第二段输出c，需c=1；其他x不重叠。"],"ans":"c=1。","verification":"此时0两规则同得1；c≠1产生两个值。","pitfall":"认为分段函数边界重复无论如何都允许。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.1","related_sections":[]}],"practice":[{"q":"f(x)=3x−2，f(−1)是多少？","given":"输入是−1整体。","analysis":"代入而非乘f。","method":"3(−1)−2。","principle":"函数规则。","steps":["−3−2=−5。","输出为−5。"],"ans":"−5。","verification":"解3x−2=−5回得x=−1。","pitfall":"把负号漏掉。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"全圆x²+y²=1能否整体表示y=f(x)？","given":"定义域拟为[−1,1]。","analysis":"部分x有两个y。","method":"用x=0检查。","principle":"函数对每个x单值。","steps":["x=0给y=±1。","同输入两个输出，整体不是y的函数；可选单独上半支。"],"ans":"不能整体，需限制分支。","verification":"上半支y=√(1−x²)则可。","pitfall":"把一条连续图形就当函数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"表中只有f(1)=2、f(2)=4，能唯一推出对所有实数f(x)=2x吗？","given":"没有模型条件。","analysis":"有限点不足唯一确定。","method":"给另一个也过两点的规则。","principle":"多个函数可有同样样本。","steps":["g(x)=2x+(x−1)(x−2)也在1、2处同值。","其他输入如0时g(0)=2而2x=0。"],"ans":"不能唯一推出。","verification":"两个候选均满足已有数据。","pitfall":"把规律猜测当被数据唯一证明。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"f(x)=x²（x<1），f(x)=2x（x≥1），求f(1)、f(0)、f(2)。","given":"区间条件互斥覆盖R。","analysis":"等号归第二段。","method":"逐个判断所属区间。","principle":"分段求值。","steps":["1≥1，f(1)=2。","0<1，f(0)=0；2≥1，f(2)=4。"],"ans":"2、0、4。","verification":"靠近1左极限值1不等于点值2，不能替代。","pitfall":"边界1代入第一段。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.1","related_sections":[]}],"quiz":{"q":"f:R→R与g:[0,+∞)→R都用平方规则，它们一定是同一函数吗？","given":"规则相同，定义域不同。","analysis":"函数包含输入集合信息。","method":"比较允许输入。","principle":"定义域是函数身份的一部分。","steps":["f接受−1并输出1。","g不接受−1，因此作为函数不相同。"],"ans":"不是同一函数。","verification":"共同输入处可同值，不代表定义完全相同。","pitfall":"只看公式忽略定义域。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.1","related_sections":[]},"exam":["判断题逐个查输入有无遗漏和一对多，不把多对一误判","求值题用完整括号代入，分段边界先选规则","图表题区分已给数据与外推模型，单位和时段写清"],"quick":["定义域A","单值对应","陪域B和值域","表示法","分段边界"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_5.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/3-1-functions-and-function-notation","page_or_section":"3-1-functions-and-function-notation","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_5.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/3-1-functions-and-function-notation","page_or_section":"3-1-functions-and-function-notation","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"判断题逐个查输入有无遗漏和一对多，不把多对一误判","method":"在0比较两规则。","principle":"函数单值性。","worked_example_index":2,"verification":"此时0两规则同得1；c≠1产生两个值。","pitfall":"认为分段函数边界重复无论如何都允许。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用定义域陪域与单值对应判断函数”的抽样复核：2与1同到a不违反单值。；若出现“误以不同输入不能共享输出。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“把不同表示法转为可验证的输入输出规则”的抽样复核：此时0两规则同得1；c≠1产生两个值。；若出现“认为分段函数边界重复无论如何都允许。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"只看公式忽略定义域。","correction":"不是同一函数。","verification":"共同输入处可同值，不代表定义完全相同。"}],"illustration_spec":{"title":"函数的单值对应与边界","objects":["集合A/B箭头","多对一合法例","一对多非法例","分段边界","圆与上半圆"],"relations":["每输入恰一输出","值域包含于陪域","竖线检验不是水平线"],"labels":["定义域","陪域","值域","允许多对一","不允许一对多"],"format":"SVG","priority":"P=0","reuse":"暂无对应旧图；箭头对应须确定性构造","english":"Show A={1,2,3} mapping to B={a,b}, with 1 and 2 both mapping to a and 3 to b as a valid function. Contrast a conflicting second output for input 1. Separate vertical-line testing of a full circle from a valid upper semicircle and mark piecewise boundary ownership."}},"5.2":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":5,"section_id":"5.2","goals":["把代数限制与实际输入范围取交集","用结构和反解求值域并检查端点"],"prerequisites":["函数定义","不等式与配方"],"flow":["允许输入","限制交集","输出结构","可达与反解","端点并集"],"concept_relation":"允许输入；限制交集；输出结构；可达与反解；端点并集","deep":["端点开闭影响是否取到最值。x∈(0,2]时x²值域(0,4]，0是可接近的下界但未取到，不能写最小值0。无穷大不是可代入的普通端点，不写函数“取到无穷”。","平方或根号变换会隐藏符号约束。反解y=f(x)后应问每个候选y是否有至少一个合法x，而不只是代数上能写式；分母不得零、主根非负和给定域都要回查。","分段函数的值域是各段实际输出范围的并集，重叠部分只计一次，可能有间隙。图象读域看水平投影，读值域看竖直投影；空心点、孤立点和渐近线不能混作普通实点。","报告定义域和值域时使用清晰集合或区间，说明变量和数域。只给几个样本输出不是完整值域；给上界也不等于证明其间每个值都能达到，必要时通过反解构造合法输入。"],"derive":["实数代数域=各分母非零条件∩偶根非负条件∩题给范围。","二次函数a(x−h)²+k，结合a符号与x范围判断输出。","反解法：令y=f(x)，找满足全部原域条件的x；有合法原像的y才在值域。"],"examples":[{"q":"求f(x)=√(2x−1)/(x−3)的定义域。","given":"实数范围，未另指定。","analysis":"根号与分母双限制。","method":"2x−1≥0且x−3≠0。","principle":"代数有意义条件。","steps":["x≥1/2。","排除x=3，得[1/2,3)∪(3,+∞)。"],"ans":"[1/2,3)∪(3,+∞)。","verification":"1/2根0可，3分母0不可。","pitfall":"只查根号或把3保留。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"f(x)=(x−2)²+1，定义域[0,3]，求值域。","given":"顶点x=2在域内。","analysis":"先看最小，再比端点最大。","method":"平方结构。","principle":"平方非负，闭区间端点及顶点。","steps":["最小值1在x=2。","端点f(0)=5、f(3)=2，最大5；连续平方变化覆盖其间。"],"ans":"[1,5]。","verification":"x距2最大为2、最小0，平方范围[0,4]再加1。","pitfall":"只按两端值得[2,5]而漏顶点。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"f(x)=1/(x−1)，定义域R去掉1，求值域并证明每个允许值可达。","given":"分母非零。","analysis":"倒数不能0，其他值可反解。","method":"y=1/(x−1)反求x。","principle":"有合法原像才可达。","steps":["y≠0时x=1+1/y，且x≠1。","因此每个非零y都有合法输入；y=0不可能。"],"ans":"R去掉0。","verification":"代回1/[(1+1/y)−1]=y。","pitfall":"把水平渐近线y=0当已取到。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.2","related_sections":[]}],"practice":[{"q":"f(x)=√(4−x²)定义域和值域。","given":"实主根。","analysis":"圆上半支，先域再输出。","method":"4−x²≥0，根非负。","principle":"平方与主根。","steps":["−2≤x≤2。","0≤4−x²≤4，根值[0,2]。"],"ans":"域[−2,2]，值域[0,2]。","verification":"x=±2取0，x=0取2。","pitfall":"把值域写[−2,2]。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"x∈(0,2]，f=x²，值域有最小值吗？","given":"仅正输入，左端开。","analysis":"下界0未取到。","method":"单调平方。","principle":"开端点不可自动取。","steps":["输出大于0且不超过4。","值域(0,4]，没有最小值，最大4。"],"ans":"(0,4]，无最小值。","verification":"任意正x可取更小正输入得到更小输出。","pitfall":"把下确界0叫最小值。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"x表示长方形一边，周长20，面积A=x(10−x)，实际定义域？","given":"两边均为正长度。","analysis":"实际域比所有实数小。","method":"x>0且10−x>0。","principle":"长度正约束。","steps":["x>0，x<10。","故(0,10)，面积最大25在x=5。"],"ans":"实际域(0,10)。","verification":"x=0或10退化不为通常长方形。","pitfall":"只因多项式可算就答R。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"f=x+1（0≤x<1），f=4−x（1≤x≤2），求值域。","given":"两段域按题给。","analysis":"分别求输出再并集。","method":"端点开闭逐段。","principle":"分段输出范围并集。","steps":["第一段[1,2)。","第二段x从1到2，输出[2,3]。","并为[1,3]。"],"ans":"[1,3]。","verification":"2虽第一段未取到，却第二段x=2取到。","pitfall":"看到一个空端点就把整个并集2删除。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.2","related_sections":[]}],"quiz":{"q":"陪域B=R，f:R→R且f=x²，能否说值域R？","given":"函数输入全实数。","analysis":"陪域只是允许输出集合。","method":"由平方非负与可达性求。","principle":"值域为实际输出。","steps":["所有输出≥0。","任意y≥0取x=√y可达，故值域[0,+∞)。"],"ans":"不能，值域非负实数。","verification":"负y无实平方原像。","pitfall":"把箭头后的集合直接当值域。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.2","related_sections":[]},"exam":["域题把每个代数/情境限制列出取交集","值域题同时证明界限与可达，注意顶点是否在输入区间","端点题区分下界与最小值，分段范围最后取并集"],"quick":["允许输入","限制交集","输出结构","可达与反解","端点并集"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_5.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/3-2-domain-and-range","page_or_section":"3-2-domain-and-range","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_5.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/3-2-domain-and-range","page_or_section":"3-2-domain-and-range","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"域题把每个代数/情境限制列出取交集","method":"y=1/(x−1)反求x。","principle":"有合法原像才可达。","worked_example_index":2,"verification":"代回1/[(1+1/y)−1]=y。","pitfall":"把水平渐近线y=0当已取到。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“把代数限制与实际输入范围取交集”的抽样复核：1/2根0可，3分母0不可。；若出现“只查根号或把3保留。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用结构和反解求值域并检查端点”的抽样复核：代回1/[(1+1/y)−1]=y。；若出现“把水平渐近线y=0当已取到。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把箭头后的集合直接当值域。","correction":"不能，值域非负实数。","verification":"负y无实平方原像。"}],"illustration_spec":{"title":"定义域与值域的端点","objects":["二次函数顶点与[0,3]域","倒数函数空缺","分段输出范围","开闭端点"],"relations":["(x−2)²+1值域[1,5]","倒数值域不含0","空端点与渐近线不当实点"],"labels":["定义域","值域","顶点(2,1)","空心点","y≠0"],"format":"SVG","priority":"P=0","reuse":"暂无对应图；函数必须数学绘图库或SVG准确绘制","english":"Plot y=(x-2)^2+1 restricted to [0,3], with vertex (2,1) and range [1,5]. Separately plot y=1/(x-1) with asymptotes x=1 and y=0, and use correct open/closed endpoints when projecting domains and ranges."}},"5.3":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":5,"section_id":"5.3","goals":["由关键点与定义域画函数图","用点坐标映射解释平移伸缩和反射"],"prerequisites":["坐标系","基本函数与绝对值"],"flow":["基本图形","关键点","纵向变换","横向反解","定义域同步"],"concept_relation":"基本图形；关键点；纵向变换；横向反解；定义域同步","deep":["g(x)=a f(x)改变纵坐标为a y₀，a<0还关于x轴反射；g(x)=f(bx)使横坐标变为x₀/b，b<0还关于y轴反射。横向伸缩倍数是1/|b|，不是|b|，因为要反解内层输入。","对g(x)=a f(b(x−h))+k，b≠0，原点映为(h+x₀/b,k+a y₀)。先把内式写成b(x−h)再读平移；f(2x−6)中的h是3而非6，顺序与括号不能忽略。","变换会同时改变定义域和值域。横向变化映射输入限制，纵向变化映射实际输出范围；若a=0图象退为常数但原复合表达式的输入限制仍应按题目定义处理，不能随意补入原f无定义的输入。","验证图象可用变换后的关键点、截距和范围三重检查。比例尺必须标明，纵横轴刻度不同比例时，肉眼角度或曲率不具有直接数值意义。精确图象应按坐标和定义域绘制，草图不能替代代数条件。"],"derive":["g(x)=f(x−h)+k：(x₀,y₀)→(x₀+h,y₀+k)。","g(x)=a f(b(x−h))+k，b≠0：(x₀,y₀)→(h+x₀/b,k+a y₀)。","先因式提出内层b，例如2x−6=2(x−3)；再变换定义域、值域与空点。"],"examples":[{"q":"由y=x²描述y=(x−2)²−3的顶点、对称轴和值域，并给两个对称点。","given":"定义域R。","analysis":"从基本抛物线平移。","method":"右2下3。","principle":"点坐标映射。","steps":["顶点(0,0)变(2,−3)，轴x=2。","开口仍向上，值域[−3,+∞)；原点(±1,1)变(1,−2)、(3,−2)。"],"ans":"顶点(2,−3)，轴2，值域非小于−3。","verification":"x=1和3代式均−2。","pitfall":"写向左2或只平移图不改范围。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"y=|x|改为y=−2|x|+1，顶点和点(2,2)怎样变？值域？","given":"定义域R。","analysis":"负系数反射并纵向伸长。","method":"y新=−2y旧+1。","principle":"纵坐标变换。","steps":["顶点变(0,1)。","点(2,2)变(2,−3)，图开口向下，值域(−∞,1]。"],"ans":"顶点(0,1)、点(2,−3)，最大1。","verification":"x=2代式−4+1=−3。","pitfall":"把−2当横向伸缩。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"原y=f(x)经过(6,5)，求y=−2f(3(x−1))+4对应点，并说明内层条件。","given":"只要求此原点对应新点。","analysis":"新输入须使3(x−1)=6。","method":"反解横坐标，映射纵坐标。","principle":"复合变换的坐标对应。","steps":["x−1=2，x=3。","y=−2×5+4=−6。"],"ans":"(3,−6)。","verification":"新式在x=3取f(6)=5，与给定原点一致。","pitfall":"把横坐标算成6×3+1=19。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.3","related_sections":[]}],"practice":[{"q":"y=f(x+4)相对原图移向哪里？","given":"同一纵值对应原输入x₀。","analysis":"解x+4=x₀。","method":"x新=x₀−4。","principle":"输入关系反解。","steps":["原x₀变x₀−4。","向左4。"],"ans":"向左4单位。","verification":"原点x=0对应新x−4。","pitfall":"见+4就向右。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"y=f(2x−6)应读作向右6吗？","given":"先组织内层。","analysis":"系数影响平移读法。","method":"2x−6=2(x−3)。","principle":"反解输入。","steps":["原x₀对应x=3+x₀/2。","横向缩为1/2并按该表达向右3。"],"ans":"不能，平移参数为3。","verification":"原输入0对应新x=3而非6。","pitfall":"不先提出2就读常数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"原函数域[−2,4]，g(x)=f(x−1)，求g域。","given":"内层必须在原域。","analysis":"输入范围随平移。","method":"−2≤x−1≤4。","principle":"复合定义。","steps":["两边加1。","−1≤x≤5。"],"ans":"[−1,5]。","verification":"端点分别映原−2、4。","pitfall":"图右移但域也错向左移。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"原图点(−3,2)，g(x)=f(−x/3)+5，对应点？","given":"内层系数−1/3。","analysis":"反射与横向伸长。","method":"−x/3=−3，纵加5。","principle":"坐标映射。","steps":["x=9。","y=2+5=7。"],"ans":"(9,7)。","verification":"新x=9内层−3，正确回到原点。","pitfall":"横坐标乘−1/3得到1。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.3","related_sections":[]}],"quiz":{"q":"画y=1/x时能把原点作为两支连接点吗？","given":"域排除0。","analysis":"渐近趋势不是函数值。","method":"核定义域与曲线位置。","principle":"1/0无定义。","steps":["x=0不在图上。","正负两支应分开，坐标轴是相应渐近线，不可用连线穿原点。"],"ans":"不能。","verification":"任意有限非零x的y也非0。","pitfall":"为使图连续好看补点或连线。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.3","related_sections":[]},"exam":["变换题从原点坐标反解新输入，不靠左右口诀","内层先写b(x−h)，再读横向倍数和反射","绘图题核关键点、域和值域及空点，不能沿用旧图范围"],"quick":["基本图形","关键点","纵向变换","横向反解","定义域同步"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_5.3","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/3-5-transformation-of-functions","page_or_section":"3-5-transformation-of-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_5.3","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/3-5-transformation-of-functions","page_or_section":"3-5-transformation-of-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"变换题从原点坐标反解新输入，不靠左右口诀","method":"反解横坐标，映射纵坐标。","principle":"复合变换的坐标对应。","worked_example_index":2,"verification":"新式在x=3取f(6)=5，与给定原点一致。","pitfall":"把横坐标算成6×3+1=19。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由关键点与定义域画函数图”的抽样复核：x=1和3代式均−2。；若出现“写向左2或只平移图不改范围。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用点坐标映射解释平移伸缩和反射”的抽样复核：新式在x=3取f(6)=5，与给定原点一致。；若出现“把横坐标算成6×3+1=19。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"为使图连续好看补点或连线。","correction":"不能。","verification":"任意有限非零x的y也非0。"}],"illustration_spec":{"title":"函数变换的点映射","objects":["基本抛物线","平移后抛物线","点(6,5)映射","内层输入方程","定义域区间"],"relations":["顶点(2,−3)","3(x−1)=6得x=3","纵坐标−2×5+4=−6","横向缩放1/|b|"],"labels":["y=x²","y=(x−2)²−3","(3,−6)","x新=h+x旧/b"],"format":"SVG","priority":"P=0","reuse":"无对应旧图；必须函数绘图库确定曲线","english":"Plot y=x^2 and y=(x-2)^2-3 on consistent labelled axes, marking vertex (2,-3) and symmetric points (1,-2),(3,-2). Separately map (6,5) on f to (3,-6) on -2f(3(x-1))+4, solving the inner-input equation rather than multiplying horizontal coordinates by 3."}},"5.4":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":5,"section_id":"5.4","goals":["按输入顺序求合成函数","在化简后仍保留内外层定义域条件"],"prerequisites":["函数求值","根式与分母限制"],"flow":["执行顺序","整体代入","内层域","外层输入条件","同式同域比较"],"concept_relation":"执行顺序；整体代入；内层域；外层输入条件；同式同域比较","deep":["解析式代入应把内层表达式整体放进外层每个x的位置，括号尤其重要。外层若含平方、分母或根号，内层各部分不能拆开分别运算；先保持组合结构再化简更稳妥。","多个合成可按输入路径逐层做，合成在对应域允许时具有结合性，但这不改变各层合法输入的要求。用箭头x→g(x)→f(g(x))比一口气展开更容易定位哪层越域。","应用模型可以把单位转换、费用规则或几何计算串联，但每一步的单位要与下一步输入匹配。内层输出为长度，外层却按面积公式的输入含义使用时需核定义，不可只因数字可代就认为模型有效。","验证合成式时选合法样本逐层计算，与化简式比对，并检查被排除的点。若化简得到简单直线，原来因内层无定义排除的x仍可能形成空点；不能将代数简洁当作自动扩域授权。"],"derive":["(f∘g)(x)=f(g(x))，执行顺序x→g→f。","D_(f∘g)={x∈D_g:g(x)∈D_f}。","若合成化简中约去因子，仍保留各层原定义限制；相同表达式但域不同不一定是同一函数。"],"examples":[{"q":"f(x)=2x+1，g(x)=x²，求f∘g与g∘f，并在x=2比较。","given":"两函数全实数域。","analysis":"顺序不同。","method":"整体代入外层。","principle":"合成定义。","steps":["f(g(x))=2x²+1，x=2给9。","g(f(x))=(2x+1)²，x=2给25。"],"ans":"2x²+1与(2x+1)²，通常不同。","verification":"逐层2→4→9与2→5→25。","pitfall":"把合成写(2x+1)x²。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.4","related_sections":[]},{"q":"f(x)=√x，g(x)=1/(x−2)，求两个顺序的合成域。","given":"各取实数最大代数域。","analysis":"分别核内层域与外层输入。","method":"对f∘g要求1/(x−2)≥0；对g∘f要求√x≠2。","principle":"合成域的双条件。","steps":["f∘g=√[1/(x−2)]，x≠2且商非负，得x>2。","g∘f=1/(√x−2)，要求x≥0且x≠4。"],"ans":"前域(2,+∞)；后域[0,4)∪(4,+∞)。","verification":"x=0只对后者可得−1/2，对前者根内负。","pitfall":"只看外层或把两个顺序的域相同。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.4","related_sections":[]},{"q":"f(x)=1/x，g(x)=1/(x−1)，化简f∘g并写域。","given":"f域x≠0、g域x≠1。","analysis":"化简会隐藏g的排除点。","method":"先列x≠1且g(x)≠0。","principle":"合成输入限制。","steps":["g在x≠1时永不为0。","f(g(x))=1/[1/(x−1)]=x−1，但仍x≠1。"],"ans":"x−1，定义域R去掉1。","verification":"x=2时逐层1→1与化简1一致；x=1原g无定义。","pitfall":"看到直线就把域改回R。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.4","related_sections":[]}],"practice":[{"q":"f(x)=x−3，g(x)=4x，求f(g(2))。","given":"顺序从内到外。","analysis":"先算g(2)。","method":"g(2)=8。","principle":"合成求值。","steps":["g(2)=8。","f(8)=5。"],"ans":"5。","verification":"f∘g=4x−3，x=2为5。","pitfall":"先f(2)再g得到−4。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.4","related_sections":[]},{"q":"f(x)=x²+1，g(x)=x−2，求f(g(x))。","given":"全实数域。","analysis":"代入完整括号。","method":"(x−2)²+1。","principle":"函数规则。","steps":["平方展开x²−4x+4。","加1得x²−4x+5。"],"ans":"x²−4x+5。","verification":"x=0逐层−2再5，与式同。","pitfall":"写x²−2+1而不平方整个内层。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.4","related_sections":[]},{"q":"f域[0,4]且f(x)=√x，g=x+1，合成f∘g域？","given":"g全实数，但外层有给定域。","analysis":"内层值须0至4。","method":"0≤x+1≤4。","principle":"合成域条件。","steps":["减1得−1≤x≤3。","端点内层0、4均合法。"],"ans":"[−1,3]。","verification":"不能只用√(x+1)代数域x≥−1忽略外层上界4。","pitfall":"仅查根号而漏题给域。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.4","related_sections":[]},{"q":"摄氏温度C=5(F−32)/9，模型费用H(C)=2C+10，求H(C(F))并说明不能把函数名直接相乘。","given":"仅作给定代数模型，不保证负费用现实适用。","analysis":"先换温度后代费用。","method":"整体代入。","principle":"合成串联及单位解释。","steps":["H=2×5(F−32)/9+10。","=10(F−32)/9+10；实际适用温区需题给。"],"ans":"10(F−32)/9+10。","verification":"F=32时C0、H10，与式一致。","pitfall":"将H×C当合成或忽略适用温区。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.4","related_sections":[]}],"quiz":{"q":"两合成函数化简表达式一样，能否不比较定义域就宣布相同？","given":"可能存在隐藏排除点。","analysis":"函数身份包括域。","method":"核每层限制。","principle":"同式同域才具相同输入输出定义。","steps":["一个可在某点计算而另一个原层无定义时，二者不同。","如1/[1/(x−1)]与x−1，在1的域不同。"],"ans":"不能。","verification":"x=1是区分反例。","pitfall":"只比较展开式。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.4","related_sections":[]},"exam":["合成题先画执行顺序，内层输出是外层输入","域题同时列内层合法与输出落外层域，再化简","比较题同时核顺序、式子和域，不凭偶然相等推广交换律"],"quick":["执行顺序","整体代入","内层域","外层输入条件","同式同域比较"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_5.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/3-4-composition-of-functions","page_or_section":"3-4-composition-of-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_5.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/3-4-composition-of-functions","page_or_section":"3-4-composition-of-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"合成题先画执行顺序，内层输出是外层输入","method":"先列x≠1且g(x)≠0。","principle":"合成输入限制。","worked_example_index":2,"verification":"x=2时逐层1→1与化简1一致；x=1原g无定义。","pitfall":"看到直线就把域改回R。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按输入顺序求合成函数”的抽样复核：逐层2→4→9与2→5→25。；若出现“把合成写(2x+1)x²。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“在化简后仍保留内外层定义域条件”的抽样复核：x=2时逐层1→1与化简1一致；x=1原g无定义。；若出现“看到直线就把域改回R。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"只比较展开式。","correction":"不能。","verification":"x=1是区分反例。"}],"illustration_spec":{"title":"合成函数的顺序与域","objects":["x→g→f流程","反向流程对照","根号与倒数门槛","化简直线空点"],"relations":["f∘g先g后f","x∈Dg且g(x)∈Df","1/[1/(x−1)]简化后仍排除1"],"labels":["内层","外层","Dg","Df","x≠1空点"],"format":"SVG","priority":"P=0","reuse":"暂无对应旧图；映射箭头和函数空点须精确","english":"Draw x flowing through g then f, distinct from the reversed order. State both domain tests x in Dg and g(x) in Df. For f(x)=1/x and g(x)=1/(x-1), show the simplified line y=x-1 with an open point at x=1, not a fully defined straight line."}},"5.5":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":5,"section_id":"5.5","goals":["按定义判断单射映成及双射","解释定义域陪域改变怎样影响性质"],"prerequisites":["函数与值域","方程解的唯一性"],"flow":["函数单值","单射唯一原像","映成覆盖","双射","集合与参数"],"concept_relation":"函数单值；单射唯一原像；映成覆盖；双射；集合与参数","deep":["水平线检验检验单射：同一水平线若与图象多处相交，说明不同输入共用输出。竖线检验只判断是否为y关于x的函数，两者不可混淆。图中未显示完整域时，仅凭局部水平线情况也不能证明全域单射。","可用代数证明单射与映成。单射从相等输出推出输入相等；映成从任意y属于陪域出发，构造合法x使f(x)=y，并检查x在定义域。只验证几个值不能证明对全部元素成立。","有限集合且定义域陪域元素数相同的函数中，单射与映成可互相推出，因为没有重复就必须覆盖所有位置；这依有限等势条件，不能无条件推广所有无限集函数。","参数改变可使函数性质退化。例如f(x)=ax+b由R到R，a≠0时可唯一反解x=(y−b)/a而为双射；a=0时常值，不单射也不映成R。若陪域改为单元素{b}，映成结论又会变，显示参数与集合都重要。"],"derive":["单射：f(x₁)=f(x₂)⇒x₁=x₂；映成：对任意y∈B有x∈A使f(x)=y。","双射=单射且映成；实际值域B′满足B′⊆B。","线性f:R→R、f=ax+b，a≠0时任意y唯一原像x=(y−b)/a；a=0另论。"],"examples":[{"q":"f:R→R，f=x²，是否单射、映成或双射？若把域陪域都改为[0,+∞)呢？","given":"先后比较两组定义。","analysis":"公式不变集合变。","method":"用±1反例和任意非负y的根。","principle":"单射与映成定义。","steps":["R→R时f(1)=f(−1)=1故非单射，负y无原像故非映成。","[0,+∞)→[0,+∞)时平方严格保持正向大小，且任意y≥0由x=√y得到，为双射。"],"ans":"前者两者皆非；后者双射。","verification":"非负域排除负根，输出覆盖全部非负数。","pitfall":"只看x²公式给固定性质标签。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.5","related_sections":[]},{"q":"A={1,2,3}、B={a,b}，1→a、2→a、3→b，判断。","given":"关系已为函数。","analysis":"覆盖与重复分开检查。","method":"看B是否全被到达及输入是否共享。","principle":"满射允许一个输出有多个原像。","steps":["a,b均有原像，映成。","1、2共享a，不单射，因此不双射。"],"ans":"映成但非一对一。","verification":"函数单值仍满足，不与非单射矛盾。","pitfall":"把满射误认为每个输出恰一个原像。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.5","related_sections":[]},{"q":"f:R→R，f=ax+b，讨论a何时使其一一映成，并给一般反解。","given":"a,b实数。","analysis":"斜率为0是退化点。","method":"a≠0时解y=ax+b。","principle":"任意输出唯一原像证明双射。","steps":["a≠0时x=(y−b)/a为唯一实数，故双射。","a=0时所有输入到b，非单射且不能覆盖R。"],"ans":"恰在a≠0时双射。","verification":"把反解代入a(y−b)/a+b=y。","pitfall":"不分a=0就除以a。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.5","related_sections":[]}],"practice":[{"q":"通过竖线检验能保证一对一吗？","given":"只知y是x的函数。","analysis":"竖线与水平线问题不同。","method":"用y=x²反例。","principle":"单值不等于单射。","steps":["抛物线每x一个y。","水平y=1有x=±1两个原像，非单射。"],"ans":"不能。","verification":"满足函数定义却不满足单射。","pitfall":"把两种检验混用。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.5","related_sections":[]},{"q":"f:[0,+∞)→R，f=x²，单射且映成吗？","given":"域已限制、陪域仍R。","analysis":"去重不等于覆盖负数。","method":"分别检查。","principle":"单射与满射独立条件。","steps":["非负输入平方单射。","输出仍非负，负陪域元素无原像，不映成。"],"ans":"单射但不映成R。","verification":"若陪域改非负才双射。","pitfall":"限制域后自动说双射。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.5","related_sections":[]},{"q":"A、B均有3元素，函数已知单射，是否映成？","given":"有限且元素数相同。","analysis":"三个不同输出占满三个位置。","method":"有限计数。","principle":"等势有限集下单射蕴含满射。","steps":["3输入必须到3不同B元素。","B仅3个元素，故全覆盖。"],"ans":"是。","verification":"若B有4个元素，结论不再由此保证。","pitfall":"忘记有限且同样多的条件。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.5","related_sections":[]},{"q":"f:R→R，f=3x−2，用定义证明一对一并证明映成。","given":"全实数域陪域。","analysis":"两性质需两段论证。","method":"相等输出比较，任意y构造输入。","principle":"单射与满射定义。","steps":["3x₁−2=3x₂−2得x₁=x₂，单射。","任意y取x=(y+2)/3∈R，f(x)=y，映成。"],"ans":"双射。","verification":"两个证明都不依有限样本。","pitfall":"只说图是斜线而未说明覆盖及唯一。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.5","related_sections":[]}],"quiz":{"q":"将f:R→R、f=x²的陪域改为[0,+∞)，是否已经使它双射？","given":"定义域仍全实数。","analysis":"改陪域只修复覆盖，未去掉多对一。","method":"分别重查两个定义。","principle":"单射由输入共享输出决定。","steps":["非负陪域均有平方根原像，满射。","±1仍同到1，非单射，所以非双射。"],"ans":"不是，只成为映成。","verification":"要再限制域到非负或非正等适当区间。","pitfall":"把一次集合修改当全部问题解决。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.5","related_sections":[]},"exam":["性质题写清A、B再分别判单射与映成","证明单射从相等输出推输入，证明映成从任意y构造合法x","参数题先分可除与不可除情境，图形检验不能替代未显示全域"],"quick":["函数单值","单射唯一原像","映成覆盖","双射","集合与参数"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_5.5","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/3-7-inverse-functions","page_or_section":"3-7-inverse-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_5.5","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/3-7-inverse-functions","page_or_section":"3-7-inverse-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"性质题写清A、B再分别判单射与映成","method":"a≠0时解y=ax+b。","principle":"任意输出唯一原像证明双射。","worked_example_index":2,"verification":"把反解代入a(y−b)/a+b=y。","pitfall":"不分a=0就除以a。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“按定义判断单射映成及双射”的抽样复核：把反解代入a(y−b)/a+b=y。；若出现“不分a=0就除以a。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e0","review_module":5,"feedback":"目标“解释定义域陪域改变怎样影响性质”的抽样复核：非负域排除负根，输出覆盖全部非负数。；若出现“只看x²公式给固定性质标签。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把一次集合修改当全部问题解决。","correction":"不是，只成为映成。","verification":"要再限制域到非负或非正等适当区间。"}],"illustration_spec":{"title":"单射、映成与双射对照","objects":["四种有限映射图","平方函数不同域陪域","水平线检验","线性参数分支"],"relations":["多输入同输出可仍为函数","满射需覆盖陪域","双射同时覆盖且唯一"],"labels":["一对一/单射","映成/满射","一一映成/双射","值域=陪域","a≠0"],"format":"SVG","priority":"P=0","reuse":"暂无对应图；每个箭头必须核对定义","english":"Construct separate finite-set diagrams for injective-only, surjective-only, bijective and neither, with exactly one outgoing arrow per domain element. Compare x^2 on R versus nonnegative domains/codomains, and distinguish horizontal-line testing from vertical-line testing."}},"5.6":{"content_batch":"batch05","subject":"数学","subject_code":"math_shared","chapter_id":5,"section_id":"5.6","goals":["在一一对应范围内求反函数","交换定义域值域并用合成和对称验证"],"prerequisites":["合成函数","双射与解方程"],"flow":["双射与反向","解出原输入","分支","域值域交换","双向合成与对称"],"concept_relation":"双射与反向；解出原输入；分支；域值域交换；双向合成与对称","deep":["平方函数在全实数域不单射，反向给±√y不能作为单值反函数。限制原域到非负时反函数为√x，限制到非正则为−√x；选择分支由原域决定，不能永远取正根。","原函数定义域成为反函数值域，原值域成为反函数定义域。即使式子简单，也不能把题给有限区间随意扩大，例如f(x)=2x+3在[0,2]上反函数域仅[3,7]。","图象上点(a,b)与反向点(b,a)关于y=x对称。因此图形可辅助检查域和值域、端点与空点，但必须在一致比例坐标轴上比较。对称不表示每点落在y=x，两个函数交点或不动点需另分析。","最终用两个方向的合成在各自合法域验证，再检查取值范围。只验一个数或只化简一个方向不能替代域的完整核对，尤其有理式约分和平方根分支容易隐藏错误。"],"derive":["f:A→B双射时，f⁻¹:B→A，f⁻¹∘f=id_A，f∘f⁻¹=id_B。","求法：y=f(x) → 在原域解x → 交换字母 → 标反函数域和值域 → 双向合成验证。","原图(a,b)反射为(b,a)，对称轴y=x；f⁻¹(x)≠1/f(x)一般成立。"],"examples":[{"q":"f(x)=2x+3，原域[0,2]，求反函数及其域值域。","given":"线性递增且单射。","analysis":"先求原实际输出区间。","method":"y=2x+3反解x。","principle":"反向对应交换域和值域。","steps":["原值域[3,7]。","x=(y−3)/2，故f⁻¹(x)=(x−3)/2，域[3,7]、值域[0,2]。"],"ans":"(x−3)/2，域[3,7]。","verification":"f⁻¹(3)=0、f⁻¹(7)=2，合成还原输入。","pitfall":"只给式不保留区间。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.6","related_sections":[]},{"q":"f(x)=(2x+1)/(x−3)，域R去掉3，求反函数并写域。","given":"原为分式线性，需排除输出2。","analysis":"反解后检查分母。","method":"y(x−3)=2x+1。","principle":"一一反解与域交换。","steps":["x(y−2)=3y+1，x=(3y+1)/(y−2)，y≠2。","反函数f⁻¹(x)=(3x+1)/(x−2)，域x≠2，值域去3。"],"ans":"(3x+1)/(x−2)，x≠2。","verification":"双向合成得到原输入；反式不能取3，因为方程3x+1=3(x−2)无解。","pitfall":"把原排除3照抄为反函数排除。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.6","related_sections":[]},{"q":"f(x)=(x−2)²+1，原域x≤2，求反函数并验一个点。","given":"原取抛物线左支。","analysis":"解平方需按原域选负分支。","method":"y−1=(x−2)²且x−2≤0。","principle":"主根非负与分支条件。","steps":["x−2=−√(y−1)，x=2−√(y−1)。","f⁻¹(x)=2−√(x−1)，域x≥1、值域x≤2。"],"ans":"2−√(x−1)，输入≥1。","verification":"原x=−1时f=10，反函数10→2−3=−1。","pitfall":"不看左支而选2+√(x−1)。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.6","related_sections":[]}],"practice":[{"q":"f(x)=x+4全实数域，f⁻¹(x)与1/f(x)各是什么？","given":"区分两种记号。","analysis":"反操作与倒数不同。","method":"反解与分式分别写。","principle":"逆函数合成还原。","steps":["f⁻¹(x)=x−4，全实数。","1/f(x)=1/(x+4)，x≠−4。"],"ans":"x−4与1/(x+4)。","verification":"f(f⁻¹(x))=x而f(x)×1/f(x)=1。","pitfall":"把上标−1按普通幂处理。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.6","related_sections":[]},{"q":"f(x)=x²，域x≥0，反函数？若原域x≤0又怎样？","given":"两个单射分支。","analysis":"原输入符号决定反向输出。","method":"解x²=y并选支。","principle":"反函数值域等于原域。","steps":["非负原域选+√y。","非正原域选−√y；两者反函数域均y≥0。"],"ans":"分别√x和−√x，输入均非负。","verification":"原−3在非正支对应9，反向必须回−3。","pitfall":"两个分支都默认正根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.6","related_sections":[]},{"q":"原函数点(2,7)在反函数图上对应哪点？","given":"反向输入输出。","analysis":"交换坐标。","method":"(a,b)→(b,a)。","principle":"关于y=x反射。","steps":["原输入2输出7。","反输入7输出2，点(7,2)。"],"ans":"(7,2)。","verification":"与y=x镜像，距离对称。","pitfall":"只把y变号当反函数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.6","related_sections":[]},{"q":"f(x)=3x−1全实数，候选g=(x+1)/3，双向验证。","given":"两个线性式全域可算。","analysis":"两个合成分别核。","method":"求f(gx)、g(fx)。","principle":"反函数定义。","steps":["f(gx)=3(x+1)/3−1=x。","g(fx)=(3x−1+1)/3=x。"],"ans":"g为f反函数。","verification":"域值域均R，未漏排除点。","pitfall":"只验g(1)之类单点就证明。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.6","related_sections":[]}],"quiz":{"q":"x²全实数域画成y=±√x的反向关系，为什么不能称单一反函数？","given":"原域没有限制。","analysis":"一个非负输入可有两个反向输出。","method":"以输入4检查。","principle":"函数需单值，原函数需单射才能反向单值。","steps":["反向4可对应2或−2。","必须限制原域选分支，才有反函数。"],"ans":"反向关系非单值函数。","verification":"0是特殊单值点不挽救其他输入冲突。","pitfall":"把正负两个分支同时叫一个函数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":5,"primary_section":"5.6","related_sections":[]},"exam":["反函数题先判单射及实际值域，再反解选支","式子写完同步交换域值域，排除点不是照抄","验证题双向合成并核域，图象用y=x反射而非变号"],"quick":["双射与反向","解出原输入","分支","域值域交换","双向合成与对称"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_5.6","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/3-7-inverse-functions","page_or_section":"3-7-inverse-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_5.6","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/3-7-inverse-functions","page_or_section":"3-7-inverse-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"反函数题先判单射及实际值域，再反解选支","method":"y−1=(x−2)²且x−2≤0。","principle":"主根非负与分支条件。","worked_example_index":2,"verification":"原x=−1时f=10，反函数10→2−3=−1。","pitfall":"不看左支而选2+√(x−1)。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“在一一对应范围内求反函数”的抽样复核：f⁻¹(3)=0、f⁻¹(7)=2，合成还原输入。；若出现“只给式不保留区间。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“交换定义域值域并用合成和对称验证”的抽样复核：原x=−1时f=10，反函数10→2−3=−1。；若出现“不看左支而选2+√(x−1)。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把正负两个分支同时叫一个函数。","correction":"反向关系非单值函数。","verification":"0是特殊单值点不挽救其他输入冲突。"}],"illustration_spec":{"title":"反函数与定义域值域交换","objects":["线性受限函数及反函数","抛物线左支","反向根式","y=x对称轴","空点"],"relations":["(2,7)到(7,2)","原左支反式2−√(x−1)","原域与反值域交换","倒数另论"],"labels":["f⁻¹","不是1/f","y=x","x≤2","反域x≥1"],"format":"SVG","priority":"P=0","reuse":"暂无对应旧图；曲线与反射必须确定性绘制","english":"Plot a restricted function and its inverse as reflections across y=x using equal axis scales. For f(x)=(x-2)^2+1 on x<=2, draw inverse 2-sqrt(x-1) on x>=1, not the positive branch. Swap (2,7) to (7,2) and distinguish inverse notation from reciprocal."}}},"物理1":{"1.1":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":1,"section_id":"1.1","goals":["用物理量与条件描述现象","区分模型预测、测量与结论"],"prerequisites":["基本算术","观察与推断"],"flow":["观察问题","物理量","理想模型","预测测量","条件与修正"],"concept_relation":"观察问题；物理量；理想模型；预测测量；条件与修正","deep":["规律包含适用范围。匀速模型要求相应参考系和时间段内速度不变；近地面重力加速度近似常量并不表示从地面到无限远都适用。模型预测与观测不符时，应检查测量、条件与模型，而不是先把数据改到公式上。","实验值通常有不确定性，精确的理论关系在测量中不必表现为所有点完全共线。用趋势、误差范围和重复性比较模型，比只挑一组吻合数字更可靠。但“不确定”也不意味任何结论同样正确，证据仍能排除明显不符的解释。","物理学与技术相互促进，技术应用还受到材料、成本、环境与安全等限制。一项理论能够说明某过程，不表示任何规模的技术装置都已可行；现实工程需要检验边界条件与能量、材料等约束。","做定量题应先把语言转为对象、状态、过程与条件，再选公式。单位检查和极限情况可快速排除错误，例如平均速度结果若没有长度/时间单位就应回查；单位正确只是一项必要检查，不能证明所用物理模型一定正确。"],"derive":["物理量Q=数值×单位；换单位时量保持不变，数值按换算改变。","平均速度定义为位移/对应时间间隔；路程/时间是平均速率，不能仅凭单位相同便当作同量。","模型有效性检验：明确条件 → 给可测预测 → 与含不确定性的结果比较 → 保留或修正。"],"examples":[{"q":"学生写一段长度为2，另一人写200，能直接判断谁测得更长吗？","given":"未给单位。","analysis":"数值依赖单位。","method":"补单位并统一。","principle":"物理量需数值与单位。","steps":["若分别为2 m与200 cm，二者相等。","若同为m，则200 m更长，现信息不足。"],"ans":"不能，先明确单位。","verification":"1 m=100 cm，故2 m=200 cm。","pitfall":"不看单位直接比较数值。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"公交车从家到学校研究行程时间时可否看作质点？研究它能否通过窄门又怎样？","given":"比较两个不同问题。","analysis":"同一物体能否作质点依任务。","method":"检查尺寸是否影响答案。","principle":"模型忽略因素必须对当前问题可忽略。","steps":["路程远大于车尺寸且不研究转动时可近似质点。","过门时车宽高直接决定通过，不能忽略。"],"ans":"前者在条件满足时可以，后者不可。","verification":"门宽若小于车宽，质点模型会给错误通过结论。","pitfall":"把质点当物体固定属性。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"公式算得1.5 m/s，实测1.6±0.2 m/s，可否只因数值不同就否定模型？","given":"不确定性范围给定为比较用。","analysis":"要比较预测与测量范围及其他条件。","method":"检查是否相容，再看测量与模型假设。","principle":"测量有不确定性；相容不等于最终证明。","steps":["范围为1.4至1.8 m/s。","1.5在其中，因此这次差异本身不足否定，但还应多条件重复检验。"],"ans":"不能仅据此否定；此次结果相容。","verification":"1.5在给定范围内且单位相同。","pitfall":"要求实验值与理论小数完全一致。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]}],"practice":[{"q":"速度与速率单位相同，是否概念必相同？","given":"两者都可用m/s。","analysis":"单位不能编码方向及全部定义。","method":"比较位移与路程。","principle":"速度含方向，速率为标量。","steps":["往返原点位移为0。","路程可大于0，平均速度与平均速率可不同。"],"ans":"不同。","verification":"往返例子可同单位而数值不同。","pitfall":"只按单位判断物理概念。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"球大小很小，所以研究它滚动时必能完全忽略转动吗？","given":"研究滚动能量。","analysis":"绝对尺寸小不等于转动效应小。","method":"检查所求是否依赖转动。","principle":"模型要保留影响目标的自由度。","steps":["滚动可有平动与转动能。","若要求总能量，不能无条件忽略转动。"],"ans":"不能。","verification":"即使球小，转动能所占比例未必趋零。","pitfall":"用小这一形容代替尺度与影响比较。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"单位检查通过能证明方程一定正确吗？","given":"只知两边量纲相同。","analysis":"相容是必要检查而非充分验证。","method":"给同量纲错式反例。","principle":"无量纲系数及物理条件仍可能错误。","steps":["v=s/t与v=2s/t量纲相同。","只有正确的定义或模型才能决定系数。"],"ans":"不能。","verification":"两式在同一s,t下不同，不可都由量纲证明。","pitfall":"把量纲相同当完整证明。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"测量范围3.0±0.1 N，模型预测3.4 N，怎样提出下一步而非直接改数据？","given":"按题给范围比较。","analysis":"明显不相容应追查。","method":"检查仪器、重复与模型条件。","principle":"科学推理要求保留原记录。","steps":["范围2.9至3.1 N，不含3.4。","复核校准、控制变量及模型适用性，再新测，不篡改原值。"],"ans":"存在不相容，需调查来源。","verification":"偏差0.4 N大于给定0.1 N范围。","pitfall":"为吻合模型修改观察。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]}],"quiz":{"q":"一条关系在实验室低速情境吻合，能否无条件宣布适用于任何速度与尺度？","given":"证据仅在有限条件内。","analysis":"验证范围有限。","method":"限定条件并提出外推检验。","principle":"规律模型的适用性需证据支持。","steps":["明确已测速度与尺度。","到新范围需重新核理论假设和观测，不能由有限证据推出无限适用。"],"ans":"不能无条件外推。","verification":"未测范围仍可存在需要修正的效应。","pitfall":"把若干吻合当作无限证明。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]},"exam":["概念题用定义、对象和条件作答，不仅写一句生活描述","模型题说明略去因素为什么不影响当前目标","证据题同时写相容性与检验范围，不将一次吻合称为证明"],"quick":["观察问题","物理量","理想模型","预测测量","条件与修正"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":2,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_1.1","url":"https://openstax.org/books/college-physics-2e/pages/1-1-physics-an-introduction","page_or_section":"1-1-physics-an-introduction","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":2,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_1.1","url":"https://openstax.org/books/college-physics-2e/pages/1-1-physics-an-introduction","page_or_section":"1-1-physics-an-introduction","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"概念题用定义、对象和条件作答，不仅写一句生活描述","method":"检查是否相容，再看测量与模型假设。","principle":"测量有不确定性；相容不等于最终证明。","worked_example_index":2,"verification":"1.5在给定范围内且单位相同。","pitfall":"要求实验值与理论小数完全一致。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用物理量与条件描述现象”的抽样复核：1 m=100 cm，故2 m=200 cm。；若出现“不看单位直接比较数值。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“区分模型预测、测量与结论”的抽样复核：1.5在给定范围内且单位相同。；若出现“要求实验值与理论小数完全一致。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把若干吻合当作无限证明。","correction":"不能无条件外推。","verification":"未测范围仍可存在需要修正的效应。"}],"illustration_spec":{"title":"从现象到可检验模型","objects":["实际物体","质点近似","可测量量","含误差数据","模型预测"],"relations":["近似由问题决定","证据比较有条件","不画成一次吻合终结验证"],"labels":["数值×单位","对象与条件","预测","测量与不确定性"],"format":"SVG","priority":"P2","reuse":"可用文字关系图，非必须新增插画","english":"Show observation, physical quantities, a question-specific model, measurable predictions and uncertainty-aware comparison. Contrast treating a bus as a particle for a long journey with retaining its size at a narrow doorway."}},"1.2":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":1,"section_id":"1.2","goals":["设计可检验的单因素实验","区分归纳、演绎与因果证据"],"prerequisites":["变量与比例","测量记录"],"flow":["提出可测假设","控制变量","重复记录","图象与推断","修正模型"],"concept_relation":"提出可测假设；控制变量；重复记录；图象与推断；修正模型","deep":["理想化与等效方法降低问题复杂度，例如用一个合力描述多个力对质点运动的共同效果。等效须说明等效于哪种作用；相同合力未必对刚体产生相同力矩，不能在所有任务中把力的作用点删去。","实验结果需要原始记录、单位、仪器分辨与处理说明。发现异常点应先核记录或操作原因；没有依据不能只为直线好看就删点。拟合或平均值是对数据的处理，不能伪装成每一次实际读数。","相关性可提示机制，却不自动表明因果。同步变化可能来自共同因素或选择偏差；设置对照、改变自变量及检查时间先后等能增强因果判断，但还应明确实验条件和不确定性。","报告研究时，应把观察事实、数据处理、模型解释及限制分别说清。若只在小伸长范围验证弹簧关系，就写该范围内近似成立，不将其推广至塑性变形或断裂。可复核的过程比一个没有记录的漂亮结论更重要。"],"derive":["检验正比y=kx：比较y/x是否近似恒定，并检查图线是否与原点相容；非零截距需解释或改模型。","重复n次取平均x̄=Σxᵢ/n可减小部分随机波动影响，但共同偏移b仍留在x̄中。","设计结构：问题 → 自变量与水平 → 因变量测法 → 控制与对照 → 重复记录 → 处理 → 条件内结论。"],"examples":[{"q":"研究单摆长度对周期的影响，应改变什么、测什么，并控制什么？","given":"以小摆角近似实验，不讨论详细公式。","analysis":"区分变量角色。","method":"设计单因素系列比较。","principle":"控制变量隔离长度影响。","steps":["改变摆长并测每次多周期总时再平均。","保持摆角小且可比，摆球与计时方式一致，重复各长度测量。"],"ans":"改摆长、测周期，控制摆角等并重复。","verification":"若同时改摆角和长度，就无法独立归因。","pitfall":"控制全部量导致根本没有自变量。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"测得x=1,2,3时y=3,5,7，可称y与x成正比吗？","given":"数据精确作数学示例。","analysis":"直线可有非零截距。","method":"求比值及截距。","principle":"正比需y=kx。","steps":["y/x分别3、2.5、7/3，不恒定。","数据满足y=2x+1，截距1。"],"ans":"是线性关系，但不是正比。","verification":"x=0时延长模型给y=1而非0。","pitfall":"见直线就写正比。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"所有长度读数都因零点偏移多0.2 cm，取100次平均能自动消除吗？","given":"每次同方向同量偏移。","analysis":"系统偏移不会因次数互相抵消。","method":"写读数=真值+共同偏移+随机项。","principle":"平均只可能减小独立随机波动部分。","steps":["平均后共同0.2 cm仍存在。","需校准零点或在有依据时修正，并记录方法。"],"ans":"不能自动消除。","verification":"相同常数的平均仍是该常数。","pitfall":"将重复视为一切误差的解药。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]}],"practice":[{"q":"一异常点偏离趋势，是否可以直接删除？","given":"未找到操作或记录错误。","analysis":"删点需依据。","method":"保留原值并调查重复。","principle":"数据处理须可复核。","steps":["检查读数、仪器与条件。","重测并报告处理理由，不能仅为拟合好看删点。"],"ans":"不可无依据删除。","verification":"异常也可能揭示模型范围失效。","pitfall":"用预期规律筛掉不喜欢的结果。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"合力相同能否保证对刚体转动作用相同？","given":"不同力作用点。","analysis":"平动与转动的等效条件不同。","method":"比较力矩。","principle":"力矩还依力臂。","steps":["相同大小方向的力可在不同位置作用。","力臂不同使转动效果不同。"],"ans":"不能。","verification":"门把手和铰链附近推门提供反例。","pitfall":"把质点等效推广所有刚体作用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"三次周期1.9、2.0、2.1 s，平均多少？能否说误差已完全没有？","given":"三次同条件测量。","analysis":"平均是估计不是绝对真值。","method":"求和除次数再讨论。","principle":"算术平均可减小随机波动影响。","steps":["(1.9+2.0+2.1)/3=2.0 s。","仍可能有分辨限制和共同偏移。"],"ans":"2.0 s；不代表零误差。","verification":"结果处在读数范围内。","pitfall":"平均后报告无限精确。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"测y随x变化为2,4,6对应1,2,3，能证明任何x下y=2x吗？","given":"只测三个范围内点。","analysis":"归纳范围有限。","method":"写局部模型并安排新范围检验。","principle":"有限观测不能自动证明无穷范围。","steps":["这些点与y=2x相容。","在未测范围需继续检验并考虑条件是否改变。"],"ans":"不能证明所有x，只支持已测条件中的模型。","verification":"其他函数也可通过这三个点。","pitfall":"把数据相容写成全域恒等证明。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]}],"quiz":{"q":"夏季冰品销量和溺水数同增，能证明吃冰品导致溺水吗？","given":"只有相关趋势。","analysis":"可能有气温等共同因素。","method":"列替代解释与可比数据。","principle":"相关不自动构成因果。","steps":["高温可同时增加冰品购买及游泳活动。","需控制暴露人数等并有机制证据，不能直接归因冰品。"],"ans":"不能。","verification":"共同因素能解释相关而无需直接因果。","pitfall":"把同时变化当作作用机制。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]},"exam":["探究题逐项给变量、测量、控制、重复及处理方法","图象题分线性与正比，截距和单位都要解释","结论题写在何范围支持何关系，不虚构完全证明或官方步骤分"],"quick":["提出可测假设","控制变量","重复记录","图象与推断","修正模型"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":11,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_1.2","url":"https://openstax.org/books/college-physics-2e/pages/1-1-physics-an-introduction","page_or_section":"1-1-physics-an-introduction","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":11,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_1.2","url":"https://openstax.org/books/college-physics-2e/pages/1-1-physics-an-introduction","page_or_section":"1-1-physics-an-introduction","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"探究题逐项给变量、测量、控制、重复及处理方法","method":"写读数=真值+共同偏移+随机项。","principle":"平均只可能减小独立随机波动部分。","worked_example_index":2,"verification":"相同常数的平均仍是该常数。","pitfall":"将重复视为一切误差的解药。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“设计可检验的单因素实验”的抽样复核：若同时改摆角和长度，就无法独立归因。；若出现“控制全部量导致根本没有自变量。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"q","review_module":7,"feedback":"目标“区分归纳、演绎与因果证据”的抽样复核：共同因素能解释相关而无需直接因果。；若出现“把同时变化当作作用机制。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把同时变化当作作用机制。","correction":"不能。","verification":"共同因素能解释相关而无需直接因果。"}],"illustration_spec":{"title":"正比、线性与实验偏移","objects":["两坐标图","y=2x","y=2x+1","重复读数","零点偏移"],"relations":["正比图过原点","线性可非零截距","共同偏移平均后仍存在"],"labels":["x单位","y单位","截距","随机波动","共同偏移"],"format":"SVG","priority":"P1","reuse":"未有匹配图，宜确定性坐标绘图","english":"Draw accurately scaled plots of y=2x and y=2x+1 with labelled axes and intercepts. Separately show random scatter around a shifted mean to explain why averaging does not remove a common zero offset."}},"1.3":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":1,"section_id":"1.3","goals":["把题干转成对象过程与条件","用多种复核定位解题错误"],"prerequisites":["基本代数","单位换算"],"flow":["读题建图","审查条件","符号关系","单位计算","复核与迁移"],"concept_relation":"读题建图；审查条件；符号关系；单位计算；复核与迁移","deep":["建立关系后先作符号推导，再在单位一致时代值，能更容易看出结构和适用范围。负号不应在最后随意删去：它可能表示所选正方向相反，也可能来自错误符号或物理条件，必须回到定义解释。","复核可分单位、数量级、极限情况、独立方法与回代。每种检查都只能发现一类问题，不能单独代替完整推理。例如速度结果超过常见尺度应回查换算，但陌生情境不一定必须符合日常经验，应结合题设模型。","错题记录要保存触发条件、错法原因和改正后的判断步骤，不只抄正确答案。若把摩擦力恒写成μmg，应记录法向力为何未必为mg；下一次用斜面、竖直运动或外力改变压力的变式检验是否真正理解。","间隔回忆先合书解释概念与条件，再独立做新题，最后对照解析定位薄弱环节。能复述刚看过的解答不等于迁移掌握；自评应对应具体能力，例如能否正确建模、说明守恒条件和发现一个错误结果。"],"derive":["解题链：题意与对象 → 已知未知 → 方法条件 → 原理关系 → 符号推导 → 统一单位计算 → 答案解释 → 多项复核。","若同一过程匀加速，v=v₀+at；使用前必须把速度、时间与加速度对应到同一段。","量纲复核以速度为例：[at]=(m/s²)×s=m/s；即使通过仍需核初值、符号和条件。"],"examples":[{"q":"汽车以36 km/h行驶3 s，题目说明期间速度恒定，求位移。应先做什么？","given":"直线同方向匀速，36 km/h、3 s。","analysis":"速度单位与时间单位须统一。","method":"换算再用位移定义。","principle":"匀速同方向Δx=vΔt。","steps":["36 km/h=36/3.6=10 m/s。","Δx=10×3=30 m，方向为行驶方向。"],"ans":"30 m，沿行驶方向。","verification":"每秒10 m，3 s三份；单位m。","pitfall":"直接36×3得到108 m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"直线运动取向右为正，v₀=5 m/s，恒定a=−2 m/s²，3 s末速度为负，能把负号去掉吗？","given":"同一参考系、同一匀加速阶段。","analysis":"负号表达方向，不是算错的充分证据。","method":"计算并回到方向定义。","principle":"v=v₀+at。","steps":["v=5−2×3=−1 m/s。","在2.5 s速度到0，此后向左，故3 s负速度合理。"],"ans":"不能；速度−1 m/s，速率1 m/s。","verification":"0点时刻5/2=2.5 s，3 s已转向。","pitfall":"把速度与速率混写。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"学生把一切摩擦题都写f=μmg，应怎样用错题记录改进？","given":"只知接触摩擦情境，未给平面等条件。","analysis":"μN中的N须由受力求得，且静摩擦不一定达到最大。","method":"分类摩擦类型再求法向力。","principle":"滑动摩擦近似f=μₖN，N不普遍为mg。","steps":["先画接触双方受力，判断滑动或静止。","再用垂直接触面方向的动力学求N；静摩擦按平衡需要及上限检查。"],"ans":"记录“先判类型、再求N、最后用适用关系”，不能固定μmg。","verification":"斜面N可能为mg cosθ，已构成反例。","pitfall":"只抄正确公式而不改选式条件。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]}],"practice":[{"q":"公式中t用min、速度用m/s，可以直接相乘得m吗？","given":"未转换单位。","analysis":"时间基准不一致。","method":"把min转为s。","principle":"量纲与单位换算需一致。","steps":["1 min=60 s。","先乘60再代入，或把速度改成m/min。"],"ans":"不可直接忽略单位差。","verification":"m/s×min尚有60倍转换。","pitfall":"把符号相同t看成单位已自动统一。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"题目发生碰撞，就一定能用两物体动量守恒吗？","given":"未给系统外冲量。","analysis":"关键词不足决定守恒。","method":"先选系统审查外冲量。","principle":"系统动量变化由外冲量决定。","steps":["看碰撞时段和外力冲量是否可忽略。","若不能忽略，须计外冲量而非直接设前后相等。"],"ans":"不一定。","verification":"内力大不自动保证外冲量严格零。","pitfall":"见碰撞便无条件套守恒。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"算得质量−3 kg应怎样处理？","given":"普通经典力学物体质量。","analysis":"负结果可能意味着方程、方向或条件有问题。","method":"回代和检查建模。","principle":"质量在本情境为非负量。","steps":["复核已知、方程移项和单位。","若假设无物理解，说明条件或模型不成立，不能仅去掉负号。"],"ans":"回查模型计算，不能机械取绝对值。","verification":"把3代原式若不满足就暴露修改不合法。","pitfall":"所有负号都删掉求漂亮答案。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"v₀=0、a=3 m/s²、t=4 s的匀加速运动，求末速度并给两项复核。","given":"同方向恒加速度。","analysis":"明确原理、计算与检查。","method":"v=v₀+at。","principle":"速度每秒增加3 m/s。","steps":["v=0+3×4=12 m/s。","单位(m/s²)s=m/s；逐秒3、6、9、12与结果一致。"],"ans":"12 m/s。","verification":"单位和逐步累积两项检查通过，但仍依恒a条件。","pitfall":"只写12而漏单位和条件。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]}],"quiz":{"q":"看解析时每一步都懂，是否已证明能独立解同类题？","given":"尚未合书独立作答。","analysis":"识别理解与主动生成不同。","method":"设计迁移自测。","principle":"掌握需能独立识别条件和选择方法。","steps":["合书重做并解释为何选式。","再做改变一个条件的变式，按错误定位概念、模型或运算。"],"ans":"尚不能证明；需独立和迁移检验。","verification":"换条件后仍能解释适用性才有更强证据。","pitfall":"把刚读过的熟悉感当作掌握。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]},"exam":["答题前把对象、方向和阶段写清，公式必须解释条件","负数结果分辨方向量与本应非负量，不统一取绝对值","复盘题记录选法错误并做条件变式，不能只抄答案"],"quick":["读题建图","审查条件","符号关系","单位计算","复核与迁移"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":17,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_1.3","url":"https://openstax.org/books/college-physics-2e/pages/1-2-physical-quantities-and-units","page_or_section":"1-2-physical-quantities-and-units","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":17,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_1.3","url":"https://openstax.org/books/college-physics-2e/pages/1-2-physical-quantities-and-units","page_or_section":"1-2-physical-quantities-and-units","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"答题前把对象、方向和阶段写清，公式必须解释条件","method":"分类摩擦类型再求法向力。","principle":"滑动摩擦近似f=μₖN，N不普遍为mg。","worked_example_index":2,"verification":"斜面N可能为mg cosθ，已构成反例。","pitfall":"只抄正确公式而不改选式条件。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“把题干转成对象过程与条件”的抽样复核：每秒10 m，3 s三份；单位m。；若出现“直接36×3得到108 m。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用多种复核定位解题错误”的抽样复核：斜面N可能为mg cosθ，已构成反例。；若出现“只抄正确公式而不改选式条件。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把刚读过的熟悉感当作掌握。","correction":"尚不能证明；需独立和迁移检验。","verification":"换条件后仍能解释适用性才有更强证据。"}],"illustration_spec":{"title":"条件驱动的物理解题流程","objects":["对象与阶段","受力/状态示意","方法选择节点","单位与回代检查","变式自测"],"relations":["选法由条件决定而非关键词","负号先解释物理意义","复核有多种互补方法"],"labels":["对象","条件","原理","单位","方向","验算"],"format":"SVG","priority":"P2","reuse":"可使用页面文字关系图","english":"Create a decision-oriented physics-solving flow from object and process to model conditions, symbolic equations, unit conversion and independent checks. Show that a negative velocity means direction whereas a negative ordinary mass requires model review."}}},"物理2":{"2.1":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":2,"section_id":"2.1","goals":["以SI单位和操作定义表达测量","由仪器结构选择读数与校正方法"],"prerequisites":["十进制换算","长度与时间"],"flow":["SI与派生单位","仪器选择","读数","零点校正","间接测量"],"concept_relation":"SI与派生单位；仪器选择；读数；零点校正；间接测量","deep":["用直尺测两刻度之间长度应作末读数减初读数，避免把尺的端部磨损或非零起点当作零。视线尽量垂直刻度以减视差；弯曲物或很小厚度可采用适合的间接方法，但要说明额外假设和可能偏差。","游标卡尺的读数由主尺读数加游标重合分度对应的增量，具体分度值依仪器设计；螺旋测微器由固定刻度与可动刻度合成，读前须识别螺距与分格，不可把某型号的公式数值套到所有仪器。下题均给定分度值，非用文字代替实际仪器图。","零点误差可带符号记录：若真零时读数为e，校正值=读数−e。正偏移要减，负偏移要加；不是看到“误差”就统一加上。修正也不表示其余不确定性全部消失。","重复测量、累计测量和测差等方法解决不同问题。测100张同类纸总厚度再除100可以降低单张太薄的读数困难，但纸受压、厚度差异和计数错误仍存在；方法应根据对象性质评估而不只追求多次。"],"derive":["1 cm=10⁻² m；1 cm²=10⁻⁴ m²；1 cm³=10⁻⁶ m³。","游标读数=主尺值+重合格数×给定分度值；零点校正x=x读−e。","ρ=m/V，若m用kg且V用m³，则ρ单位kg/m³；单位换算先于数值运算。"],"examples":[{"q":"250 cm³是多少m³？","given":"1 cm=10⁻² m。","analysis":"体积换算要把长度因子立方。","method":"250×(10⁻²)³。","principle":"体积由三维长度相乘。","steps":["1 cm³=10⁻⁶ m³。","250 cm³=250×10⁻⁶=2.50×10⁻⁴ m³。"],"ans":"2.50×10⁻⁴ m³。","verification":"1 m³=10⁶ cm³，反向换回250 cm³。","pitfall":"只乘10⁻²。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"卡尺主尺12 mm，游标第7格重合，分度值0.02 mm，正零误差0.04 mm，求校正结果。","given":"仪器型号与分度值由题给。","analysis":"先合成读数，再减有符号零偏。","method":"x=12+7×0.02−0.04。","principle":"零点偏移加在全部读数上。","steps":["读数12.14 mm。","校正值12.14−0.04=12.10 mm。"],"ans":"12.10 mm。","verification":"真值加偏移为12.14，与原读数相合。","pitfall":"正零偏反而加上。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"100张纸总厚度10.0 mm，忽略压缩且厚度相同，估单张厚度。为何方法并非绝对准确？","given":"张数可靠，总厚度为测量值。","analysis":"累计解决分辨问题但有模型假设。","method":"总量除张数并说明限制。","principle":"总厚度近似各张厚度之和。","steps":["10.0/100=0.100 mm。","压缩、间隙和纸张差异会使估计偏离单张实际。"],"ans":"0.100 mm，在题设模型下。","verification":"100×0.100=10.0 mm。","pitfall":"认为累计后所有系统偏差都消失。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]}],"practice":[{"q":"0.75 m²等于多少cm²？","given":"1 m=100 cm。","analysis":"面积换算因子平方。","method":"0.75×100²。","principle":"面积单位为长度单位平方。","steps":["1 m²=10000 cm²。","0.75×10000=7500 cm²。"],"ans":"7500 cm²。","verification":"7500×10⁻⁴=0.75 m²。","pitfall":"只乘100。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"尺上物体两端对应2.3与8.7 cm，长度多少？","given":"两刻度在同一尺上。","analysis":"长度是差不是末刻度。","method":"末减初。","principle":"坐标差表示间隔。","steps":["8.7−2.3=6.4。","两读数同单位，差为cm。"],"ans":"6.4 cm。","verification":"2.3+6.4=8.7 cm。","pitfall":"直接答8.7 cm。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"测微器读数5.18 mm，真零时显示−0.02 mm，校正多少？","given":"零偏e=−0.02 mm。","analysis":"负偏移意味着读数偏小。","method":"x=x读−e。","principle":"校正减去有符号偏移。","steps":["5.18−(−0.02)=5.20。","校正后仍有仪器分辨等限制。"],"ans":"5.20 mm。","verification":"5.20−0.02=5.18。","pitfall":"把负零偏也统一减绝对值。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"质量0.540 kg、体积200 cm³，求密度的SI值。","given":"体积须转m³。","analysis":"质量与体积必须一致单位体系。","method":"先换算再ρ=m/V。","principle":"密度是单位体积质量。","steps":["V=200×10⁻⁶=2.00×10⁻⁴ m³。","ρ=0.540/(2.00×10⁻⁴)=2700 kg/m³。"],"ans":"2.70×10³ kg/m³。","verification":"2700×2.00×10⁻⁴=0.540 kg。","pitfall":"把cm³数值直接与kg配算成SI。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]}],"quiz":{"q":"两仪器分辨值0.1 mm与0.01 mm，能否仅凭这点认定后者所有测量更准确？","given":"未知校准、操作与对象适配。","analysis":"分辨与准确程度不同。","method":"核零偏、量程与方法。","principle":"更细刻度不自动减少系统偏差。","steps":["后者可读更小增量。","若零偏大或方法不合适，其结果可能更偏离真值。"],"ans":"不能仅凭分辨值保证。","verification":"细刻度但偏移1 mm就可比粗尺更差。","pitfall":"将小分度与无误差等同。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]},"exam":["仪器题先识别量程分度与零点，再读主尺/副尺","单位题把面积体积因子展开后再算","间接测量题写假设及误差来源，不能把累计当无误差"],"quick":["SI与派生单位","仪器选择","读数","零点校正","间接测量"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":24,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.1","url":"https://openstax.org/books/college-physics-2e/pages/1-2-physical-quantities-and-units","page_or_section":"1-2-physical-quantities-and-units","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":24,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.1","url":"https://openstax.org/books/college-physics-2e/pages/1-2-physical-quantities-and-units","page_or_section":"1-2-physical-quantities-and-units","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"仪器题先识别量程分度与零点，再读主尺/副尺","method":"总量除张数并说明限制。","principle":"总厚度近似各张厚度之和。","worked_example_index":2,"verification":"100×0.100=10.0 mm。","pitfall":"认为累计后所有系统偏差都消失。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“以SI单位和操作定义表达测量”的抽样复核：1 m³=10⁶ cm³，反向换回250 cm³。；若出现“只乘10⁻²。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“由仪器结构选择读数与校正方法”的抽样复核：真值加偏移为12.14，与原读数相合。；若出现“正零偏反而加上。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"将小分度与无误差等同。","correction":"不能仅凭分辨值保证。","verification":"细刻度但偏移1 mm就可比粗尺更差。"}],"illustration_spec":{"title":"卡尺读数与有符号零点校正","objects":["主尺","游标","零点对照","面积体积单位框"],"relations":["指定0.02 mm分度","第7格确实重合","正零偏减去"],"labels":["12 mm","第7格","0.02 mm","读数12.14 mm","校正12.10 mm"],"format":"SVG","priority":"P0","reuse":"无完整匹配；精确刻度必须确定性绘图","english":"Construct a mathematically consistent vernier with 0.02 mm least count, main-scale reading 12 mm and seventh matching division. Show a positive 0.04 mm zero offset and corrected result 12.10 mm. Do not improvise incompatible scale spacing."}},"2.2":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":2,"section_id":"2.2","goals":["区分偏差来源与不确定性表达","按运算与测量限制报告有效数字"],"prerequisites":["四则运算","测量与分辨率"],"flow":["系统与随机","绝对与相对","有效数字","运算舍入","传播假设"],"concept_relation":"系统与随机；绝对与相对；有效数字；运算舍入；传播假设","deep":["有效数字用于避免报告超出测量或输入支持的精度。非零数字通常有效，夹在有效数字之间的零有效，小数前只定位的零不有效；末尾零在没有明确记法时可能有歧义，科学记数法可以把保留位数说清。","加减运算通常按最粗小数位限制结果，乘除通常按输入中最少有效数字位数限制；这些是常用报告约定，不替代更完整的不确定性分析。准确的计数和定义换算因子不应不必要限制有效数字。","中间步骤保留保护位，最后一次舍入可减少累积舍入偏差。计算器显示很多位不表示测量已具有同样精度；报告到多少位应根据输入和测量方法，而不是按屏幕长度。","若题目要求估计合成不确定性，要使用题目指定规则。简单最大界限近似下，加减的绝对界限相加，乘除的相对界限近似相加；独立随机量的统计合成规则不同，不能在未说明假设时把所有规则混为一谈。"],"derive":["相对不确定性r=Δx/|x|；百分比为100r%。","例：x=(20.0±0.2) cm，r=0.2/20.0=1%。","小误差最大界限近似：z=xy或x/y时Δz/|z|≈Δx/|x|+Δy/|y|；这不是无条件适用的统计标准差公式。"],"examples":[{"q":"长度(50.0±0.5) cm的相对不确定性是多少？","given":"按题给绝对范围。","analysis":"比值单位相消。","method":"Δx/|x|。","principle":"相对指标比较误差占量值比例。","steps":["0.5/50.0=0.01。","化成百分比为1%。"],"ans":"1%。","verification":"50.0的1%为0.5 cm。","pitfall":"把0.5 cm直接写0.5%。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"计算12.35 cm+0.8 cm，应怎样报告？","given":"分别精确到0.01 cm与0.1 cm。","analysis":"加法限制看小数位。","method":"先求和再留最粗位。","principle":"小数位反映可支持的绝对位精度。","steps":["原和13.15 cm。","按0.1 cm报告为13.2 cm。"],"ans":"13.2 cm。","verification":"0.8本身未给百分位，不能宣称和到百分位。","pitfall":"按有效数字位数最少只保留一位成10 cm。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"边长a=(10.0±0.1) cm、b=(20.0±0.2) cm，用最大界限小误差近似求面积与绝对不确定性。","given":"正值，按题指定相对界限相加。","analysis":"先算面积，再算相对界限。","method":"A=ab，ΔA/A≈Δa/a+Δb/b。","principle":"一阶传播忽略小量乘积。","steps":["A=200 cm²，相对界限约1%+1%=2%。","ΔA≈200×0.02=4 cm²。"],"ans":"约(200±4) cm²。","verification":"精确端点9.9×19.8=196.02、10.1×20.2=204.02，与±4近似相合。","pitfall":"直接把0.1+0.2作为面积单位误差。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]}],"practice":[{"q":"0.00450有几位有效数字？","given":"小数记法明确。","analysis":"前导零与末尾零角色不同。","method":"从首个非零位数到末位。","principle":"定位零不计，保留的小数末零计。","steps":["首个非零为4。","4、5、0共3位。"],"ans":"3位。","verification":"可写4.50×10⁻³。","pitfall":"把所有零都忽略或都计入。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"2.4 m×3.12 m按常用规则报告面积。","given":"测量输入2位与3位有效数字。","analysis":"乘法按最少有效数字。","method":"先保留中间值再舍入。","principle":"乘积不应超过输入支持精度。","steps":["2.4×3.12=7.488 m²。","保留2位为7.5 m²。"],"ans":"7.5 m²。","verification":"处于7.488附近，单位面积。","pitfall":"按小数位规则保留到百分位。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"一把尺所有读数都多1 mm，多测几次能消掉吗？","given":"共同零偏。","analysis":"系统与随机影响需不同处理。","method":"校准零点并修正记录。","principle":"常量偏移的平均仍同偏移。","steps":["重复读数平均仍多1 mm。","需识别校准，且修正后仍有其他不确定性。"],"ans":"不能靠平均消除。","verification":"xᵢ=x真+1 mm时平均仍x真+1 mm。","pitfall":"只要次数多就准确。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"两次独立长度量按题给最大界限：A=20.0±0.2 cm，B=5.0±0.1 cm，求A−B的界限估计与相对值。","given":"使用界限相加规则，不用统计平方和。","analysis":"减法数值相减，不确定性界限仍相加。","method":"z=A−B，Δz=ΔA+ΔB。","principle":"最不利方向误差可相反。","steps":["z=15.0 cm；Δz=0.3 cm。","相对0.3/15.0=2%。"],"ans":"(15.0±0.3) cm，约2%。","verification":"最大差20.2−4.9=15.3，最小19.8−5.1=14.7。","pitfall":"把不确定性也作0.2−0.1。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]}],"quiz":{"q":"计算器给ρ=2.7182818 g/cm³，输入只到3位有效数字，能照抄全部位吗？","given":"未给更高精度测量。","analysis":"显示位不等于有效位。","method":"按输入与题设精度舍入。","principle":"结果精度受数据约束。","steps":["保留3位得2.72 g/cm³。","中间可留保护位，但报告不能把额外位冒充测量能力。"],"ans":"应约2.72 g/cm³。","verification":"第4位为8使第三位进1。","pitfall":"以计算器显示决定精度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]},"exam":["误差题先辨单位、相对指标与给定传播规则","有效数字题加减看位、乘除看位数，中间不反复舍入","“更准确”比较需核校准与不确定性，不能只比小数多"],"quick":["系统与随机","绝对与相对","有效数字","运算舍入","传播假设"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":31,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.2","url":"https://openstax.org/books/college-physics-2e/pages/1-3-accuracy-precision-and-significant-figures","page_or_section":"1-3-accuracy-precision-and-significant-figures","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":31,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.2","url":"https://openstax.org/books/college-physics-2e/pages/1-3-accuracy-precision-and-significant-figures","page_or_section":"1-3-accuracy-precision-and-significant-figures","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"误差题先辨单位、相对指标与给定传播规则","method":"A=ab，ΔA/A≈Δa/a+Δb/b。","principle":"一阶传播忽略小量乘积。","worked_example_index":2,"verification":"精确端点9.9×19.8=196.02、10.1×20.2=204.02，与±4近似相合。","pitfall":"直接把0.1+0.2作为面积单位误差。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“区分偏差来源与不确定性表达”的抽样复核：50.0的1%为0.5 cm。；若出现“把0.5 cm直接写0.5%。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“按运算与测量限制报告有效数字”的抽样复核：0.8本身未给百分位，不能宣称和到百分位。；若出现“按有效数字位数最少只保留一位成10 cm。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"以计算器显示决定精度。","correction":"应约2.72 g/cm³。","verification":"第4位为8使第三位进1。"}],"illustration_spec":{"title":"测量离散、偏移与有效位","objects":["真值参考","两组读数分布","偏移","绝对范围","科学记数法"],"relations":["集中不等于无偏","随机散布与系统偏移可并存","前导零不计有效位"],"labels":["准确性","重复性","Δx","Δx/|x|","4.50×10⁻³"],"format":"SVG","priority":"P1","reuse":"无完全对应图","english":"Show two measurement distributions with independent spread and bias relative to a stated reference. Distinguish absolute uncertainty from relative uncertainty and annotate the three significant figures in 0.00450 without implying an exact universal probability for ± notation."}},"2.3":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":2,"section_id":"2.3","goals":["规范表示极大极小量并估算","用数量级检查模型结果"],"prerequisites":["十的幂","有效数字"],"flow":["标准记数","幂运算","前缀换算","尺度比较","因素估算"],"concept_relation":"标准记数；幂运算；前缀换算；尺度比较；因素估算","deep":["数量级用于比较数量的尺度，但“以首个十次幂为数量级”与“取最接近的十次幂”是不同约定。题目未说明时应写出所用约定，避免把两种答案差一档当成纯计算错。本节若说“最近十次幂”，按对数距离比较，分界为系数√10。","费米估算把复杂数量拆为可说明的因素，用合理范围先得到尺度。估算不是随意猜数，应写假设、单位和主导不确定因素，例如每户每日用水乘户数可估总需求，入住率和季节变化会改变结果。","数量级检查能识别错用毫秒、千米或平方单位引入的巨大偏差。它不保证精确答案，但可对结果施加约束：若步行速度算得10⁶ m/s，优先回查单位和题意；对非常规情境仍需依据模型而非日常印象否定。","估算报告应与信息质量匹配，不把粗略假设算出的许多位写成真实测量。范围估算常比单一数字更诚实；列出哪项改进最能减少不确定性，能把估算转为可进一步研究的问题。"],"derive":["(a×10ᵐ)(b×10ⁿ)=ab×10ᵐ⁺ⁿ；相除则系数相除、指数相减。","加减必须先同幂：3×10³+2×10²=(3+0.2)×10³=3.2×10³。","最近十次幂的对数分界：a×10ⁿ到10ⁿ和10ⁿ⁺¹等距时log₁₀a=1/2，即a=√10；若用另一约定须注明。"],"examples":[{"q":"把0.000560 m写成科学记数法并保持有效数字。","given":"原值末尾小数零有效。","analysis":"系数需在1到10之间。","method":"移动小数点并补幂。","principle":"量值不变且保留有效位。","steps":["0.000560=5.60×10⁻⁴。","5、6、0为三位有效数字。"],"ans":"5.60×10⁻⁴ m，三位。","verification":"5.60/10000=0.000560。","pitfall":"丢掉末零或把指数写正。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"算(6.0×10⁵)/(2.0×10⁻³)，按有效数字报告。","given":"系数均2位。","analysis":"负指数相减应注意括号。","method":"系数相除、指数相减。","principle":"10ᵐ/10ⁿ=10ᵐ⁻ⁿ。","steps":["6.0/2.0=3.0。","5−(−3)=8，得3.0×10⁸。"],"ans":"3.0×10⁸。","verification":"3.0×10⁸乘2.0×10⁻³=6.0×10⁵。","pitfall":"将5−(−3)算成2。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"估学校1000人，每人每天饮水约1到2 L，五天需多少饮水？结果应报几位？","given":"只估饮用，不含清洁和烹饪。","analysis":"明确活动与范围边界。","method":"人数×每人量×天数。","principle":"总需求为可加的个体需求近似。","steps":["低端1000×1×5=5000 L。","高端1000×2×5=10000 L。","入住、出勤与天气等会改变假设。"],"ans":"约5×10³至1×10⁴ L，不应报大量精确小数。","verification":"单位人×L/(人·日)×日=L。","pitfall":"把饮用估算当所有生活用水精确值。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]}],"practice":[{"q":"3×10⁴+2×10³等于5×10⁷吗？","given":"加法而非乘法。","analysis":"幂规则不可混用。","method":"统一指数。","principle":"同类项相加。","steps":["2×10³=0.2×10⁴。","和为3.2×10⁴。"],"ans":"不是，3.2×10⁴。","verification":"30000+2000=32000。","pitfall":"加法也把指数相加。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"2.5 ms是多少s？","given":"milli为10⁻³。","analysis":"单位前缀对应幂次。","method":"2.5×10⁻³。","principle":"换算不改变物理时长。","steps":["1 ms=10⁻³ s。","2.5 ms=0.0025 s。"],"ans":"2.5×10⁻³ s。","verification":"乘1000转回2.5 ms。","pitfall":"把milli与micro混用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"按最近十次幂的对数距离约定，8×10⁴更近10⁴还是10⁵？","given":"明确使用最近十次幂约定。","analysis":"系数与√10比较。","method":"8>√10，取上一级。","principle":"对数中点系数约3.162。","steps":["8大于3.162。","因此离10⁵的对数距离较小。"],"ans":"10⁵。","verification":"80000比100000只差1.25倍，比10000差8倍。","pitfall":"不声明约定导致把首指数4当唯一答案。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"一页约500字，约200页，估总字数并说明不宜报100000.00字的理由。","given":"每页字数和页数均粗估。","analysis":"乘法不产生额外测量精度。","method":"分因素估算尺度。","principle":"估计结果精度受假设限制。","steps":["500×200≈1×10⁵字。","插图、空白与排版使实际量偏离，末两位小数无依据。"],"ans":"约10⁵字。","verification":"5×10²乘2×10²=10×10⁴=10⁵。","pitfall":"把计算器整数或小数当真实精度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]}],"quiz":{"q":"算得步行100 m耗时20 s的速度为5×10⁵ m/s，怎样不用重做全题先检查？","given":"常规地面步行与题设距离时间。","analysis":"尺度严重不合理且可直接估比。","method":"100/20近5，再核幂和单位。","principle":"速度=距离/时间，此处同单位。","steps":["10²/(2×10¹)=5×10⁰ m/s。","原结果多10⁵倍，应查指数或单位误用。"],"ans":"应为5 m/s，原结果数量级错误。","verification":"5×20=100 m。","pitfall":"发现离谱只说不合理却不定位幂次。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]},"exam":["科学记数先标准化系数，运算后再标准化","数量级题注明约定，用倍数或对数比较而非随意取整","估算题列边界、因素、单位与范围，避免虚假精度"],"quick":["标准记数","幂运算","前缀换算","尺度比较","因素估算"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":34,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.3","url":"https://openstax.org/books/college-physics-2e/pages/1-4-approximation","page_or_section":"1-4-approximation","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":34,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.3","url":"https://openstax.org/books/college-physics-2e/pages/1-4-approximation","page_or_section":"1-4-approximation","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"科学记数先标准化系数，运算后再标准化","method":"人数×每人量×天数。","principle":"总需求为可加的个体需求近似。","worked_example_index":2,"verification":"单位人×L/(人·日)×日=L。","pitfall":"把饮用估算当所有生活用水精确值。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“规范表示极大极小量并估算”的抽样复核：单位人×L/(人·日)×日=L。；若出现“把饮用估算当所有生活用水精确值。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"q","review_module":5,"feedback":"目标“用数量级检查模型结果”的抽样复核：5×20=100 m。；若出现“发现离谱只说不合理却不定位幂次。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"发现离谱只说不合理却不定位幂次。","correction":"应为5 m/s，原结果数量级错误。","verification":"5×20=100 m。"}],"illustration_spec":{"title":"科学记数与对数尺度","objects":["十进制小数","标准系数","十次幂数轴","√10分界"],"relations":["系数1至10","对数轴等距表示相同倍数","数量级约定显式标注"],"labels":["10⁻⁴","10⁰","10⁴","5.60×10⁻⁴","最近十次幂"],"format":"SVG","priority":"P1","reuse":"需确定性数轴，无需AI辅助画","english":"Create a labelled logarithmic powers-of-ten scale and illustrate 0.000560=5.60×10^-4. If showing nearest power of ten, explicitly mark the multiplicative midpoint sqrt(10), not an arithmetic midpoint."}},"2.4":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":2,"section_id":"2.4","goals":["由图象解释斜率截距及面积","辨认变量关系和适用区间"],"prerequisites":["坐标系与斜率","单位与比例"],"flow":["轴与刻度","斜率","截距","有向面积","变量变换"],"concept_relation":"轴与刻度；斜率；截距；有向面积；变量变换","deep":["曲线在某点的切线斜率表示局部变化率，割线表示区间平均变化率。两者可不同，不能从一段平均值推出每时刻恒定。折线拐点处是否有唯一切线还需按模型处理。","图线下有向面积的单位为两轴单位的乘积；面积代表什么须从所画量关系推导。速度—时间图面积给位移，速率—时间图面积给路程，力—位移图面积在相关力分量与运动关系满足条件时给功；不能说任何图面积都是能量。","线性化把非线性关系转为适当变量间的直线，例如y=kx²可画y对x²，而非强行把y对x画直。新横轴单位也须平方。变量变换可以便于求参数，但不会自动证明原模型在所有范围成立。","数据处理应同时展示适当点、趋势与不确定性；读图精度受刻度和图线宽度限制。图看起来没有明显弯曲不能单独保证严格线性，报告应与测量范围和分辨能力相称。"],"derive":["斜率m=Δy/Δx，单位[y]/[x]；截距b在y=mx+b中与y同单位。","v-t图：Δx=图线与时间轴之间的有向面积；负速度部分给负位移。","若y=kx²，令X=x²，则y=kX；X单位为[x]²，斜率k单位[y]/[x]²。"],"examples":[{"q":"x-t直线过(1 s,3 m)和(5 s,11 m)，斜率与截距分别是什么？","given":"横轴t、纵轴x，直线模型。","analysis":"斜率给速度，截距给t=0的位置外推。","method":"两点求m再代回。","principle":"x=vt+x₀。","steps":["v=(11−3)/(5−1)=2 m/s。","3=2×1+x₀，得x₀=1 m。"],"ans":"斜率2 m/s，截距1 m。","verification":"t=5时x=2×5+1=11 m。","pitfall":"直接11/5忽略非零初位置。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"v-t图0至2 s为+3 m/s，2至4 s为−1 m/s，求位移和路程。","given":"分段恒速，转向时刻的理想突变按题处理。","analysis":"有向面积与绝对面积不同。","method":"分别加vΔt和|v|Δt。","principle":"位移有方向，路程不抵消。","steps":["位移=3×2−1×2=4 m。","路程=3×2+1×2=8 m。"],"ans":"位移+4 m，路程8 m。","verification":"从0到6 m再回到4 m，总走8 m。","pitfall":"将负区域删去或把路程也相消。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"关系y=kx²，x单位m、y单位N，作y对x²图得到斜率5，应给k什么单位？","given":"横轴已换为x²。","analysis":"新横轴单位平方。","method":"斜率单位N/m²。","principle":"斜率=纵量/横量。","steps":["x²单位m²。","k=5 N/m²，且y随x²正比而非随x正比。"],"ans":"5 N/m²。","verification":"k x²单位(N/m²)m²=N。","pitfall":"沿用原x单位把k写N/m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]}],"practice":[{"q":"同一x-t图拉宽纸张，直线视觉角度减小，速度会变吗？","given":"坐标刻度数值及物理数据不变。","analysis":"斜率应由数值比求而非视觉角。","method":"比较Δx/Δt。","principle":"绘图长宽不改变物理数据。","steps":["同两点坐标差不变。","速度比值保持，只有画面倾角改变。"],"ans":"不会。","verification":"单位比例尺变化使角度不能直接当m/s。","pitfall":"以角度大小无条件比较不同刻度图。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"F-x图恒定沿位移方向力4 N，位移3 m，面积及含义？","given":"力为位移方向分量。","analysis":"轴乘积为功单位。","method":"矩形面积FΔx。","principle":"恒力功=FΔx。","steps":["4×3=12 N·m。","1 N·m=1 J，此处表示功12 J。"],"ans":"12 J功。","verification":"与恒力公式相同。","pitfall":"不看轴变量就把所有面积说成速度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"y=3x+2图象是直线，y与x成正比吗？","given":"范围中模型给定。","analysis":"非零截距破坏固定比值。","method":"求y/x或看原点。","principle":"正比需y=kx。","steps":["x=1时y/x=5，x=2时为4。","图线截距2，不通过原点。"],"ans":"不成正比。","verification":"不同x比值不恒定。","pitfall":"线性与正比混用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"速度从0到4 s线性由2升到6 m/s，求加速度与位移并用另一方法核查。","given":"恒加速度阶段。","analysis":"斜率和面积对应不同物理量。","method":"斜率求a，梯形面积求Δx。","principle":"a=Δv/Δt，位移为v-t面积。","steps":["a=(6−2)/4=1 m/s²。","Δx=(2+6)×4/2=16 m。"],"ans":"1 m/s²与16 m。","verification":"v₀t+at²/2=8+8=16 m。","pitfall":"用斜率作位移或漏初速度面积。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]}],"quiz":{"q":"某曲线两点割线斜率为2，能否说两点间每处切线斜率都为2？","given":"只给区间平均变化率。","analysis":"平均与局部不同。","method":"考虑非直线反例。","principle":"切线描述局部，割线描述两点差。","steps":["曲线可在不同位置更陡或更平。","只有额外证据表明该段直线等条件，才能说局部斜率恒定。"],"ans":"不能。","verification":"总平均相同可对应多种局部变化。","pitfall":"把区间平均当处处瞬时值。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]},"exam":["读图题先圈轴量、单位、刻度和原点，再解释斜率或面积","拟合题从拟合线取合适远点，非任意散点","线性化题重写变量及其单位，物理解释随轴改变"],"quick":["轴与刻度","斜率","截距","有向面积","变量变换"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":37,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.4","url":"https://openstax.org/books/college-physics-2e/pages/2-8-graphical-analysis-of-one-dimensional-motion","page_or_section":"2-8-graphical-analysis-of-one-dimensional-motion","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":37,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.4","url":"https://openstax.org/books/college-physics-2e/pages/2-8-graphical-analysis-of-one-dimensional-motion","page_or_section":"2-8-graphical-analysis-of-one-dimensional-motion","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"读图题先圈轴量、单位、刻度和原点，再解释斜率或面积","method":"斜率单位N/m²。","principle":"斜率=纵量/横量。","worked_example_index":2,"verification":"k x²单位(N/m²)m²=N。","pitfall":"沿用原x单位把k写N/m。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由图象解释斜率截距及面积”的抽样复核：t=5时x=2×5+1=11 m。；若出现“直接11/5忽略非零初位置。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“辨认变量关系和适用区间”的抽样复核：k x²单位(N/m²)m²=N。；若出现“沿用原x单位把k写N/m。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把区间平均当处处瞬时值。","correction":"不能。","verification":"总平均相同可对应多种局部变化。"}],"illustration_spec":{"title":"图象的斜率、截距与有向面积","objects":["x-t直线","v-t正负矩形","y对x²直线"],"relations":["x-t过(1,3)(5,11)","v-t面积+6和−2给+4","路程取绝对面积8"],"labels":["t/s","x/m","v/(m/s)","斜率2 m/s","截距1 m","Δx=4 m"],"format":"SVG","priority":"P0","reuse":"V22运动图可作补充，需避免重复并保持数值一致","english":"Draw three exact coordinate panels: x=2t+1 through (1,3) and (5,11); v=3 for 0–2 s and v=-1 for 2–4 s with signed areas +6 and -2 m; a separate y versus x-squared linearization with squared horizontal units."}}},"物理5":{"5.1":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":5,"section_id":"5.1","goals":["由平衡条件建立分量方程","用受力图检查约束与解的可行性"],"prerequisites":["向量分解","牛顿定律"],"flow":["选对象","画外力","分量平衡","约束上限","可行性核查"],"concept_relation":"选对象；画外力；分量平衡；约束上限；可行性核查","deep":["只有三力且平衡时，矢量首尾相接可形成闭合三角形。用几何求张力需确认角是力方向之间还是图中补角；两根对称绳的夹角越大，竖直分量比例越小，所需张力可能增大，而不是总是各承受一半重量。","静摩擦是在接触条件允许范围内按维持相对静止的需要取值，0≤|fₛ|≤μₛN；仅在临界滑动时才达到最大值。法向力取决垂直于接触面的动力学及其他外力，不应一律等于mg。","绳通常只能拉，接触面通常只能推。求得负张力或负法向力，可能意味着所假设约束状态不成立，须回到物理情境判断松绳或失去接触。代数方程有解不保证模型可实现。","做平衡题应先计算所需摩擦或拉力，再检查上限和约束。当外力改变到临界值，平衡可能失效；要清楚区分“求维持平衡所需力”与“给定条件是否足以维持平衡”这两类问题。"],"derive":["平面共点力平衡：ΣFₓ=0，ΣFᵧ=0。","两对称绳各与竖直夹角θ，2T cosθ=mg，故T=mg/(2 cosθ)，需cosθ>0且绳能承受。","静摩擦先求所需f，再检验|f|≤μₛN；等号只描述临界情况。"],"examples":[{"q":"质量4 kg物体在水平面受水平拉力8 N静止，g=10 m/s²，求摩擦和支持力。","given":"无其他竖直力，静止。","analysis":"平衡分量分别求。","method":"水平与竖直列ΣF=0。","principle":"加速度零，接触力满足约束。","steps":["水平方向摩擦8 N，反向于拉力。","竖直N=mg=40 N。"],"ans":"f=8 N、N=40 N。","verification":"两方向合力分别0；是否可维持还需摩擦上限≥8 N。","pitfall":"未给μ就说无法求实际静摩擦。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"重100 N物体由两根对称绳吊住，各与竖直60°，各张力多少？","given":"绳轻，结点平衡。","analysis":"每根竖直分量只占T的一半。","method":"水平抵消、竖直相加。","principle":"2T cos60°=100。","steps":["cos60°=0.5。","T=100/(2×0.5)=100 N。"],"ans":"各100 N。","verification":"两根各向上分量50 N，总100 N。","pitfall":"直接各50 N忽略方向。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"质量5 kg物体在水平面，μₛ=0.4，受水平力25 N，g=10，能否平衡？","given":"无其他竖直力，讨论静摩擦上限。","analysis":"先求所需再比最大。","method":"f需=25，f最大=μₛmg。","principle":"静摩擦只能在允许范围内调节。","steps":["N=50 N，最大20 N。","所需25>20，静止平衡无法维持。"],"ans":"不能按静止模型平衡。","verification":"即使取最大摩擦仍有至少5 N合力；运动后摩擦须另用条件。","pitfall":"把静摩擦无条件设为25 N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]}],"practice":[{"q":"物体瞬时速度为零就必平衡吗？","given":"仅知某一时刻v=0。","analysis":"速度与加速度不同。","method":"找反例并看合力。","principle":"平衡需加速度零。","steps":["竖直上抛最高点v=0。","重力仍向下，加速度不为零。"],"ans":"不必。","verification":"其下一时刻向下运动说明速度在变。","pitfall":"把静止瞬间等同持续静止。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"两个力大小都10 N，夹角120°，合力大小？能仅凭大小相等说平衡吗？","given":"只受这两个力。","analysis":"方向决定是否抵消。","method":"用余弦关系或分解。","principle":"R²=F²+F²+2F²cos120°。","steps":["R²=100+100−100=100。","R=10 N，不为0。"],"ans":"10 N，不平衡。","verification":"只有相反方向180°才可两力抵消。","pitfall":"相等就当作用反作用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"重量60 N由对称绳吊住，各与竖直30°，各T？","given":"结点平衡，理想绳。","analysis":"用竖直分量。","method":"T=60/(2cos30°)。","principle":"水平分量相消。","steps":["cos30°=√3/2。","T=60/√3=20√3≈34.6 N。"],"ans":"约34.6 N。","verification":"2×34.6×0.866≈60 N。","pitfall":"用sin30°代替与竖直夹角的cos。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"4 kg物体受水平拉力10 N、向上拉力6 N，g=10，μₛ=0.3，能静止吗？","given":"物体保持接触，竖直平衡假设。","analysis":"上拉减小N也减小摩擦上限。","method":"先竖直求N，再查水平。","principle":"N+6=mg，|f|≤μₛN。","steps":["N=40−6=34 N，f最大10.2 N。","所需f=10 N≤10.2 N，可静止，实际f=10 N。"],"ans":"可以，N=34 N、静摩擦10 N。","verification":"竖直34+6−40=0，水平10−10=0。","pitfall":"仍把N写40或把摩擦强设10.2。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]}],"quiz":{"q":"受力图把物体对桌面的压力与桌面对物体支持力都画在物体上并抵消，错在哪里？","given":"研究对象为物体。","analysis":"作用反作用所属对象不同。","method":"逐力问施力与受力物体。","principle":"受力图只包括作用于该对象的力。","steps":["桌面对物体支持力应保留。","物体对桌面压力属于桌面的受力图，不可拿来抵消。"],"ans":"混入了研究对象对外施加的力。","verification":"若抵消支持力，重力将无法与实际静止相符。","pitfall":"把相互作用一对当同体平衡力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]},"exam":["先选对象画外力，再分解列平衡，不能先猜μmg","绳角题写清角从竖直或水平量起，验每根竖直分量","求解后检查N≥0、T≥0和摩擦上限，说明是否可实现"],"quick":["选对象","画外力","分量平衡","约束上限","可行性核查"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":146,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_5.1","url":"https://openstax.org/books/college-physics-2e/pages/9-1-the-first-condition-for-equilibrium","page_or_section":"9-1-the-first-condition-for-equilibrium","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":146,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_5.1","url":"https://openstax.org/books/college-physics-2e/pages/9-1-the-first-condition-for-equilibrium","page_or_section":"9-1-the-first-condition-for-equilibrium","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"先选对象画外力，再分解列平衡，不能先猜μmg","method":"f需=25，f最大=μₛmg。","principle":"静摩擦只能在允许范围内调节。","worked_example_index":2,"verification":"即使取最大摩擦仍有至少5 N合力；运动后摩擦须另用条件。","pitfall":"把静摩擦无条件设为25 N。"},"diagnostics":[{"goal_index":0,"question_ref":"e1","review_module":4,"feedback":"目标“由平衡条件建立分量方程”的抽样复核：两根各向上分量50 N，总100 N。；若出现“直接各50 N忽略方向。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用受力图检查约束与解的可行性”的抽样复核：即使取最大摩擦仍有至少5 N合力；运动后摩擦须另用条件。；若出现“把静摩擦无条件设为25 N。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把相互作用一对当同体平衡力。","correction":"混入了研究对象对外施加的力。","verification":"若抵消支持力，重力将无法与实际静止相符。"}],"illustration_spec":{"title":"对称悬吊与静摩擦约束","objects":["结点","两根对称绳","重量","张力分量","水平接触物体"],"relations":["θ从竖直量","2Tcosθ=mg","静摩擦小于等于上限而非恒取上限"],"labels":["θ","T","Tcosθ","mg","|fₛ|≤μₛN"],"format":"SVG","priority":"P0","reuse":"V22向量图可局部参考，不替代本题受力几何","english":"Draw a symmetric suspension with each rope angle measured from the vertical, showing 2T cos(theta)=mg. In a separate horizontal-contact free-body diagram, distinguish required static friction from its maximum and do not include reaction forces acting on other bodies."}},"5.2":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":5,"section_id":"5.2","goals":["用垂直力臂计算力矩","联合平动转动条件求平面刚体平衡"],"prerequisites":["共点力平衡","三角函数"],"flow":["选矩心","画作用线","定垂距和符号","联合平衡","查支承约束"],"concept_relation":"选矩心；画作用线；定垂距和符号；联合平衡；查支承约束","deep":["选支点是求解策略，不改变物理事实。取未知支承力作用点为矩心，可使该力矩为零并减少未知量；不是忽略该力，它仍必须进入合力方程。若合力已为零，平衡时绕任一点的合力矩也为零。","平面刚体静力平衡常用ΣFₓ=0、ΣFᵧ=0、Στ=0三个独立条件。未知力多于可提供的独立方程时，可能需要材料变形等额外信息，不能任意再选几个矩心假装得到更多独立约束。","重力在均匀杆上可视为作用于中点，但“均匀”是质量分布条件。非均匀物体的重心不能无依据取几何中心；复杂负载可把各重力按力矩等效求重心位置。支持点是否能拉、支承是否会脱离也需检查。","平衡问题的答案要同时满足力与矩，并符合支承方向。只用矩方程求一个力后，应代回竖直和水平方程；若某支点反力为负而该支承不能拉，说明所假设双支承接触状态失效。"],"derive":["τ=Fℓ=Fr sinθ，其中ℓ为支点到作用线的垂直距离。","平面静力平衡：ΣFₓ=0，ΣFᵧ=0，Στ_O=0。","力偶大小相等反向平行，间距d时合力0而合力矩Fd；关于不同点力偶矩相同。"],"examples":[{"q":"水平杆绕左端，右端距支点0.5 m，施向下10 N，力矩多大、什么方向？","given":"力与杆垂直。","analysis":"力臂正好为0.5 m。","method":"τ=Fℓ并判转向。","principle":"绕支点转动趋势。","steps":["τ=10×0.5=5 N·m。","右端向下使杆顺时针转动。"],"ans":"5 N·m，顺时针。","verification":"若力作用线通过支点则应零，此处垂距非零。","pitfall":"只写5 J或把方向漏掉。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"长2 m均匀杆重40 N，两端支承，中点另挂20 N，支反力各多少？","given":"载荷均在中点，无其他竖直力。","analysis":"对称可猜但需力矩验证。","method":"绕左端取矩再列竖直力。","principle":"平衡要求合力与合矩都零。","steps":["右支力R_B满足2R_B=40×1+20×1，得30 N。","R_A+R_B=60，故R_A=30 N。"],"ans":"两端各30 N向上。","verification":"绕中点两支力矩抵消，总向上60 N等于重力60 N。","pitfall":"只令合力零便认为任何分配都行。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"杆长0.8 m，末端受50 N，与杆夹角30°，求绕另一端力矩，比较误用全长力臂。","given":"力方向与位矢夹角30°。","analysis":"有效垂距为r sinθ。","method":"τ=Fr sinθ。","principle":"力矩取垂直分量。","steps":["ℓ=0.8 sin30°=0.4 m。","τ=50×0.4=20 N·m，方向须由图给；题只求大小。"],"ans":"20 N·m。","verification":"等价垂直分力25 N乘0.8 m也得20。","pitfall":"用50×0.8=40而漏sin。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]}],"practice":[{"q":"力的作用线通过支点，作用点离支点1 m，F=100 N，力矩？","given":"作用线穿过支点。","analysis":"力臂是到作用线垂距。","method":"ℓ=0。","principle":"τ=Fℓ。","steps":["穿过意味着垂距0。","100×0=0。"],"ans":"0。","verification":"沿杆推不能产生该轴转动趋势。","pitfall":"直接把支点到作用点1 m当力臂。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"两反向平行力各8 N，作用线距0.3 m，合力与力偶矩？","given":"同一平面。","analysis":"合力抵消但转动不抵消。","method":"分别求矢量和与Fd。","principle":"力偶矩依两作用线间距。","steps":["合力0。","矩大小8×0.3=2.4 N·m。"],"ans":"0与2.4 N·m。","verification":"两力关于任一合适点矩相加为同值。","pitfall":"合力零就宣称完全平衡。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"一根2 m均匀杆重20 N，左端支点，右端竖直绳拉住，杆水平，绳张力？","given":"杆重在中点，静止。","analysis":"取支点矩消去支点反力。","method":"2T=20×1。","principle":"合矩零。","steps":["T=10 N。","竖直支反力R=20−10=10 N。"],"ans":"T=10 N。","verification":"右端向上矩20与重力向下矩20抵消。","pitfall":"把张力直接设等于杆重。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"3 m杆重忽略，左端支承A、距A 2 m处支承B，距A 3 m处挂60 N，按静力方程求反力并判断可行性。","given":"两支承只能向上推。","analysis":"悬出负载可能使A需要向下拉。","method":"绕A取矩，后验支承约束。","principle":"合矩与合力条件及单向接触。","steps":["2R_B=60×3，R_B=90 N。","R_A=60−90=−30 N，要求A向下拉，与仅向上支承不符。"],"ans":"该双接触平衡不可实现，需额外固定或会失去A接触。","verification":"若代入力方程可平衡，但违反物理支承方向。","pitfall":"负反力取绝对值30后继续说平衡。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]}],"quiz":{"q":"为何绕某未知支反力作用点取矩后，该力仍要出现在竖直合力方程？","given":"该力关于所选点力臂零。","analysis":"零力矩不等于力不存在。","method":"区分平动作用与绕点转动作用。","principle":"合力与合矩是不同条件。","steps":["取矩时该项因ℓ=0消去。","它仍参与总向上向下力平衡，须用合力方程求或检查。"],"ans":"因为它只是关于该点矩为零。","verification":"单支点仍能提供承重反力，即使对该点无矩。","pitfall":"把数学消元当作物理删除。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]},"exam":["矩题先画作用线和垂距，不能只找杆长","选未知力作用点取矩减少未知，之后代回合力","刚体题求完检查支承可推可拉及临界脱离，不只看方程数"],"quick":["选矩心","画作用线","定垂距和符号","联合平衡","查支承约束"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":150,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_5.2","url":"https://openstax.org/books/college-physics-2e/pages/9-2-the-second-condition-for-equilibrium","page_or_section":"9-2-the-second-condition-for-equilibrium","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":150,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_5.2","url":"https://openstax.org/books/college-physics-2e/pages/9-2-the-second-condition-for-equilibrium","page_or_section":"9-2-the-second-condition-for-equilibrium","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"矩题先画作用线和垂距，不能只找杆长","method":"τ=Fr sinθ。","principle":"力矩取垂直分量。","worked_example_index":2,"verification":"等价垂直分力25 N乘0.8 m也得20。","pitfall":"用50×0.8=40而漏sin。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用垂直力臂计算力矩”的抽样复核：若力作用线通过支点则应零，此处垂距非零。；若出现“只写5 J或把方向漏掉。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“联合平动转动条件求平面刚体平衡”的抽样复核：绕中点两支力矩抵消，总向上60 N等于重力60 N。；若出现“只令合力零便认为任何分配都行。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把数学消元当作物理删除。","correction":"因为它只是关于该点矩为零。","verification":"单支点仍能提供承重反力，即使对该点无矩。"}],"illustration_spec":{"title":"力臂与平面杆的平衡","objects":["支点O","r=0.8 m杆","50 N斜力","垂直力臂0.4 m","双支承杆"],"relations":["夹角30°","ℓ=r sinθ","力臂画到延长作用线的垂线","反力方向符合约束"],"labels":["O","r","θ=30°","ℓ=0.4 m","τ=20 N·m"],"format":"SVG","priority":"P0","reuse":"现有力图不能代替准确垂距图","english":"Draw a 0.8 m position vector and a 50 N force at 30 degrees to it. Construct the perpendicular distance from pivot O to the force line as 0.4 m, giving torque 20 N m. Distinguish the full rod length from the moment arm."}},"5.3":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":5,"section_id":"5.3","goals":["求平行力的合力与作用线","用力矩确定重心并判断稳定性"],"prerequisites":["力矩平衡","加权平均"],"flow":["代数合力","矩等效","作用线","质量重心","支承与稳定"],"concept_relation":"代数合力；矩等效；作用线；质量重心；支承与稳定","deep":["在近似均匀重力场内，物体各部分的重力形成平行力系，可用总重力作用于重心来等效其转动作用。由x_G=Σmᵢxᵢ/Σmᵢ可求离散质量的重心坐标；负坐标表示相对原点位置，不是负质量。","均匀规则物体重心常在对称中心，条件是质量分布也对称。挖孔、附加负载或材料密度改变会移动重心；几何中心不能无条件当作重心，重心也可以在物体材料之外，如环的中心。","稳定性取决于小扰动后重力矩的趋势或势能变化。支撑面上的物体在相应条件下，重力作用线落在支撑范围内才可由非负支承力维持；重心低、底面宽往往提高抗倾倒能力，但还需考虑外力、摩擦与动态效应。","求解后要检查合力的矩与原力系一致，坐标和距离的单位一致。对零合力情况先辨是否仍有力偶，不把ΣF=0自动解释成任何点都可任意安放一个“零合力”而忽略转动。"],"derive":["平行力沿共同方向取正：R=ΣFᵢ；当R≠0时，x_R=ΣFᵢxᵢ/R，由力矩等效确定。","均匀重力场：x_G=Σmᵢxᵢ/Σmᵢ；g相同可在分子分母相消。","R=0而ΣFᵢxᵢ≠0时为非零力偶，不能用一个单力等效。"],"examples":[{"q":"两同向向下力10 N与30 N，位于x=0和x=2 m，求合力及位置。","given":"平行力，原点在小力线上。","analysis":"合力与矩都需等效。","method":"R求和，x_R求加权。","principle":"R x_R=ΣFᵢxᵢ。","steps":["R=40 N向下。","x_R=(10×0+30×2)/40=1.5 m。"],"ans":"40 N向下，x=1.5 m。","verification":"合力矩40×1.5=60 N·m，原矩30×2=60；位置靠30 N。","pitfall":"总力对了却把位置取1 m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"x=0处向下30 N，x=2 m处向上10 N，取向下为正，求等效合力位置。","given":"反向平行力，R不为零。","analysis":"位置可能在线外。","method":"带符号求R和矩。","principle":"同一符号约定下R x_R=ΣFᵢxᵢ。","steps":["R=30−10=20 N向下。","x_R=(30×0−10×2)/20=−1 m。"],"ans":"20 N向下，作用线x=−1 m。","verification":"等效矩20×(−1)=−20与原−10×2一致。","pitfall":"认为位置必须在0至2 m内。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"2 kg位于x=0，3 kg位于x=4 m，支点放何处可使无质量杆平衡？","given":"g均匀，忽略杆重。","analysis":"重心按质量加权。","method":"x_G=Σmx/Σm。","principle":"各重力矩等效于总重力在重心。","steps":["x_G=(2×0+3×4)/(2+3)=12/5=2.4 m。","支点设在2.4 m，左右力矩2g×2.4与3g×1.6相等。"],"ans":"距2 kg端2.4 m。","verification":"4.8g=4.8g。","pitfall":"用中点2 m而不考虑质量差。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]}],"practice":[{"q":"两个相反平行力各5 N，相距1 m，可以用一个零合力完全替代吗？","given":"作用线不同。","analysis":"合力零但矩不零。","method":"算力偶。","principle":"M=Fd。","steps":["R=0。","M=5×1=5 N·m，单个零力不能提供此矩。"],"ans":"不能。","verification":"选择一个力作用线作矩心，另力仍给5 N·m。","pitfall":"零合力就无任何作用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"质量1 kg在x=−2 m，质量3 kg在x=2 m，重心？","given":"同一坐标系与均匀g。","analysis":"负坐标不是负质量。","method":"带坐标符号加权。","principle":"x_G=Σmx/Σm。","steps":["分子1×(−2)+3×2=4 kg·m。","除总质量4 kg得1 m。"],"ans":"x_G=1 m。","verification":"重心在两物体间且靠3 kg侧。","pitfall":"先把所有坐标取绝对值。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"均匀圆环重心可位于没有材料的圆心吗？","given":"质量分布对称、g近似均匀。","analysis":"重心是等效位置不是必须有物质的点。","method":"按对称质量配对。","principle":"相反位置等质量矩抵消。","steps":["各对质量关于圆心对称。","加权坐标和为0，故圆心是重心。"],"ans":"可以。","verification":"转动等效作用线并不要求该点有材料。","pitfall":"认为重心必须落在实体材料内。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"底面左右边界x=0与1 m，总重100 N，重力线x=0.8 m，求两端支持力；若重力线到1.2 m怎样？","given":"简化两支点，仅竖直力且支点只能推。","analysis":"支反力非负决定静态可行性。","method":"绕左端取矩，再求合力。","principle":"R_B×1=100x_G，R_A+R_B=100。","steps":["x=0.8时R_B=80、R_A=20 N，均可行。","x=1.2时R_B=120、R_A=−20 N，不能由仅向上接触维持。"],"ans":"前者可静止；后者需其他约束否则倾倒趋势。","verification":"负支反力揭示超出支撑范围。","pitfall":"把−20取正后说仍平衡。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]}],"quiz":{"q":"用x_R=ΣFᵢxᵢ/ΣFᵢ时分母为零，能直接答x_R=0吗？","given":"零合力，矩尚未判断。","analysis":"除零公式不适用。","method":"另查合矩。","principle":"零合力可伴非零力偶。","steps":["若合矩非零，为力偶，不能单力等效。","若合矩也零，整体系对平面刚体可为零作用，但不能由除零求位置0。"],"ans":"不能；必须分类审查合矩。","verification":"同量反向平行力分离就是反例。","pitfall":"把无定义商直接替成零。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]},"exam":["平行力题先定共同正方向，再带符号算总力和矩","重心题检查均匀g和质量分布，不先猜几何中心","稳定性题用支反力非负或重力矩解释，明确静态假设"],"quick":["代数合力","矩等效","作用线","质量重心","支承与稳定"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":156,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_5.3","url":"https://openstax.org/books/college-physics-2e/pages/9-3-stability","page_or_section":"9-3-stability","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":156,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_5.3","url":"https://openstax.org/books/college-physics-2e/pages/9-3-stability","page_or_section":"9-3-stability","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"平行力题先定共同正方向，再带符号算总力和矩","method":"x_G=Σmx/Σm。","principle":"各重力矩等效于总重力在重心。","worked_example_index":2,"verification":"4.8g=4.8g。","pitfall":"用中点2 m而不考虑质量差。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“求平行力的合力与作用线”的抽样复核：合力矩40×1.5=60 N·m，原矩30×2=60；位置靠30 N。；若出现“总力对了却把位置取1 m。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"p3","review_module":5,"feedback":"目标“用力矩确定重心并判断稳定性”的抽样复核：负支反力揭示超出支撑范围。；若出现“把−20取正后说仍平衡。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把无定义商直接替成零。","correction":"不能；必须分类审查合矩。","verification":"同量反向平行力分离就是反例。"}],"illustration_spec":{"title":"平行力合力位置与重心","objects":["同向10/30 N","反向30/10 N","x轴","合力作用线","支撑区"],"relations":["同向合力x=1.5 m","反向合力x=−1 m","R=0不强画有限单力"],"labels":["x/m","40 N","20 N","ΣFᵢxᵢ","支撑范围"],"format":"SVG","priority":"P0","reuse":"需准确比例和带符号位置的新SVG","english":"Construct exact parallel-force diagrams: downward 10 N at x=0 and 30 N at x=2 m give 40 N at x=1.5 m; downward 30 N at x=0 and upward 10 N at x=2 give downward 20 N at x=-1 m. Keep force and moment equivalence visible."}}},"物理7":{"7.1":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":7,"section_id":"7.1","goals":["由力与位移判断功的正负","区分平均功率和瞬时功率"],"prerequisites":["力与位移","三角函数与单位"],"flow":["力与位移","正负功","总功","平均与瞬时功率","效率收支"],"concept_relation":"力与位移；正负功；总功；平均与瞬时功率；效率收支","deep":["功率描述做功或能量传递的快慢，不是功的大小。平均功率为一段时间的功除时间；瞬时功率可写为F·v，需同一时刻、同一对象的力与速度。匀速拖拉时不代表所有功率都为零，只说明合力净功率可为零。","额定或输入功率、输出功率与效率不能混写。若效率η=有用输出能量/输入能量，在相同时间下也可用输出功率/输入功率；损耗能量不是从总能量中消失，而是转向不作为目标输出的形式。","单位1 J=1 N·m，1 W=1 J/s；kWh为能量单位，不能因为带W就称功率。设备一段时间的能耗需考虑功率随时间变化，恒功率模型才可直接用Pt。","解应用题先确定算哪一个力的功或哪一环节功率，审查给的是平均还是瞬时、输入还是输出。角度从力与位移量起，不能把题图中力与竖直的角未经转换就代入cos。"],"derive":["恒力功W=Fs cosθ；多个力总功W总=ΣWᵢ。","P平均=W/Δt；瞬时P=Fv cosθ。","η=W有用/W输入=P输出/P输入（同时间边界）；1 kWh=1000 W×3600 s=3.6×10⁶ J。"],"examples":[{"q":"20 N恒力与水平位移夹角60°，物体水平移动5 m，该力做功？","given":"夹角指力与位移。","analysis":"只取沿位移分量。","method":"W=Fs cosθ。","principle":"恒力做功定义。","steps":["沿位移分量20×0.5=10 N。","W=10×5=50 J。"],"ans":"+50 J。","verification":"垂直分量不做这段水平位移的功。","pitfall":"直接20×5忽略角度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]},{"q":"起重机5 s把100 kg负载匀速提高2 m，g=10，忽略其他负载，输出功率？","given":"求负载获得的机械能率。","analysis":"匀速不代表拉力不做功。","method":"W=mgh，再P=W/t。","principle":"拉力克服重力增加势能。","steps":["W=100×10×2=2000 J。","P=2000/5=400 W。"],"ans":"400 W有用输出。","verification":"拉力1000 N、速度0.4 m/s，Fv=400 W。","pitfall":"以合力零推出起重机功率零。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]},{"q":"电机输入功率1.0 kW，效率80%，以2 m/s匀速拉物体，拉力同向，求输出功率与拉力。","given":"效率在该工作状态给定。","analysis":"Fv对应输出而非输入。","method":"P出=ηP入，再F=P出/v。","principle":"同时间功率效率。","steps":["P出=0.80×1000=800 W。","F=800/2=400 N。"],"ans":"800 W、400 N。","verification":"输出800加损耗200等输入1000 W。","pitfall":"直接1000/2得500 N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]}],"practice":[{"q":"水平支持力竖直向上，物体水平移动3 m，这个力做功？","given":"支持方向与位移垂直。","analysis":"不是所有非零力都有非零功。","method":"cos90°=0。","principle":"功取沿位移分量。","steps":["W=Ns cos90°。","余弦0，故功0。"],"ans":"0 J。","verification":"支持力可存在但无水平分量。","pitfall":"只看有力有位移就说做功。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]},{"q":"摩擦力恒定5 N与位移反向，移动4 m，摩擦功？","given":"方向始终相反。","analysis":"负号代表阻碍。","method":"W=Fs cos180°。","principle":"反向力做负功。","steps":["5×4×(−1)=−20 J。","大小20 J但带负方向意义。"],"ans":"−20 J。","verification":"若只它做功，动能减少20 J。","pitfall":"答0因为反向。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]},{"q":"2 kWh是多少J？这是功率吗？","given":"kWh是功率乘时间。","analysis":"组合单位量纲。","method":"2×3.6×10⁶。","principle":"能量=功率×时间。","steps":["等于7.2×10⁶ J。","单位是能量，不是功率。"],"ans":"7.2×10⁶ J，能量。","verification":"2 kW连续1 h的能量。","pitfall":"把kWh读成千瓦每小时的功率。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]},{"q":"车受500 N恒定驱动力，同方向速度由10变20 m/s，瞬时驱动功率各多少？能直接说平均功率为后者吗？","given":"力恒定，未给速度随时间过程。","analysis":"瞬时量与区间平均不同。","method":"分别P=Fv。","principle":"功率依同一时刻速度。","steps":["起初5000 W。","末10000 W；平均需对应总功和总时间或额外速度过程。"],"ans":"5 kW、10 kW；不能把末值当平均。","verification":"若速度线性随时变才可另算平均7.5 kW。","pitfall":"用末速替代整个过程平均。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]}],"quiz":{"q":"人抱重物静止，手累且身体消耗能量，是否与“手对重物机械功为零”矛盾？","given":"重物没有位移，人体内部过程另论。","analysis":"对象和能量过程不同。","method":"分别划定重物外力功与人体代谢。","principle":"机械功依所研究物体位移。","steps":["重物位移0，手对它W=0。","人体肌肉维持状态仍可消耗化学能并散热。"],"ans":"不矛盾。","verification":"同一事件可有不同系统内部能量转换。","pitfall":"以主观疲劳替代物理功定义。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]},"exam":["功题明确施力者、对象、位移与夹角","功率题分平均/瞬时及输入/输出，匀速不等于驱动力功率零","效率题先画能量收支，损耗不说消失"],"quick":["力与位移","正负功","总功","平均与瞬时功率","效率收支"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":222,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.1","url":"https://openstax.org/books/college-physics-2e/pages/7-1-work-the-scientific-definition","page_or_section":"7-1-work-the-scientific-definition","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":222,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.1","url":"https://openstax.org/books/college-physics-2e/pages/7-1-work-the-scientific-definition","page_or_section":"7-1-work-the-scientific-definition","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"功题明确施力者、对象、位移与夹角","method":"P出=ηP入，再F=P出/v。","principle":"同时间功率效率。","worked_example_index":2,"verification":"输出800加损耗200等输入1000 W。","pitfall":"直接1000/2得500 N。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由力与位移判断功的正负”的抽样复核：垂直分量不做这段水平位移的功。；若出现“直接20×5忽略角度。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"p3","review_module":5,"feedback":"目标“区分平均功率和瞬时功率”的抽样复核：若速度线性随时变才可另算平均7.5 kW。；若出现“用末速替代整个过程平均。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"以主观疲劳替代物理功定义。","correction":"不矛盾。","verification":"同一事件可有不同系统内部能量转换。"}],"illustration_spec":{"title":"功的分量与功率边界","objects":["斜拉力20 N","水平位移5 m","60°夹角","输入输出损耗功率"],"relations":["沿位移分量10 N","W=50 J","输入1000=输出800+损耗200 W"],"labels":["θ=60°","Fcosθ","W/J","P/W","η=80%"],"format":"SVG","priority":"P0","reuse":"V22相关功图可核后复用，题值不同须说明","english":"Show a 20 N force at 60 degrees to a 5 m horizontal displacement, giving 50 J of work. Add a separate power balance of 1000 W input, 800 W useful output and 200 W loss; do not imply uniform motion means zero driving power."}},"7.2":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":7,"section_id":"7.2","goals":["由力位移图求有向功","用分段与面积处理变力并核条件"],"prerequisites":["恒力功","图象面积"],"flow":["恒力矩形","线性梯形","一般曲线","弹力与外力","总功检查"],"concept_relation":"恒力矩形；线性梯形；一般曲线；弹力与外力；总功检查","deep":["弹簧在胡克定律近似范围内，弹簧对物体的力与相对平衡位置的位移反向：F弹=−kx。把弹簧从0拉至伸长x时，若准静态外力平衡弹力，外力F外=+kx，其功与弹力功大小相等、符号相反。","变力功取决路径上的力分量分布，图下面积只表示所画力做功，并不自动是总功。若还存在摩擦或重力等其他做功力，求动能变化需加总所有相关功；“图给了一个力”不代表其他力不存在。","使用实验F-x数据估功时，应统一单位，辨测力的是外拉力还是弹力、x是位移还是伸长，并注意加载卸载曲线可能不同。若存在滞后，不能只按一条理想直线把储能和耗散全部合并。","对结果可用量纲、分段加法以及力是否助推或阻碍判断正负。若整段力分量非负且x增加，总功不应为负；若图面积相消为零，物体仍可能在中途先加速后减速，净功零不表示过程里每段无功。"],"derive":["一维W为Fₓ-x图有向面积；分段功可相加。","线性由F₁变F₂、位移Δx时W=(F₁+F₂)Δx/2；一般非线性不可只取端点平均。","胡克范围：0至x的准静态外力功+kx²/2，弹力功−kx²/2。"],"examples":[{"q":"F-x图0到3 m恒为4 N，求该力功。","given":"F为沿x分量，x增加。","analysis":"矩形面积。","method":"W=FΔx。","principle":"功对应F-x有向面积。","steps":["面积4×3=12 N·m。","图在正区，功为正。"],"ans":"+12 J。","verification":"与恒力公式一致。","pitfall":"把F-t面积冲量公式混用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]},{"q":"力随x由0 m时2 N线性增到4 m时10 N，求功并比较末力乘位移。","given":"沿运动方向的线性变力。","analysis":"梯形面积或线性平均。","method":"W=(2+10)×4/2。","principle":"线性情况下端点平均为位移平均力。","steps":["平均力6 N。","W=6×4=24 J；末力法10×4=40 J高估。"],"ans":"24 J。","verification":"矩形2×4=8加三角形8×4/2=16，共24。","pitfall":"所有变力都拿末值乘总位移。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]},{"q":"弹簧k=200 N/m，从自然长准静态拉长0.10 m，外力与弹力分别做功？","given":"胡克定律有效，无其他耗散。","analysis":"两力方向相反且线性。","method":"各取三角形面积及符号。","principle":"F外=kx，F弹=−kx。","steps":["末外力20 N，外力功0.5×20×0.10=1.0 J。","弹力功−1.0 J。"],"ans":"外力+1.0 J，弹力−1.0 J。","verification":"准静态动能变化近0，两力总功相消。","pitfall":"把20 N乘0.1得2 J或两功同号。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]}],"practice":[{"q":"0到2 m力+3 N，2到5 m力−2 N，总功？","given":"力分量图，x单调增。","analysis":"负区有向面积抵消。","method":"分段相加。","principle":"W=ΣFᵢΔxᵢ。","steps":["前段+6 J。","后段−6 J，合0。"],"ans":"0 J。","verification":"可中间先增能6再减6，不表示无作用。","pitfall":"把面积都取正得到12 J。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]},{"q":"F-x图面积单位是什么？与F-t图面积是否相同物理量？","given":"横轴分别m与s。","analysis":"单位乘积决定基本解释。","method":"分别相乘。","principle":"力位移给功，力时间给冲量。","steps":["N·m=J。","N·s=kg·m/s，两个不同物理量。"],"ans":"前为功，后为冲量。","verification":"不能把m与s互换。","pitfall":"不看横轴只认力图面积。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]},{"q":"一曲线起末力相同均为0，中间有正峰，能以端点平均0推功0吗？","given":"中间力在一段为正且x增加。","analysis":"非线性端点不代表平均。","method":"看整个曲线面积。","principle":"功累积所有位置贡献。","steps":["正峰下有正面积。","端点平均只对线性等条件成立，此处不能套。"],"ans":"不能；功应为正。","verification":"曲线可类似正半波，端点0不消除内部面积。","pitfall":"把梯形公式用于任意曲线。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]},{"q":"k=100 N/m弹簧由0.10拉至0.20 m，准静态外功？","given":"胡克范围，无耗散。","analysis":"计算储能差而非末储能。","method":"W外=k(x₂²−x₁²)/2。","principle":"面积为两三角形之差。","steps":["0.5×100×(0.04−0.01)=1.5 J。","等价力从10到20 N，平均15乘0.10=1.5 J。"],"ans":"+1.5 J。","verification":"两个方法相合。","pitfall":"直接算到0.2的2 J而忘初已伸长。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]}],"quiz":{"q":"给出某拉力F-x面积10 J，能否直接说物体动能增加10 J？","given":"未说明其他力功。","analysis":"单力功与总功不同。","method":"列其他力并求总功。","principle":"动能变化等于合力总功。","steps":["摩擦等可做负功。","只有其他总功为0等条件下，ΔK才等10 J。"],"ans":"不能无条件。","verification":"若摩擦功−10 J，净功0而动能不变。","pitfall":"把所画一个力当成所有力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]},"exam":["面积题先核横轴与力的分量，分正负段求和","端点平均只在线性条件用，曲线需更多信息","弹簧题明确外力或弹力、起末伸长与准静态条件"],"quick":["恒力矩形","线性梯形","一般曲线","弹力与外力","总功检查"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":229,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.2","url":"https://openstax.org/books/college-physics-2e/pages/7-2-kinetic-energy-and-the-work-energy-theorem","page_or_section":"7-2-kinetic-energy-and-the-work-energy-theorem","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":229,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.2","url":"https://openstax.org/books/college-physics-2e/pages/7-2-kinetic-energy-and-the-work-energy-theorem","page_or_section":"7-2-kinetic-energy-and-the-work-energy-theorem","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"面积题先核横轴与力的分量，分正负段求和","method":"各取三角形面积及符号。","principle":"F外=kx，F弹=−kx。","worked_example_index":2,"verification":"准静态动能变化近0，两力总功相消。","pitfall":"把20 N乘0.1得2 J或两功同号。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由力位移图求有向功”的抽样复核：与恒力公式一致。；若出现“把F-t面积冲量公式混用。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用分段与面积处理变力并核条件”的抽样复核：准静态动能变化近0，两力总功相消。；若出现“把20 N乘0.1得2 J或两功同号。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把所画一个力当成所有力。","correction":"不能无条件。","verification":"若摩擦功−10 J，净功0而动能不变。"}],"illustration_spec":{"title":"力位移面积与弹簧功","objects":["2到10 N线性图","正负分段图","弹力/外力对称图"],"relations":["0至4 m面积24 J","正负面积可抵消","外力与弹力方向相反"],"labels":["Fₓ/N","x/m","24 J","F外=kx","F弹=−kx"],"format":"SVG","priority":"P0","reuse":"V22 P25力位移图可复用经核数值，勿重复展示同图","english":"Plot F_x increasing linearly from 2 to 10 N over 0 to 4 m and shade exactly 24 J. In a separate Hookean spring panel distinguish applied quasi-static force +kx from restoring force -kx, with signed work areas."}},"7.3":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":7,"section_id":"7.3","goals":["由总功求动能及速度变化","区分动能、动量和参考系依赖"],"prerequisites":["牛顿第二定律","匀变速关系"],"flow":["运动参考系","平方关系","总功","初末动能","物理可行性"],"concept_relation":"运动参考系；平方关系；总功；初末动能；物理可行性","deep":["一维恒定合力推导时，F=ma与v²−u²=2as联立得到Fs=mv²/2−mu²/2。该推导中的恒力是方便的起点，不意味着动能定理只适用于恒力；对变力可分段并求极限或用图面积累积。","净功为正使速率增加，负使速率下降，零使初末动能相同。但总功零不保证运动方向不变，圆周运动的向心力可改变速度方向而不改变速率；动能定理也不直接给出运动轨迹方向。","制动距离可在阻力恒定等假设下由动能定理估计：制动力做负功把初动能减少至零。真实刹车还包括反应距离和随条件改变的摩擦，不能把纯制动模型当作任何道路的安全停车距离保证。","求速度时由平方只得到速率大小，方向要结合几何、过程和初始条件判断。若算得末动能负值，通常说明物体在预设位置前已停下、假设不成立或计算有误，不能对负数取平方根后忽略其物理含义。"],"derive":["由Fs=mas、2as=v²−u²，得W总=m(v²−u²)/2。","K=mv²/2；p=mv时K=p²/(2m)，仅同一经典平动模型。","恒定反向阻力f使物体停止：fs=mu²/2，s=mu²/(2f)，需阻力恒定且不含反应阶段。"],"examples":[{"q":"质量2 kg物体速率3 m/s，动能多少？若速度改成−3 m/s呢？","given":"同一参考系，经典平动。","analysis":"平方使用速率大小。","method":"K=mv²/2。","principle":"动能非负。","steps":["K=0.5×2×9=9 J。","−3平方仍9，动能也9 J。"],"ans":"均9 J。","verification":"方向相反改变动量但不改变相同速率的K。","pitfall":"把负速度代成负动能。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]},{"q":"2 kg物体初速2 m/s，驱动力功20 J、摩擦功−8 J，其余功0，末速率？","given":"总功12 J。","analysis":"先求初能再加净功。","method":"K末=K初+W总。","principle":"动能定理。","steps":["K初=0.5×2×4=4 J，K末=4+20−8=16 J。","v=√(2×16/2)=4 m/s。"],"ans":"4 m/s。","verification":"动能增加12 J正等于净功。","pitfall":"只用20或把初K漏掉。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]},{"q":"1000 kg车初速10 m/s，恒定制动力5000 N反向，忽略反应距离，制动距离？若初速加倍呢？","given":"水平，无其他净功，阻力恒定。","analysis":"停止需要耗掉初动能。","method":"−fs=0−mu²/2。","principle":"动能定理。","steps":["s=1000×100/(2×5000)=10 m。","初速20时s=1000×400/10000=40 m。"],"ans":"10 m；加倍初速为40 m。","verification":"距离与u²成正比，增为4倍。","pitfall":"说速度两倍距离仅两倍，或包含未计算的反应距离。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]}],"practice":[{"q":"质量不变、速率由2到6 m/s，动能变几倍？","given":"同一模型参考系。","analysis":"速率比平方。","method":"(6/2)²。","principle":"K∝v²。","steps":["速率3倍。","动能9倍。"],"ans":"9倍。","verification":"若m=1，K从2到18 J。","pitfall":"按线性比答3倍。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]},{"q":"两物体动量大小同为6 kg·m/s，质量2与3 kg，动能各多少？","given":"经典平动。","analysis":"固定p时反比于m。","method":"K=p²/(2m)。","principle":"由p=mv代入。","steps":["2 kg者36/4=9 J。","3 kg者36/6=6 J。"],"ans":"9 J与6 J。","verification":"速度分别3和2 m/s，直接计算相同。","pitfall":"固定p仍说质量大K必大。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]},{"q":"匀速圆周运动向心力的功为0，是否速度矢量不变？","given":"力处处垂直瞬时位移。","analysis":"速率与方向不同。","method":"说明动能与动量变化。","principle":"垂直力不做功但可改变方向。","steps":["动能不变即速率不变。","方向持续变化，所以速度矢量变。"],"ans":"不是，只有速率恒定。","verification":"向心加速度非零支持方向变化。","pitfall":"总功0推出合力0。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]},{"q":"1 kg物体初速4 m/s，受恒阻力2 N，想计算走5 m后的动能得到−2 J，应如何解释？","given":"除阻力外无净功，阻力始终反向。","analysis":"预设5 m超过停距。","method":"先求初K和停距。","principle":"动能不可能负。","steps":["K初=8 J，s停=8/2=4 m。","已在4 m停下，不能仍按同方向滑动5 m模型计算。"],"ans":"5 m状态假设不成立，须重新描述停止后的过程。","verification":"4 m时K=0；负值是模型外推警报。","pitfall":"把负动能取绝对值或虚构速度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]}],"quiz":{"q":"物体受恒力转向，初末速率相同，能由动能定理断言初末动量相同吗？","given":"只知速率大小相同。","analysis":"动能为标量不包含方向。","method":"比较K与p定义。","principle":"K依v²，p依速度矢量。","steps":["ΔK=0说明总功0。","若方向改变，p可改变；需方向信息才能求Δp。"],"ans":"不能。","verification":"反向同速可有Δp大小2mv而ΔK0。","pitfall":"以能量守恒替代矢量关系。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]},"exam":["能量题先加总各力功并保留初动能","比较题说清固定m还是固定p，不同约束结论不同","求得负K要检查是否提前停止，速率根号不提供方向"],"quick":["运动参考系","平方关系","总功","初末动能","物理可行性"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":232,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.3","url":"https://openstax.org/books/college-physics-2e/pages/7-2-kinetic-energy-and-the-work-energy-theorem","page_or_section":"7-2-kinetic-energy-and-the-work-energy-theorem","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":232,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.3","url":"https://openstax.org/books/college-physics-2e/pages/7-2-kinetic-energy-and-the-work-energy-theorem","page_or_section":"7-2-kinetic-energy-and-the-work-energy-theorem","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"能量题先加总各力功并保留初动能","method":"−fs=0−mu²/2。","principle":"动能定理。","worked_example_index":2,"verification":"距离与u²成正比，增为4倍。","pitfall":"说速度两倍距离仅两倍，或包含未计算的反应距离。"},"diagnostics":[{"goal_index":0,"question_ref":"e1","review_module":4,"feedback":"目标“由总功求动能及速度变化”的抽样复核：动能增加12 J正等于净功。；若出现“只用20或把初K漏掉。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"q","review_module":5,"feedback":"目标“区分动能、动量和参考系依赖”的抽样复核：反向同速可有Δp大小2mv而ΔK0。；若出现“以能量守恒替代矢量关系。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"以能量守恒替代矢量关系。","correction":"不能。","verification":"反向同速可有Δp大小2mv而ΔK0。"}],"illustration_spec":{"title":"动能平方关系与制动距离","objects":["同质量不同速度","K对v²直线","恒阻力制动图","停距标记"],"relations":["速度2倍K4倍","恒阻力停距与初速平方正比","不画负动能实态"],"labels":["K=mv²/2","W总=ΔK","10 m","40 m","不含反应距离"],"format":"SVG","priority":"P0","reuse":"相关V22能量图可补充，需核是否对应本题","english":"Show kinetic energy proportional to speed squared and compare ideal constant-force braking distances 10 m and 40 m for initial speeds 10 and 20 m/s. State that reaction distance and road variability are excluded, and never depict negative kinetic energy as a real state."}},"7.4":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":7,"section_id":"7.4","goals":["用保守力功定义势能差","分别求重力与弹性势能并说明零点"],"prerequisites":["功与能","胡克定律"],"flow":["相互作用系统","保守力","零点与差","重力势能","弹性势能"],"concept_relation":"相互作用系统；保守力；零点与差；重力势能；弹性势能","deep":["重力功由高度差决定，不由路径总长度决定。缓坡路径较长但重力沿运动分量较小，固定起终高度下二者效果相抵；外力做功是否相同还需审查摩擦等其他作用，不能把重力路径无关推广所有力。","理想弹簧在胡克范围内以自然长度为零形变，U_s=kx²/2。伸长与压缩相同大小时势能相同，但弹力方向相反；x是相对自然长度的形变量，不是弹簧总长，也不是物体任意位移。","弹簧势能公式可由准静态外力F=kx的F-x三角形面积得到。若材料有明显滞后或超出弹性范围，输入功不一定全部变成可恢复弹性势能，模型需要修改。","使用势能差时先选系统、零点和符号，再求初末差。负势能不代表系统不可能，负的ΔU说明势能降低；不要为了结果为正随意改零点或取绝对值，尤其在守恒方程中必须前后使用同一约定。"],"derive":["W重=mg(h_i−h_f)=−ΔU_g；近地面U_g=mgh+C。","U_s=kx²/2，x为自然长起算的伸长或压缩；W弹=U_s初−U_s末。","改零点只加同一常数，不改势能差、保守力功或可观测运动。"],"examples":[{"q":"2 kg物体从所选h=1 m升到h=4 m，g=10，势能增加及重力功？","given":"均匀重力场。","analysis":"势能增量与重力功反号。","method":"ΔU=mgΔh，W重=−ΔU。","principle":"保守力功关系。","steps":["Δh=3 m，ΔU=2×10×3=60 J。","重力功−60 J。"],"ans":"势能+60 J，重力功−60 J。","verification":"升高时重力与位移相反，负功合理。","pitfall":"把重力功也写+60。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]},{"q":"k=100 N/m弹簧自然长0.30 m，被拉到0.40 m，势能？","given":"胡克范围，以自然长为零形变。","analysis":"应取伸长而非总长。","method":"x=0.40−0.30，U=kx²/2。","principle":"外力准静态输入三角形功储为弹性势能。","steps":["x=0.10 m。","U=0.5×100×0.01=0.50 J。"],"ans":"0.50 J。","verification":"末弹力10 N，平均外力5 N乘0.1 m=0.5 J。","pitfall":"把0.40当x。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]},{"q":"同一物体在两个零点约定下初末势能分别为20到50 J、−80到−50 J，运动预测会不同吗？","given":"两套能量只差共同常数100 J。","analysis":"绝对值不同但差相同。","method":"比较ΔU与保守力功。","principle":"势能零点不影响差值。","steps":["第一套ΔU=30 J。","第二套ΔU=(−50)−(−80)=30 J，W保均−30 J。"],"ans":"不会仅因零点不同而改变预测。","verification":"各状态差100，但初末变化一致。","pitfall":"看到负势能就判不可能。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]}],"practice":[{"q":"1 kg物体下降2 m，g=10，重力功和势能变化？","given":"均匀重力场。","analysis":"下降与重力同向。","method":"W=mg×下降高度。","principle":"W重=−ΔU。","steps":["W=1×10×2=20 J。","ΔU=−20 J。"],"ans":"+20 J、−20 J。","verification":"势能减少可供其他形式能增加。","pitfall":"把下降高度带负后又多加一次负号。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]},{"q":"同弹簧伸长0.05与压缩0.05 m，储能相同吗、弹力方向相同吗？","given":"胡克模型，以自然长为原点。","analysis":"平方与带符号力不同。","method":"比较U和F。","principle":"U=kx²/2，F=−kx。","steps":["两种x²相同故U相同。","x符号相反故F方向相反。"],"ans":"能量相同，弹力方向相反。","verification":"恢复力都指向自然长。","pitfall":"势能相同就说力方向也相同。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]},{"q":"同起终高度沿两不同无摩擦路径，重力功会因路径长而更大吗？","given":"仅比较重力功。","analysis":"重力为保守力。","method":"用mg(h_i−h_f)。","principle":"功只由高度差。","steps":["两路径高度差相同。","故重力功相同，不用路程总长乘mg。"],"ans":"不会。","verification":"长缓坡的重力沿程分量较小。","pitfall":"把重力大小mg乘全部曲线长度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]},{"q":"k=200 N/m弹簧形变由0.20变0.10 m，弹力做多少功？","given":"均为伸长，胡克范围。","analysis":"弹力释放储能。","method":"W弹=U初−U末。","principle":"保守力功等于势能减少。","steps":["U初=0.5×200×0.04=4 J。","U末=1 J，W=3 J。"],"ans":"+3 J。","verification":"伸长减小，弹力与收缩位移同向。","pitfall":"只算末U=1 J当作功。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]}],"quiz":{"q":"某点重力势能−40 J，可以用“能量不能为负”判错吗？","given":"零点任意选定。","analysis":"势能与动能的非负性质不同。","method":"问零点并比较势能差。","principle":"势能加常数不影响物理。","steps":["该点可位于所选零点下方。","检查初末零点一致与差值，而非强迫U≥0。"],"ans":"不能仅据负号判错。","verification":"同点换零面可得到正值而运动不变。","pitfall":"把K非负推广所有能量定义。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]},"exam":["势能题先选系统零点并写初末，不只记mgh","弹簧题先求形变量再平方，区分总长和伸长","路径题明确只讨论保守力功，其他力功另审"],"quick":["相互作用系统","保守力","零点与差","重力势能","弹性势能"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":239,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.4","url":"https://openstax.org/books/college-physics-2e/pages/7-3-gravitational-potential-energy","page_or_section":"7-3-gravitational-potential-energy","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":239,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.4","url":"https://openstax.org/books/college-physics-2e/pages/7-3-gravitational-potential-energy","page_or_section":"7-3-gravitational-potential-energy","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"势能题先选系统零点并写初末，不只记mgh","method":"比较ΔU与保守力功。","principle":"势能零点不影响差值。","worked_example_index":2,"verification":"各状态差100，但初末变化一致。","pitfall":"看到负势能就判不可能。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用保守力功定义势能差”的抽样复核：升高时重力与位移相反，负功合理。；若出现“把重力功也写+60。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“分别求重力与弹性势能并说明零点”的抽样复核：各状态差100，但初末变化一致。；若出现“看到负势能就判不可能。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把K非负推广所有能量定义。","correction":"不能仅据负号判错。","verification":"同点换零面可得到正值而运动不变。"}],"illustration_spec":{"title":"势能零点和弹簧形变","objects":["同高度两零点","初末高度","自然长弹簧","伸长与压缩"],"relations":["改零点差值不变","伸压同大小U相同","弹力恢复方向相反"],"labels":["ΔU","W保=−ΔU","x相对自然长","U_s=kx²/2"],"format":"SVG","priority":"P0","reuse":"V22 P18弹簧能图可复用，需说明自然长与零点","english":"Show two gravitational potential references yielding the same delta U, and an ideal spring at natural length, equal extension and compression. Mark deformation x from natural length and opposite restoring-force arrows with equal stored energies."}},"7.5":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":7,"section_id":"7.5","goals":["按做功类别判定机械能是否守恒","用能量收支求速度高度及耗散"],"prerequisites":["动能与势能","功和系统边界"],"flow":["选系统零点","初末K与U","其他力功","分段收支","可达与接触"],"concept_relation":"选系统零点；初末K与U；其他力功；分段收支；可达与接触","deep":["选零点并列初末状态有助于减少中间过程计算。沿曲线运动仍可用相同起终能量关系，只要条件满足；但求运动方向、接触力和是否离轨，能量方程通常不够，还需动力学与几何约束。","弹簧与重力共同作用时应把相应势能都列入，先区分自然长度、初形变与高度变化。弹簧由压缩释放可以把储能转为动能，但物体是否继续接触弹簧、何时脱离等需按装置条件分析。","多个过程可分段：粗糙段有耗散、光滑段可守恒、碰撞段机械能可能突变。不能因为整个题出现某个光滑面就把碰撞和粗糙段也一并守恒；系统和条件可随问题分段明确。","解完检查所需能量是否充足、末速率是否实数，以及机械能差与其他力功是否一致。若能量不足到达某高度，应求转向点或说明不可达，不把负的v²继续当作正常数值答案。"],"derive":["由W总=ΔK及W保=−ΔU，得Δ(K+U)=W其他。","W其他=0时K初+U初=K末+U末；有摩擦等时保留其功。","近地面无耗散下v²=v₀²+2g(h₀−h)，只给速率关系，接触与方向需另判。"],"examples":[{"q":"1 kg物体从5 m高静止滑到地面，光滑且保持接触，g=10，地面速率？","given":"重力势能零面取地面，法向力不做功。","analysis":"机械能守恒。","method":"mgh=mv²/2。","principle":"其他力总功0。","steps":["初U=1×10×5=50 J。","末K=50 J，v=√100=10 m/s。"],"ans":"10 m/s。","verification":"0.5×1×100=50 J，与初能一致。","pitfall":"把路径总长当h或忘平方根。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]},{"q":"2 kg物体初速4 m/s，从3 m高到1 m高，摩擦功−8 J，g=10，末速率？","given":"起末高度同零点，已给摩擦总功。","analysis":"不能机械能守恒，需收支。","method":"K末=K初+mg(h初−h末)+W摩。","principle":"Δ(K+U)=W其他。","steps":["K初=16 J，势能降低40 J。","K末=16+40−8=48 J，v=√(2×48/2)=√48≈6.93 m/s。"],"ans":"约6.93 m/s。","verification":"末机械能48+20=68，初16+60=76，差−8。","pitfall":"因有势能就把摩擦忽略。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]},{"q":"0.5 kg物体靠在压缩0.10 m、k=200 N/m弹簧上，在光滑水平面释放，弹簧回自然长后物体速率？","given":"理想接触，弹簧不再拉物体，无其他耗散。","analysis":"形变储能转平动能。","method":"kx²/2=mv²/2。","principle":"选物体弹簧系统，其他功0。","steps":["初弹性能1 J。","0.25v²=1，v=2 m/s。"],"ans":"2 m/s。","verification":"初末均1 J，形变到0时储能释放完。","pitfall":"把最大弹力20 N当全程恒力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]}],"practice":[{"q":"光滑轨道上有电机持续驱动，能无条件机械能守恒吗？","given":"无摩擦但电机可做功。","analysis":"无摩擦不等于无能量输入。","method":"核其他力功。","principle":"ΔE机械=W其他。","steps":["电机正功输入机械能。","若未把能源系统完整纳入，机械能一般增加。"],"ans":"不能。","verification":"无摩擦只排除了一个耗散项。","pitfall":"只看光滑一词决定守恒。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]},{"q":"初机械能30 J，其他力总功−12 J，末机械能多少？总能量消失了吗？","given":"同一系统机械形式。","analysis":"负功转出机械能。","method":"E末=E初+W其他。","principle":"能量收支。","steps":["E末=30−12=18 J。","12 J可转内能等，总能量并未因此消失。"],"ans":"18 J；未消失。","verification":"初30=末机械18+转出12。","pitfall":"把机械能损失称总能量消灭。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]},{"q":"物体以10 m/s向上运动，g=10，无阻力，最高再升多高？","given":"末速0，均匀g。","analysis":"初动能转重力势能。","method":"mv₀²/2=mgΔh。","principle":"机械能守恒。","steps":["Δh=v₀²/(2g)=100/20=5 m。","质量相消。"],"ans":"5 m。","verification":"运动学0=100−2×10×5相合。","pitfall":"用v₀/g=1 s当高度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]},{"q":"1 kg从高3 m静止出发，到高1 m处前累计摩擦功−25 J，g=10，能到吗？","given":"无外部输入。","analysis":"可释放势能只有20 J。","method":"估可用K并判负值。","principle":"能量必须满足K≥0。","steps":["K末=30−10−25=−5 J。","负值说明不能按该过程到该状态，需更早停止或条件改变。"],"ans":"不能依题设过程到达。","verification":"目标路径所需耗散超出可用势能5 J。","pitfall":"对负能量取绝对值得速度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]}],"quiz":{"q":"过山车能量计算给出某位置正的速率，是否已经证明车不会离开轨道？","given":"未给向心力和接触约束分析。","analysis":"能量不包含全部力与接触信息。","method":"另列径向动力学并查法向力。","principle":"接触通常需N≥0等条件。","steps":["能量方程仅提供候选速率。","用该v审查径向合力及支持约束，若需负N则假设接触失效。"],"ans":"尚未证明。","verification":"同一速率在不同曲率位置的N不同。","pitfall":"把能量可达等同所有动力学条件可行。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]},"exam":["能量题先定系统，重力功与势能别重复算","分段题逐段审查摩擦、驱动和碰撞，不能全程一式守恒","算出v后若涉及轨道再查接触，负v²说明预设状态不可达"],"quick":["选系统零点","初末K与U","其他力功","分段收支","可达与接触"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":245,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.5","url":"https://openstax.org/books/college-physics-2e/pages/7-6-conservation-of-energy","page_or_section":"7-6-conservation-of-energy","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":245,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.5","url":"https://openstax.org/books/college-physics-2e/pages/7-6-conservation-of-energy","page_or_section":"7-6-conservation-of-energy","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"能量题先定系统，重力功与势能别重复算","method":"kx²/2=mv²/2。","principle":"选物体弹簧系统，其他功0。","worked_example_index":2,"verification":"初末均1 J，形变到0时储能释放完。","pitfall":"把最大弹力20 N当全程恒力。"},"diagnostics":[{"goal_index":0,"question_ref":"p0","review_module":4,"feedback":"目标“按做功类别判定机械能是否守恒”的抽样复核：无摩擦只排除了一个耗散项。；若出现“只看光滑一词决定守恒。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“用能量收支求速度高度及耗散”的抽样复核：末机械能48+20=68，初16+60=76，差−8。；若出现“因有势能就把摩擦忽略。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把能量可达等同所有动力学条件可行。","correction":"尚未证明。","verification":"同一速率在不同曲率位置的N不同。"}],"illustration_spec":{"title":"机械能收支与适用条件","objects":["高低两状态","K/U能量条","摩擦转出箭头","弹簧释放","轨道接触检查"],"relations":["初机械76末68差8","W其他=ΔE机械","能量可达与N约束分开"],"labels":["K","U_g","U_s","W其他","N≥0另查"],"format":"SVG","priority":"P0","reuse":"V22 P07可复核复用，需注明具体示例区别","english":"Draw energy-accounting bars with 76 J initial mechanical energy and 68 J final plus 8 J transferred to other forms. Show conservation only when other work is zero, and keep track-contact force constraints as a separate check."}},"7.6":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":7,"section_id":"7.6","goals":["区分静能、动能与系统质量变化","用质能关系换算能量并保持系统边界一致"],"prerequisites":["科学记数法","能量单位"],"flow":["静能定义","系统边界","质量差","单位换算","可用能与限制"],"concept_relation":"静能定义；系统边界；质量差；单位换算；可用能与限制","deep":["用原子质量计算时要审查电子数是否在两边抵消，不能混用原子质量、裸核质量和自由核子质量而不处理电子。题目直接给质量差时可换算，但完整核反应的质量差还需可靠质量数据与反应条件。","c很大，因此日常数量的能量对应质量变化极小。并非所有质量都能在任意装置中完全转为可用输出能量；给定质量所对应静能是能量尺度，不自动等于某种燃料现实可提取的能量。","光子静质量为零但有能量和动量，这提醒E₀=mc²说的是静能关系，不可把它解释为任何有能量实体都必须有非零静质量。更一般的能量动量关系超出本节基础计算时应单独说明，不能用低速K式求光子动能。","换算MeV与J时写清每反应、每个粒子或总量；乘反应次数才得到总能量。结果核验可先看数量级和单位，再核是否把能量变化、静能与可用输出混成一项。"],"derive":["静能E₀=mc²；同边界前后ΔE=Δmc²，符号需按吸收或释放解释。","本节数值题取c=3.00×10⁸ m/s；1 eV=1.602176634×10⁻¹⁹ J。","题设可用1 u c²≈931.5 MeV；质量差为u时乘该能量因子，不把u直接当kg。"],"examples":[{"q":"1.00 g质量对应多少静能？取c=3.00×10⁸ m/s。是否等于现实任意1 g燃料都可输出此能量？","given":"只求静能尺度。","analysis":"先g转kg，后解释可提取性。","method":"E₀=mc²。","principle":"质能关系不是装置效率承诺。","steps":["m=1.00×10⁻³ kg。","E₀=10⁻³×9.00×10¹⁶=9.00×10¹³ J。"],"ans":"9.00×10¹³ J；不保证现实燃料全可提取。","verification":"kg·m²/s²=J，1 kg对应9×10¹⁶ J。","pitfall":"漏g转kg或把静能当必然可用能。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]},{"q":"某假设核反应前后质量差0.0100 u，给1 u c²=931.5 MeV，释放能量多少？","given":"正质量差表示初静质量更大，其他守恒条件已满足。","analysis":"给的换算量已经含c²。","method":"Q=Δm×931.5 MeV/u。","principle":"静质量降低可转为其他能量。","steps":["Q=0.0100×931.5=9.315 MeV。","按3位有效数字约9.32 MeV。"],"ans":"约9.32 MeV/次反应。","verification":"0.01 u约百分之一931.5 MeV，数量级约9。","pitfall":"再额外乘c²或把质量差当kg。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]},{"q":"一隔离容器释放3.00×10⁸ J辐射到系统外，取c=3×10⁸，静止系统质量减少多少？若把辐射也算系统内呢？","given":"初末整体静止，辐射对称发射使净动量为零，其他交换忽略。","analysis":"质量变化取决边界是否含离开能量。","method":"Δm大小=E离开/c²。","principle":"同边界能量与质量收支。","steps":["减少3×10⁸/(9×10¹⁶)=3.33×10⁻⁹ kg。","若边界包含辐射，总系统能量仍需包含它，不能把它再次记成丢失。"],"ans":"容器系统少约3.33×10⁻⁹ kg；总系统账目另含辐射。","verification":"乘c²回得3×10⁸ J。","pitfall":"忽略系统边界而说总能量无故消失。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]}],"practice":[{"q":"2.0 MeV是多少J？","given":"1 MeV=10⁶ eV。","analysis":"先指数再基本换算。","method":"乘10⁶与eV到J因子。","principle":"能量单位换算。","steps":["2.0×10⁶×1.602176634×10⁻¹⁹=3.20435×10⁻¹³ J。","按2位约3.2×10⁻¹³ J。"],"ans":"约3.2×10⁻¹³ J。","verification":"MeV是单次微观能量仍可对应很小J。","pitfall":"把Mega写成10⁻⁶。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]},{"q":"低速物体静质量不变，其速度增加时总能量会增加吗？","given":"外界做正功加速。","analysis":"静能与动能不同项。","method":"区分E₀和K。","principle":"能量可通过动能增加，不需把静质量定义改成速度变量。","steps":["静能mc²保持。","动能随速度增加，总能量增加。"],"ans":"会。","verification":"低速ΔK≈m(v₂²−v₁²)/2。","pitfall":"说质量不变所以任何能量都不变。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]},{"q":"质量亏损是否意味着核反应可不守恒电荷和核子数？","given":"讨论所给普通核反应模型。","analysis":"质能关系不取代其他守恒律。","method":"分别检查反应式。","principle":"能量与电荷等守恒是不同约束。","steps":["质量差可对应释放能。","仍需核反应两侧电荷和核子等相应守恒。"],"ans":"不意味着。","verification":"错误配平不能因Q算得正就变合法。","pitfall":"把质能可转换当作所有粒子数随意改变。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]},{"q":"每反应释放4.0×10⁻¹³ J，共10¹⁵次反应，总能量及理想等效质量变化？取c=3×10⁸。","given":"各反应相同，能量全部计总释放。","analysis":"微观单次量先乘次数。","method":"E=NQ，再Δm=E/c²。","principle":"可加能量与质能关系。","steps":["E=10¹⁵×4.0×10⁻¹³=4.0×10² J。","Δm=400/(9×10¹⁶)≈4.4×10⁻¹⁵ kg。"],"ans":"400 J，约4.4×10⁻¹⁵ kg。","verification":"400 J虽宏观可测，等效质量仍极小。","pitfall":"用每次能量直接求整个系统变化而漏N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]}],"quiz":{"q":"光子有能量但静质量0，是否否定E₀=mc²？","given":"E₀定义为静能，光子没有静止参考系。","analysis":"不能把静能式当所有能量的唯一表达。","method":"区分适用对象与完整能量动量关系。","principle":"光子能量不由非零静质量的静能来解释。","steps":["零静质量不等于零能量。","E₀=mc²不声称光子能量全是静能，低速mv²/2也不适用于光子。"],"ans":"不否定，是误用公式范围造成表面矛盾。","verification":"光子无静止态，不能把其速度设0来定义静能实验。","pitfall":"以有能量推出必须有非零静质量。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]},"exam":["质能题先定静能或能量变化、系统边界及单位","核能换算明确每次与总量，原子/核质量数据不混用","解释题不把mc²静能等同任意燃料实际可用输出，不以其替代配平"],"quick":["静能定义","系统边界","质量差","单位换算","可用能与限制"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":250,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.6","url":"https://openstax.org/books/college-physics-2e/pages/28-6-relativistic-energy","page_or_section":"28-6-relativistic-energy","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":250,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.6","url":"https://openstax.org/books/college-physics-2e/pages/28-6-relativistic-energy","page_or_section":"28-6-relativistic-energy","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"质能题先定静能或能量变化、系统边界及单位","method":"Δm大小=E离开/c²。","principle":"同边界能量与质量收支。","worked_example_index":2,"verification":"乘c²回得3×10⁸ J。","pitfall":"忽略系统边界而说总能量无故消失。"},"diagnostics":[{"goal_index":0,"question_ref":"p1","review_module":4,"feedback":"目标“区分静能、动能与系统质量变化”的抽样复核：低速ΔK≈m(v₂²−v₁²)/2。；若出现“说质量不变所以任何能量都不变。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用质能关系换算能量并保持系统边界一致”的抽样复核：乘c²回得3×10⁸ J。；若出现“忽略系统边界而说总能量无故消失。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"以有能量推出必须有非零静质量。","correction":"不否定，是误用公式范围造成表面矛盾。","verification":"光子无静止态，不能把其速度设0来定义静能实验。"}],"illustration_spec":{"title":"质能关系的系统边界","objects":["初末静止容器","离开辐射箭头","外部总系统框","单位换算框"],"relations":["容器能量减少对应质量减少","把辐射计入时不可再漏记","静能与动能分项"],"labels":["E₀=mc²","ΔE=Δmc²","1 u c²≈931.5 MeV","不是全量可提取承诺"],"format":"SVG","priority":"P1","reuse":"无完全对应旧图；公式应SVG文字层","english":"Show a stationary container losing radiation across a defined boundary, with corresponding mass decrease delta E/c squared. Use a larger boundary to include radiation and keep total energy accounting consistent. Separate rest energy from kinetic energy and from practically extractable fuel energy."}}},"物理8":{"8.1":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":8,"section_id":"8.1","goals":["用方向和时间范围计算冲量","由力时间图求动量变化并反推平均力"],"prerequisites":["牛顿第二定律","向量与图象面积"],"flow":["选方向","初末动量","力时间面积","外冲量","平均力与缓冲"],"concept_relation":"选方向；初末动量；力时间面积；外冲量；平均力与缓冲","deep":["选正方向后先分别写初、末速度带符号值，再作p末−p初。反弹从负向到正向时，两者相减可能使变化大小等于速率之和乘质量；盲用“末速率减初速率”会把方向改变漏掉。","缓冲装置在相同初末动量变化下延长作用时间，可降低平均合力大小。峰值是否降低还依力时间曲线形状，不能只靠平均力公式保证任何峰值都下降。安全应用还要考虑位移空间、材料和允许加速度等约束。","碰撞过程中力随时间剧烈变化，冲量法避免追踪每一时刻细节。若题目给F-t图，需要确定是接触力、合力还是某一方向分量，面积单位和正负要与动量分量对应。","求得平均力后应检查作用对象和方向，并避免把球受墙力与墙受球力混在同一方程。它们大小相等方向相反，但分别属于不同对象；用同一质量解释两边运动会产生错误。"],"derive":["p=mv；Δp=mv_f−mv_i，矢量或带符号分量计算。","J外=Δp；F平均=Δp/Δt，指所选时段的合外力平均值。","三角形F-t脉冲J=底×高/2；单位N·s=kg·m/s。"],"examples":[{"q":"质量0.20 kg球沿正向以5 m/s运动，被挡停，求合外冲量。","given":"v_i=+5，v_f=0。","analysis":"冲量方向与原动量相反。","method":"Δp=m(v_f−v_i)。","principle":"合外冲量等于动量变化。","steps":["p_i=0.20×5=1.0 kg·m/s。","Δp=0−1.0=−1.0 N·s。"],"ans":"−1.0 N·s，沿负方向。","verification":"初动量加冲量=0，符合停止。","pitfall":"只给正的1.0而漏方向。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]},{"q":"0.10 kg球向左8 m/s撞墙后向右6 m/s，接触0.02 s，忽略其他水平方向冲量，平均墙力？","given":"取右为正，v_i=−8、v_f=+6。","analysis":"反弹须带符号相减。","method":"F平均=m(v_f−v_i)/Δt。","principle":"水平方向动量定理。","steps":["Δp=0.10[6−(−8)]=1.4 N·s。","F平均=1.4/0.02=70 N向右。"],"ans":"70 N向右，作用于球。","verification":"−0.8+1.4=+0.6 kg·m/s。","pitfall":"用6−8得到力方向和大小都错。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]},{"q":"一F-t三角形脉冲底宽0.04 s、峰值100 N，质量0.5 kg物体初静止，只受该方向合力，末速度？","given":"力图是合力且全为正。","analysis":"面积给冲量而非峰值乘全时。","method":"J=半底高，再Δp。","principle":"合力冲量改变动量。","steps":["J=0.5×0.04×100=2 N·s。","v=J/m=2/0.5=4 m/s。"],"ans":"+4 m/s。","verification":"平均力50 N×0.04 s=2 N·s。","pitfall":"用峰值100 N当平均值。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]}],"practice":[{"q":"2 kg物体速度由+3变+7 m/s，冲量？","given":"质量恒定。","analysis":"同方向仍需末减初。","method":"mΔv。","principle":"动量定理。","steps":["Δv=4 m/s。","J=2×4=8 N·s。"],"ans":"+8 N·s。","verification":"初6加8=末14 kg·m/s。","pitfall":"算末动量14当冲量。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]},{"q":"同样Δp=6 N·s，作用0.02与0.06 s，平均力大小？","given":"方向不变作大小比较。","analysis":"时间延长平均力下降。","method":"F=J/Δt。","principle":"平均力定义。","steps":["6/0.02=300 N。","6/0.06=100 N。"],"ans":"300 N与100 N。","verification":"时间3倍，平均力1/3。","pitfall":"推断峰值也必精确降至1/3。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]},{"q":"动量大小相同的两物体，方向相反，它们的动量相同吗？","given":"矢量方向相反。","analysis":"大小不等于矢量。","method":"取共同正方向表示。","principle":"动量与速度同方向。","steps":["可记p与−p。","两者矢量不相等，总动量可为0。"],"ans":"不相同。","verification":"相加0不等于单体各自0。","pitfall":"把标量大小当矢量。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]},{"q":"0至1 s合力+4 N、1至3 s合力−1 N，质量1 kg初速+3 m/s，末速？","given":"分段恒力。","analysis":"有向面积相加。","method":"J=4×1−1×2。","principle":"Δp=J外。","steps":["J=2 N·s。","p末=3+2=5 kg·m/s，v末=5 m/s。"],"ans":"+5 m/s。","verification":"分段a给先到7再降到5，结果一致。","pitfall":"负力区域取绝对值加成6。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]}],"quiz":{"q":"若只给接触力冲量，能否永远令它等于物体全部动量变化？","given":"其他外力可能作用同一时间段。","analysis":"定理要求合外冲量。","method":"列所有外力并估其冲量。","principle":"各外冲量矢量和等于Δp。","steps":["接触冲量与重力等需相加。","仅在其他有关分量抵消或可忽略时，才能直接等于Δp。"],"ans":"不能无条件。","verification":"较长接触时mgΔt可不可忽略。","pitfall":"把一个力和合外力混写。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]},"exam":["冲量题先选对象方向和起止时刻，列带符号初末速度","F-t图分有向面积，峰值不是平均值","缓冲题说同Δp下延时降平均力，峰值另需曲线证据"],"quick":["选方向","初末动量","力时间面积","外冲量","平均力与缓冲"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":264,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.1","url":"https://openstax.org/books/college-physics-2e/pages/8-2-impulse","page_or_section":"8-2-impulse","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":264,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.1","url":"https://openstax.org/books/college-physics-2e/pages/8-2-impulse","page_or_section":"8-2-impulse","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"冲量题先选对象方向和起止时刻，列带符号初末速度","method":"J=半底高，再Δp。","principle":"合力冲量改变动量。","worked_example_index":2,"verification":"平均力50 N×0.04 s=2 N·s。","pitfall":"用峰值100 N当平均值。"},"diagnostics":[{"goal_index":0,"question_ref":"e1","review_module":4,"feedback":"目标“用方向和时间范围计算冲量”的抽样复核：−0.8+1.4=+0.6 kg·m/s。；若出现“用6−8得到力方向和大小都错。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“由力时间图求动量变化并反推平均力”的抽样复核：平均力50 N×0.04 s=2 N·s。；若出现“用峰值100 N当平均值。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把一个力和合外力混写。","correction":"不能无条件。","verification":"较长接触时mgΔt可不可忽略。"}],"illustration_spec":{"title":"反弹动量与三角形冲量","objects":["球向左8后向右6","右正轴","三角形F-t脉冲"],"relations":["Δp=0.1×(6+8)=1.4","0.04×100/2=2 N·s","峰值与平均值分开"],"labels":["v_i=−8 m/s","v_f=+6 m/s","Δp","F/N","t/s"],"format":"SVG","priority":"P0","reuse":"V22 P10可复用原理，具体数值需说明不同例题","english":"Show signed initial and final velocities for a rebounding ball, then a separate triangular net-force pulse of height 100 N and duration 0.04 s with impulse 2 N s. Explicitly distinguish peak force from average force."}},"8.2":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":8,"section_id":"8.2","goals":["判定所选系统能否用动量守恒","由矢量总动量求相互作用后的速度"],"prerequisites":["动量定理","系统与外力"],"flow":["系统边界","内外冲量","方向守恒","共同或分别速度","能量独立审查"],"concept_relation":"系统边界；内外冲量；方向守恒；共同或分别速度；能量独立审查","deep":["守恒式写Σmᵢvᵢ前=Σmᵢvᵢ后，所有速度需相对同一惯性参考系和同一正方向。两物体碰后速度不必相同，只有黏合或题给共同运动才可合并为(m₁+m₂)v。","动量守恒与动能守恒条件不同。内力能把机械能转为形变、热等而不改变系统总动量；有爆炸释放内能时，动能甚至可增加。不能因用了动量守恒就附送动能守恒。","有摩擦并不自动否定任何短时近似，但必须比较外冲量与相互作用的动量变化尺度，并清楚标为近似。严格等式与忽略小量的近似要分开，不能只写“时间短所以一切外力消失”。","验证解时检查初末总动量、方向与约束。若总初动量为零，最终各物体仍可以运动，只要矢量和为零；“总量零”不等于每个分量或每个个体都静止。"],"derive":["ΔP系统=J合外；J合外=0时P前=P后。","一维：m₁u₁+m₂u₂=m₁v₁+m₂v₂；若黏合，v₁=v₂=v。","分方向守恒只在该方向合外冲量可忽略时使用；动能须独立审查。"],"examples":[{"q":"2 kg小车以3 m/s与静止1 kg小车黏合，水平外冲量忽略，共同速度？","given":"取初运动方向正。","analysis":"黏合使末速度相同。","method":"动量守恒。","principle":"系统水平方向合外冲量近0。","steps":["P前=2×3+1×0=6。","3v=6，v=2 m/s。"],"ans":"+2 m/s。","verification":"P后3×2=6；初动能9 J，末6 J，动量守恒不要求动能守恒。","pitfall":"把末速度设3或强用动能守恒。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]},{"q":"1 kg以+4 m/s、2 kg以−1 m/s运动，后者相互作用后速度+1 m/s，前者末速？","given":"系统水平外冲量忽略。","analysis":"方向需共同符号。","method":"列初末动量。","principle":"内冲量不改变总动量。","steps":["P前=1×4+2×(−1)=2。","v₁+2×1=2，故v₁=0。"],"ans":"前者末速0。","verification":"末总动量0+2=2。","pitfall":"把反向初速写正使总量错。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]},{"q":"系统初动量10 N·s，0.2 s内外力恒定向正10 N，能设末动量仍10吗？","given":"外力与初动量同向。","analysis":"必须先算外冲量。","method":"ΔP=FΔt。","principle":"有非零外冲量时不守恒。","steps":["J外=10×0.2=2 N·s。","P后=10+2=12 N·s。"],"ans":"不能；应为12 N·s。","verification":"总量增2与外冲量一致。","pitfall":"看到相互作用就忽略明确给出的外力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]}],"practice":[{"q":"总动量0是否表示两个物体都静止？","given":"总量是矢量和。","analysis":"非零反向量可抵消。","method":"构造等大反向动量。","principle":"总动量相加。","steps":["1 kg以+2 m/s、2 kg以−1 m/s。","动量+2与−2总0，但两者都运动。"],"ans":"不是。","verification":"动能却为2+1=3 J大于0。","pitfall":"把总量零当各项零。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]},{"q":"黏合前总动量−9 kg·m/s，总质量3 kg，末速度？","given":"无相关外冲量，共同运动。","analysis":"符号是方向。","method":"v=P/M。","principle":"动量守恒。","steps":["v=−9/3=−3 m/s。","负号表示所选正向的反方向。"],"ans":"−3 m/s。","verification":"3×(−3)=−9。","pitfall":"把负号删成+3。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]},{"q":"为什么两个物体之间内力很大仍可守恒总动量？","given":"系统同时包括二者。","analysis":"内力成对而非不存在。","method":"将两动量定理相加。","principle":"内冲量等大反向。","steps":["J₁₂+J₂₁=0。","总变化只剩外冲量，可为0。"],"ans":"内力冲量在系统求和中抵消。","verification":"单个物体动量仍可明显改变。","pitfall":"误写内力为0或每个动量都守恒。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]},{"q":"1 kg车以6 m/s与静止2 kg车黏合，若另受合外冲量−0.6 N·s，末速多少？","given":"外冲量题给不忽略。","analysis":"用动量定理修正守恒式。","method":"Mv=P前+J外。","principle":"系统动量变化等于合外冲量。","steps":["P后=6−0.6=5.4。","v=5.4/3=1.8 m/s。"],"ans":"+1.8 m/s。","verification":"若忽略外冲量得2，题给负冲量使速度更小合理。","pitfall":"仍机械用6/3=2。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]}],"quiz":{"q":"只把小球列为系统却把它受墙的力说成内力，为什么不成立？","given":"系统边界不含墙。","analysis":"内外分类依边界。","method":"说明施力物体是否在系统内。","principle":"外部物体对系统的力是外力。","steps":["墙在系统之外。","墙对球的冲量是外冲量，因此球动量可改变。"],"ans":"系统选择与内力分类矛盾。","verification":"球反弹的动量改变正需墙冲量。","pitfall":"为了守恒任意把外力改称内力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]},"exam":["守恒题先写系统、方向、时段及外冲量依据，再列式","黏合才可共同速度，分离题每物体保留末速变量","算完同时核总动量，能量需另审，不自动守恒"],"quick":["系统边界","内外冲量","方向守恒","共同或分别速度","能量独立审查"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":272,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.2","url":"https://openstax.org/books/college-physics-2e/pages/8-3-conservation-of-momentum","page_or_section":"8-3-conservation-of-momentum","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":272,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.2","url":"https://openstax.org/books/college-physics-2e/pages/8-3-conservation-of-momentum","page_or_section":"8-3-conservation-of-momentum","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"守恒题先写系统、方向、时段及外冲量依据，再列式","method":"ΔP=FΔt。","principle":"有非零外冲量时不守恒。","worked_example_index":2,"verification":"总量增2与外冲量一致。","pitfall":"看到相互作用就忽略明确给出的外力。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“判定所选系统能否用动量守恒”的抽样复核：总量增2与外冲量一致。；若出现“看到相互作用就忽略明确给出的外力。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“由矢量总动量求相互作用后的速度”的抽样复核：末总动量0+2=2。；若出现“把反向初速写正使总量错。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"为了守恒任意把外力改称内力。","correction":"系统选择与内力分类矛盾。","verification":"球反弹的动量改变正需墙冲量。"}],"illustration_spec":{"title":"系统边界与动量收支","objects":["两车系统框","内力成对箭头","外冲量箭头","初末动量条"],"relations":["内力只在两车都纳入时相消","非零外冲量改变总量","动能另算"],"labels":["P前","P后","J外","ΔP=J外","同一参考系"],"format":"SVG","priority":"P0","reuse":"V22 P10原理可补充，不重复同一题材","english":"Draw a system boundary around two interacting carts, cancel paired internal impulses, and keep external impulse crossing the boundary. Show P_after=P_before+J_external; do not imply kinetic-energy conservation."}},"8.3":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":8,"section_id":"8.3","goals":["用系统动量解释反冲方向","区分地面速度、相对速度与系统边界"],"prerequisites":["动量守恒","相对速度"],"flow":["系统分离","初总动量","同参考系速度","相对速度条件","能源与外冲量"],"concept_relation":"系统分离；初总动量；同参考系速度；相对速度条件；能源与外冲量","deep":["火箭通过向后排出物质获得向前动量变化，不需要推空气，因此可以在真空工作。排气与火箭间的作用力遵守相互作用，但若只取火箭本体，其质量随排气改变，不能把整个燃烧过程无条件写成固定质量的F=ma或简单两块一次分离公式。","本节可用一次分离的离散模型说明反冲，对连续变质量火箭的完整方程则需进一步考虑质量流和相对排气速度。模型层次应明确，不能把忽略外力的一瞬或一小段结论扩展为真实起飞全程速度。","反冲获得动能的来源可能是化学内能、弹性势能或人做功。系统动量保持零不代表总动能为零，也不能说为了反冲必须从静止状态“创造动量”；相反方向动量可以各自非零而合为零。","实际发射存在支架、地面、空气和重力等外部作用。固定发射装置与自由可动装置条件不同，是否可忽略某方向外冲量要具体说明；不能把所有枪弹题都默认完全孤立而不看题设。"],"derive":["初静止的一次分离模型：mv+MV=0，v和V必须相对同一参考系。","若给相对速度u=v−V，与mv+MV=0联立，V=−mu/(M+m)，v=Mu/(M+m)。","反冲动能K=m v²/2+M V²/2可大于0，能量来自系统内部或外部做功，不来自动量守恒本身。"],"examples":[{"q":"自由小车质量2 kg，向右抛出0.5 kg物体，物体地面速度4 m/s，初静止且水平外冲量忽略，小车速度？","given":"抛出后车质量2 kg，物体速度相对地面。","analysis":"两部分动量和0。","method":"0.5×4+2V=0。","principle":"所选系统动量守恒。","steps":["物体动量+2 kg·m/s。","小车V=−2/2=−1 m/s。"],"ans":"1 m/s向左。","verification":"两部分动量+2与−2相消。","pitfall":"把抛出前总质量2.5当剩余车质量。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]},{"q":"同样车2 kg、物体0.5 kg，但4 m/s为物体相对车的速度，求地面速度。","given":"初静止，水平外冲量忽略。","analysis":"相对速度不能直接代地面值。","method":"联立v−V=4与0.5v+2V=0。","principle":"速度相对变换及动量守恒。","steps":["v=V+4，代入0.5(V+4)+2V=0。","2.5V=−2，V=−0.8，v=3.2 m/s。"],"ans":"车−0.8 m/s，物体+3.2 m/s。","verification":"3.2−(−0.8)=4，动量1.6−1.6=0。","pitfall":"照前题得−1与4而相对速度变成5。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]},{"q":"质量3 kg与1 kg两块初静止分离，1 kg块以6 m/s向右，求另一块速度和总动能。","given":"一次分离，外冲量忽略。","analysis":"动量零但动能可增加。","method":"先求反向速度，再求两部分动能。","principle":"内能释放可在动量守恒下增加动能。","steps":["3V+1×6=0，V=−2 m/s。","K=0.5×3×4+0.5×1×36=6+18=24 J。"],"ans":"3 kg块向左2 m/s，总动能24 J。","verification":"动量−6+6=0；能量24 J须有释放来源。","pitfall":"以初动能0推断末动能也0。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]}],"practice":[{"q":"火箭在真空能否靠排气推进？","given":"无空气但可携带并排出物质。","analysis":"推进不是推空气。","method":"考察火箭与排气总系统。","principle":"内部相互作用分配相反动量。","steps":["排气向后带走动量。","火箭获得相反方向动量变化，外部空气并非必要。"],"ans":"可以。","verification":"与动量守恒相容。","pitfall":"必须有空气给火箭反作用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]},{"q":"两部分初静止分离后质量比1:4，速度大小比？","given":"两部分总动量0，一维。","analysis":"动量大小相等。","method":"m₁|v₁|=m₂|v₂|。","principle":"守恒且方向相反。","steps":["|v₁|/|v₂|=m₂/m₁=4。","方向相反。"],"ans":"4:1，反向。","verification":"小质量需更大速度达到等动量。","pitfall":"把质量比直接作为速度比。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]},{"q":"枪固定在地面上，能只对枪和弹无条件用自由反冲公式吗？","given":"支架可提供外冲量。","analysis":"系统边界未含支架地球。","method":"审查外冲量。","principle":"动量变化由外冲量决定。","steps":["固定约束可传递明显动量给地面。","枪弹两体系统不再满足忽略外冲量的自由模型。"],"ans":"不能无条件。","verification":"固定枪末速0也不妨碍弹获动量，因为有外部交换。","pitfall":"忽略固定条件。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]},{"q":"4 kg车抛1 kg物体，物体相对车5 m/s，初静止，求两者地面速度并验证。","given":"水平外冲量忽略。","analysis":"给的是相对速度。","method":"v−V=5，v+4V=0。","principle":"动量与相对速度两式。","steps":["v=V+5，5V+5=0，V=−1。","v=4 m/s。"],"ans":"车−1，物体+4 m/s。","verification":"4−(−1)=5；4+4×(−1)=0。","pitfall":"把5直接当物体地面速度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]}],"quiz":{"q":"真实火箭燃烧时剩余质量变化，可以直接把起飞全程当固定两块瞬间分离计算吗？","given":"连续排气且外力可能存在。","analysis":"系统和质量在时间中变化。","method":"限定离散模型或采用质量流分析。","principle":"连续变质量过程需逐段计动量通量及外力。","steps":["一次两块模型可说明方向和局部理想例子。","全程须处理持续排气、变质量和重力等，不能原式无条件外推。"],"ans":"不可以无条件。","verification":"不同排气时刻有不同火箭速度，不能归为一个固定末速度块。","pitfall":"把演示模型冒充完整航天计算。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]},"exam":["反冲题先确认抛出后质量与速度参考系","给相对速度须列v抛−v体=u并与守恒联立","解释题用排气动量与内部能源，说明真空可推进及模型限制"],"quick":["系统分离","初总动量","同参考系速度","相对速度条件","能源与外冲量"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":282,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.3","url":"https://openstax.org/books/college-physics-2e/pages/8-7-introduction-to-rocket-propulsion","page_or_section":"8-7-introduction-to-rocket-propulsion","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":282,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.3","url":"https://openstax.org/books/college-physics-2e/pages/8-7-introduction-to-rocket-propulsion","page_or_section":"8-7-introduction-to-rocket-propulsion","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"反冲题先确认抛出后质量与速度参考系","method":"先求反向速度，再求两部分动能。","principle":"内能释放可在动量守恒下增加动能。","worked_example_index":2,"verification":"动量−6+6=0；能量24 J须有释放来源。","pitfall":"以初动能0推断末动能也0。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用系统动量解释反冲方向”的抽样复核：两部分动量+2与−2相消。；若出现“把抛出前总质量2.5当剩余车质量。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“区分地面速度、相对速度与系统边界”的抽样复核：3.2−(−0.8)=4，动量1.6−1.6=0。；若出现“照前题得−1与4而相对速度变成5。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把演示模型冒充完整航天计算。","correction":"不可以无条件。","verification":"不同排气时刻有不同火箭速度，不能归为一个固定末速度块。"}],"illustration_spec":{"title":"反冲的参考系与相对速度","objects":["小车2 kg","抛出物0.5 kg","地面坐标","速度箭头","相对速度括号"],"relations":["V=−0.8","v=+3.2","v−V=4","两动量等大反向"],"labels":["相对地面","相对车4 m/s","P总=0","内部能源"],"format":"SVG","priority":"P0","reuse":"须用明确参考系的新示意，旧反冲图可核后辅助","english":"For a freely moving 2 kg cart ejecting a 0.5 kg object, show ground velocities -0.8 and +3.2 m/s, with object speed relative to cart 4 m/s. Distinguish relative and ground arrows and show equal opposite momenta, not equal speeds."}},"8.4":{"content_batch":"batch05","subject":"物理","subject_code":"physics","chapter_id":8,"section_id":"8.4","goals":["先用动量再按碰撞类型审查能量","求一维碰撞速度并核方向与能量损失"],"prerequisites":["动量守恒","动能与联立方程"],"flow":["系统动量","碰撞类型","第二条件","总动能","分离与验算"],"concept_relation":"系统动量；碰撞类型；第二条件；总动能；分离与验算","deep":["同质量正碰且一个初静止，在理想一维弹性条件下可交换速度；若黏合则共同速度为初速度的一半。两个结果都可满足动量守恒，说明只用一个守恒方程不足以判定两个独立末速度。","动能损失要用两物体的总动能前后比较，不可只看一个物体变慢。某个物体可能变快而系统总动能仍减少。若题给可释放内能的爆发性相互作用，末动能可能增加，此时也不属于普通仅耗散的非弹性模型。","实际二维碰撞要分方向列动量方程，动能为各速度大小的平方；先画方向能避免把不同轴分量混用。本节典型计算聚焦一维，不把二维条件简化成所有速度带一个正负号。","最终检查包括碰后是否满足黏合或分离条件、动量总量是否一致、动能变化是否符合类型。代数联立可能包含“仍保持碰前状态”的根，须用实际碰撞与分离条件排除不合物理的分支。"],"derive":["一维动量：m₁u₁+m₂u₂=m₁v₁+m₂v₂。","弹性另有m₁u₁²/2+m₂u₂²/2=m₁v₁²/2+m₂v₂²/2，可推出v₂−v₁=u₁−u₂。","黏合共同速度v=(m₁u₁+m₂u₂)/(m₁+m₂)；损失ΔK=K前−K后，不必等于K前。"],"examples":[{"q":"1 kg车以4 m/s撞静止1 kg车并黏合，求共同速度与动能损失。","given":"水平外冲量忽略。","analysis":"黏合可合并末质量，不能守恒动能。","method":"动量求v再算K。","principle":"完全非弹性模型。","steps":["2v=4，v=2 m/s。","K前=0.5×1×16=8 J，K后=0.5×2×4=4 J，损失4 J。"],"ans":"共同+2 m/s，损失4 J。","verification":"动量前4后4，末动能仍4不为0。","pitfall":"完全非弹性误写末动能零。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]},{"q":"同样两辆1 kg车，初速4与0，改为一维弹性碰撞，末速？","given":"外冲量忽略且弹性。","analysis":"需动量与弹性相对速度两条件。","method":"v₁+v₂=4，v₂−v₁=4。","principle":"一维弹性守恒两量。","steps":["两式相加2v₂=8，v₂=4。","v₁=0。"],"ans":"第一车停，第二车+4 m/s。","verification":"总动量4，动能8 J均与初相同。","pitfall":"只用动量任猜2和2。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]},{"q":"2 kg车以3 m/s撞静止1 kg车，一维弹性，求两末速并核算。","given":"正方向沿初车速度。","analysis":"两质量不等，不能直接交换速度。","method":"2v₁+v₂=6，v₂−v₁=3。","principle":"动量和一维弹性关系。","steps":["代v₂=v₁+3得3v₁=3，v₁=1。","v₂=4 m/s。","K后=0.5×2×1²+0.5×1×4²=1+8=9 J。"],"ans":"2 kg车+1、1 kg车+4 m/s。","verification":"初K=0.5×2×9=9 J，动量2+4=6。","pitfall":"把等质量交换速度推广不等质量。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]}],"practice":[{"q":"碰后两物体黏合，能默认动能守恒吗？","given":"非特殊零相对速度情境。","analysis":"黏合限制末速度但一般耗散动能。","method":"动量后独立算K。","principle":"完全非弹性不要求动能守恒。","steps":["共同速度由动量确定。","通常存在形变热等，需比较总K。"],"ans":"不能。","verification":"1 kg、4与0的例子损失一半动能。","pitfall":"把所有守恒定律捆绑使用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]},{"q":"1 kg以+3、1 kg以−3 m/s相向黏合，末速与损失？","given":"外冲量忽略。","analysis":"总动量零但初动能正。","method":"动量求共同速度。","principle":"相反动量抵消。","steps":["P前=0，v=0。","K前=4.5+4.5=9 J，K后0，损失9 J。"],"ans":"末速0，损失9 J。","verification":"这是末K为0的特殊条件，非所有黏合都如此。","pitfall":"从该特例推出所有完全非弹性末能0。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]},{"q":"某车碰撞后动能增加2 J，另一辆减少5 J，总动能变化？","given":"只有这两辆车构成所比系统。","analysis":"应求总和。","method":"ΔK总=ΣΔK。","principle":"局部获得可伴总体损失。","steps":["2+(−5)=−3 J。","系统损失3 J。"],"ans":"减少3 J。","verification":"一辆把5 J中的2 J给另一辆，其余3 J转其他形式。","pitfall":"只看一辆增能就称系统弹性或增能。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]},{"q":"3 kg以2 m/s撞静止1 kg并黏合，求v、动能损失与损失率。","given":"忽略水平外冲量。","analysis":"先动量后能量。","method":"v=P/M，再算K。","principle":"黏合共同速度。","steps":["P=6，v=6/4=1.5 m/s。","K前=6 J，K后=0.5×4×2.25=4.5 J。","损失1.5 J，比例1.5/6=25%。"],"ans":"+1.5 m/s，损失1.5 J、25%。","verification":"末P=4×1.5=6，末能为初75%。","pitfall":"把总质量4代进初车动能。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]}],"quiz":{"q":"只给两物体初速度、质量与总动量守恒，未说明碰撞类型，通常能唯一确定两个独立末速度吗？","given":"一维但没有黏合或能量等第二条件。","analysis":"一个独立方程通常有两个未知。","method":"说明缺何物理条件。","principle":"守恒动量限制总量，不确定分配唯一性。","steps":["可有不同v₁、v₂组合满足同一总P。","需弹性、恢复系数或黏合等额外信息，不能擅自添加。"],"ans":"通常不能唯一确定。","verification":"等质量4与0初态，末0与4或2与2均满足动量而类型不同。","pitfall":"看见碰撞便自动假定弹性。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]},"exam":["碰撞题先写系统外冲量，再从弹性/黏合/其他条件选第二关系","能量损失按两物体总K前后求，明确非总能量消失","一维弹性相对速度仅在适用模型用，最后核分离方向"],"quick":["系统动量","碰撞类型","第二条件","总动能","分离与验算"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":287,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.4","url":"https://openstax.org/books/college-physics-2e/pages/8-4-elastic-collisions-in-one-dimension","page_or_section":"8-4-elastic-collisions-in-one-dimension","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":287,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.4","url":"https://openstax.org/books/college-physics-2e/pages/8-4-elastic-collisions-in-one-dimension","page_or_section":"8-4-elastic-collisions-in-one-dimension","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"碰撞题先写系统外冲量，再从弹性/黏合/其他条件选第二关系","method":"2v₁+v₂=6，v₂−v₁=3。","principle":"动量和一维弹性关系。","worked_example_index":2,"verification":"初K=0.5×2×9=9 J，动量2+4=6。","pitfall":"把等质量交换速度推广不等质量。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“先用动量再按碰撞类型审查能量”的抽样复核：动量前4后4，末动能仍4不为0。；若出现“完全非弹性误写末动能零。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“求一维碰撞速度并核方向与能量损失”的抽样复核：初K=0.5×2×9=9 J，动量2+4=6。；若出现“把等质量交换速度推广不等质量。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"看见碰撞便自动假定弹性。","correction":"通常不能唯一确定。","verification":"等质量4与0初态，末0与4或2与2均满足动量而类型不同。"}],"illustration_spec":{"title":"弹性与黏合碰撞的双重核查","objects":["等质量初4与0","弹性末0与4","黏合末2与2","动量条","动能条"],"relations":["两例P均4","弹性K8保持","黏合K由8到4，差为其他形式"],"labels":["kg","m/s","P/(kg·m/s)","K/J","转为内能等"],"format":"SVG","priority":"P0","reuse":"V22 P27优先复核复用，避免与P11重复显示","english":"Compare two 1 kg carts initially at 4 and 0 m/s. Elastic final velocities are 0 and 4; sticking final velocity is 2. Plot momentum total 4 in both and kinetic energies 8 to 8 versus 8 to 4 J. Do not label dissipated kinetic energy as destroyed energy."}}}});
